// Content for Money, Together (node g58, ages 22+, Chapter 7): NEW v2 build to GDD 58 (mechanic-embodying),
// carrying the Work & Money domain from Money & Independence (g48) into shared adult life: two incomes, one life,
// and a lot of decisions. 84 researched, India-grounded scenarios across money-talk → plan-together →
// stay-independent → fair-not-gendered → control-is-abuse → tools-and-help, each encoded as one of the shared v2
// play actions (branch / strike-rewrite / sort / reflect / match / spot / role-play): no binary "tap the right
// card". Lead: branch (your move), strike-rewrite (bust the myth), sort. Six modes: the money talk (open, early,
// honest about incomes/debts/goals: talking money is care, not coldness), plan together (joint AND personal
// accounts, shared goals, budgeting for a baby/home/emergency, both partners knowing the money), stay independent
// (keep your own account, literacy & footing; busts "he handles the money because he earns it"; the homemaker's
// unpaid work is real economic value), fair not gendered (managing money isn't a man's job; the earner doesn't get
// a bigger vote; a stay-at-home partner is an equal, not a dependent), control is abuse (allowances, cut-offs,
// seizing a salary or stridhan, barring work are ECONOMIC ABUSE: recognised domestic violence under the PWDVA
// 2005 → Respect at Home g56 + help), tools & help. Even-handed and warm; centres each partner's financial
// independence, especially women's; educational, NOT financial or legal advice. Builds on Money & Independence
// (g48); pairs with Equal Partners (g55); guards against the financial control covered in Respect at Home (g56).
// India: money in marriages is often gendered and entangled with in-laws, dowry & gold; stridhan is a woman's own
// property by law; economic abuse is recognised DV with remedies under the PWDVA 2005 (181, 1091, 112, NALSA legal
// aid 15100). gameId "money-together".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"mt-001","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking about money before or early in marriage is unromantic.\"","myth":{"un":"Talking about money before or early in marriage is unromantic.","re":"Open, early money talks are an act of respect and care; they prevent most money fights.","why":"Clarity now spares conflict later."},"relearn":"Talking money openly and early is care, not coldness; it prevents most fights.","persona":"Sneha","source":"money talk is care"},
  {"id":"mt-002","cat":"money-talk","type":"strike-rewrite","hook":"\"If we love each other, we'll never fight about money.\"","myth":{"un":"If we love each other, we'll never fight about money.","re":"Money is a top source of couple conflict even in loving partnerships; talking openly is what protects you.","why":"Love doesn't auto-solve finances; communication does."},"relearn":"Love alone doesn't prevent money fights; open, honest money talk does.","persona":"any","source":"love isn't enough"},
  {"id":"mt-003","cat":"money-talk","type":"sort","hook":"Sort: belongs in an honest early money talk, or none of a partner's business?","items":[{"id":"a","text":"Each person's income and debts"},{"id":"b","text":"A friend's private salary"},{"id":"c","text":"Shared goals and big costs ahead"},{"id":"d","text":"A stranger's spending habits"},{"id":"e","text":"Loans or EMIs you're carrying"},{"id":"f","text":"A neighbour's bank balance"}],"bins":[{"id":"talk","label":"In the money talk","valence":"pos"},{"id":"not","label":"Not relevant","valence":"neutral"}],"key":{"a":"talk","b":"not","c":"talk","d":"not","e":"talk","f":"not"},"relearn":"Your incomes, debts and shared goals belong in the talk; other people's private finances don't.","persona":"any","source":"what to share"},
  {"id":"mt-004","cat":"money-talk","type":"branch","persona":"Karthik","source":"start the talk","hook":"You're about to share a life with someone but have never discussed money honestly.","steps":[{"prompt":"You're both looking at places to move into together, and money keeps almost coming up. What do you do?","options":[{"text":"Start a calm, judgement-free talk about incomes, debts and goals","then":"It's a little awkward at first, then surprisingly easy.","best":true},{"text":"Avoid it and assume it'll probably sort itself out later","then":"The move gets planned, and the actual money talk keeps waiting."},{"text":"Wait for your partner to bring it up first, instead of you","then":"Neither of you brings it up, and the waiting becomes its own habit."},{"text":"Ask a mutual friend to gently raise it for you instead","then":"It's awkward for everyone, and still isn't really your conversation."}],"why":"Starting the talk yourself, calmly, is what actually opens it."},{"prompt":"The topic of existing debt comes up, and it's more than expected. What do you do?","options":[{"text":"Stay curious and ask what a manageable plan looks like","then":"The number stops feeling like a verdict and starts feeling like a plan.","best":true},{"text":"Go quiet for a moment, honestly unsure what to even say","then":"The silence makes the number feel bigger than it needs to."},{"text":"React with visible shock at hearing the actual number","then":"The shock lands harder than the actual number did."},{"text":"Say it doesn't matter, and brush right past it quickly","then":"Brushing past it skips a conversation you'll likely need later anyway."}],"why":"Staying curious turns a hard number into something you can plan around."},{"prompt":"You start listing shared goals: a home someday, savings, maybe a trip. What do you focus on?","options":[{"text":"Agreeing what matters most to both of you, in order","then":"The list gets shorter, and clearer, once it's actually shared.","best":true},{"text":"Listing your own goals first, then asking for theirs after","then":"It quietly sets the starting order, before hearing theirs."},{"text":"Assuming your goals probably match, without really checking","then":"An assumption stands in for an actual, honest conversation."},{"text":"Picking whichever goal sounds the most impressive to say","then":"Impressive doesn't always mean actually shared."}],"why":"Agreeing an order together is what turns separate wishes into a real shared plan."},{"prompt":"A relative says couples shouldn't talk money this early, since it spoils the romance. What do you say?","options":[{"text":"Say open money talk is part of caring for each other","then":"The relative looks doubtful, then admits it saves fights later.","best":true},{"text":"Say it's fine to skip as long as you both earn well","then":"The relative agrees, and debts and goals stay unspoken."},{"text":"Laugh and say romance never paid anyone's rent","then":"Everyone laughs, and the idea that money talk is cold stands."},{"text":"Say money talk does feel a bit unromantic, to be fair","then":"The relative nods, and the talk you need feels harder to start."}],"why":"Naming money talk as care answers the myth that it spoils romance."}],"debrief":"Open the money talk deliberately; avoidance just defers the conflict.","relearn":"Start the money talk calmly; avoiding it defers, not avoids, the conflict."},
  {"id":"mt-005","cat":"money-talk","type":"match","hook":"Match each money-talk topic to why it matters.","pairs":[{"left":"Incomes and debts","right":"A shared, honest starting picture"},{"left":"Spending values","right":"Where you'll naturally agree or clash"},{"left":"Goals and big costs","right":"What you're saving and planning for"},{"left":"Who pays what","right":"A split that feels fair to both"},{"left":"Money worries","right":"Fears you can face as a team"}],"relearn":"Incomes, values and goals are the things an honest money talk needs to cover.","persona":"any","source":"talk topics"},
  {"id":"mt-006","cat":"money-talk","type":"strike-rewrite","hook":"\"Debts you brought in are private and your partner never needs to know.\"","myth":{"un":"Debts you brought in are private and your partner never needs to know.","re":"Shared life means shared visibility; hiding major debt undermines the trust money decisions need.","why":"Transparency, not secrecy, builds financial trust."},"relearn":"Major debts belong in the open with a partner; hiding them erodes the trust money needs.","persona":"any","source":"debt transparency"},
  {"id":"mt-007","cat":"money-talk","type":"reflect","hook":"Lensy: the couples who talk money openly fight about it least. Worth having the awkward talk?","prompt":"What do you think?","options":["Worth it","I'll have it","Makes sense"],"affirm":"Open financial communication is linked to less money stress and more satisfaction; the awkward talk pays off.","relearn":"Couples who talk money openly fight about it least; the awkward talk is worth it.","persona":"any","source":"talk beats silence"},
  {"id":"mt-008","cat":"money-talk","type":"spot","hook":"Spot the two unhealthy money-talk habits to drop.","scene":[{"id":"a","text":"Sharing real numbers, not vague hints","trick":false},{"id":"b","text":"Hiding purchases to avoid a reaction","trick":true},{"id":"c","text":"Checking in on goals regularly","trick":false},{"id":"d","text":"Going silent and stewing instead of saying it","trick":true},{"id":"e","text":"Naming a worry calmly before it grows","trick":false}],"why":"Hiding purchases and going silent are unhealthy; real numbers, check-ins and naming a worry are the healthy habits.","relearn":"Real numbers and regular check-ins beat hidden purchases and silent stewing.","persona":"Pooja","source":"healthy talk habit"},
  {"id":"mt-009","cat":"money-talk","type":"branch","persona":"Karthik","source":"fair split","hook":"You earn much more than your wife, Meera, and you're unsure how to split shared costs fairly.","steps":[{"prompt":"The first joint bill arrives, and neither of you has said how to split it. What do you do?","options":[{"text":"Bring it up and discuss a fair split, like proportional to income","then":"It's a new conversation, but not an awkward one, once it starts.","best":true},{"text":"Quietly pay more yourself, without discussing it","then":"It works this time, but nothing's actually been agreed."},{"text":"Split it evenly between you, without discussing incomes at all","then":"Even feels fair on the surface, and less fair underneath."},{"text":"Leave the bill on the table and see who pays first","then":"Meera pays it, and neither of you says a word."}],"why":"Discussing the split openly is what makes it actually fair, not just paid."},{"prompt":"A week later, Meera says she'd rather pay exactly half, so she isn't a burden. What do you do?","options":[{"text":"Say she's no burden, and ask to work out a split together","then":"She hesitates, then agrees to sit down and look at both incomes.","best":true},{"text":"Agree to half, since it's what she wants","then":"She pays half, and cuts back on things she enjoys to manage it."},{"text":"Insist you'll pay most of it, whatever she says","then":"She goes quiet, feeling overruled about her own money."},{"text":"Say you'll cover the big bills and she can do groceries","then":"She agrees, unsure how you picked which bills were whose."}],"why":"Easing the burden worry and deciding the split together is what makes it fair."},{"prompt":"Months later, your mother asks whether Meera 'pays her share' at home. What do you say?","options":[{"text":"Say the split is for you and Meera to decide together","then":"Your mother raises an eyebrow, but lets it go.","best":true},{"text":"Say Meera earns less, so you cover most of it","then":"Your mother nods, as if Meera owes you for it."},{"text":"Say Meera pays exactly half, so no one can say otherwise","then":"Your mother looks satisfied, and the 'share' idea sticks."},{"text":"Tell her to ask Meera herself","then":"She does, and Meera is left explaining her own money."}],"why":"Keeping the split a decision for the two of you means Meera owes no one an account."}],"debrief":"Decide shared costs together and openly, not by default to the higher earner.","relearn":"Design a fair split together; don't let the higher earner decide alone."},
  {"id":"mt-010","cat":"money-talk","type":"sort","hook":"Sort: a green-flag money-talk behaviour, or a red-flag one?","items":[{"id":"a","text":"Honesty about what you earn and owe"},{"id":"b","text":"Hiding accounts from each other"},{"id":"c","text":"Deciding big spends together"},{"id":"d","text":"One partner kept in the dark on purpose"},{"id":"e","text":"Bringing up money calmly, not only in a fight"},{"id":"f","text":"Using the talk to score points"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Honesty, joint big-decisions and a calm tone are green; hidden accounts, dark-keeping and point-scoring are red.","persona":"any","source":"green or red"},
  {"id":"mt-011","cat":"money-talk","type":"role-play","persona":"Sneha","source":"warm opener","hook":"You want to open the money conversation with your partner Kabir without him feeling judged.","setup":"You pick a relaxed evening to start.","steps":[{"prompt":"Kabir asks: \"What's this about? Are we okay?\"","options":[{"text":"\"We're fine. I just want us to map our money together, no judgement.\"","then":"He relaxes. \"Okay, that actually sounds nice.\"","best":true},{"text":"\"We need to talk about your spending habits lately.\"","then":"He stiffens. \"What did I do wrong now?\""},{"text":"\"Nothing, forget I even said anything about it.\"","then":"He looks unconvinced but lets it go for now."},{"text":"\"It's just something I read about somewhere, not urgent.\"","then":"He nods, but the moment loses its momentum."}],"why":"Framing it as a team map, not a complaint, keeps him open, not defensive."},{"prompt":"A little later, Kabir asks: \"So, should we actually look at this or not?\"","options":[{"text":"\"Let's each share what we earn and where it goes.\"","then":"\"Fair enough,\" he says, and pulls out his phone to check.","best":true},{"text":"\"You go first. I'll just listen for now.\"","then":"He hesitates. \"Feels one-sided if it's just me.\""},{"text":"\"Let's just guess roughly. It's not that deep anyway.\"","then":"The numbers stay vague, and so does the plan."},{"text":"\"Doesn't matter. Let's just set a savings goal instead.\"","then":"\"Sure,\" he says, though neither of you knows the real picture yet."}],"why":"Sharing both sides first builds the honest picture a plan needs."},{"prompt":"Kabir asks: \"So what's the actual next step here?\"","options":[{"text":"\"Let's pick one small goal and check in monthly.\"","then":"He smiles. \"I like that, something we're actually building.\"","best":true},{"text":"\"I'll figure out a plan on my own and just tell you.\"","then":"\"Oh,\" he says, sounding less involved than a moment ago."},{"text":"\"We probably won't need to talk about this again really.\"","then":"He looks unsure whether that's really true."},{"text":"\"We'll see how it goes, no real plan needed for now.\"","then":"The openness from earlier starts to lose its shape."}],"why":"A shared goal with a check-in keeps the momentum you just built."}],"relearn":"A warm, no-judgement, team-framed opener makes the money talk safe instead of accusatory."},
  {"id":"mt-012","cat":"money-talk","type":"strike-rewrite","hook":"\"One big money talk at the start is enough to sort it forever.\"","myth":{"un":"One big money talk at the start is enough to sort it forever.","re":"Money needs revisiting as life changes, new jobs, a baby, a move; it's an ongoing conversation.","why":"Finances shift, so the talk recurs."},"relearn":"Money is an ongoing conversation revisited as life changes, not a one-time talk.","persona":"Pooja","source":"ongoing talk"},
  {"id":"mt-013","cat":"money-talk","type":"reflect","hook":"Lensy: 'no judgement, we're a team' turns a money fight into a money plan. Try it?","prompt":"What's your take?","options":["I'll try it","Team framing","Good idea"],"affirm":"Framing money as a shared team problem, not a blame game, is what makes the talk productive.","relearn":"Frame money as a team problem, not a blame game; that's what makes the talk work.","persona":"any","source":"team not blame"},
  {"id":"mt-014","cat":"money-talk","type":"branch","persona":"Karthik","source":"side by side","hook":"A money disagreement is heating up and you both feel defensive.","steps":[{"prompt":"Voices are starting to rise over a spending decision. What do you do?","options":[{"text":"Pause, and name the shared goal you're actually both after","then":"The pause changes the shape of the conversation.","best":true},{"text":"Push your point harder, to actually win the disagreement","then":"Winning the argument doesn't actually solve the money problem."},{"text":"Go quiet and just let the whole thing drop for now","then":"Dropping it now usually means having it again later, worse."},{"text":"Bring up an old, unrelated money mistake from before","then":"The old mistake derails the actual, current decision."}],"why":"Naming the shared goal turns two people arguing into a team facing a problem."},{"prompt":"Once you're calmer, your partner asks what actually worries you about this. What do you say?","options":[{"text":"Say plainly what worries you, with no blame attached","then":"The specific worry is easier to actually solve than the argument was.","best":true},{"text":"Say you're not sure, just that something feels off here","then":"The vague answer leaves nothing concrete to work with."},{"text":"Say it's mostly that they're just bad with money","then":"It reopens exactly the defensiveness you were both trying to move past."},{"text":"Say it doesn't matter now. You'll manage somehow","then":"The actual worry stays unspoken, and unsolved."}],"why":"A specific worry, without blame, is something you can actually work on together."},{"prompt":"A few days later, a similar spending question comes up. What do you do?","options":[{"text":"Agree on how you'll decide questions like this together","then":"The talk is shorter this time, with somewhere useful to start.","best":true},{"text":"Say nothing, and hope it doesn't become another argument","then":"It simmers, and the next argument starts from the old place."},{"text":"Keep quiet score of who was right last time","then":"Keeping score turns this disagreement into round two."},{"text":"Agree to never disagree about money again, as a rule","then":"The rule breaks within the week, and neither of you says so."}],"why":"Agreeing how you'll decide together turns one fight into a way forward."}],"debrief":"In a money clash, get side by side against the problem, not against each other.","relearn":"Tackle money problems side by side; don't turn them into who's right."},
  {"id":"mt-015","cat":"plan-together","type":"strike-rewrite","hook":"\"A couple should pool everything into one account with nothing personal.\"","myth":{"un":"A couple should pool everything into one account with nothing personal.","re":"Many couples do best with both a joint account for shared costs and personal accounts for autonomy.","why":"Sharing goals doesn't require erasing personal money."},"relearn":"Both a joint account for shared costs and personal accounts for autonomy often works best.","persona":"any","source":"both accounts"},
  {"id":"mt-016","type":"sort","persona":"Pooja","source":"joint vs personal","hook":"Sort: a shared expense for the joint pot, or a personal one?","items":[{"id":"a","text":"Rent and household bills"},{"id":"b","text":"A personal hobby"},{"id":"c","text":"The family emergency fund"},{"id":"d","text":"A private gift for your partner"},{"id":"e","text":"The weekly groceries"},{"id":"f","text":"Your own pocket money"}],"bins":[{"id":"joint","label":"Shared / joint","valence":"pos"},{"id":"personal","label":"Personal","valence":"neutral"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Rent, groceries and the emergency fund are shared; a hobby, a surprise gift and pocket money are personal.","cat":"plan-together"},
  {"id":"mt-017","cat":"plan-together","type":"branch","persona":"Karthik","source":"shared goal","hook":"You and your partner Neha are planning your wedding, and the cost is big.","steps":[{"prompt":"You sit down to talk about it for the first time. What do you propose?","options":[{"text":"Set a shared goal, a timeline and a monthly amount","then":"Neha nods, relieved to have something concrete to work with.","best":true},{"text":"Suggest saving whatever is spare each month, with no set amount","then":"It feels easy now, but with no target the cost keeps creeping closer."},{"text":"Say you'll handle the planning side entirely by yourself","then":"She's left out of a decision that genuinely affects her too."},{"text":"Suggest waiting until the cost is a lot closer to plan for it","then":"Waiting shrinks the time you'll actually have to save for it."}],"why":"A shared goal with a timeline turns a big cost into a plan, not a panic."},{"prompt":"A month later, Neha asks how you're both doing on saving for it. What do you focus on?","options":[{"text":"Checking how much you've saved against the total needed","then":"You are a little behind, and you agree a small adjustment together.","best":true},{"text":"Whether one of you is quietly saving more than the other","then":"It turns a simple check-in into a small, unspoken competition."},{"text":"Putting it off for a month since money's been a bit tight","then":"A month off turns into two, and the cost keeps getting closer."},{"text":"Raising the monthly amount sharply to catch up straight away","then":"A big jump feels heavy, and the goal starts to feel like a burden."}],"why":"Checking progress against the target keeps the plan on track and shared."},{"prompt":"The wedding is now only a few months away. What do you do?","options":[{"text":"Review the total together and work out any gap left","then":"You see the real gap together, and can still plan the last stretch.","best":true},{"text":"Avoid checking the exact number since it feels stressful","then":"Not knowing the gap makes the final stretch feel scarier."},{"text":"Assume it'll all work out somehow when the time comes","then":"It might not, and assuming leaves no room to adjust in time."},{"text":"Ask family to cover any shortfall without discussing it first","then":"It may cover the gap, but Neha hears about it from them first."}],"why":"Reviewing the total together keeps the last stretch a shared, clear one."}],"debrief":"Plan big costs as a shared goal with a timeline and an agreed monthly amount.","relearn":"Turn big costs into a shared, timed savings goal rather than winging it."},
  {"id":"mt-018","type":"match","persona":"any","source":"the money tools","hook":"Match each money tool to the job it does.","pairs":[{"left":"Joint account","right":"Shared bills and goals"},{"left":"Personal accounts","right":"Each partner's autonomy"},{"left":"Emergency fund","right":"A cushion for shocks"},{"left":"A shared timed goal","right":"Funding a big planned cost"},{"left":"Shared access","right":"Both partners knowing the money"}],"relearn":"A joint account, personal accounts, an emergency fund, a timed goal and shared access each do a distinct job.","cat":"plan-together"},
  {"id":"mt-019","cat":"plan-together","type":"strike-rewrite","hook":"\"Saving and planning can wait until we're older and earn more.\"","myth":{"un":"Saving and planning can wait until we're older and earn more.","re":"Starting small and early, even tiny amounts, builds the habit and the cushion that protect a couple.","why":"Early habits beat late intentions."},"relearn":"Start saving and planning early, even small amounts; the habit and cushion matter more than the size.","persona":"Sneha","source":"start early"},
  {"id":"mt-020","type":"sort","persona":"any","source":"smart or risky","hook":"Sort: a smart shared-planning move, or a risky gap?","items":[{"id":"a","text":"Building an emergency fund"},{"id":"b","text":"No savings and no plan at all"},{"id":"c","text":"Both knowing where the money is"},{"id":"d","text":"Only one partner knowing the accounts"},{"id":"e","text":"Saving a little every month"},{"id":"f","text":"Spending every rupee as it comes"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risky","label":"Risky gap","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"A fund, shared knowledge and steady saving are smart; no plan, sole access and saving nothing are risky.","cat":"plan-together"},
  {"id":"mt-021","cat":"plan-together","type":"reflect","hook":"Lensy: a plan you both helped build is one you'll both stick to. Plan together, not for each other?","prompt":"What do you think?","options":["Together","We both build it","Agreed"],"affirm":"Plans both partners help build get more buy-in and last longer than ones imposed by one person.","relearn":"Build the money plan together; a shared plan is the one you both keep.","persona":"any","source":"build it together"},
  {"id":"mt-022","cat":"plan-together","type":"branch","persona":"Pooja","source":"both know","hook":"You realise only your partner Rakesh actually knows where all the money and documents are.","steps":[{"prompt":"You ask where the fixed deposit papers are, and Rakesh says he'll find them. What do you do?","options":[{"text":"Ask to sit together and go through everything once","then":"He agrees, and you set a quiet evening for it.","best":true},{"text":"Let it go since he clearly seems to have it under control","then":"It stays convenient for now, and a risk for later."},{"text":"Ask him to just write you a quick list some other time","then":"The list never quite gets written, and nothing really changes."},{"text":"Say you'll figure it out yourself if it's ever actually needed","then":"You'd be starting from nothing in an actual emergency."}],"why":"Sitting down together is what actually closes the gap, not a promise."},{"prompt":"Soon after, a bank form needs papers only Rakesh can find, so you sit down with them. What do you cover first?","options":[{"text":"The essentials: main accounts, nominees and key documents","then":"You both leave knowing enough to manage if you had to.","best":true},{"text":"Every single small account and subscription in careful detail","then":"The detail is thorough but takes so long you both lose steam."},{"text":"Just the accounts that happen to hold the most money","then":"It covers the big ones but misses documents you'd actually need."},{"text":"A rough verbal summary instead of writing anything down","then":"It feels done, but neither of you can recall it later."}],"why":"Covering the essentials clearly is what actually protects you both."},{"prompt":"A cousin asks why you're suddenly asking about the accounts. What do you say?","options":[{"text":"Say it's just sensible for both partners to know","then":"She nods, and it doesn't feel strange to her at all.","best":true},{"text":"Say you're worried that something might be wrong","then":"It plants a worry in her mind that isn't actually true."},{"text":"Say a wife shouldn't really need to track the money","then":"She agrees, and the idea that money is his department goes unchallenged."},{"text":"Say Rakesh insisted that you finally learn all of it","then":"It quietly frames it as his idea, not a shared choice."}],"why":"Naming it as ordinary and sensible keeps it a normal habit, not a red flag."},{"prompt":"Six months later, Rakesh renews the health insurance. What do you do?","options":[{"text":"Ask him to show you the new policy and where it's kept","then":"He shows you, and you both know exactly where it is.","best":true},{"text":"Assume it's the same as last year and leave it at that","then":"It probably is, but you couldn't find it in a hurry."},{"text":"Let him file it wherever he likes, the way it's always been","then":"The papers go back into a drawer only he knows about."},{"text":"Ask him to just send you a photo of it when you need it","then":"It works while he's around, and not when he isn't."}],"why":"Going over each change together is what keeps both of you in the know."}],"debrief":"Both partners should know the accounts and documents; sole knowledge is a risk, not a convenience.","relearn":"Both partners knowing the money protects the couple; sole control is a hidden risk."},
  {"id":"mt-023","type":"match","persona":"any","source":"plan for changes","hook":"Match a life change to the planning it calls for.","pairs":[{"left":"A new baby","right":"Budget for new costs and lower income"},{"left":"Buying a home","right":"A down-payment and EMI plan"},{"left":"A job loss","right":"Lean on the emergency fund"},{"left":"A wedding to fund","right":"A timed savings goal"},{"left":"A move to a new city","right":"Deposit and setup costs"}],"relearn":"Each life change, like a baby, a home, a job loss, a wedding, or a move, calls for the couple to re-plan together.","cat":"plan-together"},
  {"id":"mt-024","type":"spot","persona":"any","source":"resilient setup","hook":"Spot the two fragile parts of this couple's money setup.","scene":[{"id":"a","text":"An emergency fund of a few months' costs","trick":false},{"id":"b","text":"Everything riding on one income, no buffer","trick":true},{"id":"c","text":"Shared goals tracked together","trick":false},{"id":"d","text":"Only one partner knows the accounts","trick":true},{"id":"e","text":"Both partners can access the money","trick":false}],"why":"Everything on one income with no buffer, and only one partner knowing the accounts, are the fragile, risky parts.","relearn":"Resilience is a buffer and shared access; one income and sole knowledge are the fragile parts.","cat":"plan-together"},
  {"id":"mt-025","cat":"plan-together","type":"branch","persona":"Sneha","source":"both-and","hook":"You and your partner Aakash are settling into shared life, and you value having some money of your own.","steps":[{"prompt":"He suggests one joint account for everything. What do you say?","options":[{"text":"Propose a joint account for shared life, plus personal accounts","then":"He considers it, then agrees it sounds fair to both.","best":true},{"text":"Give in fully and keep absolutely nothing of your own","then":"It's simple now, but your own footing quietly disappears."},{"text":"Refuse to merge anything at all, even the shared costs","then":"He feels shut out of a shared plan you actually want too."},{"text":"Agree for now, quietly planning to reopen your own account later","then":"The unspoken plan sits there, and for now his setup goes ahead as suggested."}],"why":"A joint plus personal setup gives you shared goals and real autonomy."},{"prompt":"A few days later, you revisit the account setup together. What do you focus on?","options":[{"text":"Shared costs go joint; personal spending stays personal","then":"It's a clean, simple line, and you both understand it easily.","best":true},{"text":"Everything either of you spends should go through the joint account","then":"It's simple, but it quietly erases any personal spending room."},{"text":"Whatever feels shared in the moment, decided case by case","then":"Without a rule, small disagreements keep coming up again."},{"text":"Let him decide it, since he suggested merging first","then":"The line ends up drawn mostly around his own preferences."}],"why":"A clear, simple rule keeps the split fair without constant renegotiation."},{"prompt":"A friend says a proper couple keeps everything in one account. What do you say?","options":[{"text":"Say joint plus personal is a fair setup for couples","then":"She hadn't thought of it that way, and asks how that would work.","best":true},{"text":"Agree with her, and wonder if you've set it up wrongly","then":"You leave doubting the setup you have, and wondering what she sees that you don't."},{"text":"Say it's all perfect between you two, with no issues at all","then":"The easy answer skips over anything that isn't quite working."},{"text":"Say Aakash mostly handles the money side of things for you","then":"It hands him the credit, whatever your own part in it is."}],"why":"A fair setup needn't match anyone else's. Joint plus personal is a real, working choice."},{"prompt":"A year later, you're both saving comfortably. What do you check in on?","options":[{"text":"Whether the setup still feels fair and leaves room for each of you","then":"You talk it through, and tweak the setup so it fits you both.","best":true},{"text":"Whether to put every rupee into one account from now on","then":"It would be simpler, and it would leave neither of you room of your own."},{"text":"Whether one of you is saving noticeably better than the other","then":"It turns a simple check-in into a quiet comparison."},{"text":"Nothing at all, since the system seems to be working just fine","then":"Skipping the check-in means small changes go unnoticed."}],"why":"Checking the setup still fits you both keeps the balance working over time."}],"debrief":"You can share finances and keep some independence: propose joint plus personal accounts.","relearn":"Combine joint and personal accounts; sharing needn't surrender all autonomy."},
  {"id":"mt-026","cat":"plan-together","type":"reflect","hook":"Lensy: planning isn't about being rich, it's about being ready, together. Sit right?","prompt":"What's your take?","options":["Ready together","Sits right","Not about rich"],"affirm":"Financial planning is about readiness and teamwork, not wealth; any couple can start.","relearn":"Planning is about being ready together, not being rich; any couple can begin.","persona":"any","source":"ready not rich"},
  {"id":"mt-027","type":"sort","persona":"any","source":"fair with unequal income","hook":"Sort: a fair way to handle unequal incomes, or an unfair one?","items":[{"id":"a","text":"Splitting shared costs in proportion to income"},{"id":"b","text":"The lower earner going without essentials"},{"id":"c","text":"Both having personal spending money"},{"id":"d","text":"One partner controlling all the spending"},{"id":"e","text":"Agreeing the split openly together"},{"id":"f","text":"The top earner deciding it all alone"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Proportional splits, both having spending money and an open agreement are fair; deprivation and control aren't.","cat":"plan-together"},
  {"id":"mt-028","cat":"stay-independent","type":"strike-rewrite","hook":"\"In a marriage, one partner should handle all the money and the other stay out of it.\"","myth":{"un":"In a marriage, one partner should handle all the money and the other stay out of it.","re":"Both partners keeping financial literacy, access and some independence protects them both.","why":"Total dependence is a vulnerability, not a virtue."},"relearn":"Both partners staying financially literate and independent protects them; total dependence is a risk.","persona":"Pooja","source":"both stay involved"},
  {"id":"mt-029","cat":"stay-independent","type":"strike-rewrite","hook":"\"He handles the money because he earns it.\"","myth":{"un":"He handles the money because he earns it.","re":"Earning more doesn't grant control over a shared life's money; both partners have a say and a stake.","why":"Income isn't authority over the household."},"relearn":"Earning more isn't a licence to control the money; both partners have a say and a stake.","persona":"Reshma","source":"earning isn't control"},
  {"id":"mt-030","cat":"stay-independent","type":"sort","persona":"Reshma","source":"protect or erode","relearn":"Your own account, literacy and shared access protect independence; surrendering your salary, never knowing the finances and needing permission erode it.","hook":"Sort: protects your financial independence, or quietly erodes it?","items":[{"id":"a","text":"Keeping your own account"},{"id":"b","text":"Handing over your whole salary, no access"},{"id":"c","text":"Staying financially literate"},{"id":"d","text":"Never knowing the family finances"},{"id":"e","text":"Both knowing where the documents are"},{"id":"f","text":"Needing permission for every rupee"}],"bins":[{"id":"protects","label":"Protects independence","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"protects","b":"erodes","c":"protects","d":"erodes","e":"protects","f":"erodes"}},
  {"id":"mt-031","cat":"stay-independent","type":"strike-rewrite","hook":"\"A homemaker doesn't earn, so she has no real claim on the money.\"","myth":{"un":"A homemaker doesn't earn cash, so she has no real claim on the money.","re":"Running a home and raising children is unpaid economic work of huge value; her claim is equal, not lesser.","why":"Unpaid work is real economic contribution."},"relearn":"A homemaker's unpaid work has real economic value; her claim on the money is equal, not lesser.","persona":"Pooja","source":"homemaker's value"},
  {"id":"mt-032","cat":"stay-independent","type":"branch","persona":"Reshma","source":"own footing","hook":"You've drifted into having no money of your own, and it makes you uneasy.","steps":[{"prompt":"You notice you keep asking your husband before buying small things for yourself. What do you do?","options":[{"text":"Decide to open your own account and start saving a little","then":"It feels small, but it's the first step back toward your own footing.","best":true},{"text":"Tell yourself independence doesn't really matter since you trust him","then":"Trust is real, but it leaves you without any footing of your own."},{"text":"Wait until things feel a bit calmer to even think about it","then":"The uneasy feeling stays, unaddressed, week after week."},{"text":"Ask your husband to give you a bit more spending money each month","then":"It might help a little, though the money still starts and stays as his to give."}],"why":"Rebuilding some footing of your own is a safety net, whatever trust exists."},{"prompt":"A few weeks later, opening an account of your own comes to mind again. What do you do?","options":[{"text":"Go ahead and open it yourself, with your own documents","then":"The account is set up in your name, held by you alone.","best":true},{"text":"Ask your husband to come along and help with the whole process","then":"It's set up fine, though he still handles most of it for you."},{"text":"Put it off again, telling yourself you're still not ready","then":"The uneasy feeling nudges you forward, and a few weeks later you finally go open one."},{"text":"Ask a friend to open one for you instead","then":"It's opened, but it isn't really yours to control."}],"why":"Opening it yourself, in your own name, is what makes the footing real."},{"prompt":"A month in, a small amount has built up in the account. What do you do?","options":[{"text":"Keep adding a little each month, however small it is","then":"The habit steadies, and the account slowly stops feeling fragile.","best":true},{"text":"Stop adding, since the amount already feels like enough","then":"A small one-time deposit doesn't really build lasting footing."},{"text":"Move it all back into the shared account for convenience","then":"The footing you just built quietly disappears again."},{"text":"Spend it fairly quickly before anyone happens to notice it","then":"The account empties, and the safety net vanishes with it."}],"why":"Adding a little regularly is what turns one deposit into real footing."},{"prompt":"A while later, you see 181, a free helpline for women, on a poster at the clinic. What do you do?","options":[{"text":"Note the number somewhere private, to call when you want to talk","then":"It's saved where only you look, and it's there if you ever want to talk.","best":true},{"text":"Tell yourself it's only for women whose husbands are cruel","then":"You put the thought aside, and the number stays unsaved."},{"text":"Tell yourself you'd only be making a fuss over small things","then":"The doubt grows louder than the question you actually had."},{"text":"Wait until you're sure something is really wrong before calling","then":"Waiting to be certain keeps the question to yourself for another few weeks."}],"why":"You can reach 181 quietly, even when unsure. Wanting your own footing is never wrong or your fault."}],"debrief":"Keep some financial footing of your own. Trust is good, but footing is your safety net, and wanting it is never wrong.","relearn":"Build some footing of your own; trust plus a safety net beats trust alone."},
  {"id":"mt-033","cat":"stay-independent","type":"match","persona":"Reshma","source":"pillars of independence","relearn":"Your own account, financial literacy, savings, your own ID and a way back to earning are the pillars of personal financial independence.","hook":"Match each pillar of financial independence to what it gives you.","pairs":[{"left":"Your own account","right":"Money you can access freely"},{"left":"Financial literacy","right":"Understanding to decide for yourself"},{"left":"Some savings","right":"A cushion and real options"},{"left":"Your own ID and documents","right":"Proof of who you are, kept by you"},{"left":"A way back to earning","right":"Choices kept open for the future"}]},
  {"id":"mt-034","cat":"stay-independent","type":"reflect","hook":"Lensy: financial independence isn't distrust of your partner, it's respect for your own future self. Hear that?","prompt":"What do you think?","options":["I hear it","For my future self","Not distrust"],"affirm":"Keeping financial independence is self-respect and prudence, not a sign of distrusting your partner.","relearn":"Financial independence is respect for your future self, not distrust of your partner.","persona":"any","source":"not distrust"},
  {"id":"mt-035","cat":"stay-independent","type":"spot","persona":"Reshma","source":"what erodes independence","relearn":"Own-money access and shaping the finances keep you independent; needing permission for every rupee, and zero access, don't.","hook":"Spot the two lines that strip a partner's financial independence.","scene":[{"id":"a","text":"Access to their own money","trick":false},{"id":"b","text":"Needing permission for every rupee","trick":true},{"id":"c","text":"Knowing and shaping the finances","trick":false},{"id":"d","text":"No access to any account at all","trick":true},{"id":"e","text":"A say in where the money goes","trick":false}],"why":"Needing permission for every rupee and having no account access strip independence; own-money access and a say protect it."},
  {"id":"mt-036","cat":"stay-independent","type":"strike-rewrite","hook":"\"Asking your spouse for every small expense is just normal married life.\"","myth":{"un":"Asking your spouse for every small expense is just normal married life.","re":"Needing to ask permission for ordinary spending is a sign of lost autonomy, not normal partnership.","why":"Healthy couples both have spending freedom."},"relearn":"Needing permission for every small expense isn't normal; both partners should have spending freedom.","persona":"Reshma","source":"not normal"},
  {"id":"mt-037","cat":"stay-independent","type":"branch","persona":"Pooja","source":"protected choice","hook":"Your partner Sanjay suggests you stop working to manage the home, and you're torn.","steps":[{"prompt":"He brings it up gently over dinner. What do you do?","options":[{"text":"Say you'll decide together, and want to protect your footing either way","then":"He nods, glad it's a real conversation, not a decision made for you.","best":true},{"text":"Agree on the spot, honestly, just to keep things simple","then":"The decision is made before you've actually thought it through."},{"text":"Say you'll think about it, then avoid the topic for weeks","then":"The question hangs over every dinner, and he can't tell what you think."},{"text":"Ask his parents what they think you should do","then":"They have strong views, and the choice starts to feel less like yours."}],"why":"Making it a shared choice, with your footing protected, keeps the decision truly yours."},{"prompt":"Soon after, the two of you come back to the question of your work. What do you ask about first?","options":[{"text":"What staying home, or continuing to work, would each actually look like","then":"Talking it through, a real picture starts to form for both of you.","best":true},{"text":"What your friends and family would probably think of it","then":"Outside opinions crowd out what either of you actually wants."},{"text":"Whether Sanjay would be disappointed with you either way","then":"Managing his reaction becomes the focus, not the actual decision."},{"text":"How fast you can decide, so it's settled by the weekend","then":"Rushing to settle it skips the thinking the decision deserves."}],"why":"Picturing what each option actually looks like grounds the decision in reality."},{"prompt":"You lean toward pausing work for a while. What do you make sure to protect?","options":[{"text":"Your access to money, some savings, and a way back to work","then":"The pause feels like a choice, not a loss of everything you've built.","best":true},{"text":"Nothing in particular, since it's meant to be temporary anyway","then":"Temporary can stretch, and nothing protects you if it does."},{"text":"Just your savings alone, and let the rest go for now","then":"Access and re-entry quietly slip while savings alone aren't enough."},{"text":"Whatever Sanjay happens to think is reasonable to keep","then":"The protections end up shaped mostly by his comfort, not yours."}],"why":"Protecting access, savings and re-entry keeps the pause a real choice."},{"prompt":"A year later, you're ready to consider going back to work. What do you do?","options":[{"text":"Check what access and savings you have, and plan your way back","then":"Seeing what you have, the return starts to feel possible.","best":true},{"text":"Start entirely from scratch, since you stepped away for a while","then":"You ignore what you could build on, and it's harder than it needs to be."},{"text":"Ask Sanjay to decide whether it's really the right time","then":"It hands a decision about your own work back to him."},{"text":"Delay it further still, since restarting feels a bit daunting","then":"The longer gap makes the eventual restart feel even harder."}],"why":"Taking stock and planning your way back is what keeps the return open."}],"debrief":"If you pause paid work, make it a shared choice and protect your access, savings and way back.","relearn":"Whatever you decide about working, protect your access, savings and re-entry."},
  {"id":"mt-038","cat":"stay-independent","type":"reflect","hook":"Lensy: every adult deserves some money that's simply theirs, no permission needed. Agree?","prompt":"What's your take?","options":["Agree","Some of my own","Yes"],"affirm":"Having some money that's simply yours, no permission needed, is a basic part of adult autonomy.","relearn":"Every adult deserves some money that's simply theirs, no permission required.","persona":"any","source":"money that's yours"},
  {"id":"mt-039","cat":"stay-independent","type":"sort","persona":"any","source":"independence vs dependence","relearn":"Self-support, savings and shared access are healthy; zero access, needing approval and being barred from work are not.","hook":"Sort: a sign of healthy independence, or of unhealthy dependence?","items":[{"id":"a","text":"Both partners can support themselves if needed"},{"id":"b","text":"One partner has zero access to money"},{"id":"c","text":"Each keeps some personal savings"},{"id":"d","text":"One can't make any spend without approval"},{"id":"e","text":"Both share access to the accounts"},{"id":"f","text":"One is barred from working at all"}],"bins":[{"id":"healthy","label":"Healthy independence","valence":"pos"},{"id":"dependence","label":"Unhealthy dependence","valence":"neg"}],"key":{"a":"healthy","b":"dependence","c":"healthy","d":"dependence","e":"healthy","f":"dependence"}},
  {"id":"mt-040","cat":"stay-independent","type":"role-play","persona":"Razia","source":"calm clarity","hook":"At a family gathering, your aunt turns the talk to your salary. You want to answer with calm clarity.","setup":"She catches you by the dessert table.","steps":[{"prompt":"Your aunt says: \"A good wife hands over her whole salary. That's how it's done.\"","options":[{"text":"\"We plan our money together, and I keep my own footing too.\"","then":"She raises an eyebrow. \"Is that so? And your partner is fine with that?\"","best":true},{"text":"\"Maybe you're right. I should think about it.\"","then":"She nods. \"Good. That's how it should be.\""},{"text":"\"That's an old-fashioned way to think about it.\"","then":"Her face tightens. \"I was only trying to help.\""},{"text":"\"Let's not talk about money right now.\"","then":"She shrugs. \"Suit yourself. I was only saying.\""}],"why":"Naming your actual arrangement calmly answers without starting a fight."},{"prompt":"She adds: \"And the big decisions? Who makes those in your house?\"","options":[{"text":"\"We decide the big things together, as a team.\"","then":"She pauses. \"That sounds like a lot of talking.\"","best":true},{"text":"\"Honestly, he does, mostly.\"","then":"She nods. \"That's exactly how it should be.\""},{"text":"\"That's between us, not really your business.\"","then":"She stiffens. \"I was only asking.\""},{"text":"\"I suppose whoever earns more should decide.\"","then":"She smiles. \"Exactly what I always say.\""}],"why":"Naming shared decisions keeps your actual arrangement clear, not smoothed over."},{"prompt":"At the next family lunch, your uncle asks: \"Why keep your own account at all, now that you're married?\"","options":[{"text":"\"It's my own footing. We still plan the rest together.\"","then":"He chuckles. \"Fair enough, fair enough.\"","best":true},{"text":"\"We're still figuring that part out between us.\"","then":"He nods. \"Well, there's still time, I suppose.\""},{"text":"\"Can we not get into this at lunch?\"","then":"He shrugs. \"Fine, fine. For now.\""},{"text":"\"I suppose I could close it. It would be simpler.\"","then":"He beams. \"Now that's what I like to hear.\""}],"why":"Your own account is your footing, and saying so plainly shows it sits fine with planning together."}],"relearn":"Naming your shared-plan-plus-own-footing model calmly holds your autonomy without a fight."},
  {"id":"mt-041","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Managing money is a man's job; women aren't good with finances.\"","myth":{"un":"Managing money is a man's job; women aren't good with finances.","re":"Financial skill has nothing to do with gender; anyone can learn it, and both partners should.","why":"Money sense is learned, not gendered."},"relearn":"Managing money isn't a man's job; financial skill is learned, not gendered, and both partners should have it.","persona":"Pooja","source":"money isn't gendered"},
  {"id":"mt-042","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Whoever earns more should get the final say on all money decisions.\"","myth":{"un":"Whoever earns more should get the final say on all money decisions.","re":"A shared life's money decisions are shared; earning more is not a bigger vote.","why":"Partnership isn't priced by paycheque."},"relearn":"Earning more doesn't buy a bigger vote; shared-life money decisions are made together.","persona":"Karthik","source":"income isn't a vote"},
  {"id":"mt-043","cat":"fair-not-gendered","type":"sort","hook":"Sort: a fair basis for a money decision, or an unfair, gendered one?","items":[{"id":"a","text":"What you both agreed your goals are"},{"id":"b","text":"'He's the man, so he decides'"},{"id":"c","text":"Each partner's needs and the plan"},{"id":"d","text":"'She earns less, so she gets no say'"},{"id":"e","text":"What the budget can actually carry"},{"id":"f","text":"'Money is men's work, not hers'"}],"bins":[{"id":"fair","label":"Fair basis","valence":"pos"},{"id":"unfair","label":"Unfair / gendered","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Agreed goals, each partner's needs and what the budget can carry are fair bases; 'he's the man', 'she earns less' and 'money is men's work' are gendered ones.","persona":"any","source":"fair basis"},
  {"id":"mt-044","cat":"fair-not-gendered","type":"branch","persona":"Pooja","source":"rebalance the default","hook":"By default, your household has him handle all the money while you just ask for it when you need it.","steps":[{"prompt":"You notice it again when you need cash for something small. What do you do?","options":[{"text":"Say you'd like to understand and decide the finances together","then":"He looks a little surprised, then curious.","best":true},{"text":"Ask for the amount, like always, and quietly let it go","then":"The default holds, quietly, for one more day."},{"text":"Complain to a friend about it instead of to him directly","then":"It feels good to vent, but nothing at home actually shifts."},{"text":"Decide it's tradition and probably not worth disturbing","then":"Tradition keeps the imbalance comfortably unexamined."}],"why":"Asking to decide together, plainly, is how the default actually shifts."},{"prompt":"A few days later, money comes up again over dinner. What do you suggest?","options":[{"text":"Suggest sitting down monthly to look at everything, together","then":"He agrees, a little relieved not to carry it alone either.","best":true},{"text":"Say you're not sure, just 'more involved' somehow, generally","then":"The vague ask is easy to quietly forget."},{"text":"Say you'll just take over managing it all instead of him","then":"One default swaps for another, still only one person deciding."},{"text":"Say never mind. It's probably fine as it is, honestly","then":"The moment that opened a door lets it close again."}],"why":"A regular joint look at everything makes 'together' concrete, not vague."},{"prompt":"A month later, a cousin's wedding brings big gift and travel costs. What do you do?","options":[{"text":"Sit down with him and go through the whole budget together","then":"You both spot things about the household you hadn't known.","best":true},{"text":"Let him sort it out, since he knows the numbers better","then":"He sorts it, and the knowing stays on his side."},{"text":"Offer to cut your own spending to cover it","then":"He agrees, and only your habits get looked at."},{"text":"Wait for him to come up with a plan first","then":"Days pass, and he sorts it the usual way, alone."}],"why":"Going through the whole budget together is what rebalancing actually looks like."}],"debrief":"Rebalance gendered money defaults so both partners understand and decide together.","relearn":"Rebalance gendered money roles; 'tradition' is no reason to keep a partner in the dark."},
  {"id":"mt-045","cat":"fair-not-gendered","type":"match","hook":"Match a gendered money myth to the fair reality.","pairs":[{"left":"Men are naturally better with money","right":"Skill is learned, not gendered"},{"left":"The earner is the decider","right":"Shared money is decided together"},{"left":"Homemaking has no economic value","right":"Unpaid home work is real value"},{"left":"A wife needn't grasp finances","right":"Both partners should know the money"},{"left":"He's head, so he holds the cash","right":"A shared life pools, not rules"}],"relearn":"Skill is learned, decisions are shared, home work has value, both should know the money, and a shared life pools rather than rules.","persona":"any","source":"myth to reality"},
  {"id":"mt-046","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A stay-at-home partner is a dependent, not an equal.\"","myth":{"un":"A stay-at-home partner is a dependent, not an equal.","re":"A partner doing unpaid home and care work is an equal contributor whose work has real economic value.","why":"Equality isn't measured by who earns cash."},"relearn":"A stay-at-home partner is an equal contributor, not a dependent; unpaid work has real value.","persona":"Pooja","source":"equal not dependent"},
  {"id":"mt-047","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a fair home runs its money as a partnership of equals, whoever happens to earn the salary. Resonate?","prompt":"What do you think?","options":["Resonates","Equals","Whoever earns"],"affirm":"Fair money is run as an equal partnership regardless of who earns the salary.","relearn":"Fair money is an equal partnership, whoever earns the salary.","persona":"any","source":"partnership of equals"},
  {"id":"mt-048","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered red flags in how this home runs its money.","scene":[{"id":"a","text":"Both partners know and shape the budget","trick":false},{"id":"b","text":"Only the husband sees the accounts","trick":true},{"id":"c","text":"Decisions made by agreement, not gender","trick":false},{"id":"d","text":"'Investing is a man's job, not yours'","trick":true},{"id":"e","text":"Both names are on the savings goal","trick":false}],"why":"'Only the husband sees the accounts' and 'investing is a man's job' are the gendered flags; the rest are fair.","relearn":"Fair money means both see and shape it; one partner seeing the accounts or 'investing is a man's job' are gendered flags.","persona":"any","source":"fair arrangement"},
  {"id":"mt-049","cat":"fair-not-gendered","type":"branch","persona":"Sneha","source":"both count","hook":"Your partner earns more and starts treating your smaller income as not counting.","steps":[{"prompt":"He makes an offhand comment that your paycheque is 'pocket money' next to his. What do you do?","options":[{"text":"Say plainly that both contributions count, not just the bigger","then":"He looks a little startled, not meaning it as sharply as it landed.","best":true},{"text":"Laugh it off, since it's probably just a joke, honestly","then":"The joke sits there, and the framing quietly takes hold."},{"text":"Stop mentioning your income at all after that comment","then":"Your voice in money talk gets a little smaller too."},{"text":"Match it with a comment about something he's bad at","then":"It scores a point, but the actual issue stays unaddressed."}],"why":"Naming that both contributions count answers the comment directly."},{"prompt":"A week later, a decision comes up and he moves ahead without really asking you. What do you do?","options":[{"text":"Say your voice in decisions doesn't shrink with your income","then":"He pauses, connecting it back to the earlier comment.","best":true},{"text":"Go along with it, since he's more invested financially here","then":"The pattern the comment started keeps quietly building."},{"text":"Bring up every past decision he's made without you around","then":"It turns into a long list, and the current point gets buried."},{"text":"Say nothing at all, but feel resentful about it privately","then":"The resentment stays private, and so does the actual problem."}],"why":"A smaller income doesn't mean a smaller voice in decisions."},{"prompt":"That weekend, he asks how you feel about the way you two decide on money. What do you say?","options":[{"text":"Say you'd like decisions to include both of you from now on","then":"He nods. \"Fair. Let's decide things together.\"","best":true},{"text":"Say it's fine, since he probably doesn't mean anything by it","then":"He's relieved, and the next decision goes the same way."},{"text":"Say he should just always ask first, no exceptions ever","then":"He bristles at 'no exceptions ever', and the talk stalls."},{"text":"Suggest whoever pays more for something decides it","then":"He likes it, and his bigger income quietly gets the bigger vote."}],"why":"Naming what you want going forward turns a comment into a real shift."}],"debrief":"Both partners' contributions count; a smaller income doesn't mean a smaller voice.","relearn":"Insist both contributions count; a smaller income isn't a smaller say."},
  {"id":"mt-050","cat":"fair-not-gendered","type":"match","hook":"Match each partner role to its real contribution.","pairs":[{"left":"The salary earner","right":"Cash income for the household"},{"left":"The homemaker","right":"Unpaid home and care work of real value"},{"left":"Both together","right":"A team running a shared life"},{"left":"The lower earner","right":"A full and equal say in the plan"},{"left":"The one who tracks bills","right":"Order that keeps the money working"}],"relearn":"The earner, homemaker, the team, the lower earner and the bill-tracker each make a real contribution; none is 'lesser'.","persona":"any","source":"real contributions"},
  {"id":"mt-051","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"It's fine for only the husband to know the family's full finances.\"","myth":{"un":"It's fine for only the husband to know the family's full finances.","re":"Both partners knowing the full picture is fairer and safer; one-sided knowledge creates dependence and risk.","why":"Shared knowledge is shared power and safety."},"relearn":"Both partners should know the full finances; one-sided knowledge creates unfair dependence and risk.","persona":"Reshma","source":"shared knowledge"},
  {"id":"mt-052","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: fair money isn't about who earns it, it's about how openly and equally you run it. Clear?","prompt":"What's your take?","options":["Clear","How you run it","Not who earns"],"affirm":"Fairness in money is about running it openly and equally, not about who earns the most.","relearn":"Fair money is about running it openly and equally, not who earns it.","persona":"any","source":"how not who"},
  {"id":"mt-053","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Controlling all the household money is just being a responsible head of family.\"","myth":{"un":"Controlling all the household money is just being a responsible head of family.","re":"Controlling a partner's access to money, with allowances and cut-offs, is economic abuse, a recognised form of domestic violence.","why":"Control over money is control over a person."},"relearn":"Controlling a partner's money through allowances and cut-offs is economic abuse, recognised domestic violence.","persona":"Reshma","source":"control is abuse"},
  {"id":"mt-054","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Economic abuse isn't real domestic violence because no one gets hit.\"","myth":{"un":"Economic abuse isn't real domestic violence because no one gets hit.","re":"Indian law recognises economic abuse, denying money, assets or access, as domestic violence under the PWDVA 2005.","why":"Harm without bruises is still abuse."},"relearn":"Economic abuse is recognised domestic violence under the PWDVA 2005, even with no physical violence.","persona":"Reshma","source":"economic abuse is DV"},
  {"id":"mt-055","cat":"control-is-abuse","type":"sort","hook":"Sort: a fair shared-money arrangement, or a sign of economic abuse?","items":[{"id":"a","text":"Agreeing a budget together"},{"id":"b","text":"A tiny allowance you must account for"},{"id":"c","text":"Both having access to money"},{"id":"d","text":"Stopped from working or having an account"},{"id":"e","text":"Each keeping personal money"},{"id":"f","text":"Salary handed over, access blocked"}],"bins":[{"id":"fair","label":"Fair arrangement","valence":"pos"},{"id":"abuse","label":"Economic abuse","valence":"neg"}],"key":{"a":"fair","b":"abuse","c":"fair","d":"abuse","e":"fair","f":"abuse"},"relearn":"Agreed budgets, shared access and personal money are fair; policed allowances, barred work and seized salary are abuse.","persona":"Reshma","source":"fair or abuse"},
  {"id":"mt-056","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: the signs of economic abuse hiding in 'normal' married life.","scene":[{"id":"a","text":"Being denied money for basic needs","trick":true},{"id":"b","text":"Jointly planning the monthly budget","trick":false},{"id":"c","text":"Having your salary taken and access blocked","trick":true},{"id":"d","text":"Both partners knowing the balances","trick":false},{"id":"e","text":"Each keeping a little personal money","trick":false}],"why":"Denial of money for basics and having your salary taken are economic abuse; planning, shared visibility and personal money are healthy.","relearn":"Denying basics and seizing a partner's salary or access are economic abuse, not budgeting.","persona":"Reshma","source":"spot economic abuse"},
  {"id":"mt-057","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"A wife's gold and gifts, her stridhan, belong to her husband or in-laws.\"","myth":{"un":"A wife's gold and gifts, her stridhan, belong to her husband or in-laws.","re":"Stridhan is a woman's own property by law; taking or withholding it is wrong and can be economic abuse.","why":"Her property is hers, full stop."},"relearn":"Stridhan is a woman's own property by law; taking or withholding it is wrong and can be economic abuse.","persona":"Razia","source":"stridhan is hers"},
  {"id":"mt-058","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"name and reach out","hook":"Your partner has cut off your access to money and forbids you from working.","steps":[{"prompt":"He tells you the cut-off is final and walks off. What do you do first?","options":[{"text":"Quietly name it as economic abuse, not normal marriage","then":"Naming it clearly steadies you, though nothing outside has changed yet.","best":true},{"text":"Tell yourself he's just stressed about money right now","then":"The excuse buys him time, and the lock on your access stays the same."},{"text":"Wonder if you brought this on by spending carelessly","then":"The doubt turns inward, though the cut-off was his choice."},{"text":"Believe him: a wife doesn't need money of her own","then":"The belief settles in, though it never quite felt true."}],"why":"Naming it truthfully, even privately, is the first real step toward help."},{"prompt":"A few days later he takes your phone to check something and keeps it. What do you do?","options":[{"text":"Save a trusted number once it's back, where he can't see it","then":"A small flicker of control returns to your own hands.","best":true},{"text":"Confront him at once about taking your phone from you","then":"He turns defensive, and the phone stays with him even longer."},{"text":"Tell yourself checking on you is just his way of caring","then":"The thought quiets things for now, and nothing about the lock changes."},{"text":"Take a friend's word that most husbands go through this phase","then":"Her words make it sound ordinary, and nothing changes at home."}],"why":"A hidden trusted number is a small, safe step toward real help."},{"prompt":"A month on, you finally get a few private minutes alone. What do you do?","options":[{"text":"Call a women's helpline to learn your options and rights","then":"A calm voice listens and lays out real, safe next steps.","best":true},{"text":"Believe family troubles must never leave the home","then":"The belief keeps the phone in your lap, and the minutes run out."},{"text":"Decide to wait for a clearer sign before doing anything","then":"The moment passes, and the waiting starts to feel endless."},{"text":"Tell yourself you can manage this alone, like always","then":"You close the window without using it, and the isolation holds."}],"why":"A helpline gives you real options and rights, not more waiting."}],"debrief":"Cutting off money and forbidding work is economic abuse. Name it and seek help. It is not your fault.","relearn":"Cutting off money and barring work is abuse. Name it and reach for help, not silence."},
  {"id":"mt-059","cat":"control-is-abuse","type":"match","hook":"Match each India help route to when it's for.","pairs":[{"left":"Women Helpline 181","right":"Talk through abuse or immediate danger"},{"left":"Emergency 112","right":"You're in immediate danger now"},{"left":"PWDVA 2005 protection & relief","right":"Legal remedy for economic abuse"},{"left":"NALSA free legal aid 15100","right":"Free legal help on your rights"},{"left":"Respect at Home + a counsellor","right":"Naming and planning around abuse"}],"relearn":"181 to talk, 112 for danger, the PWDVA's protection and relief, NALSA 15100 for legal aid, and Respect at Home plus a counsellor are real routes.","persona":"Reshma","source":"help routes"},
  {"id":"mt-060","cat":"control-is-abuse","type":"reflect","hook":"Lensy: open planning is teamwork; controlling a partner's money is abuse. The line is the difference. Clear?","prompt":"What do you think?","options":["Clear","That's the line","Get help then"],"affirm":"The line between teamwork and abuse is control: planning together is healthy; controlling a partner's money is abuse.","relearn":"Planning money together is teamwork; controlling a partner's money is abuse.","persona":"Reshma","source":"the line"},
  {"id":"mt-061","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"If you depend on someone financially, you have no right to complain about control.\"","myth":{"un":"If you depend on someone financially, you have no right to complain about control.","re":"Financial dependence never justifies control or abuse; everyone has the right to dignity and safety.","why":"Dependence doesn't cancel rights."},"relearn":"Financial dependence never justifies control; everyone keeps the right to dignity, safety and help.","persona":"Reshma","source":"dependence isn't consent"},
  {"id":"mt-062","cat":"control-is-abuse","type":"branch","persona":"Razia","source":"believe and inform","hook":"A friend says her husband gives her vegetable money and demands the change back, tracking every rupee.","steps":[{"prompt":"She tells you this quietly, looking embarrassed. What do you do first?","options":[{"text":"Listen fully and say this sounds like control, not care","then":"She relaxes a little, relieved someone finally named it.","best":true},{"text":"Say that's just how careful, protective husbands are","then":"She nods and swallows the feeling that something is wrong."},{"text":"Offer to go speak to her husband about it yourself","then":"She looks alarmed and asks you not to get involved."},{"text":"Quietly change the subject so she doesn't feel worse","then":"The moment passes, and she's left holding it alone."}],"why":"Naming it as control, gently, tells her she isn't imagining things."},{"prompt":"A week later she brings it up again, unsure if she's overreacting. What do you do?","options":[{"text":"Reassure her she isn't imagining it, and it's not her fault","then":"She exhales, like she's been holding her breath for weeks.","best":true},{"text":"Tell her every marriage needs some give and take","then":"She goes quiet, unsure whether to trust her own read of things."},{"text":"Ask her exactly how much money he gives her, to judge for yourself","then":"She feels quizzed rather than heard, and says less."},{"text":"Suggest she just ask him for more money","then":"The ask misses the real issue, which isn't the amount."}],"why":"Believing her, without quizzing her, is what she needs right now."},{"prompt":"She asks quietly what she could even do about it. What do you tell her?","options":[{"text":"Share that help and her rights exist, at whatever pace she's ready for","then":"She writes it down, glad to have real options, not orders.","best":true},{"text":"Tell her firmly she should leave him this week","then":"She flinches, not ready for a timeline she didn't choose."},{"text":"Say it's really only her choice, and leave it there","then":"She's left with the weight, and nothing concrete to hold onto."},{"text":"Suggest she just manage it quietly to avoid more trouble","then":"The family's image stays intact, and so does the control."}],"why":"Sharing real routes, at her pace, gives her something a bare 'it's your choice' doesn't."}],"debrief":"Policing every rupee is economic control, and never her fault. Name it gently and share that help and rights exist.","relearn":"Naming financial control and offering help beats calling it 'just how marriage works'."},
  {"id":"mt-063","cat":"control-is-abuse","type":"reflect","hook":"Lensy: needing financial help to leave or to rebuild is never your shame; it's exactly what support exists for. Hear it?","prompt":"What's your take?","options":["I hear it","Not my shame","Thank you"],"affirm":"Needing financial support to leave or rebuild is what help exists for; it is never a personal failing.","relearn":"Needing financial help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"not your shame"},
  {"id":"mt-064","cat":"control-is-abuse","type":"sort","hook":"Sort: handle within the couple, or this needs outside help now?","items":[{"id":"a","text":"Disagreeing about a big purchase"},{"id":"b","text":"Being financially cut off and isolated"},{"id":"c","text":"Different saving styles"},{"id":"d","text":"Threats tied to money or stridhan"},{"id":"e","text":"A one-off overspend to talk through"},{"id":"f","text":"Being barred from leaving home with any money"}],"bins":[{"id":"couple","label":"Handle as a couple","valence":"pos"},{"id":"help","label":"Needs help now","valence":"uhoh"}],"key":{"a":"couple","b":"help","c":"couple","d":"help","e":"couple","f":"help"},"relearn":"Purchase disagreements, saving styles and one-off overspends are couple-level; being cut off, isolated, threatened or trapped needs help now.","persona":"Reshma","source":"couple or help"},
  {"id":"mt-065","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"the structure","hook":"You want a simple structure to keep your money fair and open over time.","steps":[{"prompt":"You sit down together for the first time to plan it out. What do you do?","options":[{"text":"Set up a joint account, a personal one each, and a shared goal","then":"You leave the evening with a simple plan you both understand.","best":true},{"text":"Agree to keep it loose and adjust as you go","then":"Nothing's written down, and the plan starts to blur within weeks."},{"text":"Let whoever's better with numbers set it up alone","then":"One of you understands the plan, and the other nods along."},{"text":"Decide to revisit it once you're both less busy","then":"Busy keeps happening, and the structure never quite forms."}],"why":"A joint plus personal setup with a shared goal turns fairness into a habit."},{"prompt":"A month in, you take stock of how the money side is actually going. What do you do?","options":[{"text":"Pick a short, regular time to check in each month","then":"You agree on a ten-minute Sunday chat, and it sticks.","best":true},{"text":"Say you'll check in only if something feels off","then":"Small issues quietly build with no set time to raise them."},{"text":"Assume the structure is enough on its own","then":"The plan runs on autopilot, and drift goes unnoticed."},{"text":"Wait for your partner to suggest a check-in first","then":"Neither of you brings it up, and the habit never starts."}],"why":"A set check-in time is what keeps a good structure from quietly drifting."},{"prompt":"Six months on, your partner asks what you think of how it's all working. What do you say?","options":[{"text":"Suggest looking at it together and fixing what's slipped","then":"You spend an evening on it, and the plan fits your life better.","best":true},{"text":"Say it's fine, without really thinking about it","then":"They take that at face value, and nothing gets looked at."},{"text":"Say it was more effort than it was worth","then":"They look deflated, and neither of you tends to it after that."},{"text":"Tell them to adjust whatever they think needs changing","then":"They tweak it alone, and you're less sure how it all works."}],"why":"Reviewing it together, honestly, keeps the structure working instead of quietly drifting."}],"debrief":"A light structure, joint plus personal accounts, a shared goal, a monthly check-in, keeps money fair.","relearn":"Build a light money structure; vagueness lets fairness drift."},
  {"id":"mt-066","cat":"tools-and-help","type":"match","hook":"Match each tool to the job it does.","pairs":[{"left":"The money talk","right":"Open the topic safely"},{"left":"Joint + personal accounts","right":"Share goals, keep autonomy"},{"left":"The help routes","right":"When money becomes control"},{"left":"The monthly check-in","right":"Keep fairness on track"},{"left":"The emergency fund","right":"A cushion for shocks"}],"relearn":"The money talk, the both-accounts setup and the help routes are the core tools of fair, safe money.","persona":"any","source":"the toolkit"},
  {"id":"mt-067","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"the check-in","hook":"It's your monthly money check-in. You want to keep it light and collaborative.","setup":"It's Sunday morning, and you both have tea in hand.","steps":[{"prompt":"Your partner asks: \"So, how do you want to start today?\"","options":[{"text":"\"Quick check-in: how's the goal, and does the split still feel fair?\"","then":"They relax. \"Sounds good. Let's start with the goal.\"","best":true},{"text":"\"We really need to go through everything you spent this month.\"","then":"They tense up. \"Alright, if you think that's needed.\""},{"text":"\"Let's just skip it this month, honestly. Nothing's really changed.\"","then":"\"Sure, if you're sure nothing's up,\" they say."},{"text":"\"Tell me if there's anything I should know about.\"","then":"\"Okay, let me think of anything first,\" they say."}],"why":"Framing it around the goal and fairness keeps the check-in a team effort."},{"prompt":"They say: \"The goal's on track, but I'm a bit stretched by the rent split.\"","options":[{"text":"\"Let's look at the split together and see what'd feel fairer.\"","then":"\"Thanks, that would help a lot,\" they say.","best":true},{"text":"\"It's the same split as always. Should be fine.\"","then":"\"Okay, I suppose it'll sort itself out,\" they say."},{"text":"\"You should have brought this up sooner.\"","then":"\"I'm bringing it up now, aren't I?\" they say."},{"text":"\"Let's talk about it another time, when things are less busy.\"","then":"\"Sure, whenever you're ready,\" they say."}],"why":"Working the split out together is what turns a worry into a fix."},{"prompt":"Next month, they open with: \"Same time as usual?\"","options":[{"text":"\"Yes, let's keep going. These check-ins are worth it.\"","then":"\"Agreed, glad we're keeping it up,\" they say.","best":true},{"text":"\"Maybe we can skip a few months. Things feel stable.\"","then":"\"If you think that's fine, sure,\" they say."},{"text":"\"Sure, though I don't think we need it every time.\"","then":"\"Alright, we'll see how it goes,\" they say."},{"text":"\"I suppose so, if you think it's necessary.\"","then":"\"I do, but only if you're keen too,\" they say."}],"why":"Keeping the rhythm going is what makes the check-in actually protective."}],"relearn":"A light, goal-and-fairness framed check-in keeps money collaborative instead of accusatory."},
  {"id":"mt-068","cat":"tools-and-help","type":"sort","hook":"Sort: a money habit that protects the couple, or one that quietly harms it?","items":[{"id":"a","text":"Regular open check-ins"},{"id":"b","text":"Hiding spending from each other"},{"id":"c","text":"Both keeping financial literacy"},{"id":"d","text":"One partner controlling all access"},{"id":"e","text":"Each keeping some personal money"},{"id":"f","text":"Barring a partner from working"}],"bins":[{"id":"protect","label":"Protective habit","valence":"pos"},{"id":"harm","label":"Harmful habit","valence":"neg"}],"key":{"a":"protect","b":"harm","c":"protect","d":"harm","e":"protect","f":"harm"},"relearn":"Open check-ins, shared literacy and personal money protect the couple; hiding, control and work-barring harm it.","persona":"any","source":"protect or harm"},
  {"id":"mt-069","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's nothing you can do to make money fair; it just depends on who earns.\"","myth":{"un":"There's nothing you can do to make money fair; it just depends on who earns.","re":"Fair money is built with tools, open talks, shared goals, both-accounts and check-ins, whatever the incomes.","why":"Fairness is designed, not inherited."},"relearn":"Fair money is built with tools and talks, whatever the incomes; it isn't fixed by who earns.","persona":"any","source":"fairness is built"},
  {"id":"mt-070","cat":"tools-and-help","type":"reflect","hook":"Lensy: open + planned + both-independent + control-free. That's the whole money-together formula. Got it?","prompt":"What do you think?","options":["Got it","The formula","Let's do it"],"affirm":"Open, planned, both-independent and control-free is the formula for fair, healthy couple finances.","relearn":"The money-together formula: open, planned, both independent, and free of control.","persona":"any","source":"the formula"},
  {"id":"mt-071","cat":"tools-and-help","type":"branch","persona":"Reshma","source":"reach out unsure","hook":"You're unsure whether a money pattern at home is unfair or actually abusive.","steps":[{"prompt":"You notice you're always short on cash despite your own income. What do you do?","options":[{"text":"Call 181 or a counsellor. You don't have to be sure to ask","then":"The counsellor listens without judging, and helps you think it through.","best":true},{"text":"Wait until you're certain, alone","then":"The uncertainty sits with you, unresolved, for weeks."},{"text":"Wait for a friend to confirm it's abuse before getting help","then":"Your friend can't say for sure, so getting help keeps waiting."},{"text":"Assume it's probably just how your household happens to run","then":"You talk yourself out of the worry, though it doesn't go away."}],"why":"You can seek help while unsure. You needn't be certain first."},{"prompt":"A week later, your salary account balance is lower than expected again. What do you do?","options":[{"text":"Note dates and amounts somewhere only you can see","then":"Having it written down, safely, makes the pattern clearer to you.","best":true},{"text":"Let it go, assuming you miscounted","then":"The same thing happens again the next month."},{"text":"Ask your partner directly what happened to it","then":"The conversation turns tense, and you don't get a clear answer."},{"text":"Stop checking the account altogether","then":"The bank app sits unopened, and the same questions pile up unanswered."}],"why":"A private record of what you notice turns a vague worry into something clear to act on."},{"prompt":"You call 181 and they ask what's been happening. What do you say?","options":[{"text":"Describe the pattern plainly, even without being sure it's abuse","then":"They listen closely and help you sort what's happening from what's normal.","best":true},{"text":"Say you're probably overreacting","then":"They gently ask you to say more anyway, so you do."},{"text":"Say it can't really be abuse, since he's never hit you","then":"They explain that controlling money can be abuse too, and ask you to go on."},{"text":"Say you're not sure it's worth their time","then":"They reassure you it is, and ask you to go on."}],"why":"Describing it plainly, unsure or not, is what actually gets you real help."},{"prompt":"Afterwards, a friend asks how the call went. What do you say?","options":[{"text":"Say it helped to talk it through, whatever it turns out to be","then":"Your friend is glad you reached out, and asks how you're feeling now.","best":true},{"text":"Say you probably shouldn't have called","then":"Your friend isn't sure how to respond to that."},{"text":"Say you'll only call again once you have real proof","then":"Your friend nods, and the next worry waits until you feel sure enough."},{"text":"Say it's a family matter you shouldn't have taken outside","then":"Your friend goes quiet, unsure whether to ask about it again."}],"why":"Naming that reaching out helped keeps the door open to ask again if needed."}],"debrief":"You can seek help while unsure whether money trouble is unfair or abusive. It's never your fault, and you needn't be certain first.","relearn":"Seek help while unsure; you don't have to be certain it's abuse to reach out."},
  {"id":"mt-072","cat":"tools-and-help","type":"match","hook":"Match a money moment to the tool that fits it.","pairs":[{"left":"Starting shared life","right":"Have the money talk"},{"left":"A big upcoming cost","right":"Set a shared, timed goal"},{"left":"Signs of control","right":"Reach out to 181 or a counsellor"},{"left":"Staying fair over time","right":"A monthly check-in"},{"left":"Wanting your rights","right":"Reach NALSA 15100"}],"relearn":"Each money moment has a tool: the talk, the shared goal, the check-in, or a help route when there's control.","persona":"Reshma","source":"moment to tool"},
  {"id":"mt-073","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that aren't sustainable money, just crisis reactions.","scene":[{"id":"a","text":"Small, regular, honest check-ins","trick":false},{"id":"b","text":"One dramatic audit when trust breaks","trick":true},{"id":"c","text":"Both staying informed and independent","trick":false},{"id":"d","text":"Only talking money after a blow-up","trick":true},{"id":"e","text":"Updating the goal as life changes","trick":false}],"why":"A one-off audit and talking only after a blow-up are crisis reactions; regular honesty is sustainable.","relearn":"Sustainable money is regular honesty and shared independence, not one crisis audit or blow-up talks.","persona":"Pooja","source":"sustainable money"},
  {"id":"mt-074","cat":"tools-and-help","type":"reflect","hook":"Lensy: you've got the talk, the plan, your own footing, and the help routes. Money, together, sorted? ","prompt":"What's your take?","options":["Sorted","I've got this","Ready"],"affirm":"With the money talk, a shared plan, personal footing and help routes, a couple can run money fairly and safely.","relearn":"You hold the money-together toolkit: the talk, the plan, your footing, and the help routes.","persona":"any","source":"toolkit complete"},
  {"id":"mt-075","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"one principle","hook":"You want one principle to carry into every money decision as a couple.","steps":[{"prompt":"You're setting up your first joint account together. What guides the decision?","options":[{"text":"Plan together, keep both independent, get help if control appears","then":"You both agree on the account setup in one calm conversation.","best":true},{"text":"Let whoever earns more decide the split","then":"The higher earner's preference quietly becomes the default."},{"text":"Copy whatever your parents did","then":"It doesn't quite fit your own situation, but you go with it anyway."},{"text":"Decide it later, once you both see how things actually go","then":"Weeks pass without an actual account being opened."}],"why":"One clear principle gives you a compass instead of guessing each time."},{"prompt":"A big cost comes up, your sister's wedding gift. What guides the decision?","options":[{"text":"Plan it together as a shared, timed goal","then":"You both add a little each month, and the cost stops feeling sudden.","best":true},{"text":"Let the higher earner cover it and settle up later","then":"'Settling up later' quietly never happens."},{"text":"Split it evenly without discussing amounts","then":"One of you feels the pinch more than the other."},{"text":"Wait until closer to the date to figure it out","then":"You scramble for the amount at the last minute."}],"why":"The same principle, planning together, works just as well for a big one-off cost."},{"prompt":"A relative later hints that the higher earner should just decide these things. What do you say?","options":[{"text":"Say you plan money decisions together, as a rule","then":"The relative shrugs, and the conversation moves on.","best":true},{"text":"Say it mostly works out that way anyway, most of the time","then":"It sounds like the relative's assumption was right."},{"text":"Laugh it off without really answering","then":"The comment goes unanswered, and it may well return."},{"text":"Agree it would be simpler that way","then":"The idea of shared decisions quietly loses ground."}],"why":"Naming the principle out loud is what keeps it as your actual practice, not just an ideal."}],"debrief":"One principle carries it: plan together, keep both independent, and get help if control creeps in.","relearn":"Lead with open and fair; defaulting to the top earner rebuilds the imbalance."},
  {"id":"mt-076","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"set the tone","hook":"You and your partner are newly married and have never really sat down to discuss money.","setup":"Tonight, over chai, she brings it up.","steps":[{"prompt":"She asks: \"So how do you want to handle money between us?\"","options":[{"text":"\"Let's plan it openly, both keep our own footing, and decide the big stuff together.\"","then":"She smiles. \"I like that. Where do we start?\"","best":true},{"text":"\"Let's just deal with it whenever something comes up.\"","then":"\"Okay, I suppose that works too,\" she says."},{"text":"\"I'll mostly handle it, and you can ask me anything.\"","then":"\"Alright, if that's easier for you,\" she says."},{"text":"\"Whatever you think is best, honestly.\"","then":"\"I was hoping you'd have an idea too,\" she says."}],"why":"Naming an open, both-independent tone sets a clear shared starting point."},{"prompt":"A few days later, she raises it again: \"Where should we actually start with this?\"","options":[{"text":"\"Let's set up joint and personal accounts, and a shared goal.\"","then":"\"Good. Let's open them this week,\" she says.","best":true},{"text":"\"Let's just see how the month goes first.\"","then":"\"Okay, we'll revisit it later then,\" she says."},{"text":"\"You look into the options, and I'll approve whatever you pick.\"","then":"\"Alright, I'll look into it,\" she says."},{"text":"\"Let's not overthink it. We'll figure it out.\"","then":"\"Sure, whenever it comes up naturally,\" she says."}],"why":"A concrete first step turns the shared tone into an actual plan."},{"prompt":"A few weeks later, she checks: \"Are we still doing the money thing we talked about?\"","options":[{"text":"\"Let's pick a monthly day, starting this week.\"","then":"\"Good. Let's look at the calendar,\" she says.","best":true},{"text":"\"We've been busy. Let's pick it up soon.\"","then":"\"Okay, let me know when,\" she says."},{"text":"\"I've mostly been handling it. It's fine.\"","then":"\"Oh. I thought we were doing it together,\" she says."},{"text":"\"Honestly, I forgot about that.\"","then":"\"That's alright. Let's start now then,\" she says."}],"why":"Fixing an actual day is what turns an intention into a habit."}],"relearn":"Setting a shared, open, both-independent tone beats lurching from one money surprise to the next."},
  {"id":"mt-077","cat":"plan-together","type":"role-play","persona":"Karthik","source":"shared goal talk","hook":"You want to set your first shared savings goal with your partner Priya without it feeling like a chore.","setup":"You bring it up over the weekend.","steps":[{"prompt":"Priya asks: \"A savings goal? Sounds like homework.\"","options":[{"text":"\"Let's pick one goal we both care about, with a small monthly amount.\"","then":"She smiles. \"Okay, that actually sounds fun.\"","best":true},{"text":"\"I'll just decide how much we save each month myself.\"","then":"\"Oh,\" she says, sounding less interested already."},{"text":"\"It's important. Honestly, we should just go ahead and do it.\"","then":"She agrees, though it still feels like an obligation to her."},{"text":"\"Never mind. We can just skip it for now.\"","then":"The idea drops for now, though Priya brings it up again a few days later."}],"why":"Framing a goal you both care about makes saving feel shared, not assigned."},{"prompt":"A few days later, Priya asks: \"So, are we still doing a savings goal or not?\"","options":[{"text":"\"What's something you'd genuinely love for us to save for?\"","then":"\"A weekend trip,\" she says, brightening at the thought.","best":true},{"text":"\"I already have something in mind, honestly, so let's go with that.\"","then":"She goes along with it, though it wasn't really her idea."},{"text":"\"Whatever's most practical, I guess, nothing fancy.\"","then":"The goal ends up vague, and neither of you feels pulled toward it."},{"text":"\"Let's just save without naming anything specific for now.\"","then":"Without a name, the goal is easy to quietly forget."}],"why":"Asking what she'd love makes the goal genuinely shared, not assigned."},{"prompt":"Priya asks: \"How do we make sure this doesn't just fizzle out?\"","options":[{"text":"\"Let's check in on it together, lightly, each month.\"","then":"\"I'd like that,\" she says, already looking forward to the first one.","best":true},{"text":"\"I'll keep track myself and let you know how it's going.\"","then":"\"Sure,\" she says, though it puts the follow-through on you alone."},{"text":"\"We'll just know if it's working, I think, honestly.\"","then":"Without checking in, it's easy for the habit to quietly slip."},{"text":"\"Let's not make it too formal. That would ruin it.\"","then":"The goal stays a nice idea without quite becoming a habit."}],"why":"A light, shared check-in is what keeps a goal from fizzling out."}],"relearn":"Framing a goal you both care about, with a small agreed amount, makes saving a shared project, not an order."},
  {"id":"mt-078","cat":"stay-independent","type":"role-play","persona":"Pooja","source":"stay across it","hook":"Your partner is kind and wants to spare you any money stress. You value that, but want to stay involved.","setup":"You answer warmly, not defensively.","steps":[{"prompt":"He says: \"Let me just handle all of it. You don't need to worry about the money.\"","options":[{"text":"\"Thank you. I'd like to stay across it too, so we're both equal.\"","then":"He smiles. \"Fair enough. I like that plan better anyway.\"","best":true},{"text":"\"Okay, you handle it all then.\"","then":"He nods. \"Good, one less thing for you to think about.\""},{"text":"\"That's sweet, but I don't need the details.\"","then":"He shrugs. \"If you're sure, I don't mind either way.\""},{"text":"\"Are you sure you want that much responsibility?\"","then":"He laughs. \"I don't mind at all, really.\""}],"why":"Welcoming the offer while staying involved keeps your footing without rejecting his care."},{"prompt":"A few weeks later, he mentions: \"The money's been ticking along fine, by the way.\"","options":[{"text":"\"I appreciate that. Can you walk me through this month's numbers?\"","then":"He pulls up the numbers. \"Sure, glad you asked.\"","best":true},{"text":"\"Yes, it's such a relief.\"","then":"He grins. \"See? Nothing for you to worry about.\""},{"text":"\"I trust you completely with it.\"","then":"He smiles. \"That trust means a lot to me.\""},{"text":"\"Maybe I should look at it myself sometime, once things settle down.\"","then":"He nods. \"Sure, sometime, whenever you like.\""}],"why":"Asking to see the actual numbers turns good intentions into real involvement."},{"prompt":"Months later, a friend asks: \"So who keeps track of the money in your house?\"","options":[{"text":"\"It should be both of us. I'll ask for a monthly look together.\"","then":"\"Good idea. Tell me how it goes,\" your friend says.","best":true},{"text":"\"He does, and he's good with it.\"","then":"\"I'd want to know more, if it were me,\" your friend says."},{"text":"\"I try not to think about it, honestly.\"","then":"\"That sounds like it'd worry me,\" your friend says."},{"text":"\"He does, and honestly, I don't feel I need to know any of it.\"","then":"\"If that works for you, fair enough,\" your friend says."}],"why":"A regular look at the numbers together keeps you involved, not just hopeful."}],"relearn":"Welcoming the help while staying involved keeps your literacy and footing without rejecting their care."},
  {"id":"mt-079","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered moves; the rest treat both partners as equals.","scene":[{"id":"a","text":"Both names on accounts and decisions","trick":false},{"id":"b","text":"Only the man's name on everything","trick":true},{"id":"c","text":"A say for the homemaker too","trick":false},{"id":"d","text":"'You needn't know, just ask me for cash'","trick":true},{"id":"e","text":"Goals set by both, not by who earns","trick":false}],"why":"'Only the man's name on everything' and 'you needn't know, just ask me' are the gendered moves; the rest treat both as equals.","relearn":"Equal money means both names, a homemaker's say and shared goals, not one name on everything or 'just ask me for cash'.","persona":"Pooja","source":"equal setup"},
  {"id":"mt-080","cat":"fair-not-gendered","type":"role-play","persona":"Karthik","source":"team sport","hook":"A relative likes to joke about who should handle the money in your family.","setup":"At a family lunch, he leans back, grinning.","steps":[{"prompt":"He laughs: \"Investments, accounts, all that, best left to the men, no?\"","options":[{"text":"\"In our home money's a team sport. We both learn it.\"","then":"He chuckles, a bit unsure how to follow that up.","best":true},{"text":"\"Haha, yeah, I handle all that stuff.\"","then":"\"There you go,\" he says, satisfied his joke landed."},{"text":"\"That's a pretty old-fashioned thing to say, actually.\"","then":"He gets defensive. \"I was just joking around.\""},{"text":"\"She's actually better at it than I am.\"","then":"He raises his eyebrows. \"Really? Now that's a surprise.\""}],"why":"A light, plain 'team sport' answers the joke without a real fight."},{"prompt":"He turns to you: \"So does she actually understand all the investment stuff?\"","options":[{"text":"\"We're learning it together. That's the plan.\"","then":"He nods. \"Huh. Both of you, then.\"","best":true},{"text":"\"Not really. I handle most of the details for us.\"","then":"\"Thought so,\" he says, looking pleased."},{"text":"\"More than you'd think, for a beginner.\"","then":"He smirks. \"For a beginner, sure.\""},{"text":"\"Why does that actually matter to you so much?\"","then":"His grin fades. \"Just asking. No need to get touchy.\""}],"why":"Saying you're learning it together answers him plainly, and includes her."},{"prompt":"Later, he asks you quietly: \"Seriously, why should a wife bother with investments?\"","options":[{"text":"\"So neither of us is stuck if the other can't do it.\"","then":"He thinks about that. \"Fair. My mother was stuck like that.\"","best":true},{"text":"\"It's her hobby, really. It keeps her busy in the evenings.\"","then":"\"A hobby. That makes sense,\" he says."},{"text":"\"It's not a big deal. Please don't mention it again.\"","then":"He shrugs, and the question hangs there unanswered."},{"text":"\"Very modern of us, right? That's just how we are.\"","then":"He laughs. \"Modern, sure. But why, though?\""}],"why":"Naming the real reason, so no one is ever stuck, makes the point land beyond a joke."}],"relearn":"A light, clear 'money's a team sport here' corrects the gendered joke without a confrontation."},
  {"id":"mt-081","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: which money setups are control dressed as care.","scene":[{"id":"a","text":"\"I'll protect you from money worries\": no access","trick":true},{"id":"b","text":"Sharing the budget so both feel secure","trick":false},{"id":"c","text":"\"Let me handle it\" to block all your access","trick":true},{"id":"d","text":"Both partners knowing where the money is","trick":false},{"id":"e","text":"Keeping a little money that's simply yours","trick":false}],"why":"'Protecting' you with no access and 'let me handle it' as a block are control dressed as kindness; shared budgets are care.","relearn":"Control can wear the mask of care; denying all access isn't protection, it's control.","persona":"Reshma","source":"control as care"},
  {"id":"mt-082","cat":"control-is-abuse","type":"branch","persona":"Razia","source":"support safely","hook":"Your sister can't access money and is afraid; you want to help without worsening it.","steps":[{"prompt":"She calls you crying, unsure if she should even be talking about it. What do you do?","options":[{"text":"Listen fully and say you believe her and it's not her fault","then":"Her voice steadies, just from being believed.","best":true},{"text":"Tell her to calm down and stop overreacting","then":"She apologises and goes quiet, swallowing the fear again."},{"text":"Say you'll call her husband right now to sort it out","then":"She begs you not to, afraid of what happens after you hang up."},{"text":"Tell her to just manage and not cause family trouble","then":"She hears that her safety matters less than the family's image."}],"why":"Believing her steadies her more than any advice right now."},{"prompt":"The next day she asks if her wedding gold is really still hers. What do you say?","options":[{"text":"Confirm gently that her stridhan is hers by right, always","then":"Something in her posture loosens, like she's stood on firmer ground.","best":true},{"text":"Say you're not sure and she should just ask her in-laws","then":"She's left unsure again, with nowhere solid to stand."},{"text":"Tell her not to worry about gold when there are bigger problems","then":"Her real fear gets brushed aside instead of answered."},{"text":"Say it technically belongs to the family now","then":"Her face falls, and she stops asking about the gold at all."}],"why":"Confirming her stridhan is hers gives her one solid, true fact."},{"prompt":"She asks what to do next, scared of making it worse. What do you offer?","options":[{"text":"Quietly share help routes and offer to go with her, at her pace","then":"She isn't alone with it anymore, and nothing is rushed.","best":true},{"text":"Tell her she has to leave right now for her own good","then":"She pulls back, frightened by a pace she didn't choose."},{"text":"Say you'll handle it for her so she doesn't have to","then":"She's protected from the problem, but not given any say in it."},{"text":"Tell her to wait until she's completely certain it's serious","then":"The waiting stretches on, and so does the fear."}],"why":"Sharing routes at her own pace respects her, and keeps her safe."}],"debrief":"Support someone under financial control: believe her, say it's never her fault, and quietly share rights and help.","relearn":"Believe and quietly inform her; don't tell her to just manage."},
  {"id":"mt-083","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that wrongly delay help when money turns from unfair into controlling.","scene":[{"id":"a","text":"Reaching out to 181 or a counsellor","trick":false},{"id":"b","text":"Waiting silently until it's unbearable","trick":true},{"id":"c","text":"Naming it and learning your rights","trick":false},{"id":"d","text":"Telling yourself you must be sure first","trick":true},{"id":"e","text":"Reaching NALSA 15100 about your rights","trick":false}],"why":"Waiting in silence and demanding certainty first delay help; reaching out and learning your rights don't.","relearn":"When money turns controlling, reach out and learn your rights early, don't wait in silence.","persona":"Reshma","source":"first move"},
  {"id":"mt-084","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"the ritual","hook":"You want to agree a simple monthly money ritual with your partner that keeps things fair and open.","setup":"It's a lazy Sunday, and you've both got a free hour.","steps":[{"prompt":"Your partner asks: \"What kind of ritual did you have in mind?\"","options":[{"text":"\"Once a month, ten minutes, the goal, the split, anything either of us is worried about?\"","then":"They nod. \"That sounds manageable. Let's try it.\"","best":true},{"text":"\"We'll talk about money whenever there's an actual problem.\"","then":"\"Sure, whenever something comes up then,\" they say."},{"text":"\"Maybe once a year, to keep it simple.\"","then":"\"Sounds fine. Less to remember,\" they say."},{"text":"\"Whenever it comes up naturally, I suppose.\"","then":"\"Okay, no fixed time then,\" they say."}],"why":"A short, regular time is easy to keep and catches issues early."},{"prompt":"The next time money comes up, they ask: \"Who keeps track of what we decide?\"","options":[{"text":"\"Both of us. Let's keep a shared note we can both see.\"","then":"\"Good idea. I'll start one now,\" they say.","best":true},{"text":"\"You're better at that sort of thing. You keep track.\"","then":"\"Okay, but then you'll have to ask me,\" they say."},{"text":"\"We'll remember. No need to write anything down.\"","then":"\"Sure, if you think we'll remember,\" they say."},{"text":"\"I'll keep track, and tell you whatever you need to know.\"","then":"\"Oh. Alright, if you want to,\" they say."}],"why":"A shared note you both keep means neither of you holds the picture alone."},{"prompt":"A few months in, your partner asks: \"Honestly, are these money talks worth the time?\"","options":[{"text":"\"Yes. A short, regular one stops small things from growing.\"","then":"\"Fair enough. Let's put the next one in the calendar,\" they say.","best":true},{"text":"\"Maybe every couple of months would be enough.\"","then":"\"Sure. Less to fit in,\" they say."},{"text":"\"Not really. We only need to talk when something's wrong.\"","then":"\"Okay. We'll wait for a problem, then,\" they say."},{"text":"\"If you'd rather not bother with it, that's fine with me too.\"","then":"\"Let's leave it for now, then,\" they say."}],"why":"A short, regular talk keeps money open before small things grow."}],"relearn":"A short, regular, agreed ritual keeps money open and fair before problems build, not only after."},
  {"id":"mt-900","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He gives me a fixed allowance and I report every spend. That's just good housekeeping.\"","myth":{"un":"He gives me a fixed allowance and I report every spend. That's just good housekeeping.","re":"A policed allowance you must justify rupee by rupee isn't housekeeping; it's economic abuse, a form of domestic violence.","why":"A budget is agreed; an allowance is rationed power."},"relearn":"A tiny allowance you must account for to the rupee is economic abuse, not housekeeping.","persona":"Reshma","source":"allowance not housekeeping"},
  {"id":"mt-901","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"My salary credits to his account so the family stays disciplined. That's normal.\"","myth":{"un":"My salary credits to his account so the family stays disciplined. That's normal.","re":"Your salary is yours; routing it away so you can't touch it is seizing your income, a form of economic abuse.","why":"Discipline never needs to lock you out of your own pay."},"relearn":"Your salary is yours; diverting it so you can't access it is economic abuse, not discipline.","persona":"Pooja","source":"salary seized"},
  {"id":"mt-902","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He keeps all my documents and bank cards safe with him. That's caring.\"","myth":{"un":"He keeps all my documents and bank cards safe with him. That's caring.","re":"Holding all your ID, cards and papers so you can't act alone isn't safekeeping; it's control, a form of economic abuse.","why":"Care leaves your own access intact, not locked away."},"relearn":"Holding all your documents and cards so you can't act is control, not safekeeping.","persona":"Reshma","source":"documents withheld"},
  {"id":"mt-903","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"In-laws taking my wedding gold to 'keep it secure' is just family tradition.\"","myth":{"un":"In-laws taking my wedding gold to 'keep it secure' is just family tradition.","re":"Your wedding gold is your stridhan, yours by law; taking or withholding it against your will can be economic abuse.","why":"Tradition can't override a woman's right to her own property."},"relearn":"Your wedding gold is your stridhan; taking it against your will can be economic abuse.","persona":"Razia","source":"gold taken tradition"},
  {"id":"mt-904","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He stopped me from taking that job because a wife shouldn't work. It's his right as husband.\"","myth":{"un":"He stopped me from taking that job because a wife shouldn't work. It's his right as husband.","re":"Barring a partner from working to keep her dependent isn't a husband's right; it's economic abuse.","why":"Marriage is not ownership of someone's earning future."},"relearn":"Barring a partner from working to keep her dependent is economic abuse, not a husband's right.","persona":"Reshma","source":"barred from work"},
  {"id":"mt-905","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Running up loans in my name without telling me is fine since we're married.\"","myth":{"un":"Running up loans in my name without telling me is fine since we're married.","re":"Putting debt in your name without consent, or ruining your credit to trap you, is economic abuse.","why":"Marriage isn't permission to sign your future away."},"relearn":"Taking loans in your name without consent to trap you is economic abuse.","persona":"Razia","source":"coerced debt"},
  {"id":"mt-906","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He sabotages my work, like hiding my phone or making scenes, but that's just jealousy, not abuse.\"","myth":{"un":"He sabotages my work, like hiding my phone or making scenes, but that's just jealousy, not abuse.","re":"Sabotaging a partner's job to cut off her income is economic abuse, whatever the excuse.","why":"Wrecking your livelihood is harm, not love."},"relearn":"Sabotaging a partner's work to cut her income is economic abuse, not jealousy.","persona":"Pooja","source":"work sabotage"},
  {"id":"mt-907","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"A homemaker has no money of her own, so being controlled is just her situation.\"","myth":{"un":"A homemaker has no money of her own, so being controlled is just her situation.","re":"A homemaker's unpaid work is real value; she's an equal partner, and controlling her access is still economic abuse.","why":"No income doesn't mean no rights to the shared money."},"relearn":"A homemaker is an equal partner; controlling her money access is still economic abuse.","persona":"Reshma","source":"homemaker still abused"},
  {"id":"mt-908","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"It can't be abuse if he never raises a hand and we look happy to everyone.\"","myth":{"un":"It can't be abuse if he never raises a hand and we look happy to everyone.","re":"Economic abuse is recognised domestic violence under the PWDVA 2005, with no blow needed and no outward sign.","why":"A calm face outside doesn't undo control inside."},"relearn":"Economic abuse is recognised domestic violence under PWDVA 2005, even with no violence and a happy front.","persona":"Reshma","source":"invisible abuse"},
  {"id":"mt-909","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He withholds money for my medicine until I 'behave'. That's just him teaching me.\"","myth":{"un":"He withholds money for my medicine until I 'behave'. That's just him teaching me.","re":"Denying money for essentials to punish or control you is economic abuse, not teaching.","why":"Your health is not a lever for obedience."},"relearn":"Withholding money for essentials to control you is economic abuse, not discipline.","persona":"Reshma","source":"essentials withheld"},
  {"id":"mt-910","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Reporting economic abuse means breaking the family, so I should just bear it.\"","myth":{"un":"Reporting economic abuse means breaking the family, so I should just bear it.","re":"Seeking help and your rights under the PWDVA 2005 is your safety, not breaking a family.","why":"Naming harm protects you; it isn't what broke the home."},"relearn":"Seeking help for economic abuse protects you; it isn't what breaks a family.","persona":"Razia","source":"not breaking family"},
  {"id":"mt-911","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He earns more, so he gets to decide every rupee and I get none. That's only fair.\"","myth":{"un":"He earns more, so he gets to decide every rupee and I get none. That's only fair.","re":"Earning more doesn't grant control over a shared life's money; both partners have a say and a stake.","why":"A higher salary buys no licence over another person."},"relearn":"Earning more never grants sole control of the money; both partners have a say and a stake.","persona":"Karthik","source":"earner decides flip"},
  {"id":"mt-912","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Asking my husband's permission for every small purchase is just respect.\"","myth":{"un":"Asking my husband's permission for every small purchase is just respect.","re":"Needing permission for ordinary spending isn't respect; every adult deserves some money that's simply theirs.","why":"Respect runs both ways; control runs one."},"relearn":"Needing permission for ordinary spending isn't respect; every adult deserves money that's simply theirs.","persona":"Pooja","source":"permission not respect"},
  {"id":"mt-913","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He says I'm bad with money, so it's safer he controls all of it.\"","myth":{"un":"He says I'm bad with money, so it's safer he controls all of it.","re":"Calling a partner hopeless to justify taking total control is a tactic of economic abuse, not safety.","why":"Put-downs that grab the purse are control wearing concern."},"relearn":"Belittling a partner to seize total money control is a tactic of economic abuse.","persona":"Reshma","source":"belittle to control"},
  {"id":"mt-914","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He gives me a card but watches every transaction and questions each one. That's transparency.\"","myth":{"un":"He gives me a card but watches every transaction and questions each one. That's transparency.","re":"Surveilling and interrogating your every spend to control you is economic abuse, not transparency.","why":"Shared visibility is mutual; surveillance points one way."},"relearn":"Monitoring and interrogating your every spend to control you is economic abuse, not transparency.","persona":"Pooja","source":"surveillance not transparency"},
  {"id":"mt-915","cat":"control-is-abuse","type":"sort","hook":"Sort each money move: a fair shared arrangement, or a sign of economic abuse?","items":[{"id":"a","text":"Agreeing a monthly budget together"},{"id":"b","text":"Being made to hand over your whole salary"},{"id":"c","text":"Both knowing the passwords and balances"},{"id":"d","text":"Being barred from opening an account"},{"id":"e","text":"Each keeping some personal money"},{"id":"f","text":"Card confiscated as punishment"}],"bins":[{"id":"fair","label":"Fair arrangement","valence":"pos"},{"id":"abuse","label":"Economic abuse","valence":"neg"}],"key":{"a":"fair","b":"abuse","c":"fair","d":"abuse","e":"fair","f":"abuse"},"relearn":"Agreed budgets, shared visibility and personal money are fair; seized salary, blocked accounts or confiscated cards are abuse.","persona":"Reshma","source":"fair or abuse six"},
  {"id":"mt-916","cat":"control-is-abuse","type":"sort","hook":"Sort: a couple can work this out, or it needs outside help now?","items":[{"id":"a","text":"Disagreeing on how much to save"},{"id":"b","text":"Being financially cut off and isolated"},{"id":"c","text":"Different views on lending to relatives"},{"id":"d","text":"Threats tied to your money or stridhan"},{"id":"e","text":"A one-off overspend to talk through"},{"id":"f","text":"Being stopped from leaving the house with cash"}],"bins":[{"id":"couple","label":"Work out as a couple","valence":"pos"},{"id":"help","label":"Needs help now","valence":"uhoh"}],"key":{"a":"couple","b":"help","c":"couple","d":"help","e":"couple","f":"help"},"relearn":"Saving and lending disagreements are couple-level; being cut off, threatened or trapped needs help now.","persona":"Reshma","source":"couple or help six"},
  {"id":"mt-917","cat":"control-is-abuse","type":"sort","hook":"Sort each line a controlling partner says: honest care, or control in disguise?","items":[{"id":"a","text":"\"Let's plan this big spend together\""},{"id":"b","text":"\"You don't need an account, I'll handle it all\""},{"id":"c","text":"\"Here's the password, it's our money\""},{"id":"d","text":"\"Prove what you did with every rupee\""},{"id":"e","text":"\"Keep some money just for yourself\""},{"id":"f","text":"\"Your family's gold is mine to keep now\""}],"bins":[{"id":"care","label":"Honest care","valence":"pos"},{"id":"control","label":"Control in disguise","valence":"neg"}],"key":{"a":"care","b":"control","c":"care","d":"control","e":"care","f":"control"},"relearn":"Planning together and shared access are care; blocking accounts, policing rupees and seizing stridhan are control.","persona":"Reshma","source":"care or control lines"},
  {"id":"mt-918","cat":"control-is-abuse","type":"sort","hook":"Sort: which of these is your right by law, and which is a partner's false claim?","items":[{"id":"a","text":"Your wedding gold (stridhan) is yours"},{"id":"b","text":"\"After marriage your salary belongs to me\""},{"id":"c","text":"You can hold your own bank account"},{"id":"d","text":"\"A wife has no claim on family money\""},{"id":"e","text":"You can seek protection from economic abuse"},{"id":"f","text":"\"Only the earner gets a say in spending\""}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"false","label":"False claim","valence":"neg"}],"key":{"a":"right","b":"false","c":"right","d":"false","e":"right","f":"false"},"relearn":"Your stridhan, your own account and protection from abuse are real rights; 'your salary is mine' and 'no claim' are false.","persona":"Razia","source":"right or false claim"},
  {"id":"mt-919","cat":"control-is-abuse","type":"sort","hook":"Sort each tactic: an early warning sign of control, or an ordinary money habit?","items":[{"id":"a","text":"Asking to split rent fairly"},{"id":"b","text":"Cutting you off from friends who'd help"},{"id":"c","text":"Sharing a budgeting app you both use"},{"id":"d","text":"Insisting all earnings funnel to him"},{"id":"e","text":"Saving together for a shared goal"},{"id":"f","text":"Tracking you whenever you spend"}],"bins":[{"id":"habit","label":"Ordinary habit","valence":"pos"},{"id":"warning","label":"Warning sign","valence":"uhoh"}],"key":{"a":"habit","b":"warning","c":"habit","d":"warning","e":"habit","f":"warning"},"relearn":"Splitting fairly and shared saving are ordinary; isolating you, funnelling earnings and tracking spending are warning signs.","persona":"Reshma","source":"warning or habit"},
  {"id":"mt-920","cat":"control-is-abuse","type":"sort","hook":"Sort: which step rebuilds your footing, and which keeps you stuck?","items":[{"id":"a","text":"Quietly opening an account only you reach"},{"id":"b","text":"Handing over your last savings for peace"},{"id":"c","text":"Saving a small private emergency fund"},{"id":"d","text":"Destroying your own ID so you can't leave"},{"id":"e","text":"Talking to a counsellor about options"},{"id":"f","text":"Vowing never to tell anyone"}],"bins":[{"id":"footing","label":"Rebuilds footing","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"footing","b":"stuck","c":"footing","d":"stuck","e":"footing","f":"stuck"},"relearn":"Your own account, a private fund and a counsellor rebuild footing; surrendering savings, destroying ID or vowing silence keep you stuck.","persona":"Reshma","source":"footing or stuck"},
  {"id":"mt-921","cat":"control-is-abuse","type":"sort","hook":"Sort each remedy under the PWDVA 2005: real legal relief, or a myth about it?","items":[{"id":"a","text":"A protection order can be sought"},{"id":"b","text":"\"Only physical injury counts\""},{"id":"c","text":"Monetary relief for the harm is possible"},{"id":"d","text":"\"You must leave home to get any help\""},{"id":"e","text":"You can stay in the shared home (residence right)"},{"id":"f","text":"\"It only applies if you are formally married\""}],"bins":[{"id":"real","label":"Real relief","valence":"pos"},{"id":"myth","label":"Myth about it","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Protection orders, monetary relief and residence rights are real PWDVA relief; 'only injury counts' and 'must leave home' are myths.","persona":"Razia","source":"pwdva real or myth"},
  {"id":"mt-922","cat":"control-is-abuse","type":"sort","hook":"Sort: handle it together as partners, or this is control to name and route to help?","items":[{"id":"a","text":"Choosing between two phone plans"},{"id":"b","text":"Given just enough for one meal a day"},{"id":"c","text":"Debating a holiday budget"},{"id":"d","text":"Your wages collected by his mother"},{"id":"e","text":"Splitting a surprise gift's cost"},{"id":"f","text":"Forbidden money you don't beg for"}],"bins":[{"id":"together","label":"Handle together","valence":"pos"},{"id":"control","label":"Control: get help","valence":"uhoh"}],"key":{"a":"together","b":"control","c":"together","d":"control","e":"together","f":"control"},"relearn":"Phone plans, holiday budgets and shared gifts are couple-level; rationing food money, seizing wages and forced begging are control.","persona":"Reshma","source":"together or control"},
  {"id":"mt-923","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: lines where 'looking after the money' is really control.","scene":[{"id":"a","text":"\"Let's set the budget together this month\"","trick":false},{"id":"b","text":"\"You don't need a card; ask me for every rupee\"","trick":true},{"id":"c","text":"\"Here's the account login, it's ours\"","trick":false},{"id":"d","text":"\"Account for every paisa or no money next week\"","trick":true},{"id":"e","text":"\"Keep something aside that's just yours\"","trick":false}],"why":"Blocking access and rationing money are control; shared budgets, logins and personal money are care.","relearn":"'Ask me for every rupee' and 'account for every paisa' are control, not managing money.","persona":"Reshma","source":"spot control five"},
  {"id":"mt-924","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags in how 'protecting' a wife can hide economic abuse.","scene":[{"id":"a","text":"\"I keep all your documents safe\": out of your reach","trick":true},{"id":"b","text":"\"Let's both know where the papers are kept\"","trick":false},{"id":"c","text":"\"I cancelled your job offer to spare you stress\"","trick":true},{"id":"d","text":"\"Take the job; we'll manage childcare\"","trick":false},{"id":"e","text":"\"Your stridhan stays yours, always\"","trick":false}],"why":"Locking away your papers and killing your job 'for your good' are control; shared knowledge and stridhan are care.","relearn":"'Protection' that locks away your documents or cancels your job is economic abuse.","persona":"Reshma","source":"spot protection abuse"},
  {"id":"mt-925","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: early signs a money habit is turning into control.","scene":[{"id":"a","text":"He asks to split bills fairly each month","trick":false},{"id":"b","text":"He stops you seeing friends who could help","trick":true},{"id":"c","text":"He shares the savings goal openly","trick":false},{"id":"d","text":"He routes every rupee you earn to his account","trick":true},{"id":"e","text":"He suggests you both keep personal money","trick":false}],"why":"Isolating you and funnelling all your earnings to him are control signs; fair splits and shared goals are not.","relearn":"Cutting you off from people and routing all your earnings to him are early signs of control.","persona":"Pooja","source":"spot early signs"},
  {"id":"mt-926","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: claims a controlling partner makes that the law does not back.","scene":[{"id":"a","text":"\"Your wedding gold is your stridhan, it's yours\"","trick":false},{"id":"b","text":"\"After marriage your salary belongs to me\"","trick":true},{"id":"c","text":"\"You're allowed your own bank account\"","trick":false},{"id":"d","text":"\"A wife has no claim on family money\"","trick":true},{"id":"e","text":"\"You can seek protection from money control\"","trick":false}],"why":"'Your salary is mine' and 'no claim' are false; stridhan, your own account and protection are real rights.","relearn":"'Your salary belongs to me' and 'a wife has no claim' are false; stridhan and account are yours.","persona":"Razia","source":"spot false legal claims"},
  {"id":"mt-927","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags in a 'caring' offer to manage everything for you.","scene":[{"id":"a","text":"\"Tell me what you spend and I'll note it\"","trick":false},{"id":"b","text":"\"You'll never worry. Just never touch money\"","trick":true},{"id":"c","text":"\"Let's review the budget on Sundays\"","trick":false},{"id":"d","text":"\"I froze your account so you can't slip up\"","trick":true},{"id":"e","text":"\"Your salary is yours; let's plan joint costs\"","trick":false}],"why":"Total lockout dressed as 'never worry' and freezing your account are control; shared notes and your salary are care.","relearn":"'Never touch money' and freezing your account aren't protection. They're control.","persona":"Reshma","source":"spot care mask"},
  {"id":"mt-928","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: which money behaviours are economic abuse, not strictness.","scene":[{"id":"a","text":"Setting a savings target you both agreed","trick":false},{"id":"b","text":"Withholding medicine money until you 'behave'","trick":true},{"id":"c","text":"Tracking expenses together in one notebook","trick":false},{"id":"d","text":"Putting loans in your name without telling you","trick":true},{"id":"e","text":"Talking before any big purchase","trick":false}],"why":"Withholding essentials to punish you and secret debt in your name are abuse; shared targets and talks are not.","relearn":"Withholding medicine money and hidden loans in your name are abuse, not strict budgeting.","persona":"Reshma","source":"spot abuse not strictness"},
  {"id":"mt-929","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: when a joint family's money customs cross into control.","scene":[{"id":"a","text":"In-laws and couple plan the festival budget together","trick":false},{"id":"b","text":"His mother collects your full salary monthly","trick":true},{"id":"c","text":"Everyone knows where the papers are kept","trick":false},{"id":"d","text":"You beg in-laws for fare to see your parents","trick":true},{"id":"e","text":"Costs are split openly among earners","trick":false}],"why":"Collecting your whole salary and forcing you to beg for basics are control; shared planning and open splits are not.","relearn":"In-laws seizing your salary or making you beg for basics is control, not custom.","persona":"Razia","source":"spot joint family control"},
  {"id":"mt-930","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags: moves that quietly keep someone trapped, not safe.","scene":[{"id":"a","text":"Quietly opening an account only she can reach","trick":false},{"id":"b","text":"Telling her to hand over savings 'for peace'","trick":true},{"id":"c","text":"Saving a small private emergency fund","trick":false},{"id":"d","text":"Convincing her to hide it all from everyone","trick":true},{"id":"e","text":"Sharing the help numbers with her gently","trick":false}],"why":"Pushing her to surrender savings and stay silent keep her trapped; her own account, a fund and help routes free her.","relearn":"Surrendering savings 'for peace' and silence keep someone trapped; footing and help free them.","persona":"Reshma","source":"spot trapped not safe"},
  {"id":"mt-931","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"name your own situation","hook":"Your partner controls all the money, watches every spend, and you have nothing of your own.","steps":[{"prompt":"He questions a small purchase again, the way he always does. What do you do?","options":[{"text":"Quietly name it to yourself as control, not carefulness","then":"The label feels strange, and true, even though nothing changes yet.","best":true},{"text":"Believe him that questioning every rupee is just being careful","then":"The belief holds for tonight, and the watching continues exactly the same."},{"text":"Take a friend's word that every husband checks the spending","then":"Her words make it sound ordinary, and the watching goes on."},{"text":"Decide you must just be bad with money","then":"Self-doubt quietly takes the blame that isn't yours to carry."}],"why":"Naming it as control, not carefulness, is the honest first step."},{"prompt":"Your aunt, the one you've always trusted, visits and gently asks how you really are. What do you say?","options":[{"text":"Tell her honestly that nothing is your own anymore","then":"She takes your hand and says you can call her anytime.","best":true},{"text":"Say everything's fine, since home matters stay at home","then":"The comfortable answer keeps the truth hidden a little longer."},{"text":"Joke that he's just very organised with money","then":"The joke lands, and the real weight of it goes unspoken."},{"text":"Say he's the earner, so it's only right he decides","then":"She nods slowly, and the moment to say more slips by."}],"why":"Letting a trusted person in, even a little, means you aren't alone with it."},{"prompt":"A week later, you spend an afternoon at your aunt's, away from home. What do you do?","options":[{"text":"Borrow her phone to call 181 and learn your options","then":"A calm voice explains your rights, and nothing is rushed.","best":true},{"text":"Decide it's normal since most couples argue about money","then":"The comparison talks you out of a problem that's still there."},{"text":"Believe asking for outside help would betray him","then":"The afternoon passes pleasantly, and you go home with nothing new."},{"text":"Wait until you're completely sure before doing anything","then":"The certainty you're waiting for keeps slipping further away."}],"why":"Learning your options and rights helps. None of this is your fault."}],"debrief":"Controlling all the money and watching every spend is economic abuse. It is never your fault. Name it and learn your options.","relearn":"Name money control and learn your rights; don't normalise it or blame yourself."},
  {"id":"mt-932","cat":"control-is-abuse","type":"branch","persona":"Pooja","source":"keep salary footing","hook":"Your partner insists your whole salary be credited to his account 'for the family'.","steps":[{"prompt":"He brings it up again at dinner, like it's already settled. What do you do?","options":[{"text":"Say your salary stays in your name, and propose a fair joint pool","then":"He pauses, surprised you have a counter plan ready.","best":true},{"text":"Believe your pay belongs in his account for the family's sake","then":"The belief ends tonight's argument, and the plan for his account stands."},{"text":"Believe he'll let it drop once work calms down","then":"It doesn't drop. He brings a form to sign the next week."},{"text":"Believe a partial compromise will satisfy him just as well","then":"It feels like a compromise, but he still wants the whole salary."}],"why":"Keeping your own account and proposing a shared pool protects you both fairly."},{"prompt":"Soon after, he says a family runs on trust and asks if you trust him with the money. What do you do?","options":[{"text":"Say trust and a shared, visible pool aren't opposites","then":"He thinks about that, and doesn't have a quick answer.","best":true},{"text":"Wonder if a good wife would just hand it over","then":"The doubt sits heavy, and his question hangs unanswered."},{"text":"Get defensive and list every reason you don't trust him","then":"He shuts down, hearing an accusation instead of a request."},{"text":"Take a colleague's word that pay always ends up with the husband","then":"The remark sounds like common wisdom, and the old plan stays in place."}],"why":"A visible shared pool builds trust. It doesn't question it."},{"prompt":"His mother mentions that in her day, the wife's earnings just went to the household. What do you do?","options":[{"text":"Say kindly your pay stays in your name, and costs are shared","then":"She looks at her son, curious how he'll respond.","best":true},{"text":"Believe she's right that a wife's pay belongs to the house","then":"The old default sounds true for a moment, unchallenged at the table."},{"text":"Argue that times have changed and her way was wrong","then":"The table goes tense, and no one hears the actual point."},{"text":"Tell yourself you're being selfish for wanting your own","then":"The guilt follows you home and sits with you all evening."}],"why":"Kindly stating that your pay stays yours answers the old default without a fight."},{"prompt":"A month on, he still raises the transfer every few days. What do you do?","options":[{"text":"Tell a trusted friend, and call 181 to learn your rights","then":"Your friend listens, and the call lays out your rights calmly.","best":true},{"text":"Believe all husbands push like this about money","then":"The belief makes it feel normal, and the pressure keeps coming."},{"text":"Keep it secret, since money fights shame the family","then":"No one outside knows, and you carry the pressure alone."},{"text":"Wait to tell anyone until he actually forces the transfer","then":"The waiting stretches on, with no one on your side yet."}],"why":"Reaching someone you trust, and learning your rights, means you aren't alone. It's never your fault."}],"debrief":"Your salary is yours, and pressure over it is never your fault. Keep your own account and share costs through a fair pool.","relearn":"Keep your salary in your own name and share costs fairly; don't surrender all access."},
  {"id":"mt-933","cat":"control-is-abuse","type":"branch","persona":"Razia","source":"reclaim stridhan","hook":"Your in-laws are holding your wedding gold and won't return it when you ask.","steps":[{"prompt":"You ask again, and your mother-in-law says it's safer with the family. What do you do?","options":[{"text":"Say calmly that the gold is your stridhan and you'd like it back","then":"She's quiet for a moment, not used to being asked so plainly.","best":true},{"text":"Believe that respecting elders means not asking again","then":"The gold stays exactly where it is, unspoken again."},{"text":"Get your husband to fight for it on your behalf instead of you","then":"He raises it clumsily, and it turns into a family row."},{"text":"Believe it must be the family's property now, not yours","then":"A right you actually hold quietly slips out of view."}],"why":"Naming it as your stridhan, calmly, is a real right, not a demand."},{"prompt":"Your husband later asks if it's really worth the tension. What do you say?","options":[{"text":"Say it matters because it's yours by right, not by favour","then":"He nods slowly, starting to see it your way.","best":true},{"text":"Wonder if asking makes you a bad daughter-in-law","then":"The doubt settles in, and the gold stays where it is."},{"text":"Say his family clearly doesn't respect you at all","then":"He gets defensive of his family, and the actual point gets lost."},{"text":"Suggest just buying new gold instead, to avoid the issue","then":"It sidesteps the return, without settling what's actually owed."}],"why":"Standing on the actual right keeps the ask clear, not personal."},{"prompt":"A cousin mentions she once got her own stridhan back from her in-laws. What do you do?","options":[{"text":"Call NALSA 15100 for free advice on getting it back","then":"You learn there are real, calm routes to pursue this.","best":true},{"text":"Believe they'll offer it back once they trust you more","then":"The offer never quite comes, and the gold stays with them."},{"text":"Post about it publicly online, hoping to pressure the family","then":"It gets attention, but not the gold, and it strains things further."},{"text":"Hide the dispute from everyone, to protect the family name","then":"The family's image stays spotless, and your right goes unspoken."}],"why":"Free legal aid turns a stuck ask into a calm, real plan."}],"debrief":"Stridhan is yours by law. Withholding it can be economic abuse, never your fault. Calmly assert it and seek guidance.","relearn":"Stridhan is yours by law. Assert it calmly and seek guidance, not the myth that it's the family's."},
  {"id":"mt-934","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"neighbour discloses","hook":"A neighbour quietly says her husband forbids her from working and gives her no money. She's scared.","steps":[{"prompt":"She glances at the door while she tells you, afraid someone will hear. What do you do?","options":[{"text":"Listen quietly, believe her, and say it's not her fault","then":"She lets her shoulders drop, just slightly.","best":true},{"text":"Tell her every marriage looks different from outside","then":"She hears that as a reason to stop talking, so she does."},{"text":"React with shock and ask her a dozen urgent questions","then":"She flinches at the questions and starts pulling back."},{"text":"Suggest she just adjust, since most women manage somehow","then":"Adjusting is what she's already doing, alone."}],"why":"Believing her, and saying it isn't her fault, makes it safe for her to keep talking."},{"prompt":"She asks you not to tell anyone, even her own sister. What do you do?","options":[{"text":"Promise to keep it safe, exactly as she's asked","then":"She trusts you a little more, having tested it.","best":true},{"text":"Say you'll tell just one trusted person to help figure it out","then":"She feels her control over her own story slip a little."},{"text":"Agree, but then mention it to your spouse that evening","then":"Word travels further than she wanted, without her choosing it."},{"text":"Say she should just tell her sister herself. It'd be easier for you","then":"The suggestion puts the hard work back on her, alone."}],"why":"Keeping her confidence exactly as asked respects her control over this."},{"prompt":"She whispers she doesn't know what she'd even do differently. What do you share?","options":[{"text":"Share that help and rights exist, whenever she feels ready","then":"She writes it down like something worth keeping.","best":true},{"text":"Tell her every marriage is like this and to adjust","then":"The line she's heard before settles over her again."},{"text":"Tell her exactly what she should do next","then":"She nods along, but it isn't really her plan."},{"text":"Say you'll check in again in a few months","then":"Months is a long time to carry this without a single option."}],"why":"Sharing that help exists, gently, leaves the choice and the pace with her."}],"debrief":"When someone discloses control, believe her, keep it safe, and share help and rights. Never normalise it, and it is never her fault.","relearn":"Believe her, keep her confidence, and share help and rights."},
  {"id":"mt-935","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"threat of nothing","hook":"You depend on your partner, who threatens to leave you with nothing if you 'step out of line'.","steps":[{"prompt":"He says it again after you mention visiting your parents. What do you do?","options":[{"text":"Quietly name it to yourself: that's a threat, not a boundary","then":"The naming feels small, but it's the first true thing today.","best":true},{"text":"Believe him that a wife shouldn't need to visit family so often","then":"The belief quiets the visit request, and nothing else changes."},{"text":"Tell yourself he probably doesn't mean it","then":"The thought buys him room to say it again next time."},{"text":"Decide you must be pushing him too hard by asking","then":"Self-blame settles in for something that was never yours to carry."}],"why":"Naming a threat as a threat is the honest, safe first step."},{"prompt":"At Diwali, your grandmother slips some cash into your hand. What do you do?","options":[{"text":"Keep it aside quietly, as a little money of your own","then":"It's small, but it's yours: the start of some footing.","best":true},{"text":"Tell yourself hidden savings would make you a bad wife","then":"The cash goes into the household pot, and nothing is yours again."},{"text":"Decide a sum this small can't make any difference","then":"It slips away on small things, and the footing never starts."},{"text":"Take an aunt's word that a wife keeps no money apart","then":"Her advice sounds proper, and his leverage stays exactly as it was."}],"why":"A little money of your own, kept quietly, starts to reduce his leverage."},{"prompt":"A week later, a cousin you're close to texts to ask how you are. What do you do?","options":[{"text":"Tell her a little of what's going on, and ask to stay in touch","then":"She says to call whenever it's safe, and that she's glad you told her.","best":true},{"text":"Say all is fine, since he pays for everything at home","then":"She sends a smile, and you're alone with the threats again."},{"text":"Tell her everything and ask her to confront him for you","then":"She promises to ring him tonight, and you fear how he'll react once he knows."},{"text":"Decide it's your own fault, so it isn't worth worrying her","then":"Her message sits unanswered, and you carry it alone another week."}],"why":"Letting one trusted person in, at your own pace, means you aren't alone with it."},{"prompt":"You finally have a stretch of time alone. What do you do?","options":[{"text":"Look up a women's helpline and save the number privately","then":"Help that understands threats like his is now one call away.","best":true},{"text":"Tell yourself helplines are only for women who get hit","then":"You close the search, and his threats stay yours alone to carry."},{"text":"Use the time to try once more to fix things between you","then":"Trying again on your own leaves the actual danger untouched."},{"text":"Wait until you're sure it counts as abuse before calling","then":"Days pass while you weigh it, and the threats keep coming."}],"why":"You don't need to be sure before calling. A saved number turns footing into a plan."}],"debrief":"Threatening to leave you with nothing is economic abuse, and never your fault. Build quiet footing and reach help.","relearn":"Threats to leave you with nothing are abuse; build quiet footing and reach help."},
  {"id":"mt-936","cat":"control-is-abuse","type":"branch","persona":"Razia","source":"coerced debt branch","hook":"Your partner keeps taking loans in your name without telling you, wrecking your credit.","steps":[{"prompt":"A recovery call comes in for a loan you never knew about. What do you do?","options":[{"text":"Name this as coerced debt and start a record of what you find","then":"Writing it down turns confusion into something you can act on.","best":true},{"text":"Take a relative's advice to just pay it and move on","then":"The advice sounds practical, and the pattern stays hidden."},{"text":"Confront him loudly the moment he walks in the door","then":"The shouting match ends with no real answers, only more noise."},{"text":"Assume it must be some kind of mistake and let it go","then":"The mistake theory buys him room to do it again."}],"why":"Naming it and recording it protects you before it grows further."},{"prompt":"He hands you papers to sign 'for a small loan, nothing to worry about'. What do you do?","options":[{"text":"Decline to sign until you understand exactly what it is","then":"He's annoyed, but the pen stays in your hand, not his.","best":true},{"text":"Believe him that it's nothing to worry about","then":"Believing him quiets the worry, though you still don't know what it says."},{"text":"Take your mother-in-law's word that wives just sign these","then":"Her words make it sound routine, and your questions go unasked."},{"text":"Ask him to explain, and go by how sure he sounds","then":"He sounds very sure, and you still haven't read a word."}],"why":"Understanding before signing keeps new debt from landing on you unread."},{"prompt":"You start wondering how to actually protect your name going forward. What do you do?","options":[{"text":"Call NALSA 15100 for free advice on protecting your name","then":"You get concrete steps instead of guesses.","best":true},{"text":"Believe he'll stop on his own now that you know","then":"Nothing changes, since nothing outside him has changed."},{"text":"Try to manage his spending for him from now on","then":"It becomes your full-time job, and the debt keeps growing."},{"text":"Decide it's probably too late to do anything about it","then":"That belief closes a door that's actually still open."}],"why":"Free legal aid gets you a real plan to limit the damage."}],"debrief":"Debt taken in your name without consent is economic abuse, never your fault. Name it and seek guidance to protect yourself.","relearn":"Coerced debt in your name is economic abuse, never your fault. Seek guidance, and don't sign what you haven't understood."},
  {"id":"mt-937","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"unsure still reach out","hook":"You're unsure your situation 'counts' as abuse. He just controls the money tightly.","steps":[{"prompt":"A friend mentions a helpline number in passing, about something unrelated. What do you do?","options":[{"text":"Memorise the number, or note it somewhere safe","then":"Having it in your head feels oddly steadying, even unused.","best":true},{"text":"Decide it doesn't apply since nothing 'that bad' has happened","then":"The number goes unremembered, and so does the option."},{"text":"Take a neighbour's word that helplines just break homes","then":"Her words make the number feel risky, and you let it go."},{"text":"Forget it quickly, since even thinking about it feels disloyal","then":"The guilt keeps the question from ever being asked."}],"why":"You don't need certainty to hold onto a number that might help."},{"prompt":"A week later, money feels tighter than usual, and you wonder again. What do you do?","options":[{"text":"Reach out to learn your options, even while still unsure","then":"You get real answers without having to prove anything first.","best":true},{"text":"Wait until it's 'definitely' abuse before asking anyone","then":"Waiting for certainty stretches the silence out longer."},{"text":"Take an aunt's word that tight money is normal in marriage","then":"Her words make it sound ordinary, and the worry goes quiet, not away."},{"text":"Tell yourself other people clearly have it worse than you","then":"The comparison quietly talks you out of your own concern."}],"why":"You can seek help while unsure; you don't need to diagnose it first."},{"prompt":"A few days later, the friend who mentioned the number asks how things are at home. What do you say?","options":[{"text":"Tell her what's been happening, even though you're unsure","then":"She listens closely and says it doesn't have to 'count' to matter.","best":true},{"text":"Say you're probably wasting her time with all this","then":"She says you're not, but the moment to say more slips by."},{"text":"Say husbands are meant to control the money anyway","then":"She says gently, \"Some people say that. It doesn't have to be that way.\""},{"text":"Say it can't be serious, since he's never hit you","then":"She pauses. \"Controlling money can still hurt,\" she says gently."}],"why":"Telling a trusted friend, even while unsure, means you aren't alone with it."}],"debrief":"You can seek help while unsure, and none of this is your fault. You don't have to diagnose yourself first; support exists exactly for this.","relearn":"You can reach out while unsure; you needn't be certain before asking for help."},
  {"id":"mt-938","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"plan a safe exit","hook":"You want to leave a controlling partner but have no savings, no documents, nowhere to start.","steps":[{"prompt":"You think it through late one night, alone. What do you do first?","options":[{"text":"Decide to reach a helpline or counsellor for a real plan","then":"The thought of not doing this alone is a small relief.","best":true},{"text":"Give up on the idea, since you 'can't afford' to leave","then":"The cost feels final, though no one's actually costed it yet."},{"text":"Start planning entirely on your own, telling no one at all","then":"It's slow going, and every step feels heavier without help."},{"text":"Wait until you've saved enough money to feel truly ready","then":"The saving is hard without access, and 'ready' keeps moving."}],"why":"A helpline or counsellor turns an impossible plan into real steps."},{"prompt":"A pamphlet with a women's helpline number turns up at a clinic waiting room. What do you do?","options":[{"text":"Take it quietly, and actually call once you're alone","then":"The call turns 'someday' into an actual conversation.","best":true},{"text":"Take it, but tuck it away for 'when things get worse'","then":"'When things get worse' keeps drifting further off."},{"text":"Leave it, since a helpline can't fix having no money","then":"The pamphlet stays behind, and so do the routes it listed."},{"text":"Decide someone else clearly needs it more than you","then":"The moment passes, and so does the chance it offered."}],"why":"Calling, not just keeping the number, is what turns it into real help."},{"prompt":"A relative offers to help, but you're not sure you can trust them fully. What do you do?","options":[{"text":"Share only what's needed for now, and keep the rest private","then":"You get help without handing over the whole plan.","best":true},{"text":"Tell them everything, relieved to finally say it out loud","then":"It feels good briefly, but you can't take the words back."},{"text":"Turn down the help, since needing it feels shameful","then":"You stay in control of it, and entirely alone with it."},{"text":"Let them take over the planning entirely for you","then":"The plan becomes theirs, moving faster than actually feels safe."}],"why":"Sharing carefully keeps you supported without losing the reins."},{"prompt":"The exit date finally gets set. What do you focus on?","options":[{"text":"Following the plan step by step, checking in with a counsellor","then":"Each step gets checked with someone who knows the routes, at your pace.","best":true},{"text":"Moving the date up on your own, since waiting feels unbearable","then":"Going early and alone skips steps the plan actually needed."},{"text":"Telling your partner your plans have changed, to be honest","then":"He turns watchful, and the quiet the plan relied on is gone."},{"text":"Doubting it's serious enough, since he's never hit you","then":"The doubt makes the plan feel heavier, and you nearly call it off."}],"why":"Steps planned with support keep you safer, and a counsellor can slow them whenever you need."}],"debrief":"Leaving safely takes a plan, and none of this is your fault. Reach a helpline or counsellor for the routes; needing help is never shameful.","relearn":"Plan a safe exit with a helpline or counsellor; needing help is what support is for."},
  {"id":"mt-939","cat":"control-is-abuse","type":"branch","persona":"Karthik","source":"modern husband pushback","hook":"A friend brags that he keeps his wife on a tight allowance she must justify.","steps":[{"prompt":"He grins, expecting you to agree with him. What do you do?","options":[{"text":"Say plainly it's control, not good sense","then":"He blinks, not expecting pushback from you.","best":true},{"text":"Laugh along so you don't seem soft in front of him","then":"He laughs harder, taking it as backup for his way."},{"text":"Say nothing and quietly change the subject instead","then":"The comment stands unchallenged, and he takes that as agreement."},{"text":"Joke that no partner of yours would tolerate that","then":"It gets a laugh, but the actual point never lands."}],"why":"Naming it plainly, without a joke, is what actually shifts the room."},{"prompt":"He adds that it's his money anyway, since he earns most of it. What do you say?","options":[{"text":"Say earning more doesn't mean he decides alone","then":"He goes quiet, turning that over.","best":true},{"text":"Back off, since it's technically true that he earns more","then":"The 'earning more' logic wins the room by default."},{"text":"Get heated and call him a bad husband to his face","then":"He gets defensive, and the actual point gets lost in the fight."},{"text":"Agree it's complicated and just leave it unresolved","then":"Unresolved is comfortable, and nothing about his habit changes."}],"why":"Earning more never grants control over a shared life's money."},{"prompt":"Later, he asks quietly what you actually do differently in your own relationship. What do you say?","options":[{"text":"Describe how you both plan and review money together","then":"He listens closely, and asks how you two got started.","best":true},{"text":"Say you basically do the same thing, just less obviously","then":"The honest chance to show a real alternative slips by."},{"text":"Tell him exactly what he's doing wrong, in careful detail","then":"It lands as a lecture, and he stops listening halfway through."},{"text":"Say it's really not your place to say anything at all","then":"A real answer, one he actually asked for, goes unsaid."}],"why":"Describing what shared, fair money actually looks like models the alternative."}],"debrief":"Policing a partner's every rupee is control, not good husbanding. Name it and model fair, shared money.","relearn":"Push back on policing a wife's spending and model fair shared money."},
  {"id":"mt-940","cat":"control-is-abuse","type":"branch","persona":"Razia","source":"sister-in-law begs","hook":"Your sister-in-law confides the family makes her beg for every expense and shames her for asking.","steps":[{"prompt":"She tells you quietly, ashamed to even be saying it. What do you do?","options":[{"text":"Believe her at once and say plainly it isn't her fault","then":"Some of the shame in her face eases, just a little.","best":true},{"text":"Ask her what she did to make the family react that way","then":"She hears blame, and shrinks a little further."},{"text":"Tell her to keep the family's image and just manage somehow","then":"Managing is exactly what's been asked of her all along."},{"text":"Say every joint family has friction like this sometimes","then":"The comparison quietly excuses what's actually happening."}],"why":"Believing her, without any blame, is what she needs to hear first."},{"prompt":"She asks if she's wrong to feel humiliated over something as small as a bus fare. What do you say?","options":[{"text":"Say clearly that being made to beg for anything is control","then":"She looks relieved someone finally called it what it is.","best":true},{"text":"Say it's not really that serious in the bigger picture","then":"Her real feeling gets measured against a bigger problem, and loses."},{"text":"Say she should just ask for a fixed amount instead","then":"The practical fix skips the actual issue: being made to beg at all."},{"text":"Tell her gently not to take it so personally","then":"It is personal, and telling her otherwise leaves her more alone."}],"why":"Naming it as control, not oversensitivity, validates what she's feeling."},{"prompt":"She asks what she could actually do, since leaving isn't something she's considering. What do you offer?","options":[{"text":"Quietly share help and her rights, at whatever pace she wants","then":"She takes the information without feeling pushed anywhere.","best":true},{"text":"Tell her plainly she has to leave, for her own good","then":"She wasn't asking for that, and now feels unheard."},{"text":"Offer to talk to the whole family on her behalf","then":"It might help or backfire, and either way it wasn't her choice."},{"text":"Say honestly there's nothing to do but wait it out","then":"Waiting it out is exactly what's kept her stuck this long."}],"why":"Sharing help and rights, without pushing a pace, respects her choices."}],"debrief":"Making someone beg and shaming her is control, and never her fault. Believe her and quietly share help and rights.","relearn":"Believe her and quietly share help and rights; don't tell her to just manage."},
  {"id":"mt-941","cat":"control-is-abuse","type":"branch","persona":"Reshma","source":"account threat","hook":"You opened a small account of your own. Your partner found out and demands the login 'or else'.","steps":[{"prompt":"That night, his 'or else' keeps replaying in your head. What do you tell yourself?","options":[{"text":"That was a threat, and my own account was never wrong","then":"Naming it steadies you, even with his demand still hanging.","best":true},{"text":"A wife shouldn't keep an account her husband can't see","then":"The thought quietly turns his demand into your guilt."},{"text":"I brought this on myself by opening it at all","then":"Self-blame settles in, though the account was always your right."},{"text":"He's just worried about money and doesn't mean 'or else'","then":"The worry eases for a night, and the demand is still there tomorrow."}],"why":"Seeing a threat for what it is, and not blaming yourself, is the first steady step."},{"prompt":"The next day, you get a few minutes alone while he's out. What do you do?","options":[{"text":"Call a friend you trust and tell her what he said","then":"She listens, believes you, and says to call her any time.","best":true},{"text":"Wait to see whether he actually does anything first","then":"The day passes, and 'or else' hangs over every quiet hour."},{"text":"Ask your mother-in-law to talk some sense into him","then":"She says a husband should know everything, and you feel more alone."},{"text":"Keep it to yourself, since a marriage's matters stay private","then":"The minutes pass, and no one else knows what he said."}],"why":"Telling someone you trust means you aren't carrying a threat alone."},{"prompt":"Things go quiet for a few days, oddly normal. What do you do?","options":[{"text":"Look into reaching a counsellor about what happened","then":"The plan starts moving even though the crisis feels paused.","best":true},{"text":"Assume the danger has passed since he seems calmer now","then":"You relax a little, and make no plan in case the demand returns."},{"text":"Bring the account up again yourself, just to test the waters","then":"His mood darkens, and the demand is back on the table."},{"text":"Decide a good wife wouldn't need an account of her own","then":"Guilt creeps in, and the account starts to feel like the problem."}],"why":"Reaching for a counsellor turns quiet days into a real plan, not just relief."},{"prompt":"A cousin mentions a women's helpline number she happened to see somewhere. What do you do?","options":[{"text":"Save it, and actually call once you get a private moment","then":"Support that knows threats like this is now just a call away.","best":true},{"text":"Note it mentally, planning to call only if things get worse","then":"'If things get worse' keeps moving further away."},{"text":"Tell yourself you can probably handle this alone","then":"You nod along, and go on carrying the threat by yourself."},{"text":"Save it, but only call once you've decided to leave","then":"The number sits unused while you're still working out what you want."}],"why":"Actually calling, not just noting it, is what turns a number into real help."}],"debrief":"Your own account is your right. A demand backed by a threat is economic abuse and never your fault. Reach support.","relearn":"Your own account is your right. A threat over it is abuse, so reach help."},
  {"id":"mt-942","cat":"control-is-abuse","type":"match","hook":"Match each India help route to exactly what it's for.","pairs":[{"left":"Women Helpline 181","right":"Talk to someone about abuse and your options"},{"left":"Women in distress 1091","right":"A woman facing harm needs support now"},{"left":"Emergency 112","right":"You're in immediate danger right now"},{"left":"NALSA free legal aid 15100","right":"Free legal help on your rights and reliefs"},{"left":"Respect at Home + a counsellor","right":"Naming control and planning a safe path"}],"relearn":"181 to talk, 1091 in distress, 112 for danger, NALSA 15100 for free legal help, and Respect at Home plus a counsellor for planning.","persona":"Razia","source":"help routes five"},
  {"id":"mt-943","cat":"control-is-abuse","type":"match","hook":"Match each controlling money tactic to the right name for it.","pairs":[{"left":"Salary must credit only to his account","right":"Seizing your income"},{"left":"A tiny ration you justify rupee by rupee","right":"A policed allowance"},{"left":"In-laws keep your wedding gold from you","right":"Withholding your stridhan"},{"left":"He forbids you from taking any job","right":"Barring you from work"},{"left":"Loans taken in your name without consent","right":"Coerced debt"}],"relearn":"Seized income, policed allowances, withheld stridhan, barred work and coerced debt are all named forms of economic abuse.","persona":"Razia","source":"name the tactic"},
  {"id":"mt-944","cat":"control-is-abuse","type":"match","hook":"Match each PWDVA 2005 remedy to what it actually does.","pairs":[{"left":"Protection order","right":"Tells the abuser to stop the harm"},{"left":"Monetary relief","right":"Covers losses caused by the abuse"},{"left":"Residence right","right":"Lets you stay in the shared home"},{"left":"Stridhan recovery","right":"Helps return property that is yours"},{"left":"Counsellor referral","right":"Support to plan your next steps"}],"relearn":"Protection orders, monetary relief, residence rights, stridhan recovery and counselling are real PWDVA-linked supports.","persona":"Razia","source":"pwdva remedies match"},
  {"id":"mt-945","cat":"control-is-abuse","type":"match","hook":"Match each money behaviour to whether it's fair partnership or economic abuse.","pairs":[{"left":"Agreeing a budget together","right":"Fair partnership"},{"left":"Confiscating your card to punish you","right":"Economic abuse"},{"left":"Both knowing the passwords","right":"Shared trust"},{"left":"Making you beg for bus fare","right":"Control and isolation"},{"left":"Each keeping personal money","right":"Healthy independence"}],"relearn":"Shared budgets, shared passwords and personal money are fair; confiscating cards and forcing you to beg are abuse.","persona":"Reshma","source":"fair or abuse match"},
  {"id":"mt-946","cat":"control-is-abuse","type":"match","hook":"Match each worry someone under control feels to the truth that answers it.","pairs":[{"left":"\"It's not abuse, he never hit me\"","right":"Economic abuse is recognised DV without a blow"},{"left":"\"I depend on him, so I can't complain\"","right":"Dependence never cancels your rights"},{"left":"\"Needing help to leave is shameful\"","right":"That's what support is for"},{"left":"\"My gold isn't really mine now\"","right":"Stridhan stays your property"},{"left":"\"I must be certain before asking\"","right":"You can seek help while unsure"}],"relearn":"No blow still counts, dependence keeps your rights, help isn't shameful, gold is yours.","persona":"Reshma","source":"worry to truth"},
  {"id":"mt-947","cat":"control-is-abuse","type":"match","hook":"Match each early warning sign to the fair alternative a safe partner would choose.","pairs":[{"left":"Cutting you off from friends","right":"Keeping your support network intact"},{"left":"Funnelling all earnings to him","right":"A fair joint pool plus your account"},{"left":"Policing every rupee you spend","right":"An agreed budget you both see"},{"left":"Taking your papers 'for safety'","right":"Both knowing where papers are kept"},{"left":"Shaming you for asking","right":"Money that's simply yours"}],"relearn":"Isolation, funnelled earnings, policed spending, withheld papers and shaming each have a fair alternative.","persona":"Pooja","source":"warning to fair"},
  {"id":"mt-948","cat":"control-is-abuse","type":"match","hook":"Match each true statement about your rights to why it matters.","pairs":[{"left":"Your salary is yours","right":"Routing it away to lock you out is abuse"},{"left":"You may hold your own account","right":"Footing of your own protects you"},{"left":"Your stridhan is your property","right":"Withholding it can be economic abuse"},{"left":"Unpaid home work has real value","right":"A homemaker's claim is equal"},{"left":"You can seek help while unsure","right":"You needn't diagnose yourself first"}],"relearn":"Your salary, account, stridhan, unpaid work's value and your right to help while unsure are all yours.","persona":"Razia","source":"rights and why"},
  {"id":"mt-949","cat":"control-is-abuse","type":"reflect","hook":"Lensy: control can wear the face of love: 'I'll handle it all so you never worry'. You get to feel the difference. Sit with that?","prompt":"What's coming up for you?","options":["I can feel it","Love shares, control takes","I'll stay alert"],"affirm":"Love shares access and a say; control takes them away while calling itself care. The difference is yours to trust.","relearn":"Love shares money access and a say; control takes them while posing as care.","persona":"Reshma","source":"love vs control feel"},
  {"id":"mt-950","cat":"control-is-abuse","type":"reflect","hook":"Lensy: if you've doubted yourself, wondering 'maybe I'm just bad with money'. That doubt is often the control talking. Hear it?","prompt":"What's your take?","options":["I hear it","Not my fault","I'll be gentler with myself"],"affirm":"Being told you're hopeless with money is a tactic, not a fact; the doubt it plants is the control speaking, not the truth.","relearn":"'You're bad with money' is often a control tactic; the self-doubt it plants isn't the truth.","persona":"Reshma","source":"doubt is control"},
  {"id":"mt-951","cat":"control-is-abuse","type":"reflect","hook":"Lensy: a homemaker's day holds real, costly work: care, cooking, running a home. Her stake in the money is equal. Land for you?","prompt":"How does that sit?","options":["It lands","Equal, not lesser","Worth saying aloud"],"affirm":"Unpaid home and care work is real economic value; a homemaker's claim on the shared money is equal, never a favour.","relearn":"A homemaker's unpaid work is real value; her claim on the money is equal, not lesser.","persona":"Reshma","source":"homemaker value reflect"},
  {"id":"mt-952","cat":"control-is-abuse","type":"reflect","hook":"Lensy: needing money help to leave or rebuild isn't weakness. It's the whole reason support exists. Can you let that be true?","prompt":"What do you notice?","options":["I can","Not my shame","Support is for this"],"affirm":"Needing financial help to leave or start again is exactly what support is built for; it is never a personal failing.","relearn":"Needing financial help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"help not shame reflect"},
  {"id":"mt-953","cat":"control-is-abuse","type":"reflect","hook":"Lensy: you don't have to prove it's 'really' abuse before you're allowed to ask for help. Unsure is reason enough. Okay to hold?","prompt":"What's your take?","options":["Okay to hold","I can ask while unsure","That's a relief"],"affirm":"You can reach out while still unsure; you never have to diagnose yourself or earn your way to support first.","relearn":"You can seek help while unsure; you needn't prove it's abuse before asking.","persona":"Reshma","source":"unsure is enough"},
  {"id":"mt-954","cat":"control-is-abuse","type":"reflect","hook":"Lensy: 'log kya kahenge' keeps a lot of people silent. Your safety matters more than the neighbours' opinions. Worth remembering?","prompt":"How does that feel?","options":["Worth remembering","My safety first","Their talk isn't my cage"],"affirm":"What people might say is never worth more than your safety and dignity; seeking help is care for yourself, not scandal.","relearn":"Fear of 'what will people say' shouldn't outweigh your safety; seeking help isn't scandal.","persona":"Reshma","source":"log kya kahenge reflect"},
  {"id":"mt-955","cat":"control-is-abuse","type":"reflect","hook":"Lensy: open planning is teamwork; controlling a partner's money is abuse. Control is the line between them. Clear?","prompt":"What do you think?","options":["Clear","That's the line","Good to name"],"affirm":"Planning money together is teamwork; controlling a partner's access and say is abuse. Control is the dividing line.","relearn":"Planning money together is teamwork; controlling a partner's money is abuse. Control is the line.","persona":"any","source":"the line reflect"},
  {"id":"mt-956","cat":"control-is-abuse","type":"reflect","hook":"Lensy: keeping a little money and access that's simply yours isn't distrust. It's footing. Both partners deserve it. Sit okay?","prompt":"What's coming up?","options":["Sits okay","Footing, not distrust","Both deserve it"],"affirm":"Your own money and access aren't a sign of distrust; they're the footing that keeps both partners free and safe.","relearn":"Your own money and access are footing, not distrust; both partners deserve them.","persona":"any","source":"footing not distrust"},
  {"id":"mt-957","cat":"control-is-abuse","type":"role-play","persona":"Pooja","source":"rp salary","hook":"Practise the words when a partner wants your salary sent to his account.","setup":"He says: \"It's simpler if it just comes to me.\"","steps":[{"prompt":"He adds: \"You worry about it too much, honestly.\"","options":[{"text":"\"My salary stays in my name. Let's pool a fair share.\"","then":"He pauses. \"A pool. Okay, tell me how that'd work.\"","best":true},{"text":"\"A husband should manage the salary, I suppose.\"","then":"\"Exactly,\" he says. \"So why do you still look unsure?\""},{"text":"\"Maybe I am worrying too much. Sorry for fussing.\"","then":"He smiles. \"See? Just leave it to me.\""},{"text":"\"Why does it have to be your account and not joint?\"","then":"\"Because that's how my parents did it,\" he says."}],"why":"Keeping your salary in your name and proposing a pool protects you fairly."},{"prompt":"He asks: \"You do trust me with money, don't you?\"","options":[{"text":"\"Trust isn't the point. I want us both to see the money.\"","then":"He goes quiet, working through that.","best":true},{"text":"\"A good wife wouldn't question this. Maybe I'm wrong.\"","then":"He nods. \"So let's not make it a thing.\""},{"text":"\"I don't trust you, actually, if you must know.\"","then":"He looks hurt. \"That's a lot to say over a bank account.\""},{"text":"\"Trust means not needing to see the money at all, right?\"","then":"He nods. \"Right. So there's nothing to see.\""}],"why":"Both seeing the money builds trust. It doesn't question it."},{"prompt":"That night your friend Meera asks on the phone: \"You sound tense. What's going on?\"","options":[{"text":"\"He wants my whole salary, and the pressure worries me.\"","then":"\"I'm glad you told me,\" she says. \"That's not on you. Let's talk.\"","best":true},{"text":"\"Nothing much. Money is between husband and wife.\"","then":"\"Okay,\" she says, \"but I'm here if that changes.\""},{"text":"\"It's my fault. I made a fuss over a bank account.\"","then":"\"A fuss? It's your own salary,\" she says, surprised."},{"text":"\"My mother says a good wife hands over her pay.\"","then":"\"Is that what you want, though?\" she asks gently."}],"why":"Telling someone you trust means you aren't alone with the pressure. It's never your fault."},{"prompt":"A few days later, he asks: \"Let's settle how the money works. What's your idea?\"","options":[{"text":"\"A fair share each into a joint pool we can both see.\"","then":"\"Okay,\" he says slowly. \"I can work with that.\"","best":true},{"text":"\"I'll figure out the details myself and tell you later.\"","then":"\"Sure,\" he says, but the plan stays only in your head."},{"text":"\"Maybe the man should run it, like our parents did.\"","then":"He nods. \"Then I'll set it up around my account.\""},{"text":"\"Why should I share anything with you at all now?\"","then":"He stiffens. \"Now you're just being difficult.\""}],"why":"A clear pool you can both see is what makes sharing fair, not vague trust."}],"relearn":"Your salary is yours. Share costs through a fair pool, not by surrendering your account."},
  {"id":"mt-958","cat":"control-is-abuse","type":"role-play","persona":"Reshma","source":"rp allowance","hook":"Practise the words when you're handed a tiny allowance and told to account for every rupee.","setup":"Sunday evening, he puts a few notes and a small notebook in front of you.","steps":[{"prompt":"He says: \"It's not much to ask, is it?\"","options":[{"text":"\"Recording every rupee isn't budgeting. It's control.\"","then":"He frowns, not expecting you to name it that plainly.","best":true},{"text":"\"You earn it, so I suppose it's your call.\"","then":"\"Exactly,\" he says, and slides the notebook across to you."},{"text":"\"You never give me enough to run the house anyway.\"","then":"He gets defensive. \"I give you what's needed.\""},{"text":"\"I suppose this is just how careful households run.\"","then":"\"That's the spirit,\" he says, and the amount stays exactly the same."}],"why":"Naming it as control, not budgeting, is the honest first step."},{"prompt":"Midweek he says: \"Show me what you've spent so far.\"","options":[{"text":"\"I won't justify every rupee. I want to see our accounts.\"","then":"\"The accounts?\" he says, caught off guard, and doesn't reach for the notebook.","best":true},{"text":"\"Could I just have a little more each week instead?\"","then":"\"Maybe a little more,\" he says, \"if the record is kept.\""},{"text":"\"Sorry. I know I spent extra on vegetables this week.\"","then":"He nods and writes the amount down himself."},{"text":"\"Fine. A wife should answer to her husband, I suppose.\"","then":"\"Good,\" he says, and the checking becomes a weekly habit."}],"why":"Asking for real access, not a bigger allowance, goes to the heart of the control."},{"prompt":"A week later your friend Farah asks: \"You've gone quiet. Is everything okay at home?\"","options":[{"text":"\"Not really. He polices every rupee, and I need to talk.\"","then":"She sits beside you. \"I'm here. And there are people who can help.\"","best":true},{"text":"\"It's fine. What happens at home stays at home.\"","then":"She lets it drop, though she doesn't look convinced."},{"text":"\"I'm bad with money, so he has to keep track.\"","then":"Farah frowns. \"Is that really what you believe?\""},{"text":"\"Every couple fights about money. It's nothing serious.\"","then":"\"If you say so,\" she says, and changes the subject."}],"why":"Telling someone you trust means you aren't alone with it, and none of it is your fault."}],"relearn":"A tiny, policed allowance is economic control, never your fault. Ask for real access, and reach out for support."},
  {"id":"mt-959","cat":"control-is-abuse","type":"role-play","persona":"Razia","source":"rp stridhan","hook":"Practise the words when in-laws won't return your wedding gold.","setup":"Your mother-in-law says: \"The gold is safer with us now.\"","steps":[{"prompt":"She adds: \"Why would you even need it right now?\"","options":[{"text":"\"That gold is my stridhan. I'd like it returned to me.\"","then":"She's quiet a moment, not used to being answered so plainly.","best":true},{"text":"\"Maybe it is the family's gold now, I suppose.\"","then":"\"Good,\" she says, though the question doesn't feel settled to you."},{"text":"\"My husband will ask you for it himself, then.\"","then":"She raises an eyebrow. \"Bringing my son into this now?\""},{"text":"\"Maybe asking makes me a bad daughter-in-law.\"","then":"She pats your hand and changes the subject, and the gold stays with her."}],"why":"Naming your stridhan plainly is a real right, not a demand."},{"prompt":"She comes back to it: \"You'll have it eventually. There's no rush.\"","options":[{"text":"\"I'd still like a clear date. It is mine, after all.\"","then":"She pauses, weighing that you mean it.","best":true},{"text":"\"Maybe I'm being greedy, asking for it so soon.\"","then":"She smiles and tells you to let it rest, and the date never comes."},{"text":"\"You're keeping what's legally mine, and you know it.\"","then":"The accusation lands hard, and the conversation shuts down."},{"text":"\"My aunt says a new bride shouldn't ask for gold.\"","then":"\"Your aunt is wise,\" she says, and the gold stays put."}],"why":"A clear timeline moves this past vague reassurance."},{"prompt":"Your husband later asks: \"Ma says you asked about the gold. What's going on?\"","options":[{"text":"\"It's my stridhan. It matters because it's mine by right.\"","then":"He nods slowly. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Maybe I've caused all this trouble for nothing.\"","then":"He sighs. \"It has been a lot of tension.\""},{"text":"\"Your mother clearly doesn't respect me at all.\"","then":"He gets defensive of her. \"That's not fair to Ma.\""},{"text":"\"Maybe a wife shouldn't care about gold more than peace at home.\"","then":"He looks relieved. \"That's simpler for everyone.\""}],"why":"The tension isn't your fault. Standing on your right keeps this about fairness."},{"prompt":"A week later, your cousin asks on the phone: \"Did you ever get your gold back?\"","options":[{"text":"\"Not yet. I'll call NALSA 15100 and ask how it works.\"","then":"\"I'm glad,\" she says. \"Tell me how it goes.\"","best":true},{"text":"\"No. Asking again would only shame the family.\"","then":"\"Shame them? It's yours,\" she says quietly."},{"text":"\"Please don't tell anyone I asked. It's embarrassing.\"","then":"\"I won't,\" she says, \"but you've nothing to be ashamed of.\""},{"text":"\"I'll post about it online. That'll shame them into it.\"","then":"\"That might make things much harder,\" she says slowly."}],"why":"Free legal aid gives you a calm, real route to what's already yours."}],"relearn":"Wedding gold is your stridhan; you can ask for it back and seek advice. Their keeping it from you is never your fault."},
  {"id":"mt-960","cat":"control-is-abuse","type":"role-play","persona":"Reshma","source":"rp work","hook":"Practise the words when a partner forbids you from taking a job.","setup":"He says: \"No wife of mine is going out to work.\"","steps":[{"prompt":"He adds: \"It's simply not how things are done in this house.\"","options":[{"text":"\"Whether I work is my decision, and I'm taking the offer.\"","then":"He's startled. \"You've already decided, then.\"","best":true},{"text":"\"Maybe you're right that it's not really how things are done.\"","then":"\"Glad you see it,\" he says, while the offer letter waits in your bag."},{"text":"\"Perhaps a good wife really shouldn't work outside.\"","then":"\"Good,\" he says, though you haven't actually said yes to that."},{"text":"\"Maybe I'm asking for too much, bringing this up at all.\"","then":"\"It is too much,\" he says, and waits for you to agree."}],"why":"Whether you work is your call. A fair partner doesn't bar it."},{"prompt":"He says: \"What will people even say, my wife going out to work?\"","options":[{"text":"\"It's not about what people say. It's my job and my choice.\"","then":"He has no quick reply for that.","best":true},{"text":"\"Maybe the family's name does matter more than a job.\"","then":"\"Exactly,\" he says, glad you've come around."},{"text":"\"People can say whatever they want. I don't care at all.\"","then":"\"Easy for you to say,\" he snaps. \"I'm the one they'll ask.\""},{"text":"\"I'll just keep it quiet from people for now, then.\"","then":"\"And when they find out anyway?\" he asks."}],"why":"Naming it as your choice, not others' opinions, answers his real worry."},{"prompt":"Later, your sister asks on the phone: \"So, did you take the job?\"","options":[{"text":"\"Not yet. He's forbidding it. Can we talk it through?\"","then":"\"Of course. Barring you from work isn't okay. Let's talk tonight.\"","best":true},{"text":"\"No. A wife's first duty is keeping the peace at home.\"","then":"\"Is that you talking, or him?\" she asks gently."},{"text":"\"Not yet. I think I made him angry just by asking.\"","then":"She pauses. \"You sound like you're blaming yourself.\""},{"text":"\"It's all fine. There's nothing to talk about, really.\"","then":"\"Okay,\" she says, sounding unsure, and lets it drop."}],"why":"Talking it through with someone you trust means you don't face the ban alone."},{"prompt":"That weekend he says: \"I hope you've dropped this job idea by now.\"","options":[{"text":"\"I haven't dropped it. I'm accepting the offer this week.\"","then":"He stares a moment. \"You've really made up your mind.\"","best":true},{"text":"\"Maybe I should have made this easier on everyone.\"","then":"\"You could have,\" he says, and the ban stands."},{"text":"\"I'll take it, and still do all the housework myself.\"","then":"\"Fine,\" he says, \"as long as nothing at home changes.\""},{"text":"\"My mother says a job isn't worth fighting your husband over.\"","then":"\"Your mother is wise,\" he says, and treats it as settled."}],"why":"Your work is your call, not his to permit, and his ban is never your fault."}],"relearn":"Whether you work is your call. Barring it to keep you dependent is economic abuse, never your fault."},
  {"id":"mt-961","cat":"control-is-abuse","type":"role-play","persona":"Reshma","source":"rp believe","hook":"Practise gently believing a friend who opens up about financial control.","setup":"Your friend pulls you aside, unsure how to even start.","steps":[{"prompt":"She whispers: \"He watches every paisa. Am I imagining it, or is it wrong?\"","options":[{"text":"\"You're not imagining it, and it isn't your fault.\"","then":"She lets out a breath she seems to have been holding.","best":true},{"text":"\"Maybe you're overthinking it. That's just marriage.\"","then":"She nods slowly. \"Maybe. I just thought...\" She trails off."},{"text":"\"Have you actually tried just asking him for more?\"","then":"She shakes her head. \"It's not about the amount.\""},{"text":"\"That does sound bad. Are you sure about it?\"","then":"She hesitates. \"I think so. Or maybe I'm not.\""}],"why":"Believing her plainly tells her she isn't imagining it, and that none of it is her fault."},{"prompt":"She says: \"I don't even know what I'd do differently.\"","options":[{"text":"\"You needn't decide yet. There's help when you're ready.\"","then":"She relaxes, hearing there's no deadline on this.","best":true},{"text":"\"You should just leave him. You deserve better.\"","then":"She pulls back, not ready for that, and goes quiet."},{"text":"\"Just start saving something secretly from now on.\"","then":"\"Secretly? If he found out...\" she says, and looks away."},{"text":"\"I'd probably just talk to him about it directly.\"","then":"She stiffens. \"You don't know what he's like when he's crossed.\""}],"why":"Offering help without a deadline respects her pace, not yours."},{"prompt":"She asks: \"Will you tell anyone else at all about this?\"","options":[{"text":"\"Only if you want me to, and only who you choose.\"","then":"\"Just you, for now,\" she says, looking a little steadier.","best":true},{"text":"\"I probably should tell someone who can actually help.\"","then":"Her face tightens. \"Please don't. Not yet.\""},{"text":"\"No, I won't say a single word to anyone at all.\"","then":"\"Not even if I ask you to?\" she says, unsure."},{"text":"\"That depends on what you tell me next.\"","then":"She goes quiet, weighing whether to say anything more."}],"why":"Letting her choose who knows keeps this hers, at her own pace."}],"relearn":"When someone discloses control, believe them and share that help and rights exist; it is never their fault."},
  {"id":"mt-962","cat":"control-is-abuse","type":"role-play","persona":"Reshma","source":"rp account","hook":"Practise the words when a partner demands the login to the account you opened.","setup":"He walks in holding your phone, the bank's message on the screen.","steps":[{"prompt":"He says: \"You'll share the password tonight, or else.\"","options":[{"text":"\"It's my account. I need a moment to think.\"","then":"He's momentarily thrown by the calm, flat response.","best":true},{"text":"\"A husband should know about every account, I suppose.\"","then":"\"Exactly,\" he says. \"So why did you hide it?\""},{"text":"\"Why do you even want it? What is this really about?\"","then":"He deflects the question and repeats the demand louder."},{"text":"\"You don't really mean the 'or else'. You're just stressed.\"","then":"\"Try me,\" he says. \"The password, tonight.\""}],"why":"Staying calm and giving yourself time, without arguing, is the safe first step."},{"prompt":"Later that day your sister asks on the phone: \"You sound shaken. What happened?\"","options":[{"text":"\"He demanded my account login, or else. I'm scared.\"","then":"\"I'm glad you told me,\" she says. \"This isn't your fault.\"","best":true},{"text":"\"Nothing much. He just gets angry about money sometimes.\"","then":"\"Just angry?\" she asks, and doesn't sound convinced."},{"text":"\"I opened an account without asking him, so I brought it on.\"","then":"\"Having your own account isn't wrong,\" she says, surprised."},{"text":"\"It's nothing. Ma always says couple matters stay private.\"","then":"\"Okay,\" she says slowly. \"But you don't sound like it's nothing.\""}],"why":"Telling someone you trust means you aren't alone with a threat, and it's never your fault."},{"prompt":"The next day she calls back: \"You sounded scared. Would you talk to a helpline, just to know your options?\"","options":[{"text":"\"Yes. Will you sit with me while I call 181?\"","then":"\"Of course,\" she says. \"Whenever you're ready.\"","best":true},{"text":"\"Only if he does something. Words aren't really abuse.\"","then":"\"A threat is something,\" she says quietly."},{"text":"\"I can't. What would people say if anyone found out?\"","then":"\"No one has to know,\" she says, \"but it's your call.\""},{"text":"\"Ma says every wife adjusts. Maybe I should too.\"","then":"\"Is adjusting keeping you safe?\" she asks gently."}],"why":"A helpline, with someone beside you, turns support into real options."}],"relearn":"Your own account is your right, and a threat over it is economic abuse, never your fault. Reach help."},
  {"id":"mt-963","cat":"control-is-abuse","type":"role-play","persona":"Karthik","source":"rp pushback","hook":"Practise pushing back when a friend brags about controlling his wife's money.","setup":"Your friend laughs: \"I keep her on a tight leash money-wise.\"","steps":[{"prompt":"He adds: \"Works great, honestly, no complaints at all.\"","options":[{"text":"\"Policing her every rupee isn't order. It's control.\"","then":"He blinks, not expecting that from you.","best":true},{"text":"\"Ha, yeah, you've got to keep them in check, right.\"","then":"He laughs harder, glad to have the agreement."},{"text":"\"That's a bit much, isn't it, don't you think?\"","then":"\"Nah, she's fine with it,\" he says, brushing it off."},{"text":"\"Not really my business how you run your house.\"","then":"\"Exactly. My house, my rules,\" he says."}],"why":"Naming it plainly as control is what actually lands, not a soft nudge."},{"prompt":"He adds: \"She doesn't even earn, so it's only fair I decide.\"","options":[{"text":"\"Earning doesn't buy a say. Her work at home counts too.\"","then":"He goes quiet, thinking that over for once.","best":true},{"text":"\"Fair point. I suppose earning does matter, actually.\"","then":"\"Exactly,\" he says, satisfied you see it his way."},{"text":"\"You're basically a bad husband. You know that, right?\"","then":"He gets defensive, and the actual point gets lost in it."},{"text":"\"Everyone runs their own house differently, I guess.\"","then":"\"Right,\" he shrugs, and moves on to cricket."}],"why":"A say in shared money doesn't depend on who earns it, and home work counts."},{"prompt":"Later, over chai, he asks: \"So how would you run the money, then?\"","options":[{"text":"\"Plan it together, and neither one polices the other.\"","then":"He listens, then asks how he'd even start.","best":true},{"text":"\"Pretty much like you, just less loudly.\"","then":"He grins. \"See? Everyone does it.\""},{"text":"\"Never mind me. You should stop doing what you're doing.\"","then":"It lands as a lecture, and he stops listening."},{"text":"\"No idea. I haven't really thought about it.\"","then":"\"Fair enough,\" he says, and the chance to show him passes."}],"why":"Describing how shared money works shows him a real alternative."}],"relearn":"Policing a partner's spending is control, not good husbanding; sharing is fairer."},
  {"id":"mt-964","cat":"control-is-abuse","type":"role-play","persona":"Reshma","source":"rp dependence","hook":"Practise the words when you're told dependence means you can't object.","setup":"He says: \"You don't earn a rupee, so no say.\"","steps":[{"prompt":"He adds: \"That's just how it works, isn't it?\"","options":[{"text":"\"My home work has value. Depending doesn't cancel my say.\"","then":"He pauses, not expecting an answer that firm.","best":true},{"text":"\"Maybe dependence does mean I shouldn't expect a say.\"","then":"\"Good,\" he says, though your face tells him it isn't settled."},{"text":"\"I do everything around here. You don't even notice!\"","then":"\"Here we go again,\" he mutters, hearing only the anger."},{"text":"\"Ma always said a wife who doesn't earn shouldn't argue.\"","then":"\"See? Even she knows,\" he says, settling back."}],"why":"Unpaid home work has real value; dependence never cancels your say."},{"prompt":"Later he asks: \"What do you even want a say in, anyway?\"","options":[{"text":"\"In what affects us both. Asked before, not told after.\"","then":"He considers that, like it hadn't occurred to him before.","best":true},{"text":"\"I don't know. I haven't really thought it through.\"","then":"\"Then it can't matter much,\" he says."},{"text":"\"Just the small things, sometimes. That would be enough.\"","then":"\"Small things, fine,\" he says, and keeps the big ones."},{"text":"\"Maybe I'm being ungrateful for all you provide.\"","then":"He shrugs. \"Fine.\" The question drops and nothing shifts."}],"why":"A say means being asked before, not told after, on what affects you both."},{"prompt":"He mentions, in passing: \"I'm thinking of buying a new bike next week.\"","options":[{"text":"\"That's a big spend. Can we decide it together?\"","then":"He pauses. \"I suppose it does affect us both.\"","best":true},{"text":"\"My friend says wives shouldn't question big buys.\"","then":"\"Your friend's right,\" he says, already looking at bikes online."},{"text":"\"You never include me in anything, ever, do you!\"","then":"\"That's not fair,\" he snaps. \"It's just a bike.\""},{"text":"\"I guess it's technically your money to decide.\"","then":"\"Exactly,\" he says, and books a test ride."}],"why":"Naming the specific decision keeps the ask practical, not just a feeling."},{"prompt":"A month later, your cousin asks on the phone: \"How are things with him these days?\"","options":[{"text":"\"He says I've no say since I don't earn. It's hard.\"","then":"\"That's not fair to you,\" she says. \"It's not your fault. I'm here.\"","best":true},{"text":"\"Fine. Every marriage has one person who decides.\"","then":"\"Is that what you really think?\" she asks."},{"text":"\"I'd rather not say. It would shame him if people knew.\"","then":"\"Okay,\" she says, \"but you can always tell me.\""},{"text":"\"It's my fault for not earning, so I can't complain.\"","then":"\"Earning isn't what gives you a say,\" she says gently."}],"why":"Telling someone you trust means you aren't alone with it, and it's never your fault."}],"relearn":"Unpaid home work has real value; dependence never cancels your say or dignity."},
  {"id":"mt-990","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Investing and stocks are men's territory; women should stick to running the kitchen.\"","myth":{"un":"Investing and stocks are men's territory; women should stick to running the kitchen.","re":"Investing is a learnable skill, not a male preserve; a partner who wants to learn it should, whatever their gender.","why":"Markets don't check gender; learning does the work."},"relearn":"Investing isn't men's territory; it's a learnable skill, and any partner who wants to learn it can.","persona":"Pooja","source":"investing isn't male"},
  {"id":"mt-991","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"He brings home the salary, so naturally the big purchases are his call alone.\"","myth":{"un":"He brings home the salary, so naturally the big purchases are his call alone.","re":"A salary funds a shared life, so big purchases are decided together; earning the cash isn't owning the vote.","why":"A shared life shares the big calls."},"relearn":"Earning the salary doesn't make big purchases one partner's call; a shared life decides them together.","persona":"Karthik","source":"big calls shared"},
  {"id":"mt-992","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A good wife hands her whole salary to her husband and lets him manage it.\"","myth":{"un":"A good wife hands her whole salary to her husband and lets him manage it.","re":"Being a good partner has nothing to do with surrendering your salary; keeping your own access is healthy, not disloyal.","why":"Loyalty isn't proven by handing over your pay."},"relearn":"A good partner needn't surrender their salary; keeping your own access is healthy, not disloyal.","persona":"Pooja","source":"salary isn't surrender"},
  {"id":"mt-993","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"She doesn't earn, so she has no real claim on how the household money is spent.\"","myth":{"un":"She doesn't earn, so she has no real claim on how the household money is spent.","re":"A partner running the home and care work contributes real value, so her claim on the money is equal, not lesser.","why":"Unpaid home work is value, not charity."},"relearn":"Not earning a wage doesn't erase a claim on the money; unpaid home work is real value and an equal stake.","persona":"any","source":"non-earner has a stake"},
  {"id":"mt-994","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Men handle the bank and bills; a woman fussing with paperwork looks odd.\"","myth":{"un":"Men handle the bank and bills; a woman fussing with paperwork looks odd.","re":"Handling the bank and bills is just a task, not a gender role; either partner can and should be able to do it.","why":"Paperwork has no gender, only a doer."},"relearn":"Banking and bills aren't men's work; they're a task either partner can do, and both should be able to.","persona":"Sneha","source":"paperwork has no gender"},
  {"id":"mt-995","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"He's the head of the family, so the money naturally belongs under his control.\"","myth":{"un":"He's the head of the family, so the money naturally belongs under his control.","re":"A shared household's money belongs to the partnership, not to a 'head'; one person controlling it isn't headship, it's imbalance.","why":"A partnership pools; it doesn't crown."},"relearn":"Being 'head of the family' doesn't put the money under one person's control; a shared household's money belongs to the partnership.","persona":"any","source":"no head over money"},
  {"id":"mt-996","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Daughters get gold and a wedding; the real money and property go to sons.\"","myth":{"un":"Daughters get gold and a wedding; the real money and property go to sons.","re":"Sharing wealth and property only with sons is an unfair, gendered default; daughters are equal heirs and earners.","why":"A child's worth isn't set by gender."},"relearn":"Money and property aren't a sons-only inheritance; daughters are equal heirs, and gendered defaults are worth questioning.","persona":"Razia","source":"daughters are heirs"},
  {"id":"mt-997","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"If a wife earns more than her husband, that's embarrassing and bad for the marriage.\"","myth":{"un":"If a wife earns more than her husband, that's embarrassing and bad for the marriage.","re":"Whoever earns more is just a fact about jobs, not a verdict on the marriage; a fair couple pools income without keeping score.","why":"A bigger paycheque isn't a bigger person."},"relearn":"A wife earning more isn't embarrassing; income is a fact about jobs, and a fair couple pools it without keeping score.","persona":"Karthik","source":"who earns more"},
  {"id":"mt-998","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Let the men sort the loan and the property papers; women don't need to bother.\"","myth":{"un":"Let the men sort the loan and the property papers; women don't need to bother.","re":"Both partners should understand a loan and whose name is on the property; being left out of big paperwork is a real vulnerability, not protection.","why":"Knowing the papers is footing, not fuss."},"relearn":"Big loans and property papers aren't 'men's' to sort alone; both partners should understand them, as being left out is a vulnerability.","persona":"Pooja","source":"both know the papers"},
  {"id":"mt-999","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Pocket money for the wife is generous enough; she doesn't need her own account.\"","myth":{"un":"Pocket money for the wife is generous enough; she doesn't need her own account.","re":"A doled-out allowance isn't the same as a fair say and her own account; every adult deserves money that's simply theirs.","why":"An allowance is a leash, not a share."},"relearn":"Pocket money isn't generosity in place of a fair share; every adult deserves their own account and money that's simply theirs.","persona":"Reshma","source":"allowance isn't a share"},
  {"id":"mt-1000","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Women are too emotional with money; men are the rational ones, so men should budget.\"","myth":{"un":"Women are too emotional with money; men are the rational ones, so men should budget.","re":"Careful budgeting is a habit anyone can build; tying it to gender is a stereotype, not a truth about who plans well.","why":"Good budgeting is practice, not chromosomes."},"relearn":"Women aren't 'too emotional' for money; careful budgeting is a habit anyone can build, regardless of gender.","persona":"any","source":"budgeting is a habit"},
  {"id":"mt-1001","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A man who lets his wife handle the finances has lost control of his household.\"","myth":{"un":"A man who lets his wife handle the finances has lost control of his household.","re":"Whoever is better at tracking money can run the day-to-day; that's smart teamwork, not a man losing control.","why":"Sharing a task isn't surrendering a home."},"relearn":"A husband whose wife handles the finances hasn't lost control; sharing the task by who's better at it is smart teamwork.","persona":"Karthik","source":"task isn't control"},
  {"id":"mt-1002","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"It's the wife's duty to run the house on whatever the husband decides to give.\"","myth":{"un":"It's the wife's duty to run the house on whatever the husband decides to give.","re":"Running the house on a fixed handout one partner sets isn't 'duty'; a fair home plans the household budget together.","why":"A budget you can't see isn't a budget you share."},"relearn":"Running the house on a one-sided handout isn't a wife's duty; a fair home plans the household budget together.","persona":"Pooja","source":"household budget shared"},
  {"id":"mt-1003","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Saving and bargaining is womanly; the husband shouldn't have to worry about small spends.\"","myth":{"un":"Saving and bargaining is womanly; the husband shouldn't have to worry about small spends.","re":"Watching the everyday spending is part of any adult's money sense, not a 'womanly' chore one partner is above.","why":"No partner is too important to track a rupee."},"relearn":"Saving and small spends aren't 'womanly' chores; watching everyday spending is part of any adult's money sense.","persona":"Karthik","source":"small spends are shared"},
  {"id":"mt-1004","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"The husband's name goes first on the house; the wife's name is just a formality.\"","myth":{"un":"The husband's name goes first on the house; the wife's name is just a formality.","re":"Both partners belonging on a shared home is fairness and security, not a formality; whose name 'goes first' isn't a status contest.","why":"A shared home should name both who share it."},"relearn":"A wife's name on the home isn't a formality; both partners belonging on a shared home is fairness and security.","persona":"any","source":"both on the house"},
  {"id":"mt-1005","cat":"fair-not-gendered","type":"sort","hook":"Sort each statement: a fair, even-handed view of money, or a gendered one?","items":[{"id":"a","text":"Either partner can learn to invest"},{"id":"b","text":"'Real money matters are for men'"},{"id":"c","text":"Both names belong on the home"},{"id":"d","text":"'A wife just asks for what she needs'"},{"id":"e","text":"Whoever tracks bills best can do it"},{"id":"f","text":"'Earning gives him the final word'"}],"bins":[{"id":"fair","label":"Fair / even-handed","valence":"pos"},{"id":"gendered","label":"Gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"Either partner learning, both names on the home and sharing by skill are fair; tying money to a man's role is gendered.","persona":"any","source":"fair or gendered"},
  {"id":"mt-1006","cat":"fair-not-gendered","type":"sort","hook":"Sort each way of valuing a homemaker: fair and accurate, or a gendered put-down?","items":[{"id":"a","text":"Her care work has real value"},{"id":"b","text":"'She earns nothing, so contributes nothing'"},{"id":"c","text":"She's an equal partner in the plan"},{"id":"d","text":"'A homemaker is just a dependent'"},{"id":"e","text":"Her unpaid work earns a say"},{"id":"f","text":"'Running the home isn't real work'"}],"bins":[{"id":"fair","label":"Fair & accurate","valence":"pos"},{"id":"putdown","label":"Gendered put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"A homemaker's care work is real value and an equal stake; 'earns nothing', 'just a dependent' and 'not real work' are put-downs.","persona":"Pooja","source":"homemaker value"},
  {"id":"mt-1007","cat":"fair-not-gendered","type":"sort","hook":"Sort each reason for who decides a money matter: a fair reason, or a gendered excuse?","items":[{"id":"a","text":"You both agreed this is the goal"},{"id":"b","text":"'He's the man of the house'"},{"id":"c","text":"It fits the budget you set together"},{"id":"d","text":"'Women can't be trusted with money'"},{"id":"e","text":"You took turns and reached agreement"},{"id":"f","text":"'Her job is the home, not finance'"}],"bins":[{"id":"reason","label":"Fair reason","valence":"pos"},{"id":"excuse","label":"Gendered excuse","valence":"neg"}],"key":{"a":"reason","b":"excuse","c":"reason","d":"excuse","e":"reason","f":"excuse"},"relearn":"Agreed goals, a shared budget and reaching agreement are fair reasons; 'man of the house' or 'her job is the home' are gendered excuses.","persona":"any","source":"reason or excuse"},
  {"id":"mt-1008","cat":"fair-not-gendered","type":"sort","hook":"Sort each home's money setup: shares power fairly, or keeps it gendered?","items":[{"id":"a","text":"Both partners can see every account"},{"id":"b","text":"Only he holds the bank passwords"},{"id":"c","text":"Both learn how the investments work"},{"id":"d","text":"She must ask before any spending"},{"id":"e","text":"Goals are set together each year"},{"id":"f","text":"Property is all in the men's names"}],"bins":[{"id":"fair","label":"Shares power","valence":"pos"},{"id":"gendered","label":"Keeps it gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"Both seeing accounts and setting goals together shares power; he-only passwords, ask-before-spending and men-only property keep it gendered.","persona":"Pooja","source":"share or gender power"},
  {"id":"mt-1009","cat":"fair-not-gendered","type":"sort","hook":"Sort each line a couple might say: even-handed and fair, or quietly gendered?","items":[{"id":"a","text":"'Let's both learn what we own'"},{"id":"b","text":"'You wouldn't understand the numbers'"},{"id":"c","text":"'We decide the big spends together'"},{"id":"d","text":"'Leave the money side to me'"},{"id":"e","text":"'Your income counts as much as mine'"},{"id":"f","text":"'A wife shouldn't question the budget'"}],"bins":[{"id":"fair","label":"Even-handed","valence":"pos"},{"id":"gendered","label":"Quietly gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"'Let's both learn what we own' and 'decide together' are even-handed; 'you wouldn't understand' or 'a wife shouldn't question' are quietly gendered.","persona":"any","source":"even or gendered lines"},
  {"id":"mt-1010","cat":"fair-not-gendered","type":"sort","hook":"Sort each belief about money roles: a fair, modern one, or an old gendered script?","items":[{"id":"a","text":"Money skill is learned by anyone"},{"id":"b","text":"'Finance is simply a man's domain'"},{"id":"c","text":"A homemaker is an equal partner"},{"id":"d","text":"'The non-earner is a dependent'"},{"id":"e","text":"Both should know where the money is"},{"id":"f","text":"'Only the earner gets a real vote'"}],"bins":[{"id":"fair","label":"Fair & modern","valence":"pos"},{"id":"old","label":"Old gendered script","valence":"neg"}],"key":{"a":"fair","b":"old","c":"fair","d":"old","e":"fair","f":"old"},"relearn":"'Skill is learned' and 'a homemaker is an equal partner' are fair; 'finance is a man's domain' or 'only the earner votes' are old gendered scripts.","persona":"any","source":"fair or old script"},
  {"id":"mt-1011","cat":"fair-not-gendered","type":"branch","persona":"Karthik","source":"back the shared norm","hook":"Your father-in-law tells your wife the investments are 'not her concern' and she should leave them to you.","steps":[{"prompt":"He says it at the dinner table, expecting you to agree. What do you do?","options":[{"text":"Say plainly that money here is something you both plan together","then":"Your father-in-law looks surprised you didn't just nod along.","best":true},{"text":"Stay quiet, to avoid contradicting an elder at the table","then":"Your silence reads as agreement, and the old norm sticks."},{"text":"Change the subject fairly quickly, to ease the tension","then":"The comment passes unanswered, and so does what it implies."},{"text":"Agree for now, planning to talk to her about it later","then":"Later comes, but the moment at the table is already gone."}],"why":"Backing a shared-money norm out loud is what actually changes it."},{"prompt":"Later, your wife brings up what happened at dinner. What do you say?","options":[{"text":"Ask how it felt, and say you'll back her every time","then":"She says it stung, and looks glad you asked.","best":true},{"text":"Say it's fine. You'll just keep handling it for both of you","then":"She nods, but she stops asking about the investments."},{"text":"Say it was just his generation talking, nothing to mind","then":"She looks away. \"It still mattered. It was about me.\""},{"text":"Say her father probably won't say it again anyway, really","then":"She says that isn't the point, and the evening goes quiet."}],"why":"Asking how it felt, and committing to back her, turns one moment into a pattern."},{"prompt":"At the next family gathering, her father brings it up again, more pointedly. What do you do?","options":[{"text":"Let her answer first, and back her plainly right after","then":"She speaks up, and doesn't have to stand there alone.","best":true},{"text":"Jump in quickly before she can say anything herself","then":"You answer for her, and she doesn't get the chance to speak."},{"text":"Avoid the topic entirely this time, to keep the peace","then":"His framing stands, unanswered, in front of the whole family."},{"text":"Pull her father aside privately instead, without her there","then":"It settles it quietly, but she isn't part of settling her own say."}],"why":"Letting her speak first, then backing her, makes the shared norm visible."},{"prompt":"A year on, at a family lunch, her father asks how the investments are going. What do you tell him?","options":[{"text":"Say it's for you both to answer, and turn to her","then":"She adds her view, and he listens without calling it 'not her concern'.","best":true},{"text":"Say you handle the details but keep her fully informed","then":"It sounds shared, but the decisions are still mostly yours."},{"text":"Say it's going fine, without really explaining how at all","then":"The vague answer lets him assume the old default is back."},{"text":"Say she's gotten quite good at it, actually, these days","then":"He chuckles. \"Good. Still, you'll keep an eye on it.\""}],"why":"Treating it as a question for you both, out loud, keeps the shared norm visible."}],"debrief":"Back a shared-money norm even when an elder pushes the gendered one.","relearn":"Money is a shared concern; back that norm even when an elder says it's 'not her concern'."},
  {"id":"mt-1012","cat":"fair-not-gendered","type":"branch","persona":"Sneha","source":"equal say, lower earn","hook":"You earn less than your partner, and you catch yourself staying quiet in money decisions because of it.","steps":[{"prompt":"A decision about savings comes up, and you feel the urge to just agree. What do you do?","options":[{"text":"Remind yourself your say is equal, and actually speak up","then":"Your point lands differently once you actually say it out loud.","best":true},{"text":"Nod along, since he's more invested financially right now","then":"The habit of staying quiet gets a little stronger."},{"text":"Wait to see what he decides before saying anything at all","then":"He decides, then asks what you think, and it's already settled."},{"text":"Agree out loud, but privately disagree with the whole plan","then":"The private disagreement never reaches the actual decision."}],"why":"Speaking up, even with a smaller income, keeps your real voice in it."},{"prompt":"He asks why you didn't say anything sooner about a decision you disagreed with. What do you say?","options":[{"text":"Say honestly you'd been assuming your say counted less","then":"He looks surprised. \"That was never the idea.\"","best":true},{"text":"Say you honestly didn't want to make a fuss over it","then":"He says it's no fuss at all, and the conversation ends there."},{"text":"Say you didn't want to seem like you were competing over income","then":"He reassures you about income, and the real reason stays unsaid."},{"text":"Say it really doesn't matter now anyway, so never mind","then":"He drops it, still not knowing why you went quiet."}],"why":"Naming the real reason, honestly, opens the door to actually fixing it."},{"prompt":"The next money decision comes up. What do you focus on?","options":[{"text":"Saying your view clearly, before he's already decided","then":"It becomes part of the decision, not a comment after it.","best":true},{"text":"Waiting to see his view first, out of old habit","then":"He shares his view first, and yours ends up matching it."},{"text":"Bringing up every past decision you'd quietly disagreed with","then":"It turns one moment into a long list, and loses focus."},{"text":"Saying your view, but softening it very heavily this time","then":"He hears it as a maybe, and goes with his plan."}],"why":"Speaking clearly, before the decision is made, is what an equal say looks like."}],"debrief":"A smaller paycheque is not a smaller say; speak up in the decisions.","relearn":"Earning less isn't a smaller say; remind yourself your voice is equal and use it."},
  {"id":"mt-1013","cat":"fair-not-gendered","type":"branch","persona":"any","source":"equal holders","hook":"You're setting up your first joint account, and the bank clerk assumes the husband's name should be primary.","steps":[{"prompt":"The clerk starts filling the form with his name first, without asking. What do you do?","options":[{"text":"Ask that you both choose the order, as full joint holders","then":"The clerk pauses, pen in the air, waiting for you both to decide.","best":true},{"text":"Let it go, since the form's probably just standard anyway","then":"The clerk keeps writing, his name going in first."},{"text":"Say nothing for now, planning to fix it later somehow","then":"You make a mental note, and the clerk moves on to your address."},{"text":"Ask the clerk why it has to be done that way","then":"The clerk shrugs it off as routine, and keeps writing."}],"why":"Choosing together, as full joint holders, sets the account up the way you actually run it."},{"prompt":"Before stamping the form, the clerk asks who should be able to operate the account. What do you do?","options":[{"text":"Say both of you, each able to operate it alone","then":"The clerk ticks the option that lets either of you use it.","best":true},{"text":"Say the first name can run it, since it's simpler","then":"The clerk sets it so only the first holder can operate it."},{"text":"Ask the clerk to just pick whatever is usual","then":"The clerk picks the usual setting, without explaining what it means."},{"text":"Say you'll come back another day with more time to spare","then":"You leave with the form half done, and his name still first."}],"why":"Letting either of you operate it keeps you both full, equal holders in practice."},{"prompt":"Months later, a cousin opening a joint account with her husband asks whose name should go first. What do you say?","options":[{"text":"Say to choose the order together, and ask that either can operate it","then":"She writes it down, glad to know what to ask for.","best":true},{"text":"Tell her the husband's name first is just how it's done","then":"She nods, and plans to go with the default."},{"text":"Say the bank will sort it out, so not to worry","then":"She shrugs, and plans to take whatever the clerk suggests."},{"text":"Tell her the whole story of your own visit to the bank","then":"She laughs along, but still isn't sure what to ask for."}],"why":"Telling her plainly what to ask for passes the fair setup on."}],"debrief":"Set accounts up as equal holders, not by a gendered default.","relearn":"Don't let a gendered default decide whose name is primary; set both up as equal holders."},
  {"id":"mt-1014","cat":"fair-not-gendered","type":"branch","persona":"any","source":"no need to justify","hook":"Your partner runs the home full-time and feels she must 'justify' every rupee she spends on herself.","steps":[{"prompt":"She mentions it quietly, almost apologising for even saying it. What do you say first?","options":[{"text":"Say her unpaid work gives her an equal stake, no permission needed","then":"Something in her shoulders eases, hearing it said plainly.","best":true},{"text":"Say you'll set her a fixed amount so it's simpler for everyone","then":"A fixed amount still means asking, just for a bigger number."},{"text":"Say she's probably overthinking it. It's honestly not a big deal","then":"The feeling gets waved off instead of actually heard."},{"text":"Ask her to just tell you before she spends, from now on","then":"It turns into exactly the justifying she was describing."}],"why":"Naming her equal stake, plainly, is what she actually needed to hear."},{"prompt":"A few days later, she hesitates before buying something small for herself. What do you do?","options":[{"text":"Notice the hesitation, and say out loud she needn't check first","then":"The hesitation visibly loosens.","best":true},{"text":"Say nothing and just let her decide entirely on her own","then":"Silence doesn't undo a habit built over a long time."},{"text":"Offer to buy it for her instead, just to make it easy","then":"It's kind, but it still routes her own spending through you."},{"text":"Ask what she was thinking of getting this time","then":"The question, meant kindly, still feels like a check-in."}],"why":"Naming the habit out loud, gently, helps her actually stop checking first."},{"prompt":"Her mother visits and asks how much 'pocket money' she gets these days. What do you say?","options":[{"text":"Say plainly there's no pocket money, just a shared household stake","then":"Her mother looks surprised, then thoughtful.","best":true},{"text":"Say she gets a generous amount, actually, more than most","then":"'Generous' still frames it as something given, not shared."},{"text":"Let your partner answer, since it's really her question anyway","then":"It leaves her fielding an awkward question that was never really hers to fix."},{"text":"Laugh and say she spends plenty. Don't worry about it","then":"The joke sidesteps the actual, unequal framing of the question."}],"why":"Naming it as a shared stake, not pocket money, corrects the framing directly."},{"prompt":"Months on, she buys something for herself without a second thought. What do you say?","options":[{"text":"Say nothing at all, and let it be completely ordinary","then":"It is completely ordinary, and nobody remarks on it.","best":true},{"text":"Praise her for finally not checking with you this time","then":"The praise, kindly meant, still frames it as an achievement, not a right."},{"text":"Ask what it was, purely out of friendly curiosity","then":"Innocent curiosity can still feel like the old checking, from her side."},{"text":"Mention how far you've both come with this, warmly","then":"Naming it turns an ordinary moment into a milestone it didn't need to be."}],"why":"Letting it pass unremarked is what an equal, ordinary stake looks like."}],"debrief":"A homemaker has an equal stake and needs no permission for ordinary spending.","relearn":"A homemaker shouldn't justify every rupee; her unpaid work earns an equal stake, no permission needed."},
  {"id":"mt-1015","cat":"fair-not-gendered","type":"branch","persona":"Karthik","source":"not a favour","hook":"At a family gathering, relatives praise you for 'letting' your wife work and keep her own salary.","steps":[{"prompt":"An uncle raises a toast to your 'generosity' as a husband. What do you say?","options":[{"text":"Say gently it's her right, not a favour you grant her","then":"The table goes quiet for a second, then someone changes topic.","best":true},{"text":"Accept the praise graciously and enjoy the moment fully","then":"The room's idea of a generous husband quietly gets reinforced."},{"text":"Laugh it off without correcting anything at the table","then":"The framing stands, unchallenged, in front of the whole family."},{"text":"Say your wife earns more than you anyway, so it's obvious","then":"It gives a different reason, but still frames it as needing justifying at all."}],"why":"Naming it as her right, plainly, corrects the framing without a scene."},{"prompt":"On the drive home, your wife asks what you made of the toast. What do you say?","options":[{"text":"Say her job was never yours to allow in the first place","then":"She smiles, glad you see it the way she does.","best":true},{"text":"Say it was nice of them, even if a bit old-fashioned","then":"She goes quiet, looking out of the window."},{"text":"Say you hope the uncle gets the message someday","then":"She shrugs. \"And until then, you're the generous one.\""},{"text":"Say you didn't want to embarrass anyone at the table","then":"She nods slowly, and changes the subject."}],"why":"Naming her job as her right, not yours to allow, tells her you see it as she does."},{"prompt":"At the next family event, the same uncle brings it up again. What do you do?","options":[{"text":"Say plainly it's her career, not your gift to give","then":"He blinks, then nods, and doesn't raise a toast to it again.","best":true},{"text":"Let it slide, to avoid a scene in front of everyone","then":"The uncle beams, and the story gets retold at the next event too."},{"text":"Ask your wife to handle it herself this time around","then":"It puts the correcting work back on her, in front of everyone."},{"text":"Joke that he's stuck in the old days, and move along","then":"The joke gets a laugh, and the actual framing goes uncorrected."}],"why":"Saying it plainly, calmly, is what actually corrects the framing."}],"debrief":"A partner working and keeping her salary is her right, not a favour granted.","relearn":"Don't take credit for 'letting' a partner work; her job and salary are her right, not your favour."},
  {"id":"mt-1016","cat":"fair-not-gendered","type":"branch","persona":"any","source":"split by skill","hook":"Splitting who does what with money, you're tempted to divide it 'his job / her job' by gender.","steps":[{"prompt":"The list is half written and you'd like to finish tonight. What do you do?","options":[{"text":"Pause, and split tasks by who's better or willing instead","then":"The list looks a little different once you actually think it through.","best":true},{"text":"Go with the gendered split, since it's simpler to decide today","then":"Simple now means one of you can't step in later."},{"text":"Give the 'big' money to one and household money to the other","then":"The old pattern gets a new name, but stays the same shape."},{"text":"Decide it by coin toss, just to skip the conversation","then":"The coin tosses go fast, and nobody asks who'd be good at what."}],"why":"Splitting by skill or willingness keeps you both capable, not locked in."},{"prompt":"One task, the insurance renewals, is something neither of you enjoys. What do you do?","options":[{"text":"Agree to take turns learning it together, instead of assigning it","then":"Neither of you dreads it alone, since it's genuinely shared.","best":true},{"text":"Assign it to whoever complains about it less","then":"It becomes a quiet chore for one person, resented over time."},{"text":"Leave it undecided for now, and revisit it some other day","then":"Undecided tasks tend to just not get done at all."},{"text":"Assign it by gender anyway, since it's an easy tiebreaker","then":"The old default sneaks back in exactly where it's easiest."}],"why":"Learning something neither of you enjoys, together, beats leaving it to whoever complains less."},{"prompt":"A relative asks who 'handles the money' in your house these days. What do you say?","options":[{"text":"Say it isn't about gender, and name who actually does what","then":"The relative looks mildly surprised, then moves on.","best":true},{"text":"Name whoever handles the bigger amounts, since that's simplest","then":"The answer sounds neutral, but it ranks one of you above the other."},{"text":"Say it's complicated and change the subject fairly quickly","then":"The relative shrugs, and assumes it's the husband."},{"text":"Say one of you handles it all, to keep the answer simple","then":"The relative nods, and the parts you share go unmentioned."}],"why":"Setting aside the gender question and naming the real split corrects the assumption."},{"prompt":"A year later, one of you needs to step in on something the other usually handles. What do you do?","options":[{"text":"Step in, and ask your partner to walk you through it","then":"It takes a little longer, and now you both know it.","best":true},{"text":"Wait for the other person to be free instead of trying","then":"Waiting delays something that actually needed doing now."},{"text":"Call in outside help rather than try to figure it out","then":"Outside help works, but it shows neither of you could step in."},{"text":"Muddle through alone rather than ask for a walkthrough","then":"It gets done, with a mistake that takes a week to fix."}],"why":"Asking to be walked through it means either of you can step in, whoever usually handles it."}],"debrief":"Divide money tasks by skill and willingness, never by gender.","relearn":"Split money work by who's better or willing, not 'his money / her money' by gender."},
  {"id":"mt-1017","cat":"fair-not-gendered","type":"branch","persona":"Karthik","source":"both learn it","hook":"Your partner suggests you handle all the finances 'because you're the man and that's how it's done'.","steps":[{"prompt":"She says it lightly, handing you the bank folder across the table. What do you do?","options":[{"text":"Suggest you both learn it together instead, so neither's stuck","then":"She looks relieved, more than you expected.","best":true},{"text":"Take the folder, since it is simpler if one person does it","then":"One person now holds all the knowledge, and all the risk."},{"text":"Take it, planning to slowly teach her all of it eventually","then":"Eventually keeps slipping, and the folder stays only with you."},{"text":"Suggest she handle it instead this time, just to be fair","then":"She takes the folder with a sigh, and now she's the one stuck."}],"why":"Learning it together protects you both from ever being left stuck."},{"prompt":"A few weeks later, an insurance renewal arrives, full of unfamiliar terms. What do you do?","options":[{"text":"Sit down together and work through it, slow as it is","then":"It takes the whole evening, and you both understand it after.","best":true},{"text":"Handle it alone tonight, since that's faster","then":"It's done fast, and only one of you knows how."},{"text":"Pay an agent to fill it in so neither of you has to learn","then":"It's done, and neither of you could do it next year."},{"text":"Put it off to an evening that's less busy for both","then":"The less busy evening keeps not quite arriving."}],"why":"Working through it together, even slowly, is what makes you both fluent."},{"prompt":"A year on, a bill will come due while you're away for work. What do you do before you leave?","options":[{"text":"Sit down with her and go through the bill before you leave","then":"It gets handled on time, and she knows the next one too.","best":true},{"text":"Leave instructions for her to call you if anything comes up","then":"She calls you twice in a meeting to ask where things are."},{"text":"Pay it early yourself, so she doesn't have to deal with it","then":"It's paid, and she still doesn't know where anything is."},{"text":"Assume it'll sort itself out somehow while you're away","then":"A late fee arrives before you do."}],"why":"Going through it with her before you leave means either of you can handle it."}],"debrief":"Both partners learning the money beats one doing it 'because he's the man'.","relearn":"Don't take it all on 'because you're the man'; both learning protects you both from being stuck."},
  {"id":"mt-1018","cat":"fair-not-gendered","type":"branch","persona":"Karthik","source":"own-name savings","hook":"Your wife earns and wants to start saving in her own name; an uncle says a wife's savings should sit under the husband.","steps":[{"prompt":"The uncle says it at a family lunch, expecting agreement from you. What do you do?","options":[{"text":"Say plainly that her own-name savings are healthy and normal","then":"The uncle looks mildly put out, but doesn't push further.","best":true},{"text":"Stay quiet, to avoid an argument with an elder at lunch","then":"The silence lets his version of 'normal' stand unchallenged."},{"text":"Say you'll discuss it with her privately later instead","then":"Later happens, but the moment at the table already passed."},{"text":"Half agree, saying you'll 'keep an eye on it together'","then":"'Keep an eye on it' quietly reframes her savings as shared oversight."}],"why":"Naming her own-name savings as healthy answers the old idea directly."},{"prompt":"Later, your wife asks what you really think about her saving in her own name. What do you say?","options":[{"text":"Say it's healthy, and her independence isn't disloyalty","then":"She looks steadier, hearing you say it plainly.","best":true},{"text":"Say it's fine, as long as the family doesn't find out","then":"She stiffens, hearing her savings treated as a secret."},{"text":"Say you're for it, as long as she checks with you before spending","then":"She pauses. \"Checks with you? It's my money.\""},{"text":"Say you're not sure it's wise, with the family watching","then":"She goes quiet, feeling more alone in it than before."}],"why":"Saying plainly it's healthy, not disloyal, makes your support clear to her."},{"prompt":"The uncle brings it up again at the next family gathering. What do you do?","options":[{"text":"Say calmly that it's healthy, then change the subject","then":"He grumbles, but drops it without a real fight.","best":true},{"text":"Avoid the topic entirely this time, hoping he forgets it","then":"He doesn't forget, and brings it up again next time too."},{"text":"Get visibly sharp with him for repeating it again","then":"It turns into a scene, and the actual point gets lost."},{"text":"Let your wife field it herself, since it's her savings","then":"It puts the work of defending her own choice on her, in front of everyone."}],"why":"Answering calmly, without escalation, settles a comment that keeps coming back."},{"prompt":"A few months later, she mentions her savings have grown steadily. What do you say?","options":[{"text":"Say that's great, and it's her footing to plan as she likes","then":"She smiles, hearing it stated as simply as it should be.","best":true},{"text":"Suggest moving some into a joint account now it's grown","then":"Her smile fades. \"I thought this one was mine.\""},{"text":"Ask exactly how much is in there now","then":"She tells you, a little guarded, as if reporting in."},{"text":"Joke that she's better with money than you are, these days","then":"She laughs, and the talk drifts off before anything real is said."}],"why":"Naming her savings as her own footing keeps the independence real, not just tolerated."}],"debrief":"A partner saving in her own name is healthy independence, not disloyalty.","relearn":"A wife's own-name savings are healthy footing; don't route them under the husband to please relatives."},
  {"id":"mt-1019","cat":"fair-not-gendered","type":"match","hook":"Match each gendered money line to the fair, even-handed reframe.","pairs":[{"left":"'You wouldn't get the finances'","right":"'Let's learn the finances together'"},{"left":"'I earn, so I decide'","right":"'We earn a shared life, so we decide'"},{"left":"'A wife just asks for money'","right":"'Each adult has their own to spend'"},{"left":"'Property goes in my name'","right":"'A shared home names us both'"},{"left":"'Saving is a woman's worry'","right":"'Saving is a habit we both build'"}],"relearn":"Every gendered money line has a fair reframe: learn together, decide together, each keeps their own, the home names both.","persona":"any","source":"line to reframe"},
  {"id":"mt-1020","cat":"fair-not-gendered","type":"match","hook":"Match each fair-money principle to a simple everyday example of it.","pairs":[{"left":"Skill is learned, not gendered","right":"Both partners read the bank app"},{"left":"Decisions are shared","right":"You okay the big buy together"},{"left":"Unpaid work has real value","right":"Her care work counts in the plan"},{"left":"Each keeps some footing","right":"Both have their own account"},{"left":"No one needs to ask permission","right":"Each spends their own freely"}],"relearn":"Fair-money principles are everyday acts: both read the app, okay big buys together, count care work, each keep an account and spend their own freely.","persona":"any","source":"principle to example"},
  {"id":"mt-1021","cat":"fair-not-gendered","type":"match","hook":"Match each partner's role to the equal claim it carries on the money.","pairs":[{"left":"The higher earner","right":"One vote, not a controlling one"},{"left":"The lower earner","right":"An equal vote, not a smaller one"},{"left":"The homemaker","right":"A real stake from unpaid work"},{"left":"The bill-tracker","right":"Say built from doing the work"},{"left":"Both partners","right":"Shared ownership of the plan"}],"relearn":"Every role has an equal claim: the higher earner one vote not control, the lower earner an equal vote, the homemaker a real stake, both shared ownership.","persona":"any","source":"role to claim"},
  {"id":"mt-1022","cat":"fair-not-gendered","type":"match","hook":"Match each gendered myth about money to why it doesn't hold up.","pairs":[{"left":"Men are born better with money","right":"It's a learned skill, not a trait"},{"left":"The earner should rule the money","right":"A shared life is decided jointly"},{"left":"A homemaker is a dependent","right":"Unpaid work is real economic value"},{"left":"Women are bad at investing","right":"Anyone willing can learn to invest"},{"left":"The man's name leads on assets","right":"Both belong on a shared asset"}],"relearn":"Each gendered myth fails: skill is learned, a shared life decides jointly, home work is real value, anyone can invest.","persona":"any","source":"myth to why"},
  {"id":"mt-1023","cat":"fair-not-gendered","type":"match","hook":"Match each fair-money habit to the gendered habit it replaces.","pairs":[{"left":"Both partners know the passwords","right":"Only one holds all the access"},{"left":"Big spends decided together","right":"The earner decides alone"},{"left":"Both names on the home","right":"One name on everything"},{"left":"Each keeps their own account","right":"A doled-out allowance"},{"left":"Tasks split by skill","right":"Tasks split by gender"}],"relearn":"Fair habits replace gendered ones: both know the passwords, decide big spends together, both names on the home, each keeps an account, tasks by skill.","persona":"any","source":"fair replaces gendered"},
  {"id":"mt-1024","cat":"fair-not-gendered","type":"match","hook":"Match each everyday money skill to who can do it in a fair home.","pairs":[{"left":"Reading the bank statement","right":"Either partner, it's just reading"},{"left":"Negotiating a big purchase","right":"Whoever's better at it, by skill"},{"left":"Planning the monthly budget","right":"Both, sitting down together"},{"left":"Tracking small daily spends","right":"Anyone who wants to track them"},{"left":"Choosing an investment","right":"Both, after learning together"}],"relearn":"In a fair home every money skill is open to either partner: reading, negotiating, budgeting, tracking and investing go by skill and willingness, not gender.","persona":"any","source":"skill to doer"},
  {"id":"mt-1025","cat":"fair-not-gendered","type":"match","hook":"Match each money decision to the fair basis it should rest on.","pairs":[{"left":"How much to save this year","right":"The goals you both agreed"},{"left":"Whether to make a big buy","right":"What the budget can carry"},{"left":"Who handles which money task","right":"Skill and willingness, not gender"},{"left":"How the home is owned","right":"Both partners belonging on it"},{"left":"What each spends on themselves","right":"Each adult's own fair share"}],"relearn":"Fair money rests on fair bases: agreed goals, what the budget carries, skill for tasks, both belonging on what's owned, and each adult's own share.","persona":"any","source":"decision to basis"},
  {"id":"mt-1026","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a fair home asks 'who's better at this?', never 'whose job is this by gender?'. Sit with that?","prompt":"What comes up for you?","options":["Who's better, not gender","Makes sense","Still thinking"],"affirm":"Fair money splits the work by skill and willingness, not by a gendered idea of whose job it is.","relearn":"Fair money asks who's better at a task, not whose job it is 'by gender'.","persona":"any","source":"who's better"},
  {"id":"mt-1027","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a smaller paycheque is never a smaller seat at the table. How does that land for you?","prompt":"Your honest take?","options":["A smaller pay isn't a smaller say","True","I'm not sure"],"affirm":"In fair money, a smaller income still carries a full, equal say in the decisions.","relearn":"A smaller income is still a full, equal say; pay doesn't size the seat at the table.","persona":"Sneha","source":"smaller pay, full seat"},
  {"id":"mt-1028","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: the unpaid cooking, care and running of a home is real economic value, even with no payslip. Resonate?","prompt":"What do you feel?","options":["Real value, no payslip","Resonates","Mixed feelings"],"affirm":"Unpaid home and care work is real economic value, and the partner doing it is an equal, not a dependent.","relearn":"Unpaid home and care work is real value; a homemaker is an equal partner, not a dependent.","persona":"any","source":"value without a payslip"},
  {"id":"mt-1029","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: 'who earns it' and 'who controls it' are two different questions, and a fair home keeps them apart. Clear?","prompt":"What's your read?","options":["Two different questions","Clear","Need a beat"],"affirm":"Earning the money and controlling the money are separate; a fair home shares control whatever the incomes.","relearn":"Earning the money and controlling it are different questions; a fair home shares control whatever the incomes.","persona":"any","source":"earn vs control"},
  {"id":"mt-1030","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: in fair money you're a partner who stays in the picture, not someone the other manages. Does that sit right?","prompt":"How does it land?","options":["Partner, not manager","Sits right","Hmm"],"affirm":"In a fair home both partners stay in the money picture; neither becomes a manager the other reports to.","relearn":"Fair money keeps both in the picture; a partner isn't a manager the other reports to.","persona":"Pooja","source":"partner not manager"},
  {"id":"mt-1031","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: questioning a gendered money habit isn't disrespecting your family, it's just asking for fair. Agree?","prompt":"What's your view?","options":["Asking fair isn't disrespect","Agree","Unsure"],"affirm":"Asking for a fairer money setup is a reasonable request, not a betrayal of family or tradition.","relearn":"Asking for fairer money isn't disrespect; it's a reasonable request, not a betrayal of family.","persona":"Pooja","source":"fair isn't disrespect"},
  {"id":"mt-1032","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: there's no 'man's money' and 'woman's money' in a shared life, just our money, run together. Resonate?","prompt":"Your gut take?","options":["Just our money","Resonates","Still mulling"],"affirm":"In a shared life there's no gendered 'his' and 'hers' over the household money; it's run together.","relearn":"A shared life has no 'man's money' and 'woman's money', just our money, run together.","persona":"any","source":"just our money"},
  {"id":"mt-1033","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: 'he's the head of the family' can describe respect without meaning he owns the bank. Make sense?","prompt":"What do you think?","options":["Respect, not ownership","Makes sense","Not quite"],"affirm":"Family respect doesn't require one person to own and control the money; respect and shared control can coexist.","relearn":"'Head of the family' can mean respect, not owning the money; respect and shared control coexist.","persona":"any","source":"respect not ownership"},
  {"id":"mt-1034","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered money lines hiding among the fair ones.","scene":[{"id":"a","text":"'Let's both check the statement'","trick":false},{"id":"b","text":"'Numbers aren't a woman's thing'","trick":true},{"id":"c","text":"'We pick the big buys together'","trick":false},{"id":"d","text":"'Just leave the money to me'","trick":true},{"id":"e","text":"'Your pay counts like mine'","trick":false}],"why":"'Numbers aren't a woman's thing' and 'just leave the money to me' are the gendered lines; the rest are fair.","relearn":"Fair money checks the statement together and counts both incomes; 'numbers aren't a woman's thing' or 'leave it to me' are gendered.","persona":"any","source":"spot gendered lines"},
  {"id":"mt-1035","cat":"fair-not-gendered","type":"spot","hook":"Spot the two excuses that use gender to grab the final say.","scene":[{"id":"a","text":"'We agreed this goal together'","trick":false},{"id":"b","text":"'I'm the man, so I decide'","trick":true},{"id":"c","text":"'It fits the budget we set'","trick":false},{"id":"d","text":"'A wife shouldn't question this'","trick":true},{"id":"e","text":"'We both okayed the plan'","trick":false}],"why":"'I'm the man, so I decide' and 'a wife shouldn't question this' use gender to grab the say; the rest rest on agreement.","relearn":"Decisions should rest on agreement and the budget; 'I'm the man, so I decide' or 'a wife shouldn't question' grab the say by gender.","persona":"any","source":"spot the gendered grab"},
  {"id":"mt-1036","cat":"fair-not-gendered","type":"spot","hook":"Spot the two setups that quietly lock one partner out by gender.","scene":[{"id":"a","text":"Both names on the joint account","trick":false},{"id":"b","text":"Only his name on every asset","trick":true},{"id":"c","text":"Both learn the investments","trick":false},{"id":"d","text":"She must ask for each rupee","trick":true},{"id":"e","text":"Goals set by both each year","trick":false}],"why":"'Only his name on every asset' and 'she must ask for each rupee' lock a partner out by gender; the rest don't.","relearn":"Both names, both learning and shared goals keep a partner in; one name on assets or 'ask for each rupee' lock her out.","persona":"Pooja","source":"spot the lock-out"},
  {"id":"mt-1037","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered assumptions an in-law might drop into a money chat.","scene":[{"id":"a","text":"'You two should plan this together'","trick":false},{"id":"b","text":"'Property stays in the son's name'","trick":true},{"id":"c","text":"'Both of you should know the loan'","trick":false},{"id":"d","text":"'Daughters get gold, not the land'","trick":true},{"id":"e","text":"'Either of you can handle the bank'","trick":false}],"why":"'Property stays in the son's name' and 'daughters get gold, not the land' are the gendered assumptions; the rest are fair.","relearn":"Planning together and both knowing the loan are fair; 'property to the son' or 'daughters get gold, not land' are gendered.","persona":"Razia","source":"spot the in-law myth"},
  {"id":"mt-1038","cat":"fair-not-gendered","type":"spot","hook":"Spot the two lines that treat a homemaker as 'lesser' rather than an equal.","scene":[{"id":"a","text":"'Your home work counts in our plan'","trick":false},{"id":"b","text":"'You don't earn, so it's my call'","trick":true},{"id":"c","text":"'You have an equal say in this'","trick":false},{"id":"d","text":"'You should account for what you spend'","trick":true},{"id":"e","text":"'This is our money, not just mine'","trick":false}],"why":"'You don't earn, so it's my call' and 'account for what you spend' treat a homemaker as lesser; the rest treat her as equal.","relearn":"Counting her work, an equal say and 'our money' treat a homemaker as equal; 'you don't earn' or 'account for it' make her lesser.","persona":"any","source":"spot the 'lesser'"},
  {"id":"mt-1039","cat":"fair-not-gendered","type":"spot","hook":"Spot the two money habits that split the home by gender instead of by skill.","scene":[{"id":"a","text":"Bills go to whoever tracks best","trick":false},{"id":"b","text":"'Big money' is always the husband's","trick":true},{"id":"c","text":"Both sit down for the budget","trick":false},{"id":"d","text":"'Household cash' is only the wife's","trick":true},{"id":"e","text":"Either partner can do the bank run","trick":false}],"why":"'Big money is always the husband's' and 'household cash is only the wife's' split the home by gender; the rest don't.","relearn":"Bills by skill and budgeting together are fair; 'big money is the husband's' or 'household cash is the wife's' split by gender.","persona":"any","source":"spot the gender split"},
  {"id":"mt-1040","cat":"fair-not-gendered","type":"spot","hook":"Spot the two phrases that frame a wife's independence as a favour rather than a right.","scene":[{"id":"a","text":"'Your salary is yours to keep'","trick":false},{"id":"b","text":"'I let you keep your own account'","trick":true},{"id":"c","text":"'Your work is your own choice'","trick":false},{"id":"d","text":"'I allow you to work, so be grateful'","trick":true},{"id":"e","text":"'We're equal partners in this'","trick":false}],"why":"'I let you keep your account' and 'I allow you to work' frame her independence as a favour; the rest treat it as her right.","relearn":"A partner's salary and work are her right; 'I let you keep your account' or 'I allow you to work' wrongly make them a favour.","persona":"Karthik","source":"spot the 'favour'"},
  {"id":"mt-1041","cat":"fair-not-gendered","type":"spot","hook":"Spot the two beliefs that tie money sense to gender instead of to learning.","scene":[{"id":"a","text":"Anyone can learn to budget well","trick":false},{"id":"b","text":"'Men are just born better with money'","trick":true},{"id":"c","text":"Investing is a skill you practise","trick":false},{"id":"d","text":"'Women are too emotional to invest'","trick":true},{"id":"e","text":"Both partners can grow their literacy","trick":false}],"why":"'Men are born better with money' and 'women are too emotional to invest' tie money sense to gender; the rest tie it to learning.","relearn":"Money sense comes from learning; 'men are born better' or 'women are too emotional to invest' wrongly tie it to gender.","persona":"any","source":"spot the born-with-it myth"},
  {"id":"mt-1042","cat":"fair-not-gendered","type":"role-play","persona":"Pooja","source":"our department","hook":"Your husband says, 'Don't worry about the investments. That's my department.'","setup":"He says it over breakfast, half joking.","steps":[{"prompt":"He adds: \"Honestly, it's easier if I just handle it myself.\"","options":[{"text":"\"Let's learn the investments together, so it's ours.\"","then":"He looks a little surprised, then thoughtful.","best":true},{"text":"\"Okay, you handle it then. That's totally fine by me.\"","then":"\"Great,\" he says, relieved it's settled his way."},{"text":"\"You never let me near any of it at all. You know that.\"","then":"He gets defensive. \"That's not fair. You never asked.\""},{"text":"\"Fine, but tell me the important bits sometimes, okay.\"","then":"\"Sure,\" he says, though the 'sometimes' rarely quite arrives."}],"why":"Asking to learn it together turns 'my department' into 'ours', warmly."},{"prompt":"Next week he says: \"The bank sent papers to renew an investment. I'll just sign, yes?\"","options":[{"text":"\"Let's look at it together before either of us signs.\"","then":"\"Fair enough,\" he says, and pulls up the papers.","best":true},{"text":"\"Sure, sign it. You know that stuff better.\"","then":"\"Done,\" he says, and you still don't know the terms."},{"text":"\"Just teach me the basics whenever you have time.\"","then":"\"Sure,\" he says, and signs it today anyway."},{"text":"\"You always decide without me. Why ask now?\"","then":"He sighs. \"I'm asking now, aren't I?\""}],"why":"Looking at a real decision together is the first concrete step to 'ours'."},{"prompt":"A month later, he says: \"My cousin says wives who ask about investments don't trust their husbands.\"","options":[{"text":"\"Asking isn't distrust. It's my money and future too.\"","then":"He nods slowly. \"When you put it like that, yes.\"","best":true},{"text":"\"Maybe he has a point. I'll stop asking so much.\"","then":"He looks relieved, and the papers stay on his side of the table."},{"text":"\"Your cousin should mind his own business.\"","then":"He bristles. \"He's family. He meant well.\""},{"text":"\"I only ask so you don't feel alone with it.\"","then":"\"That's sweet,\" he says, \"but I'm fine alone with it.\""}],"why":"Naming it as your own stake, not distrust, keeps 'ours' real."}],"relearn":"Asking to learn the investments together turns 'my department' into 'ours', kindly and clearly."},
  {"id":"mt-1043","cat":"fair-not-gendered","type":"role-play","persona":"Karthik","source":"both on the loan","hook":"You and your wife are taking a home loan, and relatives have views on who should handle it.","setup":"Over chai, a cousin leans in, laughing.","steps":[{"prompt":"The cousin says: \"Loan papers are so dry. Let the men deal with those.\"","options":[{"text":"\"We both go through the papers. It's on both of us.\"","then":"The cousin laughs it off, but the point lands.","best":true},{"text":"\"Yeah, I mostly handle that side of things for us.\"","then":"\"Makes sense,\" she says, and the assumption sticks."},{"text":"\"That's a bit of an old idea, isn't it?\"","then":"The cousin bristles. \"I didn't mean anything by it.\""},{"text":"\"She helps out with it whenever she has the time.\"","then":"The cousin smiles. \"Good of her to help you.\""}],"why":"Naming it as both your loan corrects the assumption without a fight."},{"prompt":"Later your wife says: \"I wish I'd answered that cousin myself.\"","options":[{"text":"\"Next time, you answer first, and I'll back you.\"","then":"She smiles. \"That would feel better.\"","best":true},{"text":"\"I'll just keep speaking up for both of us from now on.\"","then":"She frowns. \"That's not really what I meant.\""},{"text":"\"I didn't think it mattered who answered.\"","then":"\"It matters to me,\" she says quietly."},{"text":"\"The cousin probably won't bring it up again anyway.\"","then":"\"That's not the point,\" she says, and lets it drop."}],"why":"Letting her answer first, with your backing after, keeps it genuinely shared."},{"prompt":"At the bank, the officer says: \"Sir, if you could just confirm these details.\"","options":[{"text":"\"Actually, she can answer that. It's her loan too.\"","then":"The officer adjusts, and starts addressing you both evenly.","best":true},{"text":"\"I'll answer for both of us, to keep things moving.\"","then":"\"Thank you, sir,\" the officer says, and keeps his eyes on you."},{"text":"\"Ask her. I don't really follow the loan details.\"","then":"The officer turns to her, and you sit back out of it."},{"text":"\"You should really be asking her these questions.\"","then":"The officer flushes, apologises, and the rest of the meeting is stiff."}],"why":"Redirecting questions to her keeps the paperwork visibly shared, not just legally shared."},{"prompt":"Months later, while you're away, your wife asks on the phone: \"Should I sort out this loan issue myself?\"","options":[{"text":"\"Yes, go ahead. Call me if you want a second view.\"","then":"She sorts it directly, and texts you when it's done.","best":true},{"text":"\"No, wait till I'm back. I usually deal with the bank.\"","then":"\"Okay,\" she says, and the issue sits for a week."},{"text":"\"Let me talk you through exactly what to say.\"","then":"She follows your script word for word, and it gets sorted."},{"text":"\"Ask your cousin's husband. He knows banks.\"","then":"She pauses. \"I can do it myself, you know.\""}],"why":"Trusting her to handle it, with support if she wants it, keeps the loan truly shared."}],"relearn":"'We both go through the papers' backs your partner and keeps the big loan a shared, known thing."},
  {"id":"mt-1044","cat":"fair-not-gendered","type":"role-play","persona":"any","source":"not a demand","hook":"Your partner earns less than you, and the two of you are drawing up a savings plan.","setup":"Over dinner, she goes quiet when the plan comes up.","steps":[{"prompt":"She says: \"I earn less. I shouldn't really demand a say in this.\"","options":[{"text":"\"Your say isn't a demand. It's equal. Let's plan as a pair.\"","then":"She looks a little steadier, hearing it named that plainly.","best":true},{"text":"\"It's fine. I'll just decide the savings this time, okay.\"","then":"\"Okay,\" she says quietly, and the plan becomes only yours."},{"text":"\"You should speak up more, you know, in general.\"","then":"She flushes. \"I'm trying to.\""},{"text":"\"We can talk about it whenever you're ready to, no rush.\"","then":"\"Okay,\" she says, and the topic slides away for now."}],"why":"Naming her say as equal, not a demand, is what actually reassures her."},{"prompt":"A few days later, she asks: \"If we did plan it together, where would we even start?\"","options":[{"text":"\"Let's start with what we're both actually saving toward.\"","then":"\"Okay,\" she says, and starts listing things she actually wants.","best":true},{"text":"\"Whatever you think, really. You decide.\"","then":"She blinks. \"That's not together either.\""},{"text":"\"Let's just keep doing what we've been doing.\"","then":"\"So, your plan, then,\" she says quietly."},{"text":"\"I already have a rough plan. We can just start there.\"","then":"\"Oh. Okay,\" she says, and waits to hear it."}],"why":"Starting from a shared question puts the plan on equal footing from the start."},{"prompt":"A month later, a shared goal needs revisiting. She says: \"Where are we actually at with the savings plan?\"","options":[{"text":"\"Let's open it up and check it together now.\"","then":"She nods, and pulls her chair closer to see.","best":true},{"text":"\"I've mostly kept up with it. Don't worry about it.\"","then":"\"I'd still like to see it,\" she says."},{"text":"\"It's basically the same as before. Nothing's changed.\"","then":"\"Same as before,\" she repeats, and goes quiet."},{"text":"\"I haven't looked at it much lately, sorry.\"","then":"\"So no one's watching it?\" she asks."}],"why":"Checking it together, then and there, keeps her say in the plan real."}],"relearn":"Telling a lower-earning partner their say is equal, not a demand, keeps the plan a true pair's plan."},
  {"id":"mt-1045","cat":"fair-not-gendered","type":"role-play","persona":"Sneha","source":"each keep our own","hook":"An uncle has firm views on what a wife should do with her salary.","setup":"At a family lunch, he turns to you, not unkindly.","steps":[{"prompt":"He says: \"A good wife hands it all over, keeps things simple.\"","options":[{"text":"\"In our home we each keep our own and plan together.\"","then":"He pauses, not expecting a calm, ready answer.","best":true},{"text":"\"Maybe. Every family's different, I suppose.\"","then":"\"Exactly,\" he says, hearing agreement where there wasn't much."},{"text":"\"That sounds a bit outdated, if I'm being fair.\"","then":"He gets prickly. \"It's tradition, not outdated.\""},{"text":"\"We do things our own way. Don't worry about it too much.\"","then":"\"Your own way,\" he repeats, not convinced."}],"why":"A calm, specific 'we each keep our own' answers the line without a clash."},{"prompt":"He asks: \"If a wife keeps her own salary, won't her husband feel she doesn't trust him?\"","options":[{"text":"\"Trust is planning together, not holding the salary.\"","then":"\"Huh,\" he says, like it's a genuinely new idea to him.","best":true},{"text":"\"Maybe a little. Some husbands might feel that way.\"","then":"He nods, and the trust worry starts to sound reasonable."},{"text":"\"With respect, Uncle, that's really none of your concern.\"","then":"His face stiffens, and he turns to talk to someone else."},{"text":"\"Ha, then the husband should hand his salary over too!\"","then":"Everyone laughs, and his question goes unanswered."}],"why":"Separating trust from who holds the salary answers his real worry directly."},{"prompt":"On the way home, your partner asks: \"Do you think anything you said reached him?\"","options":[{"text":"\"Maybe not today. I'll keep saying it, calmly and plainly.\"","then":"Your partner squeezes your hand. \"Then I'll say it too.\"","best":true},{"text":"\"I doubt it. He's too stubborn to change.\"","then":"\"Probably,\" your partner sighs, and the topic drops."},{"text":"\"I was only trying to keep the peace, really.\"","then":"\"Keeping the peace, or keeping quiet?\" your partner asks."},{"text":"\"Next time, I'll just skip lunches with that side of the family.\"","then":"Your partner frowns. \"Skip family over one uncle?\""}],"why":"Saying it calmly and plainly, again and again, is what shifts an old idea over time."}],"relearn":"A calm 'we each keep our own and plan together' answers the 'good wife hands it over' line without a clash."},
  {"id":"mt-1046","cat":"fair-not-gendered","type":"role-play","persona":"Karthik","source":"no reason owed","hook":"Your wife hesitates every time she spends on her new hobby.","setup":"She brings it up one evening, a little sheepish.","steps":[{"prompt":"She says: \"I keep thinking I shouldn't spend on this, since I earn less.\"","options":[{"text":"\"You don't owe a reason. Your spending is yours, like mine.\"","then":"She looks relieved. \"You really mean that?\"","best":true},{"text":"\"Sure, just keep it on the small side. That seems fine.\"","then":"\"Small. Right,\" she says, and her face falls a little."},{"text":"\"That makes sense. Maybe cut back a little, just for now.\"","then":"She nods quickly. \"I thought so.\""},{"text":"\"It's fine. Don't worry about it so much.\"","then":"\"I do worry, though,\" she says quietly."}],"why":"Naming that she owes no one a reason answers the guilt directly, not around it."},{"prompt":"She asks: \"Isn't it only fair that whoever earns less spends less?\"","options":[{"text":"\"No. Fair is both of us having room, not spending by salary.\"","then":"She nods slowly. \"I've never thought of it that way.\"","best":true},{"text":"\"A bit, maybe. But don't worry about it.\"","then":"\"So it is unfair,\" she says, and looks down."},{"text":"\"You're right. Maybe spend a little less than me, then.\"","then":"\"Okay,\" she says, and starts working out how much less."},{"text":"\"I earn more, so let me pay for your hobby.\"","then":"\"That's sweet,\" she says, \"but then it's still your money.\""}],"why":"Fair isn't matching amounts. It's both of you having room, whoever earns more."},{"prompt":"The next month she says, pleased: \"I got something for my hobby today.\"","options":[{"text":"\"Oh nice, what did you get?\"","then":"She grins and pulls it out to show you.","best":true},{"text":"\"Proud of you for finally spending on yourself!\"","then":"She laughs, a bit awkward. \"It's not that big a deal.\""},{"text":"\"How much did that set you back?\"","then":"Her smile dims. \"Not much. Why?\""},{"text":"\"Sounds good.\"","then":"She nods. \"Good. I wasn't sure you'd mind.\""}],"why":"Asking about the hobby, not the cost or your approval, treats her spending as ordinary."},{"prompt":"Later, your friend Vikram asks: \"So how do you two split spending money?\"","options":[{"text":"\"I think we both deserve room to spend, whatever we each earn.\"","then":"\"That's fair,\" Vikram says. \"I might borrow that idea.\"","best":true},{"text":"\"I just don't make a big deal of whatever she spends.\"","then":"\"Big of you,\" Vikram says, \"letting her spend.\""},{"text":"\"She's careful with money, so it's never really an issue.\"","then":"\"So she keeps it low for you?\" Vikram asks."},{"text":"\"We don't really talk about it much.\"","then":"\"Huh. And that works?\" Vikram asks."}],"why":"Saying you both deserve room, whatever you earn, names the equal footing plainly."}],"relearn":"Telling a lower-earning partner she needn't justify her own spending honours her equal stake."},
  {"id":"mt-1047","cat":"fair-not-gendered","type":"role-play","persona":"Karthik","source":"her choice","hook":"Your wife kept her job after marriage, and relatives keep remarking on it.","setup":"At a wedding, an aunt pats your arm, beaming.","steps":[{"prompt":"She says: \"So good of you, letting her keep her job and her salary.\"","options":[{"text":"\"It's her choice and career, not mine to allow.\"","then":"The relative blinks, adjusting the word in her head.","best":true},{"text":"\"Haha, yes, I'm a modern husband. What can I say.\"","then":"\"So modern!\" she says, patting your arm."},{"text":"\"She works very hard for it. I'll give her that.\"","then":"\"Such a hard worker,\" she agrees, beaming at you."},{"text":"\"I don't really see it as a big deal either way.\"","then":"\"You are too modest,\" she says, still beaming at you."}],"why":"Naming it as her choice, not your permission, reframes it directly."},{"prompt":"She adds: \"Not every husband would be so easy about it. You're a rare one.\"","options":[{"text":"\"It shouldn't be rare. It's her call, and I back her.\"","then":"\"Hm,\" she says, and actually seems to think about it.","best":true},{"text":"\"Ha, I suppose I am one of the good ones.\"","then":"She laughs, and the 'good husband' praise keeps flowing."},{"text":"\"Well, someone has to be supportive, right?\"","then":"She nods warmly, as if support were a favour you're doing."},{"text":"\"Maybe other husbands should think about it more.\"","then":"She stiffens. \"Well, every family is different.\""}],"why":"Saying it was always her call answers the praise without taking credit."},{"prompt":"Later, your wife asks: \"What was that relative saying about my job?\"","options":[{"text":"\"That I 'allow' you to work. As if it's mine to allow.\"","then":"She laughs. \"Exactly. Thank you for seeing that.\"","best":true},{"text":"\"Just that I'm a supportive husband. Nothing much.\"","then":"She raises an eyebrow. \"Supportive, or permitting?\""},{"text":"\"Oh, the usual wedding gossip. Nothing important.\"","then":"\"About my job?\" she says, and waits for more."},{"text":"\"Nothing to worry about. I'll deal with my relatives.\"","then":"\"I'd still like to know,\" she says, a little hurt."}],"why":"Naming the 'allowing' frame to her, and rejecting it, shows you see her job as hers."}],"relearn":"Reframing 'allowing' her to work as 'her choice, I just back her' keeps her independence as a right."},
  {"id":"mt-1048","cat":"fair-not-gendered","type":"role-play","persona":"Karthik","source":"share the budget","hook":"Your mother has firm ideas about who should run a household's budget.","setup":"She's visiting for the weekend and sees your wife doing the accounts.","steps":[{"prompt":"She says: \"Leave the household accounts to her. That's not a man's job.\"","options":[{"text":"\"We run the budget together. It's lighter that way.\"","then":"She raises an eyebrow, clearly not expecting that answer.","best":true},{"text":"\"You're right. I'll leave that to her, as always.\"","then":"\"Good,\" she says, satisfied the old order still holds."},{"text":"\"That's a pretty old-fashioned way to think about it.\"","then":"She stiffens. \"Old-fashioned? I raised you on it.\""},{"text":"\"I help out when she needs it, mostly, when she asks.\"","then":"\"Good, you help her,\" she says, pleased."}],"why":"Naming it as genuinely shared, kindly, answers the old idea without a fight."},{"prompt":"She says: \"Households have always worked this way, you know.\"","options":[{"text":"\"Maybe, but planning it together each month is lighter.\"","then":"\"Every month?\" she asks, turning the idea over.","best":true},{"text":"\"I know. I mostly leave the details to her.\"","then":"\"As it should be,\" she says, nodding."},{"text":"\"Maybe so. She's naturally better at it than me anyway.\"","then":"\"See? It's her department,\" she says, satisfied."},{"text":"\"Maybe so. I could just look over her figures sometimes.\"","then":"\"That's sensible,\" she says. \"A husband should keep an eye.\""}],"why":"Describing a real monthly sit-down together is what makes 'together' concrete."},{"prompt":"That night, your wife asks: \"Do you think your mother's right about the budget?\"","options":[{"text":"\"No. It's our household, so the budget should be ours.\"","then":"She smiles. \"Then let's make sure it is.\"","best":true},{"text":"\"Partly. You are better at the details than me.\"","then":"She sighs. \"Better, or just the one who always does it?\""},{"text":"\"She's from another generation. Let's not argue with her.\"","then":"\"I didn't ask you to argue,\" she says. \"I asked what you think.\""},{"text":"\"It doesn't matter what she thinks, really.\"","then":"\"It matters what you think,\" she says, and waits."}],"why":"Saying plainly the budget is both of yours tells her where you stand."},{"prompt":"At the next visit, your mother says: \"She looks tired. Is the budget getting too much for her?\"","options":[{"text":"\"It shouldn't all be on her. It's ours to carry.\"","then":"Your mother pauses. \"Well. As long as it gets done.\"","best":true},{"text":"\"She manages. It's what she's good at.\"","then":"\"She's a good wife,\" your mother says, and the load stays hers."},{"text":"\"Maybe you could give her some tips, Amma.\"","then":"Your mother brightens, and plans a long talk with her."},{"text":"\"I'll hire someone to do the accounts for her.\"","then":"\"How generous,\" she says, and managing it is still her job."}],"why":"Taking your share of the budget answers the worry by sharing the load, not shifting it."},{"prompt":"A newly married cousin asks: \"Should the husband help with the household budget?\"","options":[{"text":"\"Not help. Share it. Sit down together each month.\"","then":"She writes it down, like it's more useful than she expected.","best":true},{"text":"\"Only if the wife asks him for help with it.\"","then":"\"So it's still her job, then,\" she says slowly."},{"text":"\"My mother would say no, so maybe not.\"","then":"She laughs, but looks unsure what she'll do."},{"text":"\"Whatever works for them. Every couple is different.\"","then":"She nods, no clearer than before she asked."}],"why":"Sharing it, not 'helping', with a simple monthly sit-down is advice she can use."}],"relearn":"'We run the budget together' shares a load that gender tries to hand to one partner alone."},
  {"id":"mt-1049","cat":"fair-not-gendered","type":"sort","hook":"Sort each money move: fair to both partners, or unfair and gendered?","items":[{"id":"a","text":"Both okay a big purchase first"},{"id":"b","text":"'I'll decide, I wear the pants'"},{"id":"c","text":"Each has their own spending money"},{"id":"d","text":"'Hand me your salary each month'"},{"id":"e","text":"You review the budget as a pair"},{"id":"f","text":"'A wife needn't know our savings'"}],"bins":[{"id":"fair","label":"Fair to both","valence":"pos"},{"id":"unfair","label":"Unfair / gendered","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Okaying big buys together and each having their own are fair; 'I wear the pants', 'hand me your salary' and 'a wife needn't know' are gendered.","persona":"any","source":"fair or gendered move"},
  {"id":"mt-1050","cat":"fair-not-gendered","type":"match","hook":"Match each gendered money worry to the fair reassurance for it.","pairs":[{"left":"'I earn less, do I get a say?'","right":"Yes, your say is fully equal"},{"left":"'I'm home all day, am I a burden?'","right":"No, your work is real value"},{"left":"'Should he hold all the money?'","right":"No, you both should know it"},{"left":"'Is wanting my own account selfish?'","right":"No, it's healthy footing"},{"left":"'Can I learn the finances too?'","right":"Yes, the skill is learnable"}],"relearn":"Each gendered worry has a fair answer: a lower earner's say is equal, a homemaker's work is real value, an own account is healthy.","persona":"any","source":"worry to reassurance"},
  {"id":"mt-1080","cat":"money-talk","type":"strike-rewrite","hook":"\"A real man just provides; he shouldn't have to discuss money with his wife.\"","myth":{"un":"A real man just provides; he shouldn't have to discuss money with his wife.","re":"Providing and talking openly aren't opposites; sharing the money picture is part of caring for a partner.","why":"Care includes letting her see the whole picture."},"relearn":"Providing isn't a reason to stay silent; talking money openly is part of caring for a partner.","persona":"Karthik","source":"provider can talk too"},
  {"id":"mt-1081","cat":"money-talk","type":"strike-rewrite","hook":"\"Bringing up money will make me look greedy or like I don't trust them.\"","myth":{"un":"Bringing up money will make me look greedy or like I don't trust them.","re":"Wanting an honest money talk is responsible, not greedy; clarity is a sign of trust being built, not doubted.","why":"Openness grows trust; silence lets doubt grow."},"relearn":"Asking for an honest money talk is responsible, not greedy; it builds trust rather than doubting it.","persona":"Sneha","source":"not greedy"},
  {"id":"mt-1082","cat":"money-talk","type":"strike-rewrite","hook":"\"We'll deal with money once we're actually married; no need before.\"","myth":{"un":"We'll deal with money once we're actually married; no need before.","re":"Talking incomes, debts and goals before the wedding spares painful surprises after it; early is kindest.","why":"Surprises after the vows are the hardest to undo."},"relearn":"Talk money before the wedding, not only after; early honesty spares painful surprises later.","persona":"any","source":"talk before"},
  {"id":"mt-1083","cat":"money-talk","type":"strike-rewrite","hook":"\"My family arranged everything, so we don't really need our own money talk.\"","myth":{"un":"My family arranged everything, so we don't really need our own money talk.","re":"However the match was made, the two of you still need your own honest talk about incomes, debts and goals.","why":"Elders' planning can't replace the couple's own clarity."},"relearn":"However a marriage was arranged, the couple still needs its own honest money talk.","persona":"any","source":"arranged still talk"},
  {"id":"mt-1084","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking about my old loans will scare them off, so I'll keep quiet.\"","myth":{"un":"Talking about my old loans will scare them off, so I'll keep quiet.","re":"Naming a loan early lets you plan it together; hiding it turns a manageable debt into a betrayal later.","why":"A hidden debt hurts trust more than the debt itself."},"relearn":"Name an old loan early so you can plan it together; hiding it betrays trust later.","persona":"any","source":"name the loan"},
  {"id":"mt-1085","cat":"money-talk","type":"strike-rewrite","hook":"\"If we just avoid the topic, we'll avoid the money fights.\"","myth":{"un":"If we just avoid the topic, we'll avoid the money fights.","re":"Avoiding money talk doesn't avoid the conflict; it defers it until it's bigger and harder to fix.","why":"Silence stores up the fight, it doesn't cancel it."},"relearn":"Avoiding the money talk defers the conflict, it doesn't prevent it.","persona":"Pooja","source":"avoidance defers"},
  {"id":"mt-1086","cat":"money-talk","type":"strike-rewrite","hook":"\"Whoever earns more shouldn't have to explain their spending to the other.\"","myth":{"un":"Whoever earns more shouldn't have to explain their spending to the other.","re":"In a shared life both partners stay in the loop on the money; earning more isn't a reason to go opaque.","why":"A shared life means a shared view of the money."},"relearn":"Earning more isn't a reason to go opaque; in a shared life both partners stay in the loop.","persona":"Karthik","source":"both in the loop"},
  {"id":"mt-1087","cat":"money-talk","type":"strike-rewrite","hook":"\"Good couples just know how the other feels about money without discussing it.\"","myth":{"un":"Good couples just know how the other feels about money without discussing it.","re":"No one reads a partner's money values by instinct; you learn them by actually asking and listening.","why":"Assumptions about money are where the fights start."},"relearn":"You don't read a partner's money values by instinct; you learn them by asking and listening.","persona":"any","source":"ask don't assume"},
  {"id":"mt-1088","cat":"money-talk","type":"strike-rewrite","hook":"\"Money talk has to be a big, serious, scary sit-down.\"","myth":{"un":"Money talk has to be a big, serious, scary sit-down.","re":"It works better as small, regular, low-stakes chats than one dreaded summit; little and often beats rare and tense.","why":"Frequent small talks keep the pressure low."},"relearn":"Money talk works best as small regular chats, not one big scary sit-down.","persona":"Sneha","source":"little and often"},
  {"id":"mt-1089","cat":"money-talk","type":"strike-rewrite","hook":"\"If I earn less, I've no right to ask how our money is spent.\"","myth":{"un":"If I earn less, I've no right to ask how our money is spent.","re":"Earning less doesn't forfeit your voice; both partners have a right to see and shape the shared money.","why":"A smaller paycheque isn't a smaller right to ask."},"relearn":"Earning less doesn't forfeit your voice; both partners can see and shape the shared money.","persona":"Pooja","source":"lower earner can ask"},
  {"id":"mt-1090","cat":"money-talk","type":"strike-rewrite","hook":"\"Comparing our money to the neighbours is a fine way to talk about ours.\"","myth":{"un":"Comparing our money to the neighbours is a fine way to talk about ours.","re":"A useful money talk is about your own incomes, goals and worries, not log-kya-kahenge comparisons to others.","why":"Comparison breeds pressure, not a plan."},"relearn":"Talk about your own incomes and goals, not comparisons to the neighbours.","persona":"any","source":"not comparison"},
  {"id":"mt-1091","cat":"money-talk","type":"strike-rewrite","hook":"\"Once we've talked money once, the subject is closed for good.\"","myth":{"un":"Once we've talked money once, the subject is closed for good.","re":"A raise, a baby, a move or a loss all change the picture, so the money talk reopens as life does.","why":"The numbers move, so the talk recurs."},"relearn":"One money talk doesn't close the subject; it reopens as life changes.","persona":"any","source":"talk reopens"},
  {"id":"mt-1092","cat":"money-talk","type":"strike-rewrite","hook":"\"Joking and hinting about money counts as having talked about it.\"","myth":{"un":"Joking and hinting about money counts as having talked about it.","re":"Hints and jokes leave the real numbers unsaid; a true money talk names the actual incomes, debts and plans.","why":"Hints let both of you hear what you want to."},"relearn":"Hints and jokes aren't a money talk; name the real incomes, debts and plans.","persona":"any","source":"hints aren't talk"},
  {"id":"mt-1093","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking money means one of us has to admit we've been bad with it.\"","myth":{"un":"Talking money means one of us has to admit we've been bad with it.","re":"The talk isn't a confession or a blame session; it's two people building one honest plan, no judgement.","why":"It's a plan you build, not a verdict you pass."},"relearn":"The money talk isn't a blame session; it's building one honest plan together, no judgement.","persona":"any","source":"not a confession"},
  {"id":"mt-1094","cat":"money-talk","type":"strike-rewrite","hook":"\"Love is enough; couples who really love each other don't fight over money.\"","myth":{"un":"Love is enough; couples who really love each other don't fight over money.","re":"Even loving couples clash over money; what protects them isn't more love but more open, honest talking.","why":"Love doesn't auto-solve a budget; talking does."},"relearn":"Love alone doesn't prevent money fights; open, honest talking does.","persona":"any","source":"love isn't enough"},
  {"id":"mt-1095","cat":"money-talk","type":"sort","hook":"Sort: a calm opener for the money talk, or a line that starts a fight?","items":[{"id":"a","text":"\"Can we map our money together sometime?\""},{"id":"b","text":"\"You're hopeless with money.\""},{"id":"c","text":"\"No judgement, I just want us on the same page.\""},{"id":"d","text":"\"Why do you always waste cash?\""},{"id":"e","text":"\"What are we both hoping to save for?\""},{"id":"f","text":"\"Hand over your salary and let me decide.\""}],"bins":[{"id":"calm","label":"Calm opener","valence":"pos"},{"id":"fight","label":"Starts a fight","valence":"neg"}],"key":{"a":"calm","b":"fight","c":"calm","d":"fight","e":"calm","f":"fight"},"relearn":"Team-framed, no-judgement openers invite a plan; blame and demands start a fight.","persona":"Karthik","source":"opener tone"},
  {"id":"mt-1096","cat":"money-talk","type":"sort","hook":"Sort: ready to share a life, talk money first, or skip it and hope?","items":[{"id":"a","text":"Agree how you'll split shared costs"},{"id":"b","text":"Assume it'll all just work out"},{"id":"c","text":"Compare incomes and debts honestly"},{"id":"d","text":"Stay vague to avoid an awkward chat"},{"id":"e","text":"Name the goals you're both saving for"},{"id":"f","text":"Find out the real numbers on the wedding night"}],"bins":[{"id":"talk","label":"Talk money first","valence":"pos"},{"id":"skip","label":"Skip and hope","valence":"uhoh"}],"key":{"a":"talk","b":"skip","c":"talk","d":"skip","e":"talk","f":"skip"},"relearn":"Splitting costs and naming incomes, debts and goals beats assuming it'll work out.","persona":"any","source":"talk or hope"},
  {"id":"mt-1097","cat":"money-talk","type":"sort","hook":"Sort: belongs in your honest money talk, or is it just gossip?","items":[{"id":"a","text":"Your own take-home pay"},{"id":"b","text":"Your cousin's secret salary"},{"id":"c","text":"The EMIs you're both carrying"},{"id":"d","text":"How much the neighbours overspent"},{"id":"e","text":"What you each want to save for"},{"id":"f","text":"A colleague's bonus you overheard"}],"bins":[{"id":"talk","label":"Your money talk","valence":"pos"},{"id":"gossip","label":"Just gossip","valence":"neutral"}],"key":{"a":"talk","b":"gossip","c":"talk","d":"gossip","e":"talk","f":"gossip"},"relearn":"Your own pay, debts and goals belong in the talk; other people's finances are just gossip.","persona":"any","source":"talk not gossip"},
  {"id":"mt-1098","cat":"money-talk","type":"sort","hook":"Sort: keeps the money talk safe, or makes it accusatory?","items":[{"id":"a","text":"Naming it as 'us vs the problem'"},{"id":"b","text":"Listing everything they spent to corner them"},{"id":"c","text":"Picking a calm, unhurried moment"},{"id":"d","text":"Ambushing them when you're already angry"},{"id":"e","text":"Asking what they're worried about too"},{"id":"f","text":"Keeping a tally to win the argument"}],"bins":[{"id":"safe","label":"Keeps it safe","valence":"pos"},{"id":"accuse","label":"Makes it accusatory","valence":"neg"}],"key":{"a":"safe","b":"accuse","c":"safe","d":"accuse","e":"safe","f":"accuse"},"relearn":"Us-vs-the-problem, a calm moment and shared worries keep it safe; cornering and tallies make it a fight.","persona":"any","source":"safe not accusatory"},
  {"id":"mt-1099","cat":"money-talk","type":"sort","hook":"Sort: an honest money-talk move, or a way of hiding?","items":[{"id":"a","text":"Showing the real account balance"},{"id":"b","text":"Keeping a secret account they don't know of"},{"id":"c","text":"Admitting a debt you've been carrying"},{"id":"d","text":"Downplaying a big spend so it slides by"},{"id":"e","text":"Saying out loud what you're saving toward"},{"id":"f","text":"Quietly moving money before they ask"}],"bins":[{"id":"honest","label":"Honest move","valence":"pos"},{"id":"hiding","label":"Hiding","valence":"neg"}],"key":{"a":"honest","b":"hiding","c":"honest","d":"hiding","e":"honest","f":"hiding"},"relearn":"Showing balances and admitting debts is honesty; secret accounts and downplaying spends is hiding.","persona":"Pooja","source":"honest or hiding"},
  {"id":"mt-1100","cat":"money-talk","type":"sort","hook":"Sort: a sign you're talking money well, or a sign it's drifting wrong?","items":[{"id":"a","text":"Both feel heard by the end"},{"id":"b","text":"One always gives in to end it"},{"id":"c","text":"You leave with a small next step"},{"id":"d","text":"It always becomes who's right"},{"id":"e","text":"Tough topics still get raised"},{"id":"f","text":"Whole subjects are now off-limits"}],"bins":[{"id":"well","label":"Going well","valence":"pos"},{"id":"wrong","label":"Drifting wrong","valence":"uhoh"}],"key":{"a":"well","b":"wrong","c":"well","d":"wrong","e":"well","f":"wrong"},"relearn":"Both heard, a next step and raising tough topics is healthy; giving in, scoring and off-limits topics aren't.","persona":"any","source":"well or wrong"},
  {"id":"mt-1101","cat":"money-talk","type":"branch","persona":"any","source":"hidden loan found","hook":"You found out your partner Aman has a loan he never told you about, and you feel hurt.","steps":[{"prompt":"He says he didn't want to worry you. What do you do first?","options":[{"text":"Say the secrecy hurt more than the loan itself","then":"Aman goes quiet, then admits he was ashamed to say it.","best":true},{"text":"Ask exactly how much and demand the paperwork now","then":"He hands it over, but the moment feels like an interrogation."},{"text":"Say it's fine and drop it to avoid a fight","then":"The tension eases, but the hurt sits unspoken between you."},{"text":"Walk off and call your sister to vent first","then":"She's sympathetic, but Aman still doesn't know how you feel."}],"why":"Naming the hurt honestly opens the door instead of burying it."},{"prompt":"A day later he asks if you're still upset. What do you focus on?","options":[{"text":"Whether you can make a payoff plan together","then":"He relaxes and pulls out the loan statement to look at with you.","best":true},{"text":"Whether he's hiding anything else from you","then":"He bristles and says he already apologised once."},{"text":"Whether your friends would judge him for this","then":"You waste the moment worrying about appearances, not the debt."},{"text":"Whether you should just handle the loan alone","then":"He looks surprised, unsure if you still see this as shared."}],"why":"Turning to a plan together rebuilds trust faster than more suspicion."},{"prompt":"You sit down to look at the numbers. What do you do?","options":[{"text":"List the loan alongside your other shared goals","then":"The debt stops feeling separate and becomes part of one plan.","best":true},{"text":"Insist he pays it off entirely from his own pocket","then":"He agrees quietly, though it strains the month ahead alone."},{"text":"Avoid the exact number and just estimate roughly","then":"The plan looks fine on paper but misses the real total."},{"text":"Suggest ignoring it since it's a small amount","then":"The loan quietly grows while nothing is actually paid."}],"why":"A debt counted alongside your goals gets planned for properly."},{"prompt":"Aman asks whether this changes how you see him. What do you say?","options":[{"text":"Say it doesn't. Say you just want honesty going forward","then":"He exhales, like he'd been braced for something worse.","best":true},{"text":"Say you'll need proof before trusting him with money again","then":"He agrees, though the words land like a small punishment."},{"text":"Say it's fine. Everyone hides something small sometimes","then":"He nods, but the real lesson about honesty gets lost."},{"text":"Change the subject before either of you gets emotional","then":"The question hangs there, answered by nobody."}],"why":"Naming honesty as the real ask, not punishment, keeps the door open."},{"prompt":"A month later a smaller bill turns up that he almost didn't mention. What do you do?","options":[{"text":"Thank him for telling you, then look at it together","then":"He relaxes, and telling you starts to feel normal, not scary.","best":true},{"text":"Remind him this is exactly what he did before","then":"He shrinks a little, and the next small thing may stay hidden."},{"text":"Say nothing and quietly add it to your own tracking","then":"He isn't sure you even heard, and you're tracking it on your own."},{"text":"Joke that you're keeping a list of his secrets now","then":"He laughs it off, but the joke doesn't feel light to him."}],"why":"Meeting honesty with thanks makes the next disclosure easier, not harder."}],"debrief":"Name the hurt, then turn to the debt together; rage just teaches them to hide the next thing.","relearn":"Name the hurt, then face a hidden debt as a team; exploding teaches more hiding."},
  {"id":"mt-1102","cat":"money-talk","type":"branch","persona":"Sneha","source":"partner dodges","hook":"Your fiance Rohan brushes off every attempt to talk money before the wedding.","steps":[{"prompt":"He changes the subject again over dinner. What do you do?","options":[{"text":"Say gently why the money talk matters to you","then":"He goes quiet, then admits the topic makes him anxious.","best":true},{"text":"Let it go and assume the silence means it's fine","then":"Dinner stays easy, and the question waits for another day."},{"text":"Bring it up loudly in front of his family","then":"He shuts down completely, embarrassed in front of everyone."},{"text":"Decide to just handle the wedding budget alone","then":"You quietly take it on, and he senses something's off without knowing why."}],"why":"Explaining why it matters invites him in instead of shutting him out."},{"prompt":"A few days later, he asks if you're upset with him. What do you say?","options":[{"text":"Say you're not upset, just hoping to try the talk again","then":"He relaxes and suggests a calm evening to sit down.","best":true},{"text":"Say you're fine, though the question is still unanswered","then":"He believes you, and the topic slips away again."},{"text":"Say yes, and list everything he's avoided lately","then":"He feels ambushed and retreats further from the subject."},{"text":"Say you'd rather your parents just sort the budget","then":"Your parents step in, but you and Rohan still haven't spoken about it directly."}],"why":"A calm retry, not pressure, keeps the door open for him."},{"prompt":"You finally sit down together with a cup of chai. What do you bring up first?","options":[{"text":"Ask what worries him most about talking money","then":"He admits he's scared of getting it wrong, and you start there.","best":true},{"text":"Start by listing every expense for the wedding","then":"The numbers pile up before either of you says how you feel."},{"text":"Ask what his parents think you two should do","then":"The conversation drifts to family opinion, not your own plan."},{"text":"Suggest skipping feelings and just picking a number","then":"You get a figure, but not the honesty you actually needed."}],"why":"Naming his worry first makes the real talk possible, not just numbers."}],"debrief":"If a partner dodges the money talk, explain why it matters and try again calmly. Don't just drop it.","relearn":"If a partner dodges money talk, explain why and retry calmly; don't assume silence means fine."},
  {"id":"mt-1103","cat":"money-talk","type":"branch","persona":"Karthik","source":"raise the split","hook":"You earn far more than your partner Meera and aren't sure how to raise splitting costs.","steps":[{"prompt":"You're both looking at the month's bills. What do you say?","options":[{"text":"Ask how you can split costs so it feels fair","then":"Meera relaxes and starts talking numbers with you openly.","best":true},{"text":"Announce your own plan since you earn more, and expect her to adjust","then":"She goes along with it, though something in her face falls."},{"text":"Say you'll cover everything for now without asking her view","then":"She feels grateful, but also quietly sidelined from deciding."},{"text":"Avoid the topic since it still feels awkward to bring up together","then":"The bills get paid, but the question never gets answered."}],"why":"Asking together keeps it a shared design, not a decree."},{"prompt":"A few days later, Meera raises how to split the bills. What do you say?","options":[{"text":"Suggest splitting by what each can comfortably give","then":"She nods, relieved it isn't about matching your paycheque.","best":true},{"text":"Agree to an exact fifty-fifty split since it sounds fair enough on paper","then":"It technically balances, but it stretches her budget thin."},{"text":"Say you'd rather keep paying for most shared things yourself","then":"It solves the maths, but sidelines her from the decision."},{"text":"Say her share should rise once she eventually gets a raise","then":"The comment lands as a quiet pressure, not a plan."}],"why":"Splitting by capacity is fairer than an equal number on paper."},{"prompt":"A month on, Meera suggests you both look at whether the split is working. What do you do?","options":[{"text":"Go through it together and fix whatever isn't working for either","then":"You tweak one line, and it feels like a plan you both own.","best":true},{"text":"Say it's working fine, since all the bills are getting paid","then":"The bills do get paid, and whatever pinches her stays unsaid."},{"text":"Decide on a new split yourself and tell her the numbers","then":"The numbers may be fair, but she wasn't part of choosing them."},{"text":"Ask her to track her spending first to show it's really tight","then":"She feels checked on, and the talk stalls before it starts."}],"why":"Reviewing the split together keeps it a shared design, not a decree."}],"debrief":"Raise splitting costs as a shared design question, not a decree from the higher earner.","relearn":"Design the split together with a warm question; don't decree it from the bigger paycheque."},
  {"id":"mt-1104","cat":"money-talk","type":"branch","persona":"any","source":"reset the blame","hook":"A money chat with your partner Farah is turning into a blame match about who wastes more.","steps":[{"prompt":"She lists a purchase you made last month. What do you do?","options":[{"text":"Pause and say you're a team, so what's the real problem","then":"The tone shifts, and you both step back from scorekeeping.","best":true},{"text":"List a purchase of hers right back","then":"The tally grows longer, and neither of you feels heard."},{"text":"Apologise and say you'll try to spend less overall","then":"The apology ends the moment but not the real disagreement."},{"text":"Say she always brings up money to start fights","then":"She stiffens, and the conversation turns colder."}],"why":"Naming it as a shared problem stops the scorekeeping."},{"prompt":"Once things calm down, Farah asks what's actually bothering you. What do you say?","options":[{"text":"Say you're both stressed and need an actual plan","then":"She agrees, and the talk turns from who wastes more to what you both need.","best":true},{"text":"Say nothing's wrong now that the fight is over","then":"The real issue goes unspoken and waits for the next fight."},{"text":"Say you just want her to spend less","then":"It sounds like blame again, even said more gently."},{"text":"Say you'd rather not talk about money for a while","then":"The break feels calm, but the problem is still unsolved."}],"why":"Naming the real pressure gets you both toward a fix, not a truce."},{"prompt":"A week later, the card bill arrives and Farah asks to sit down with the numbers. What do you focus on first?","options":[{"text":"Where the money is really going each month","then":"Seeing the real numbers together replaces guessing with facts.","best":true},{"text":"Whose spending habit needs to change first","then":"It slides back toward blame instead of a shared picture."},{"text":"What your friends spend, for comparison","then":"It distracts from your own numbers instead of showing where the money actually goes."},{"text":"How to avoid this kind of talk in future","then":"It sidesteps tonight's numbers, and the same pressure returns next month."}],"why":"Looking at the real numbers together replaces blame with facts."}],"debrief":"When a money talk turns to blame, pause and rename it as a shared problem to solve.","relearn":"When money talk turns to blame, pause and rename it as a team problem, not a contest."},
  {"id":"mt-1105","cat":"money-talk","type":"branch","persona":"any","source":"admit the debt","hook":"You're nervous to admit to your partner Sahil that you have credit card debt.","steps":[{"prompt":"He asks casually how your savings are doing. What do you do?","options":[{"text":"Tell him honestly, including the card debt","then":"He's quiet for a second, then asks how he can help.","best":true},{"text":"Say things are fine and change the subject","then":"The moment passes, and the debt stays your secret alone."},{"text":"Mention a smaller number than the real one","then":"He nods at the smaller figure, and the real one waits in your inbox."},{"text":"Say you'd rather not discuss money right now","then":"He drops it for now, though a card statement soon shows the real number."}],"why":"Honesty now lets you both plan from the real picture."},{"prompt":"A card statement lands, and Sahil asks how the debt built up. What do you say?","options":[{"text":"Explain plainly, without dressing it up or hiding parts","then":"He listens without judgement, just wanting the full picture.","best":true},{"text":"Blame a run of bad luck and leave it there","then":"It's a half answer, and the plan you build may miss something."},{"text":"Get defensive since it feels like an accusation","then":"The conversation stalls before you even reach a plan."},{"text":"Joke about it to keep the mood light","then":"The joke covers the discomfort, but not the actual number."}],"why":"A plain explanation lets him understand the real situation, not a story."},{"prompt":"You start listing your monthly expenses together. What do you do?","options":[{"text":"Include the card payment as a fixed line, not an extra","then":"The debt becomes one ordinary item in a real budget.","best":true},{"text":"Leave the card off for now to keep the list simple","then":"The plan looks tidy but doesn't actually cover the debt."},{"text":"Suggest he covers the card payment for a while","then":"It solves this month, but the debt still feels like yours alone."},{"text":"Round the payment down to make the budget look better","then":"The numbers look fine on paper and wrong in reality."}],"why":"Treating the debt as a normal line item makes the plan honest."},{"prompt":"A few months later, some extra money comes in. What do you do?","options":[{"text":"Agree together how to split it between the card and savings","then":"You split it, and the card balance drops while the savings still grow.","best":true},{"text":"Quietly put all of it on the card without telling him","then":"The balance falls faster, but Sahil learns later and feels left out."},{"text":"Spend it on something fun, since the card is being paid anyway","then":"It is a nice treat, and the debt stays longer than it needed to."},{"text":"Let Sahil decide what to do with it, since you feel you owe him","then":"He says he'd rather decide it with you than be handed the choice."}],"why":"Deciding together how to use extra money keeps the payoff shared and honest."}],"debrief":"Own up to debt and plan the payoff together; secrecy only grows the eventual shock.","relearn":"Own a debt honestly and plan the payoff together; secrecy grows the eventual shock."},
  {"id":"mt-1106","cat":"money-talk","type":"branch","persona":"any","source":"family steering","hook":"Your in-laws keep steering your money decisions, and you and your partner Devika haven't discussed it.","steps":[{"prompt":"Your mother-in-law suggests where your savings should go, again. What do you do?","options":[{"text":"Say you'll think about it and talk to Devika","then":"You buy time to actually decide together, not on the spot.","best":true},{"text":"Agree on the spot just to avoid an awkward moment in front of everyone","then":"You've committed to something Devika hasn't even heard yet."},{"text":"Argue with her right there in front of the entire family","then":"The room tenses, and nothing actually gets decided."},{"text":"Say plainly that your money decisions aren't really her business","then":"The line lands harshly, and the real issue stays unaddressed."}],"why":"Buying time protects a decision that should be made together first."},{"prompt":"That evening, you tell Devika what your mother-in-law said. What do you focus on?","options":[{"text":"What you two actually want, before anyone else's opinion","then":"You talk it through and land on a line you both mean.","best":true},{"text":"Whether her mother's suggestion is actually a good one","then":"You end up debating her idea instead of your own plan."},{"text":"How to avoid upsetting either set of your parents about this","then":"Keeping the peace becomes the goal instead of your own choice."},{"text":"Whose family gets to weigh in more often on decisions like these","then":"It turns into a rivalry instead of a shared decision."}],"why":"Deciding your own line first keeps the choice actually yours."},{"prompt":"At the next family gathering, your father-in-law asks how you two are handling the savings question. What do you say?","options":[{"text":"Say plainly that this is something you and Devika decide together","then":"He nods, and the room accepts it's your call to make.","best":true},{"text":"Say you're still deciding, to avoid answering directly","then":"It avoids friction now, but invites the same pressure later."},{"text":"Let Devika answer the question for both of you this time around","then":"It works this time, but it isn't really a shared front."},{"text":"Change the subject quickly to avoid any kind of family reaction","then":"The question just returns at the next family dinner."}],"why":"Standing united as a couple, kindly, holds the line without a fight."},{"prompt":"Months later, a relative brings up the topic again at a wedding function. What do you do?","options":[{"text":"Repeat your own view calmly, as something you're confident about","then":"It lands as fact, not a debate, and the topic moves on.","best":true},{"text":"Get visibly frustrated that it's still being raised again today","then":"The irritation shows, and the family reads it as instability."},{"text":"Quietly go along with whatever they happen to suggest this time","then":"Your own say in it starts to quietly erode."},{"text":"Avoid the whole function next time just to dodge the topic again","then":"You dodge the moment, but not the underlying pressure."}],"why":"Calmly repeating your own view keeps it steady, without turning it into a debate."}],"debrief":"Talk as a couple first and agree your own line before involving the wider family.","relearn":"Decide your couple's money together first, then face the family as a united pair."},
  {"id":"mt-1107","cat":"money-talk","type":"branch","persona":"Pooja","source":"partner withdraws","hook":"Every time money comes up, your partner Arvind goes quiet and withdraws.","steps":[{"prompt":"You mention the electricity bill and he stops replying. What do you do?","options":[{"text":"Suggest a short, gentle chat later instead of right now","then":"He nods, relieved the moment doesn't have to be now.","best":true},{"text":"Push harder and demand an answer on the spot","then":"He shuts down further and leaves the room."},{"text":"Drop the bill topic and let it go unpaid for now","then":"The silence continues, and nothing actually gets resolved."},{"text":"Pay it yourself without saying anything else","then":"It's handled quietly, but the pattern of avoiding stays."}],"why":"Lowering the stakes now makes room for a real talk later."},{"prompt":"A day later, the topic comes up again. What do you open with?","options":[{"text":"A small, specific question, nothing overwhelming","then":"He answers it, and the conversation starts to move.","best":true},{"text":"A full list of everything you've been worried about","then":"He freezes, overwhelmed before you even finish the list."},{"text":"An apology for bringing it up earlier","then":"It softens the moment but skips the actual question."},{"text":"A joke to break the tension first","then":"The joke lands fine, but the real topic gets postponed again."}],"why":"One small question is easier to answer than a wall of worry."},{"prompt":"Arvind admits money talk makes him anxious. What do you say?","options":[{"text":"Ask what would make it feel safer for him","then":"He thinks, then suggests shorter, scheduled talks going forward.","best":true},{"text":"Say he just needs to get used to it","then":"He nods but stays braced the next time it comes up."},{"text":"Say you'll just stop bringing it up then","then":"It solves the tension but leaves the money unmanaged."},{"text":"Say that's not a real reason to avoid it","then":"He retreats again, and the honesty from a moment ago closes."}],"why":"Asking what helps him shows the talk can change shape, not disappear."},{"prompt":"A month later, money comes up over dinner, and Arvind answers briefly, then pauses. What do you do?","options":[{"text":"Thank him for staying with it, and ask one small thing more","then":"He relaxes a little and keeps talking, a bit longer than last time.","best":true},{"text":"Drop the subject at once so he doesn't feel any pressure","then":"Dinner stays easy, and money stays something to tiptoe around."},{"text":"Push for more right away, before he goes quiet again","then":"The push makes him retreat again, right when he was opening up."},{"text":"Use the moment to bring up everything you've been holding back","then":"The wall of worries returns, and so does the shutdown."}],"why":"Noticing that he stayed, and keeping the next ask small, helps him keep opening up."}],"debrief":"If a partner withdraws, make the talk smaller and safer. Don't corner them for answers.","relearn":"If a partner withdraws from money talk, make it smaller and safer, not more cornering."},
  {"id":"mt-1108","cat":"money-talk","type":"branch","persona":"any","source":"name the goals","hook":"You and your partner Tanvi have never once named your savings goals out loud.","steps":[{"prompt":"You're both relaxing after dinner. What do you do?","options":[{"text":"Ask each of you to name one goal you care about","then":"She lights up and shares something you never knew mattered to her.","best":true},{"text":"Assume you already want the same things","then":"You skip the talk, until a comment of hers reveals she's saving for a house, not travel like you."},{"text":"Suggest just saving whatever's left each month","then":"It works for now, until you notice the amounts are meant for different things: hers for a house, yours for travel."},{"text":"Say goals feel too far off to bother with yet","then":"The talk stalls, until a passing comment shows she's quietly saving toward a house while you picture travel."}],"why":"Naming a goal out loud is the only way to find where you overlap."},{"prompt":"Your goals turn out to be different: travel for you, a house for her. What do you do?","options":[{"text":"Look for where the two goals could overlap or coexist","then":"You find a small shared plan that honours both.","best":true},{"text":"Say your goal should come first, since you've wanted it longest","then":"She agrees quietly, though it doesn't feel fully fair."},{"text":"Drop your own goal so hers gets full funding","then":"It's generous, and you quietly wonder if your own goal still has room somewhere."},{"text":"Say you'll each just save separately for your own goal","then":"It avoids conflict, though you both wonder if a shared approach might work better."}],"why":"Looking for overlap honours both goals instead of ranking one."},{"prompt":"You sit down to put numbers to both goals. What do you focus on first?","options":[{"text":"A split that funds both goals, even slowly","then":"Watching both totals grow, even slowly, feels like a shared win.","best":true},{"text":"Whichever goal is cheaper to reach first","then":"It's efficient, but the other goal quietly waits its turn."},{"text":"Whoever earns more decides the split","then":"It solves the maths but sidelines the smaller earner's say."},{"text":"A guess, since exact numbers feel like too much work","then":"The plan looks nice but doesn't really hold up."}],"why":"A split that funds both, even slowly, keeps it a shared plan."}],"debrief":"Say your goals out loud and find the overlap; don't assume you already want the same things.","relearn":"Name your goals out loud to find the overlap; don't assume you already match."},
  {"id":"mt-1109","cat":"money-talk","type":"branch","persona":"any","source":"honest start","hook":"Your partner Naveen wants to start the money talk, but you're embarrassed about how little you've saved.","steps":[{"prompt":"He asks gently where you're starting from. What do you do?","options":[{"text":"Be honest about the real number, however small","then":"He nods, unbothered, and says now's as good a start as any.","best":true},{"text":"Round the number up to sound more responsible","then":"The plan you build together rests on a number that isn't true."},{"text":"Say you'd rather talk about his savings first","then":"It delays the moment without actually avoiding it."},{"text":"Say you've never really tracked it closely","then":"It's technically true, but it dodges the actual question."}],"why":"The real number, however small, is what a real plan needs."},{"prompt":"Naveen shares his own savings, which are higher than yours. What do you focus on?","options":[{"text":"That today is simply where you're both starting from","then":"The gap stops feeling like a verdict and starts feeling like a start.","best":true},{"text":"How much further behind you feel now","then":"The comparison sits heavy, and the planning stalls."},{"text":"Whether he'll judge you for the difference","then":"You spend the talk guessing his reaction instead of planning."},{"text":"Suggesting he handle the savings side going forward","then":"It quietly hands over control instead of building it together."}],"why":"Treating today as the starting line, not a scorecard, keeps you both in it."},{"prompt":"You sit down to set a first savings target together. What do you propose?","options":[{"text":"A small, realistic monthly amount you can actually keep","then":"It feels doable, and doable is what makes it stick.","best":true},{"text":"A big number to make up for lost time","then":"It looks ambitious on paper and slips within a month."},{"text":"Whatever's left over, with no fixed amount","then":"Nothing is left over most months, so the goal drifts."},{"text":"A target set mostly around his comfort level","then":"It fits him easily, but it isn't really shared yet."}],"why":"A small, keepable amount builds the habit that actually lasts."}],"debrief":"Share your real position, however small; a plan built on inflated numbers can't hold.","relearn":"Share your real savings, however small; a plan built on inflated numbers can't hold."},
  {"id":"mt-1110","cat":"money-talk","type":"branch","persona":"Sneha","source":"schedule it","hook":"You and your partner Rahul keep meaning to talk money, but life stays too busy.","steps":[{"prompt":"Another week passes without the talk happening. What do you do?","options":[{"text":"Put a short recurring money chat on the calendar","then":"It finally has a slot on the calendar, ready for this Sunday.","best":true},{"text":"Wait for a calmer, more perfect moment","then":"The perfect moment keeps not arriving."},{"text":"Decide it can probably wait until after the busy season","then":"The busy season passes, and a new one always follows."},{"text":"Bring it up randomly whenever you remember","then":"It keeps landing at bad moments and going nowhere."}],"why":"A scheduled slot is what actually makes the talk happen."},{"prompt":"Sunday evening arrives, and you think about the money talk again. What do you do?","options":[{"text":"Sit down together for a short, deliberate chat","then":"It's short, but you both leave with one thing decided.","best":true},{"text":"Push it to next week since you're both tired","then":"Next week arrives just as tired, and it slips again."},{"text":"Do it while distracted by the television","then":"You talk, but half the details don't really land."},{"text":"Suggest texting each other the numbers instead of talking","then":"The numbers get sent, but nothing gets decided together."}],"why":"Actually sitting down for the short chat is what turns intention into a habit."},{"prompt":"A month later, Rahul asks what you want to do about money talks from here. What do you say?","options":[{"text":"Make it a short monthly chat, adding one new topic each time","then":"The habit stays light and keeps covering new ground.","best":true},{"text":"Say you only need to talk when something goes wrong","then":"Money talk becomes a crisis talk instead of a steady habit."},{"text":"Suggest one long weekly meeting to get through everything","then":"The length makes it feel like a chore, and it starts slipping."},{"text":"Say the big things feel sorted, so there's no need anymore","then":"New things quietly build up with nowhere to land."}],"why":"A short, evolving slot keeps the habit useful without becoming a chore."}],"debrief":"Schedule a short regular money chat; the 'perfect moment' rarely arrives on its own.","relearn":"Schedule a short regular money chat; the perfect spontaneous moment rarely comes."},
  {"id":"mt-1111","cat":"money-talk","type":"branch","persona":"Karthik","source":"stop the apologising","hook":"Your partner Divya earns less and keeps apologising for it during your money talks.","steps":[{"prompt":"She apologises again before sharing her opinion on the budget. What do you do?","options":[{"text":"Reassure her that her voice counts fully, not just her pay","then":"She sits up a little straighter and finishes her thought.","best":true},{"text":"Let the apology slide and move the talk along","then":"It's easier in the moment, but the pattern stays unchallenged."},{"text":"Say there's nothing to apologise for and change topics","then":"It's kind, but it skips naming why her voice actually matters."},{"text":"Take the lead on the decision to spare her the discomfort","then":"It spares her the moment, but shrinks her role further."}],"why":"Naming that her voice counts fully lets her speak as an equal."},{"prompt":"A week later, she hesitates before suggesting a change to the budget. What do you do?","options":[{"text":"Ask directly what she thinks, before she has to offer it","then":"She relaxes, and the idea comes out clearly, apology-free.","best":true},{"text":"Wait for her to bring it up in her own time","then":"The hesitation stretches, and the idea almost doesn't surface."},{"text":"Suggest she write it down instead of saying it aloud","then":"It avoids the discomfort but keeps the pattern going quietly."},{"text":"Jump in with your own idea first","then":"Hers gets crowded out before she even finishes hesitating."}],"why":"Asking first removes the need for her to earn the floor."},{"prompt":"At a family gathering, someone jokes that Divya doesn't earn enough to have a say. What do you do?","options":[{"text":"Say plainly that you decide money matters together","then":"The room moves on, and Divya looks steadier beside you.","best":true},{"text":"Laugh it off to keep the moment light","then":"The joke lands as fact, and Divya's face falls slightly."},{"text":"Stay quiet, hoping Divya will answer it herself","then":"She's left to defend her own place at the table alone."},{"text":"Agree that earning more should mean more say","then":"It sets a precedent that earning more decides who gets heard."}],"why":"Saying it plainly, in front of others, backs up what you've built at home."},{"prompt":"Months later, Divya raises an idea in a talk without any hesitation at all. What do you notice?","options":[{"text":"That she's sharing ideas freely now, and you tell her you noticed","then":"She smiles. It means more to her than you expected.","best":true},{"text":"That the apologising stopped, so the issue must be over","then":"You stop checking in, and a smaller version of it can creep back."},{"text":"That she's more confident, so you can lead a bit more now","then":"It quietly nudges the balance back the other way."},{"text":"Nothing in particular, and you move straight to the numbers","then":"The moment passes unnoticed, though it mattered to her."}],"why":"Noticing out loud helps her voice feel valued, not taken for granted."}],"debrief":"Affirm a lower earner's full voice so money talk stays a partnership, not an apology.","relearn":"Affirm a lower earner's full voice; their contribution counts beyond their pay."},
  {"id":"mt-1112","cat":"money-talk","type":"match","hook":"Match each money-talk worry to a calm way to open it.","pairs":[{"left":"Hidden debt","right":"\"I want to tell you something, no blame\""},{"left":"Unequal incomes","right":"\"How do we make the split feel fair?\""},{"left":"Different spenders","right":"\"What does money mean to you?\""},{"left":"A big future cost","right":"\"What should we start saving for?\""},{"left":"In-law pressure","right":"\"Can we agree our own line first?\""}],"relearn":"Every money worry has a calm, no-blame opener that turns it into a shared plan.","persona":"any","source":"worry to opener"},
  {"id":"mt-1113","cat":"money-talk","type":"match","hook":"Match each avoided money topic to the cost of leaving it unsaid.","pairs":[{"left":"A hidden loan","right":"A trust shock when it surfaces"},{"left":"Unspoken goals","right":"Pulling in different directions"},{"left":"An unfair split","right":"Slow-building resentment"},{"left":"Different money values","right":"Repeated baffling clashes"},{"left":"Who knows the accounts","right":"One partner exposed in a crisis"}],"relearn":"Each unsaid money topic has a real cost; naming it early is cheaper than the surprise.","persona":"any","source":"cost of silence"},
  {"id":"mt-1114","cat":"money-talk","type":"match","hook":"Match each money-talk phrase to what it signals to a partner.","pairs":[{"left":"\"We're a team on this\"","right":"Safety to be honest"},{"left":"\"You always waste money\"","right":"Brace for an attack"},{"left":"\"What are you worried about?\"","right":"Your fears are welcome here"},{"left":"\"Just give me your salary\"","right":"Your say doesn't count"},{"left":"\"Let's look at the numbers together\"","right":"Nothing's being hidden"}],"relearn":"The words you open with signal either safety and openness or attack and control.","persona":"any","source":"phrase to signal"},
  {"id":"mt-1115","cat":"money-talk","type":"match","hook":"Match each money-talk habit to the outcome research links it to.","pairs":[{"left":"Talking openly and often","right":"Fewer money fights"},{"left":"Hiding spending","right":"Eroded trust"},{"left":"Shared goals named aloud","right":"Pulling the same way"},{"left":"Blaming in every chat","right":"Topics become off-limits"},{"left":"Calm scheduled check-ins","right":"Problems caught early"}],"relearn":"Open, calm money talk links to fewer fights; hiding and blame link to broken trust.","persona":"any","source":"habit to outcome"},
  {"id":"mt-1116","cat":"money-talk","type":"match","hook":"Match each life moment to the money talk it calls for.","pairs":[{"left":"Moving in together","right":"How will we split shared costs?"},{"left":"A new raise","right":"What changes now we earn more?"},{"left":"Planning a baby","right":"What new costs are coming?"},{"left":"A job loss","right":"How do we get through lean months?"},{"left":"A family demand for money","right":"What can we say yes to together?"}],"relearn":"Each life moment reopens the money talk with a fresh question to face as a team.","persona":"any","source":"moment to talk"},
  {"id":"mt-1117","cat":"money-talk","type":"match","hook":"Match each money-talk myth to the truer reality.","pairs":[{"left":"Talking money is unromantic","right":"It's an act of care"},{"left":"Love prevents money fights","right":"Open talk does"},{"left":"One talk settles it forever","right":"It reopens as life shifts"},{"left":"Hints count as talking","right":"Real numbers do"},{"left":"The earner needn't explain","right":"Both stay in the loop"}],"relearn":"Each money-talk myth has a truer reality: talking is care, ongoing, specific and shared.","persona":"any","source":"myth to reality talk"},
  {"id":"mt-1118","cat":"money-talk","type":"match","hook":"Match each opener to the response it tends to invite.","pairs":[{"left":"\"No judgement, just us\"","right":"They relax and open up"},{"left":"\"Why are you so careless?\"","right":"They get defensive"},{"left":"\"What do you hope we save for?\"","right":"They share a dream"},{"left":"\"You owe me an explanation\"","right":"They shut down"},{"left":"\"Can we look at this together?\"","right":"They lean in"}],"relearn":"Warm, curious openers invite honesty; blaming, demanding ones invite defensiveness.","persona":"Karthik","source":"opener to response"},
  {"id":"mt-1119","cat":"money-talk","type":"reflect","hook":"Lensy: the most loving thing you can do with money is talk about it honestly. Sit right with you?","prompt":"What's your take?","options":["It does","Honesty is love","I'll talk"],"affirm":"Honest money talk is a form of care, not its opposite; couples who talk openly fight about money least.","relearn":"Honest money talk is care, not coldness; open couples fight about money least.","persona":"any","source":"honesty is love"},
  {"id":"mt-1120","cat":"money-talk","type":"reflect","hook":"Lensy: notice the awkwardness of the money talk, then have it anyway. Worth pushing through?","prompt":"What do you think?","options":["Worth it","Push through","I'll start"],"affirm":"The awkwardness fades fast and the clarity lasts; the short discomfort of the talk buys a lot of peace.","relearn":"The money talk's awkwardness is brief; the clarity it buys lasts.","persona":"Sneha","source":"push through awkward"},
  {"id":"mt-1121","cat":"money-talk","type":"reflect","hook":"Lensy: money talks go better at a calm set time than mid-argument. Pick a regular money date?","prompt":"What's your take?","options":["Set a monthly slot","Calm time only","Makes sense"],"affirm":"A scheduled, calm money check-in beats raising it mid-fight, when both of you are already defensive.","relearn":"Talk money at a calm, scheduled time, not in the heat of a fight.","persona":"any","source":"scheduled check-in reflect"},
  {"id":"mt-1122","cat":"money-talk","type":"reflect","hook":"Lensy: there's no shameful number to share; today is just the honest starting line. Hear that?","prompt":"What do you think?","options":["I hear it","No shame","Fresh start"],"affirm":"Wherever your savings or debts sit, naming the real figure is the honest start a plan is built on.","relearn":"There's no shameful number; the real figure is the honest start a plan needs.","persona":"any","source":"no shameful number"},
  {"id":"mt-1123","cat":"money-talk","type":"reflect","hook":"Lensy: you can ask about the money even if you earn less. Does that land?","prompt":"What's your take?","options":["It lands","I can ask","My say counts"],"affirm":"A smaller paycheque never cancels your right to ask; both partners get to see and shape the shared money.","relearn":"Earning less never cancels your right to ask; both partners see and shape the money.","persona":"Pooja","source":"i can ask"},
  {"id":"mt-1124","cat":"money-talk","type":"reflect","hook":"Lensy: little and often beats one big scary money summit. Does that sound easier?","prompt":"What do you think?","options":["Easier","Little and often","I'll do that"],"affirm":"Small regular money chats keep the pressure low and the honesty high, far better than one dreaded sit-down.","relearn":"Small regular money chats beat one big scary summit; little and often keeps it easy.","persona":"any","source":"little and often reflect"},
  {"id":"mt-1125","cat":"money-talk","type":"reflect","hook":"Lensy: a hidden money worry shrinks the moment you say it out loud together. Worth naming yours?","prompt":"What's your take?","options":["Worth naming","Saying it helps","I'll name it"],"affirm":"A worry kept secret grows; spoken to a partner who listens, it becomes a shared, smaller problem.","relearn":"A money worry shrinks when named together; spoken, it becomes a shared problem.","persona":"any","source":"name the worry"},
  {"id":"mt-1126","cat":"money-talk","type":"reflect","hook":"Lensy: you don't need the perfect words to start; honest and kind is enough. Ready to begin?","prompt":"What do you think?","options":["Ready","Honest is enough","I'll begin"],"affirm":"You don't need a script; an honest, kind, no-blame opener is all the money talk needs to begin.","relearn":"You don't need perfect words; an honest, kind, no-blame opener is enough to start.","persona":"any","source":"begin imperfectly"},
  {"id":"mt-1127","cat":"money-talk","type":"spot","hook":"Lensy: spot the two lines that quietly shut a money talk down.","scene":[{"id":"a","text":"\"Tell me how you really feel about it\"","trick":false},{"id":"b","text":"\"This isn't worth discussing\"","trick":true},{"id":"c","text":"\"Let's look at the numbers together\"","trick":false},{"id":"d","text":"\"Money's my department, stay out of it\"","trick":true},{"id":"e","text":"\"What are you hoping we save for?\"","trick":false}],"why":"'Not worth discussing' and 'stay out of it' shut the talk down; the others invite it open.","relearn":"Lines that dismiss or shut you out close a money talk; curious, open ones keep it going.","persona":"any","source":"shut-down lines"},
  {"id":"mt-1128","cat":"money-talk","type":"spot","hook":"Lensy: spot the two money-talk moves that are really about blame, not a plan.","scene":[{"id":"a","text":"Agreeing the shared goal first","trick":false},{"id":"b","text":"Reading out their whole spending list to corner them","trick":true},{"id":"c","text":"Asking what worries them about money","trick":false},{"id":"d","text":"Keeping score of who wasted more","trick":true},{"id":"e","text":"Looking for one small next step","trick":false}],"why":"Cornering with a spending list and keeping score are blame; goals, worries and a next step build a plan.","relearn":"Cornering and score-keeping are blame; naming goals, worries and a next step build a plan.","persona":"any","source":"blame not plan"},
  {"id":"mt-1129","cat":"money-talk","type":"spot","hook":"Lensy: spot the two things that DON'T belong in your honest money talk.","scene":[{"id":"a","text":"Your own real income and debts","trick":false},{"id":"b","text":"A relative's secret salary","trick":true},{"id":"c","text":"The goals you're saving toward","trick":false},{"id":"d","text":"Gossip about a neighbour's losses","trick":true},{"id":"e","text":"How you'll split shared costs","trick":false}],"why":"A relative's secret salary and neighbour gossip aren't yours to discuss; your own numbers and goals are.","relearn":"Other people's private finances and gossip don't belong in your money talk; your own numbers do.","persona":"any","source":"doesn't belong"},
  {"id":"mt-1130","cat":"money-talk","type":"spot","hook":"Lensy: spot the two signs a money talk has slid into avoidance.","scene":[{"id":"a","text":"You both keep changing the subject","trick":true},{"id":"b","text":"You name one clear next step","trick":false},{"id":"c","text":"'We'll deal with it later' every time","trick":true},{"id":"d","text":"You set a time to continue","trick":false},{"id":"e","text":"You each share one real number","trick":false}],"why":"Dodging the subject and endless 'later' are avoidance; a next step, a set time and a real number are progress.","relearn":"Changing the subject and endless 'later' are avoidance; next steps and real numbers are progress.","persona":"Pooja","source":"avoidance signs"},
  {"id":"mt-1131","cat":"money-talk","type":"spot","hook":"Lensy: spot the two openers that put a partner on the defensive.","scene":[{"id":"a","text":"\"Can we plan our money as a team?\"","trick":false},{"id":"b","text":"\"You're so irresponsible with cash\"","trick":true},{"id":"c","text":"\"What do you want us to save for?\"","trick":false},{"id":"d","text":"\"I'm sick of how you spend\"","trick":true},{"id":"e","text":"\"No blame, I just want clarity\"","trick":false}],"why":"'So irresponsible' and 'sick of how you spend' attack; the team and curiosity openers invite honesty.","relearn":"Attacking openers put a partner on the defensive; team-framed, curious ones invite honesty.","persona":"Karthik","source":"defensive openers"},
  {"id":"mt-1132","cat":"money-talk","type":"spot","hook":"Lensy: spot the two myths hiding in 'we never need to talk money.'","scene":[{"id":"a","text":"Talking incomes early prevents surprises","trick":false},{"id":"b","text":"Love alone keeps money fights away","trick":true},{"id":"c","text":"Goals are worth naming out loud","trick":false},{"id":"d","text":"A good couple just instinctively agrees on money","trick":true},{"id":"e","text":"Debts are better named than hidden","trick":false}],"why":"'Love alone is enough' and 'a good couple just instinctively agrees' are myths; the rest are true habits.","relearn":"Love alone and instinct don't settle money; early honest talk about incomes, goals and debts does.","persona":"any","source":"hidden myths"},
  {"id":"mt-1133","cat":"money-talk","type":"spot","hook":"Lensy: spot the two lines that turn a money chat into a contest.","scene":[{"id":"a","text":"\"What matters most to you here?\"","trick":false},{"id":"b","text":"\"I earn more, so I'm right\"","trick":true},{"id":"c","text":"\"Let's find a split we both like\"","trick":false},{"id":"d","text":"\"At least I don't waste it like you\"","trick":true},{"id":"e","text":"\"What's one thing we can agree now?\"","trick":false}],"why":"'I earn more so I'm right' and 'at least I don't waste it' compete; the others look for agreement.","relearn":"Lines that compete or rank earners turn a money chat into a contest; agreement-seeking ones don't.","persona":"any","source":"contest lines"},
  {"id":"mt-1134","cat":"money-talk","type":"role-play","persona":"Sneha","source":"go first rp","hook":"You want to start the money talk with your partner Yusuf without putting him on the spot.","setup":"Over chai on Sunday afternoon, you finally bring it up.","steps":[{"prompt":"Yusuf asks: \"Why are you bringing this up now?\"","options":[{"text":"\"Here's what I earn and where it goes. Want to compare?\"","then":"He relaxes. \"Oh, that's fair. Let me get my numbers too.\"","best":true},{"text":"\"So where exactly is all of your money actually going?\"","then":"He tenses. \"Why does it feel like I'm being checked on?\""},{"text":"\"No reason, just curious about our finances lately, honestly.\"","then":"He shrugs, unsure how seriously to take it."},{"text":"\"I think we're spending way too much money these days, honestly.\"","then":"He gets defensive before either of you has shared a number."}],"why":"Sharing your own numbers first makes it mutual, not an interrogation."},{"prompt":"Yusuf admits: \"Honestly, I've never really tracked where my money goes.\"","options":[{"text":"\"That's okay. I only started recently. Let's look together.\"","then":"He nods, relieved it isn't only him figuring this out.","best":true},{"text":"\"Well, you really should have looked at it much sooner.\"","then":"The comment lands as a small jab, and he pulls back a little."},{"text":"\"Don't worry about it at all. I'll sort it out for both of us.\"","then":"\"Okay,\" he says, and the whole job quietly becomes yours."},{"text":"\"It's fine. Honestly, most people never really look either.\"","then":"He laughs, relieved. \"Great, so we're normal.\" The numbers stay unopened."}],"why":"Owning that you're still learning too keeps it shared, not a lecture."},{"prompt":"Yusuf asks: \"So, where does this leave us?\"","options":[{"text":"\"Let's pick one thing to fix or save toward together.\"","then":"\"Deal,\" he says, and you both pick one goal to start on this month.","best":true},{"text":"\"I'll just take it from here and tell you the plan later.\"","then":"He shrugs. \"Okay. Just tell me what to do, then.\""},{"text":"\"Nothing has to change. Talking about it was the main thing.\"","then":"He looks unsure. \"Okay. Same as before, then.\""},{"text":"\"Let's not overthink it. We'll just figure it out later.\"","then":"He nods, a little too quickly. \"Sure. Later.\""}],"why":"Picking one shared next step turns the numbers into an actual plan."}],"relearn":"Sharing your own numbers first makes it mutual, not an interrogation of theirs."},
  {"id":"mt-1135","cat":"money-talk","type":"role-play","persona":"any","source":"own the debt rp","hook":"You have to tell your partner Farhan about a debt you've been dreading to mention.","setup":"It's late, and you're both still sitting at the dinner table.","steps":[{"prompt":"Farhan looks up from his phone and asks: \"You seem off. What's up?\"","options":[{"text":"\"There's a loan I should have told you about. I want us to plan it together.\"","then":"He sets his phone down. \"Okay. I'm listening.\"","best":true},{"text":"\"It's nothing. Don't worry about my money stuff.\"","then":"\"If you say so,\" he says, though he keeps glancing your way, unconvinced."},{"text":"\"I'm just tired. That's all.\"","then":"He frowns. \"You've said that all week. Something's up.\""},{"text":"\"You're going to be upset with me.\"","then":"He tenses, bracing for something worse, and asks you to just tell him."}],"why":"Naming it plainly, without hiding it, is what actually restores trust."},{"prompt":"Farhan says: \"Don't soften any of it for me. I'd rather know it all.\"","options":[{"text":"\"It's a loan. Here's the exact amount, no rounding.\"","then":"He exhales. \"Okay. A real number we can actually plan around.\"","best":true},{"text":"\"It's a loan. Roughly this much, give or take.\"","then":"\"Roughly is hard to plan around,\" he says gently."},{"text":"\"It's a loan, but do we need the exact number tonight?\"","then":"\"I think we do,\" he says, still waiting for the figure."},{"text":"\"It's a small loan. Less than you're probably imagining.\"","then":"\"Okay,\" he says slowly. \"So how much is small?\""}],"why":"The exact number is what a real plan can actually work with."},{"prompt":"Farhan asks: \"Why didn't you tell me sooner?\"","options":[{"text":"\"I was ashamed. I should have said it earlier.\"","then":"\"Thanks for saying that,\" he says. \"Let's not do secrets again.\"","best":true},{"text":"\"I didn't think it was a big deal.\"","then":"\"It kind of was,\" he says, unconvinced by the answer."},{"text":"\"I thought I could fix it before you noticed.\"","then":"He frowns. \"And all that time I had no idea.\""},{"text":"\"Does it really matter why?\"","then":"\"It does to me,\" he says, still waiting for a real answer."}],"why":"Naming the shame honestly is what actually closes the gap between you."},{"prompt":"A week later, Farhan asks: \"Should we sit down with the loan together this weekend?\"","options":[{"text":"\"Yes. Let's set the repayments and check in each month.\"","then":"\"Good,\" he says. \"Then it's our loan to sort, not just yours.\"","best":true},{"text":"\"No need. I've got it handled on my own.\"","then":"\"Okay,\" he says, though he sounds like he'd rather see it too."},{"text":"\"Maybe later. Looking at it just makes me anxious.\"","then":"\"Okay,\" he says quietly. \"Tell me when you're ready.\""},{"text":"\"Why do you keep asking about it?\"","then":"\"Because I care,\" he says, taken aback by the question."}],"why":"Planning repayments together keeps it shared, so the debt stops being a secret you carry."}],"relearn":"Owning a hidden debt plainly and asking to plan together restores trust better than brushing it off."},
  {"id":"mt-1136","cat":"money-talk","type":"role-play","persona":"any","source":"meet a confession","hook":"Your partner Ishaan has something to confess about money, and looks nervous.","setup":"He sits down across from you at the kitchen table.","steps":[{"prompt":"Ishaan says: \"I lost some of our savings in a scheme a friend pushed. I'm so sorry.\"","options":[{"text":"\"Thank you for telling me. Let's sort this out together.\"","then":"He exhales, some of the tension leaving his shoulders.","best":true},{"text":"\"How could you possibly let something like this happen?\"","then":"He flinches and goes quiet, and stops explaining."},{"text":"\"It's fine. Honestly, don't worry about it at all.\"","then":"He looks unsure. \"It's not fine, though. It's a lot.\""},{"text":"\"We'll deal with it later. I just need a minute alone.\"","then":"He nods slowly. \"Okay. I'll be here.\""}],"why":"Meeting a confession with thanks, not blame, keeps the honesty alive."},{"prompt":"Ishaan asks: \"Be honest with me. How are you feeling about it?\"","options":[{"text":"\"Shaken, honestly. I want to understand what happened.\"","then":"\"Okay,\" he says, and starts explaining more openly.","best":true},{"text":"\"No, no. It's nothing. Let's just forget it.\"","then":"He studies your face. \"It doesn't feel like nothing.\""},{"text":"\"Why does it matter how I feel right now?\"","then":"He hesitates. \"Because I need to know where we stand.\""},{"text":"\"Let's not talk about feelings. Let's just fix it now.\"","then":"\"Okay,\" he says quietly, though he still looks braced."}],"why":"Answering honestly, and asking to understand, keeps him open instead of guessing."},{"prompt":"Ishaan asks: \"So what do we do from here?\"","options":[{"text":"\"Let's make a simple plan and check in on it together.\"","then":"\"Yeah,\" he says, sitting up a little. \"I'd like that.\"","best":true},{"text":"\"I'll just figure out the plan myself and let you know later.\"","then":"\"Okay,\" he says, though he sounds like he wanted to help build it."},{"text":"\"Let's just make sure something like this never happens again.\"","then":"\"Of course,\" he says, but neither of you says how."},{"text":"\"Honestly, I need some time before we talk about this again.\"","then":"\"Okay,\" he says softly. \"I'll wait until you're ready.\""}],"why":"Building the plan together keeps the mistake from becoming his alone."}],"relearn":"Meet a money confession with thanks, not blame, and sort it out together."},
  {"id":"mt-1137","cat":"money-talk","type":"role-play","persona":"Karthik","source":"relative says husband's business","hook":"At a family gathering, your uncle brings up how a household should handle money.","setup":"Your wife is sitting right beside you.","steps":[{"prompt":"Your uncle says: \"Money matters are for the man to handle. No need to burden her.\"","options":[{"text":"\"In our home, we both plan the money openly. It works for us.\"","then":"He raises an eyebrow but moves on to another topic.","best":true},{"text":"\"You're right. She doesn't need to worry about any of that.\"","then":"He nods approvingly, and the line stands unchallenged."},{"text":"\"That's such an old-fashioned way of thinking, Uncle.\"","then":"The room tenses, and the point gets lost in the reaction."},{"text":"\"Let's not get into it now. We'll talk about it another time.\"","then":"He takes that as agreement, and the moment passes."}],"why":"Naming your open, shared model calmly holds the line without a fight."},{"prompt":"Later, your wife asks: \"Did what your uncle said bother you?\"","options":[{"text":"\"Yes, it did. Let's be clear about how we do things.\"","then":"She relaxes. \"Good. I felt the same.\"","best":true},{"text":"\"Not really. He's just old-fashioned. Ignore it.\"","then":"\"Okay,\" she says, though she looks a little let down."},{"text":"\"A bit, but let's not make a big thing of it, okay?\"","then":"\"Okay,\" she says, but she doesn't look convinced."},{"text":"\"He has a point about some things, honestly.\"","then":"She looks surprised. \"Which things?\""}],"why":"Naming that it bothered you too shows you're aligned, not just polite in the moment."},{"prompt":"At the next family function, your aunt asks: \"Who actually handles the household money?\"","options":[{"text":"\"We handle it together. Always have.\"","then":"She nods, and the topic moves on without any tension.","best":true},{"text":"\"I mostly do, but she helps sometimes.\"","then":"Your aunt smiles. \"So you're the one in charge.\""},{"text":"\"That's a bit of a private question, isn't it?\"","then":"She laughs awkwardly. \"Only asking, dear.\""},{"text":"\"Ask her, not me.\"","then":"Your aunt turns to your wife, who wasn't expecting it."}],"why":"Naming it as fully shared, plainly, keeps the truth simple and steady."},{"prompt":"Months later, your uncle asks gently: \"Have you two given that some more thought?\"","options":[{"text":"\"We have. We plan the money together, both of us.\"","then":"He shrugs and lets it drop for good this time.","best":true},{"text":"\"I've actually been thinking you might be right.\"","then":"He smiles, pleased, and your wife goes very quiet."},{"text":"\"Can we please not bring this up again?\"","then":"He raises his hands. \"Just asking. No need to snap.\""},{"text":"\"Ask my wife. It's really her call.\"","then":"He turns to her, and she's left to answer for you both."}],"why":"Saying plainly that you decide together shows it's your choice, not a debate."}],"relearn":"Naming your open, both-of-us money model calmly holds the line without a family fight."},
  {"id":"mt-1138","cat":"money-talk","type":"role-play","persona":"Sneha","source":"invite shared goal","hook":"You want to invite your partner Rian to set savings goals together for the first time.","setup":"You bring it up over the weekend.","steps":[{"prompt":"Rian asks: \"Goals? Like what, exactly?\"","options":[{"text":"\"What's one thing you'd love for us to save toward together?\"","then":"He lights up. \"Actually, I've thought about this before.\"","best":true},{"text":"\"I've already decided what we're saving for. Just follow it.\"","then":"\"Oh,\" he says, sounding less interested than a moment ago."},{"text":"\"I don't know. Whatever we can manage each month, I suppose.\"","then":"He waits. \"Sure, but saving toward what?\""},{"text":"\"Something practical, obviously, nothing too exciting.\"","then":"He hesitates. \"Practical like what, though?\""}],"why":"Inviting him to name it makes the goal his too, not just yours."},{"prompt":"Rian says: \"Honestly, I'd love a trip somewhere new.\"","options":[{"text":"\"I love that. Let's figure out a monthly amount toward it.\"","then":"\"Yes,\" he says, already pulling out his phone to calculate.","best":true},{"text":"\"That feels a bit indulgent for a first goal, don't you think?\"","then":"He deflates. \"Fine. Maybe just a short trip, then.\""},{"text":"\"Yes! Let's book it now and sort the money later.\"","then":"He is thrilled, until you both see the cost and nothing has been set aside."},{"text":"\"Okay, I'll just start putting money aside for that then.\"","then":"\"Oh. Okay,\" he says, unsure what his part in it is."}],"why":"Building on what he actually wants makes the goal genuinely shared."},{"prompt":"Rian asks: \"How do we make sure we actually stick to this?\"","options":[{"text":"\"Let's check in on it together once a month.\"","then":"\"Deal,\" he says, and marks a reminder right then and there.","best":true},{"text":"\"I'll track it myself and update you sometimes.\"","then":"\"Okay,\" he says, though it puts the follow-through mostly on you."},{"text":"\"We'll just know if it's working out or not, honestly.\"","then":"He shrugs. \"I guess we'll find out.\""},{"text":"\"Let's not overthink the tracking part too much.\"","then":"\"Okay,\" he says, and nobody sets a reminder."}],"why":"A shared, regular check-in is what turns a goal into a habit."}],"relearn":"Inviting a partner to name a shared goal makes saving a joint project, not an order."},
  {"id":"mt-1139","cat":"money-talk","type":"role-play","persona":"Pooja","source":"make it safe rp","hook":"Your partner Manav keeps going silent whenever money comes up.","setup":"Tonight you mention the budget, and he stiffens.","steps":[{"prompt":"Manav mutters: \"Do we have to do this now?\"","options":[{"text":"\"We don't have to fix it all today. Just ten minutes, no pressure?\"","then":"\"Okay,\" he says slowly, still a little wary but willing.","best":true},{"text":"\"We're not leaving this table until you explain everything.\"","then":"He goes rigid. \"Then I've got nothing to say.\""},{"text":"\"Forget it. We'll just talk about it some other time then.\"","then":"He looks relieved. \"Okay. Another time.\""},{"text":"\"Why do you always shut down like this, every time?\"","then":"He looks away. \"I don't know. I just do.\""}],"why":"Lowering the stakes with a short, no-pressure invite helps him open up."},{"prompt":"A few days later, Manav says quietly: \"I just get anxious talking about it. That's all.\"","options":[{"text":"\"That makes sense. What would help it feel easier?\"","then":"He thinks. \"Maybe if we wrote things down first, together.\"","best":true},{"text":"\"There's honestly nothing to be anxious about, come on.\"","then":"He nods, but his shoulders stay tight. \"Right. Sure.\""},{"text":"\"Well, you'll have to get over that eventually, you know.\"","then":"He shrinks a little. \"I know. I'm trying.\""},{"text":"\"Okay, then let's just not talk about it at all anymore.\"","then":"He looks relieved, then worried. \"But the bills still need sorting.\""}],"why":"Asking what would help keeps the door open instead of forcing through it."},{"prompt":"Manav adds: \"Maybe short talks would be easier for me than one big one.\"","options":[{"text":"\"Then let's do ten minutes every Sunday, just us.\"","then":"He smiles. \"Ten minutes. I can do that.\"","best":true},{"text":"\"Sure, whenever you feel ready, honestly. No rush at all.\"","then":"\"Okay,\" he says, and no time gets set."},{"text":"\"Only if we can actually cover more ground next time.\"","then":"His face tightens. \"That's the part that makes it hard.\""},{"text":"\"Let's see how you feel about it next month, maybe.\"","then":"\"Maybe,\" he says, still braced for the next big talk."}],"why":"A short chat at a set time keeps money talk small enough to feel safe."}],"relearn":"Lowering the stakes with a short, no-pressure invite helps a withdrawn partner open up; cornering shuts them down."},
  {"id":"mt-1140","cat":"money-talk","type":"role-play","persona":"Karthik","source":"raise split rp","hook":"You earn more than your partner Alia and want to raise splitting costs so it feels fair, not handed down.","setup":"You both sit down over chai on Sunday morning.","steps":[{"prompt":"Alia asks: \"Are we finally talking about the bills?\"","options":[{"text":"\"How do we share costs so it feels fair to us both?\"","then":"She relaxes. \"Thank you for asking instead of just deciding.\"","best":true},{"text":"\"Since I earn more, here's how we'll split it all.\"","then":"She agrees, though something in her posture stiffens slightly."},{"text":"\"I don't know. You tell me what feels fair, honestly.\"","then":"She hesitates. \"Why is it on me to name a number?\""},{"text":"\"Let's not make this complicated. Fifty-fifty is simplest.\"","then":"She pauses. \"Equal sounds simple, but it would stretch me a lot more.\""}],"why":"Asking how to share costs together keeps you both equal in the decision."},{"prompt":"After a moment, Alia says: \"I'd like my share to match what I can actually afford.\"","options":[{"text":"\"Then let's split by what each of us can comfortably give.\"","then":"\"That feels fair,\" she says, visibly relieved.","best":true},{"text":"\"That's fine. I'll just quietly cover the difference each month.\"","then":"\"That's not what I meant,\" she says. \"I want to decide it with you.\""},{"text":"\"We can revisit that once you're earning a bit more.\"","then":"She goes quiet. \"So until then, I just struggle?\""},{"text":"\"Let's just keep it equal for now and see how it goes.\"","then":"\"Okay,\" she says, though the tightness doesn't really ease."}],"why":"Splitting by what each can give, not an equal number, is what actually feels fair."},{"prompt":"Alia asks: \"What happens to the split if one of our incomes changes?\"","options":[{"text":"\"Then we sit down and rework it together.\"","then":"\"Good,\" she says. \"Then it stays fair as things shift.\"","best":true},{"text":"\"No need to change it. Once it's set, it's set for good.\"","then":"\"Even if one of us loses a job?\" she asks, unconvinced."},{"text":"\"Then I'll decide whether it needs changing.\"","then":"She frowns. \"Why would that be only your call?\""},{"text":"\"Let's not plan that far ahead right now, honestly.\"","then":"\"Okay,\" she says, though the question stays with her."}],"why":"Agreeing to rework it together keeps the split fair as things change."}],"relearn":"Asking how to share costs together keeps both partners equal; decreeing it from the bigger paycheque doesn't."},
  {"id":"mt-1141","cat":"money-talk","type":"sort","hook":"Sort: when is the right moment for a money talk, or a bad moment to pick?","items":[{"id":"a","text":"A calm evening, both unhurried"},{"id":"b","text":"Mid-argument, both already angry"},{"id":"c","text":"A planned weekend check-in"},{"id":"d","text":"As one rushes out the door"},{"id":"e","text":"Over chai with no distractions"},{"id":"f","text":"Right after a money mistake, to scold"}],"bins":[{"id":"good","label":"Good moment","valence":"pos"},{"id":"bad","label":"Bad moment","valence":"neg"}],"key":{"a":"good","b":"bad","c":"good","d":"bad","e":"good","f":"bad"},"relearn":"Calm, unhurried, distraction-free moments help; angry, rushed or scolding ones sink the talk.","persona":"any","source":"good or bad moment"},
  {"id":"mt-1142","cat":"money-talk","type":"sort","hook":"Sort: makes a partner feel safe to be honest, or makes them clam up?","items":[{"id":"a","text":"\"Thanks for telling me\""},{"id":"b","text":"\"I knew you were bad with money\""},{"id":"c","text":"Listening without interrupting"},{"id":"d","text":"Throwing it back in a later fight"},{"id":"e","text":"\"Let's fix this together\""},{"id":"f","text":"Mocking their worry as silly"}],"bins":[{"id":"safe","label":"Feels safe","valence":"pos"},{"id":"clam","label":"They clam up","valence":"neg"}],"key":{"a":"safe","b":"clam","c":"safe","d":"clam","e":"safe","f":"clam"},"relearn":"Thanks, listening and 'let's fix it together' build safety; blame, mockery and grudges make a partner clam up.","persona":"any","source":"safe or clam up"},
  {"id":"mt-1170","type":"strike-rewrite","persona":"any","source":"plan before kids","hook":"\"We'll start planning money properly once the baby arrives.\"","myth":{"un":"We'll start planning money properly once the baby arrives.","re":"Plan before the baby comes: a child adds real costs while income often dips, so the cushion is built early.","why":"A plan made in calm beats one scrambled in a crisis."},"relearn":"Turn a coming baby into a shared, timed savings goal before it arrives, not after.","cat":"plan-together"},
  {"id":"mt-1171","type":"strike-rewrite","persona":"Karthik","source":"emergency fund","hook":"\"Insurance covers everything, so we don't need any emergency savings.\"","myth":{"un":"Insurance covers everything, so we don't need any emergency savings.","re":"An emergency fund covers the gaps insurance won't: a job loss, a slow month, a repair before a claim clears.","why":"A liquid cushion buys time a policy can't."},"relearn":"An emergency fund and insurance do different jobs; a couple wants both, not one instead of the other.","cat":"plan-together"},
  {"id":"mt-1172","type":"strike-rewrite","persona":"Sneha","source":"goals need a number","hook":"\"Saying 'we should save for a house someday' counts as a plan.\"","myth":{"un":"Saying 'we should save for a house someday' counts as a plan.","re":"A real goal has a number and a date; 'someday' drifts, but 'this much each month by then' actually moves.","why":"A goal you can measure is a goal you can reach."},"relearn":"A shared goal needs an amount and a timeline; a vague wish isn't a plan.","cat":"plan-together"},
  {"id":"mt-1173","type":"strike-rewrite","persona":"any","source":"small savings count","hook":"\"There's no point saving when we can only spare a few hundred a month.\"","myth":{"un":"There's no point saving when we can only spare a few hundred a month.","re":"Small, steady amounts build both a habit and a cushion; the regularity matters far more than the size.","why":"A habit started small still grows."},"relearn":"Start saving early even with little; the habit and the buffer matter more than the amount.","cat":"plan-together"},
  {"id":"mt-1174","type":"strike-rewrite","persona":"Pooja","source":"both know the money","hook":"\"One of us handling all the accounts is just being efficient.\"","myth":{"un":"One of us handling all the accounts is just being efficient.","re":"One person doing the day-to-day is fine; both knowing where the money and documents are is the safety net.","why":"If only one knows, a shock leaves the other stranded."},"relearn":"Both partners knowing the accounts and documents is part of a fair plan, not a luxury.","cat":"plan-together"},
  {"id":"mt-1175","type":"strike-rewrite","persona":"any","source":"joint plus personal","hook":"\"Real commitment means merging every rupee into one shared account.\"","myth":{"un":"Real commitment means merging every rupee into one shared account.","re":"Many couples do best with a joint account for shared costs plus personal accounts for everyday autonomy.","why":"Sharing goals doesn't mean erasing personal money."},"relearn":"Both a joint account and personal accounts often work best; sharing a life needn't surrender all autonomy.","cat":"plan-together"},
  {"id":"mt-1176","type":"strike-rewrite","persona":"any","source":"plan, not wealth","hook":"\"Financial planning is something only well-off couples need to bother with.\"","myth":{"un":"Financial planning is something only well-off couples need to bother with.","re":"Planning is about being ready together, not being rich; the smaller the income, the more a plan protects it.","why":"A tight budget needs a plan most of all."},"relearn":"Any couple can start planning; it's about readiness, not wealth.","cat":"plan-together"},
  {"id":"mt-1177","type":"strike-rewrite","persona":"Karthik","source":"plan together not for","hook":"\"I'll just build the whole budget myself and tell her the final plan.\"","myth":{"un":"I'll just build the whole budget myself and tell her the final plan.","re":"A plan you build together gets buy-in and lasts; one handed down is one only its author feels bound by.","why":"People keep the plans they helped shape."},"relearn":"Build the money plan together; a shared plan is the one you both keep.","cat":"plan-together"},
  {"id":"mt-1178","type":"sort","persona":"Pooja","source":"joint vs personal","hook":"Sort: into the shared joint pot, or kept personal?","items":[{"id":"a","text":"Monthly rent and utility bills"},{"id":"b","text":"Your gym or hobby class fee"},{"id":"c","text":"The family emergency fund"},{"id":"d","text":"A surprise anniversary gift for your partner"},{"id":"e","text":"Groceries for the household"},{"id":"f","text":"A small monthly amount that's simply yours"}],"bins":[{"id":"joint","label":"Shared / joint","valence":"pos"},{"id":"personal","label":"Personal","valence":"neutral"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Rent, groceries and the emergency fund are shared; a hobby, a surprise gift and your own money stay personal.","cat":"plan-together"},
  {"id":"mt-1179","type":"sort","persona":"any","source":"smart or risky","hook":"Sort: a smart shared-planning move, or a risky gap?","items":[{"id":"a","text":"Building an emergency fund of a few months' costs"},{"id":"b","text":"Keeping no savings and no plan at all"},{"id":"c","text":"Both partners knowing where the money is"},{"id":"d","text":"Only one partner ever seeing the accounts"},{"id":"e","text":"Saving a small amount every month"},{"id":"f","text":"Spending every rupee that comes in"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risky","label":"Risky gap","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"A fund, shared knowledge and steady saving are smart; no plan, one-person-only access and saving nothing are risky.","cat":"plan-together"},
  {"id":"mt-1180","type":"sort","persona":"any","source":"fair with unequal income","hook":"Sort: a fair way to handle unequal incomes, or an unfair one?","items":[{"id":"a","text":"Splitting shared costs in proportion to income"},{"id":"b","text":"The lower earner going without essentials"},{"id":"c","text":"Both having some personal spending money"},{"id":"d","text":"One partner controlling all the spending"},{"id":"e","text":"Agreeing the split openly together"},{"id":"f","text":"The higher earner deciding everything alone"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Proportional splits, both having spending money and deciding openly are fair; depriving or controlling aren't.","cat":"plan-together"},
  {"id":"mt-1181","type":"sort","persona":"Sneha","source":"goal or not a goal","hook":"Sort: a real, workable savings goal, or a vague wish?","items":[{"id":"a","text":"Save for a home down-payment in three years"},{"id":"b","text":"\"We should be richer one day\""},{"id":"c","text":"Put aside a set amount each month for a trip"},{"id":"d","text":"\"Money will sort itself out somehow\""},{"id":"e","text":"Build six months' expenses by next year"},{"id":"f","text":"\"Let's just save whatever's left over\""}],"bins":[{"id":"goal","label":"Real goal","valence":"pos"},{"id":"vague","label":"Vague wish","valence":"uhoh"}],"key":{"a":"goal","b":"vague","c":"goal","d":"vague","e":"goal","f":"vague"},"relearn":"A real goal names an amount and a date; a vague wish has neither and quietly never happens.","cat":"plan-together"},
  {"id":"mt-1182","type":"sort","persona":"any","source":"which pot","hook":"Sort: which pot does this money belong in?","items":[{"id":"a","text":"Three months' expenses, untouched, for shocks"},{"id":"b","text":"This month's rent and bills"},{"id":"c","text":"Cash saved toward a named future goal"},{"id":"d","text":"Your everyday personal spending"},{"id":"e","text":"Money kept ready for a sudden job loss"},{"id":"f","text":"Your partner's everyday personal spending"}],"bins":[{"id":"fund","label":"Emergency fund","valence":"pos"},{"id":"daily","label":"Day-to-day","valence":"neutral"},{"id":"goal","label":"Goal savings","valence":"tell"}],"key":{"a":"fund","b":"daily","c":"goal","d":"daily","e":"fund","f":"daily"},"relearn":"An emergency fund, day-to-day money and goal savings each do a distinct job; mixing them blurs the plan.","cat":"plan-together"},
  {"id":"mt-1183","type":"sort","persona":"Karthik","source":"plan now or later","hook":"Sort: plan for this now, or genuinely handle it later?","items":[{"id":"a","text":"A baby you're hoping for next year"},{"id":"b","text":"A spontaneous treat this weekend"},{"id":"c","text":"A home you both want within five years"},{"id":"d","text":"Tonight's dinner takeaway"},{"id":"e","text":"Retirement that's decades away"},{"id":"f","text":"A bus fare for tomorrow"}],"bins":[{"id":"plan","label":"Plan ahead","valence":"pos"},{"id":"later","label":"Handle as it comes","valence":"neutral"}],"key":{"a":"plan","b":"later","c":"plan","d":"later","e":"plan","f":"later"},"relearn":"Big, dated costs like a baby, a home or retirement need planning ahead; tiny everyday spends don't.","cat":"plan-together"},
  {"id":"mt-1184","type":"sort","persona":"any","source":"sharing not control","hook":"Sort: shared planning, or one partner taking control?","items":[{"id":"a","text":"Agreeing a budget together each month"},{"id":"b","text":"One partner approving every small purchase"},{"id":"c","text":"Both able to see the joint account"},{"id":"d","text":"Hiding the passwords from your partner"},{"id":"e","text":"Setting goals as a team"},{"id":"f","text":"Deciding the goals without asking"}],"bins":[{"id":"shared","label":"Shared planning","valence":"pos"},{"id":"control","label":"One taking control","valence":"neg"}],"key":{"a":"shared","b":"control","c":"shared","d":"control","e":"shared","f":"control"},"relearn":"Agreeing budgets and goals and sharing access is teamwork; policing purchases and hiding access is control.","cat":"plan-together"},
  {"id":"mt-1185","type":"sort","persona":"Pooja","source":"new home costs","hook":"Sort: a one-time cost of moving in, or an ongoing one?","items":[{"id":"a","text":"The security deposit on a new flat"},{"id":"b","text":"The monthly rent itself"},{"id":"c","text":"Buying the first furniture set"},{"id":"d","text":"The electricity bill each month"},{"id":"e","text":"The movers' fee on shifting day"},{"id":"f","text":"The monthly maintenance charge"}],"bins":[{"id":"once","label":"One-time cost","valence":"tell"},{"id":"ongoing","label":"Ongoing cost","valence":"neutral"}],"key":{"a":"once","b":"ongoing","c":"once","d":"ongoing","e":"once","f":"ongoing"},"relearn":"Deposits, furniture and movers are one-time; rent, bills and maintenance recur. A plan budgets for both.","cat":"plan-together"},
  {"id":"mt-1186","type":"sort","persona":"any","source":"resilient or fragile","hook":"Sort: a resilient money setup, or a fragile one?","items":[{"id":"a","text":"A cushion that covers a few lean months"},{"id":"b","text":"Everything riding on one income, no buffer"},{"id":"c","text":"Shared goals you track together"},{"id":"d","text":"No idea where you both stand financially"},{"id":"e","text":"Both partners able to access the money"},{"id":"f","text":"One shock away from real trouble"}],"bins":[{"id":"resilient","label":"Resilient","valence":"pos"},{"id":"fragile","label":"Fragile","valence":"neg"}],"key":{"a":"resilient","b":"fragile","c":"resilient","d":"fragile","e":"resilient","f":"fragile"},"relearn":"A buffer, tracked shared goals and shared access are resilient; one income and no visibility are fragile.","cat":"plan-together"},
  {"id":"mt-1187","type":"sort","persona":"any","source":"who decides what","hook":"Sort: decide it together, or fine for one partner alone?","items":[{"id":"a","text":"How much to put toward the home fund"},{"id":"b","text":"Buying yourself a chai on the way home"},{"id":"c","text":"Taking on a big loan as a couple"},{"id":"d","text":"A small gift for your own friend"},{"id":"e","text":"Changing the monthly savings amount"},{"id":"f","text":"Spending your own pocket money"}],"bins":[{"id":"together","label":"Decide together","valence":"pos"},{"id":"solo","label":"Fine on your own","valence":"neutral"}],"key":{"a":"together","b":"solo","c":"together","d":"solo","e":"together","f":"solo"},"relearn":"Big shared-money calls are decided together; ordinary personal spending needs no permission.","cat":"plan-together"},
  {"id":"mt-1188","type":"sort","persona":"Sneha","source":"start early payoff","hook":"Sort: a habit that builds a cushion, or one that erodes it?","items":[{"id":"a","text":"Saving a fixed bit the day income arrives"},{"id":"b","text":"Waiting to save 'when there's more'"},{"id":"c","text":"Reviewing the plan together monthly"},{"id":"d","text":"Never checking how the goals are going"},{"id":"e","text":"Topping up the fund after you dip into it"},{"id":"f","text":"Leaving the fund empty after an emergency"}],"bins":[{"id":"builds","label":"Builds the cushion","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Saving first, reviewing together and refilling the fund build the cushion; waiting and neglect erode it.","cat":"plan-together"},
  {"id":"mt-1189","cat":"plan-together","type":"branch","persona":"Karthik","source":"shared goal","hook":"You and your partner Latha are planning for a home, and the number feels huge.","steps":[{"prompt":"You look at the down payment figure together for the first time. What do you do?","options":[{"text":"Break it into a monthly target with a clear timeline","then":"The huge number turns into something you can actually save toward.","best":true},{"text":"Decide it's too far off to really plan for yet","then":"The clock keeps running while nothing gets set aside."},{"text":"Save whatever happens to be left each month, with no set amount","then":"Some months you save and some you don't, so the date stays a guess."},{"text":"Ask both families to help cover the gap between you","then":"It might work, but it skips building a plan of your own first."}],"why":"A timed monthly target turns a huge cost into a plan you can hold."},{"prompt":"Three months on, you've saved less than you hoped toward the down payment. What do you do?","options":[{"text":"Review the budget together to find where to trim","then":"You find a little room, and a steady monthly amount starts to feel possible.","best":true},{"text":"Quietly decide the home can wait a few more years","then":"Latha finds out later and feels left out of the change."},{"text":"Blame the shortfall on a recent purchase of hers","then":"It sours the mood without adding a rupee to the savings."},{"text":"Stop looking at the numbers since they feel discouraging","then":"With nobody looking, the saving slows even further, unnoticed."}],"why":"Reviewing the budget together finds real room without blame."},{"prompt":"A relative offers to help with part of the down payment. What do you do?","options":[{"text":"Discuss it together and decide what terms feel comfortable","then":"You agree to accept a small part, on terms you're both okay with.","best":true},{"text":"Accept everything offered without discussing any terms first","then":"It closes the gap fast, but strings you didn't ask about may follow."},{"text":"Turn it down yourself, without asking Latha what she thinks","then":"Latha learns you closed the door alone, and the timeline stretches longer."},{"text":"Let Latha decide alone since it happens to be her relative","then":"It sidelines you from a decision that affects you both."}],"why":"Deciding the terms together keeps the help from becoming a quiet obligation."},{"prompt":"Months later, you have the down payment and have found a flat you both like. What do you check before finalising?","options":[{"text":"That the loan repayments still leave room for an emergency fund","then":"It does, just, and you both feel steady going into the purchase.","best":true},{"text":"Only the down payment number itself, and nothing else at all","then":"The purchase goes through, but the cushion underneath is thin."},{"text":"Whether you can stretch further and buy something a bit bigger","then":"Stretching further eats into your safety net."},{"text":"Whether a relative would step in if repayments got tight","then":"It is reassuring, though it leans on someone else instead of your own cushion."}],"why":"Protecting the emergency fund keeps the purchase from leaving you exposed."}],"debrief":"Turn big costs into a shared, timed savings goal with an agreed monthly amount.","relearn":"Plan big costs as a shared goal with a timeline, not by hoping the money appears."},
  {"id":"mt-1190","cat":"plan-together","type":"branch","persona":"Pooja","source":"both know","hook":"You realise you and your partner Suresh don't know each other's accounts, or where the key papers are.","steps":[{"prompt":"A bank form needs details of an account only he handles. What do you do?","options":[{"text":"Suggest sitting together to list the main accounts and papers","then":"He agrees, and you pick Sunday to go through it all together.","best":true},{"text":"Ask him to just tell you the details whenever you need them","then":"It works occasionally, but leaves you stuck when he's unreachable."},{"text":"Decide it's fine since he already handles that account anyway","then":"It stays convenient today, and a risk if something ever changes."},{"text":"Ask his sister to get the details from him for you","then":"His sister mentions it to him first, and it feels like going around him."}],"why":"Sitting together to list what exists and where it is closes the gap for good."},{"prompt":"A few days later, Suresh suggests you both write down what the other would need in an emergency. What goes on the list first?","options":[{"text":"The main accounts, key papers, nominees, and where each is kept","then":"The list is short, and you both know exactly where everything is.","best":true},{"text":"Every single account you have, however minor it might be","then":"It's thorough, but it takes so long that you give up halfway."},{"text":"Just his accounts, since yours feel simple enough already","then":"It leaves him without the same access to yours in return."},{"text":"A rough mental note instead of writing anything down at all","then":"Neither of you can quite recall it a few weeks later."}],"why":"Focusing on what truly matters keeps the habit useful and doable."},{"prompt":"A few weeks later, you open a new savings account. What do you do?","options":[{"text":"Go through it with him right away so you both know the details","then":"Now you both know it, and neither of you is left in the dark.","best":true},{"text":"Mean to tell him later, once things settle down a bit","then":"\"Later\" keeps slipping, and he never hears about it."},{"text":"Mention it in passing while he's busy with something else","then":"He nods along and forgets the details within a week."},{"text":"Decide it's too small an account to bother mentioning","then":"Small accounts add up, and the gaps start to matter."}],"why":"Sharing each change right away is what keeps you both in the know."}],"debrief":"Both partners should know the accounts and documents; sole knowledge is a risk, not a convenience.","relearn":"Both partners knowing the money protects the couple; sole control is a hidden risk."},
  {"id":"mt-1191","cat":"fair-not-gendered","type":"branch","persona":"Sneha","source":"shared-pot proportion","hook":"You earn far less than your partner Dev, yet every bill splits 50/50, and it's squeezing you.","steps":[{"prompt":"Rent is due again, and counting out your half leaves almost nothing. What do you do?","options":[{"text":"Tell Dev you'd like to split by share of income instead","then":"Dev looks surprised, then asks what that would look like.","best":true},{"text":"Ask Dev to cover a bit more, just this once","then":"He agrees, though you both know the same squeeze returns next month."},{"text":"Keep paying half, since equal partners should pay equally","then":"You pay, and dip into your savings to do it."},{"text":"Quietly cut your own spending so the half still fits","then":"The rent is covered, and your own life gets smaller."}],"why":"Raising a split by share of income fixes the squeeze instead of hiding it."},{"prompt":"That weekend, Dev says he's been reading about couples who split bills by income. What do you do?","options":[{"text":"Suggest you both put your exact incomes on the table","then":"It feels a little exposing, and also finally accurate.","best":true},{"text":"Say you'd rather each guess a rough number than share salaries","then":"The guesses land close, but neither of you trusts the result."},{"text":"Tell him to set whatever split he thinks is fair","then":"He picks a number alone, and you're not sure how he got it."},{"text":"Say you'll manage with half, since you don't want to seem needy","then":"He lets it drop, and the squeeze stays yours."}],"why":"Real incomes, shared honestly, are what make a split by income share fair."},{"prompt":"At dinner, a friend jokes that splitting by income means the richer one gets taken for a ride. What do you say?","options":[{"text":"Say it's fair, because each pays the same share of their income","then":"The table goes quiet, then someone says that actually sounds fair.","best":true},{"text":"Laugh, and agree it seems a bit unfair on the higher earner","then":"Everyone laughs, and the joke starts to sound like the truth."},{"text":"Say it's only fair if the richer one feels generous","then":"A friend nods. \"So it's a favour, really.\""},{"text":"Say you'd rather keep 50/50, so nobody feels used","then":"The table agrees, and the squeeze stays invisible to them."}],"why":"The same share of each income is what makes the split fair, not the same rupees."},{"prompt":"Months later, Dev gets a big raise. What do you do?","options":[{"text":"Sit down together and rework the split around both incomes","then":"The new split lands fairly, and neither of you feels squeezed.","best":true},{"text":"Say nothing, since asking him to pay more feels greedy","then":"The split stays as it was, and the gap between you grows."},{"text":"Leave it to him to decide whether the split should change","then":"He means to bring it up, and months go by."},{"text":"Hint that he could start treating you more often","then":"He does, sometimes, and each time it feels like a favour."}],"why":"Reworking the split together keeps it fair as incomes change."},{"prompt":"A year later, a newly married cousin asks how to split bills when one earns more. What do you tell her?","options":[{"text":"Split by share of income, and work it out with real numbers","then":"She writes it down, relieved to have a concrete starting point.","best":true},{"text":"Just talk about money more, in general","then":"She nods, but still doesn't know where to start."},{"text":"Let the higher earner be generous about it","then":"She frowns. \"And if he doesn't feel generous?\""},{"text":"Every couple is different, so it's hard to give real advice","then":"She thanks you, no clearer than before."}],"why":"A split by income share, worked out with real numbers, is advice she can use."}],"debrief":"With unequal incomes, splitting by share of income is fairer than rupee-for-rupee.","relearn":"Split shared costs by proportion of income, not a flat 50/50, when you earn differently."},
  {"id":"mt-1192","cat":"plan-together","type":"branch","persona":"any","source":"windfall plan","hook":"A bonus lands in your and your partner Zoya's account that neither of you expected.","steps":[{"prompt":"Zoya sees the amount and gets excited. What do you suggest?","options":[{"text":"Talk it over and split it between the fund, a goal and some fun","then":"She likes the idea, and you sketch a rough split together.","best":true},{"text":"Spend a chunk of it on impulse before thinking it through","then":"It's a fun treat, but a chunk is already gone before you've planned the rest."},{"text":"Put most of it into savings without asking Zoya first","then":"It's mostly saved, though Zoya feels left out of deciding the rest."},{"text":"Let her decide alone since she happened to see it first","then":"She picks something for herself, and you're left to catch up on deciding the rest together."}],"why":"A planned split lets the windfall strengthen the plan and be enjoyed."},{"prompt":"That evening, you and Zoya sit down to settle where the bonus goes. What do you focus on?","options":[{"text":"A clear amount for each part: fund, goal, and a treat","then":"The split feels fair, and each part gets its own honest share.","best":true},{"text":"Whichever part feels most urgent right now, skipping the rest","then":"One part grows first, and the treat portion is still to be worked out."},{"text":"A vague sense of \"mostly saving\" without any real numbers","then":"Without a real number, exactly how much goes to the treat part is still an open question."},{"text":"Splitting it purely by who contributed more that month","then":"It turns a windfall into a small, unnecessary competition."}],"why":"Clear amounts for each part keep the split honest and fair."},{"prompt":"A week later, Zoya suggests using a little of the bonus for a day out together. What do you do?","options":[{"text":"Agree on an amount and pick something you'll both enjoy","then":"You spend what you agreed and enjoy it without second-guessing.","best":true},{"text":"Say no to a treat and put every rupee into savings","then":"More is saved, but Zoya feels the bonus brought no joy at all."},{"text":"Pick the outing yourself, without asking what she'd enjoy","then":"It's fun for you, and less so for Zoya."},{"text":"Book the fanciest option, since it's bonus money anyway","then":"It's fun in the moment, but it eats into the fund and the goal."}],"why":"Agreeing on the amount and the outing together keeps the fun shared and the rest safe."}],"debrief":"Fold a windfall into the plan: the fund, a goal, and a bit of fun for each.","relearn":"Channel an unexpected bonus through your shared plan instead of spending it on impulse."},
  {"id":"mt-1193","cat":"plan-together","type":"branch","persona":"any","source":"missed a month","hook":"Money was tight for you and your partner Kunal, and you missed saving this month.","steps":[{"prompt":"Kunal notices the savings app shows nothing added. What do you say?","options":[{"text":"Say it was a tight month, and suggest adjusting together","then":"He nods, relieved you're not treating it as a failure.","best":true},{"text":"Say the whole plan has pretty clearly failed at this point","then":"One missed month gets treated like the end of the plan."},{"text":"Avoid mentioning it and hope he lets it go without asking","then":"He brings it up anyway, and the silence beforehand adds a little worry."},{"text":"Blame the tight month mostly on his recent spending habits","then":"It turns a shared setback into a one-sided accusation."}],"why":"Naming it plainly and adjusting keeps a tight month from becoming a failure."},{"prompt":"You sit down to look at what made the month tight. What do you focus on?","options":[{"text":"What actually changed this month, without any blame","then":"You spot a one-off cost, not a real pattern, and both relax.","best":true},{"text":"Whether either of you overspent on something specific","then":"It edges back toward blame instead of real understanding."},{"text":"Whether the target amount was ever even realistic to begin with","then":"You end up doubting the whole plan over one lean month."},{"text":"Rushing through it quickly since it feels discouraging","then":"Without looking closely, next month risks the same surprise."}],"why":"Looking at what actually changed, calmly, keeps this a fix, not a fight."},{"prompt":"Next month arrives. What do you do?","options":[{"text":"Restart the saving as planned, at the same or lighter amount","then":"The rhythm picks back up, steadier for having adjusted once.","best":true},{"text":"Try to save double this month to make up for the missed one","then":"The pressure makes this month tight too, and it slips again."},{"text":"Wait one more month first, just to be sure things have settled","then":"The pause stretches longer than either of you meant it to."},{"text":"Drop the target altogether since one month already slipped","then":"The plan quietly ends over something that was never a real failure."}],"why":"Simply restarting, without overcorrecting, is what keeps the plan alive."}],"debrief":"A missed month is a tweak, not a failure. Adjust together and carry on.","relearn":"One lean month doesn't break a plan; restart it together rather than abandoning it."},
  {"id":"mt-1194","cat":"plan-together","type":"branch","persona":"Pooja","source":"income drop","hook":"Your partner Vivek takes a pay cut, and your old budget no longer fits.","steps":[{"prompt":"He tells you the new number over dinner. What do you do?","options":[{"text":"Suggest sitting down together to re-plan the budget","then":"He looks relieved it's a \"we\" problem, not just his.","best":true},{"text":"Ask what exactly he's going to do about it now","then":"He hears it as his problem alone to solve."},{"text":"Reassure him it's fine and quietly avoid the numbers for now","then":"It's kind in the moment, and the budget stays unfixed."},{"text":"Suggest you take on extra work to cover the gap alone","then":"It solves this month, but sidesteps re-planning together."}],"why":"Re-planning together turns his pay cut into a shared adjustment."},{"prompt":"A few days later, the budget question comes up again. What do you trim first?","options":[{"text":"Shared costs that can flex without hurting either of you","then":"You find enough room without either of you feeling squeezed.","best":true},{"text":"Only Vivek's own personal spending, and nothing shared","then":"It closes the gap, but it feels like his cut alone, not yours too."},{"text":"Nothing yet, hoping the pay cut turns out to be temporary","then":"The gap sits open while you wait for something uncertain."},{"text":"The savings goal, since it feels like the easiest thing to cut","then":"It's easy to cut, and it's also the part that protects you both."}],"why":"Trimming shared costs first keeps the adjustment fair to both of you."},{"prompt":"Weeks later, Vivek says the budget talks make him feel like he's failing. What do you do?","options":[{"text":"Say it's a shared problem, and keep the talks short and regular","then":"He softens, and you agree to keep each check-in to ten minutes.","best":true},{"text":"Drop the talks, and quietly track the budget on your own","then":"The spreadsheet stays accurate, and he is left out of it."},{"text":"Say it's fine, and let the budget slide so he feels better","then":"He is relieved for now, and the numbers drift a bit further each week."},{"text":"Suggest he take on extra work so the talks aren't needed","then":"It might close the gap, but the fix falls on him and the talks are still due."}],"why":"Keeping the talks short and shared keeps a pay cut from becoming his burden alone."},{"prompt":"A few months later, Vivek's income recovers a little. What do you do?","options":[{"text":"Sit down together and rework the budget for the new income","then":"You decide together what the new number allows, and it feels steady.","best":true},{"text":"Quietly go back to your old spending habits from before","then":"Spending drifts up again before you've checked what the new income allows."},{"text":"Let Vivek decide alone since it's really his income change","then":"It leaves you out of a decision that affects you both."},{"text":"Keep everything exactly as it is for now, just to be safe","then":"It's cautious, but the budget stops matching your real life."}],"why":"Reworking the budget together keeps it matching your real life."}],"debrief":"When income changes, re-plan together rather than letting the budget silently break.","relearn":"A pay cut means re-planning as a team, not pretending the old budget still works."},
  {"id":"mt-1195","cat":"plan-together","type":"branch","persona":"Karthik","source":"baby costs","hook":"You and your partner Ritu are expecting your first child, and the costs feel overwhelming.","steps":[{"prompt":"You sit down to talk through the money side for the first time. What do you do first?","options":[{"text":"List the new costs and the likely income dip honestly","then":"Ritu relaxes slightly, seeing the shape of it laid out clearly.","best":true},{"text":"Avoid the numbers for now since they feel too stressful","then":"The stress grows quietly while nothing gets planned."},{"text":"Assume family will help cover whatever costs come up","then":"It might happen, but it's not a plan you can actually count on."},{"text":"Focus only on the single biggest cost for the moment","then":"The smaller, steady costs slip through completely unplanned."}],"why":"Naming the costs and the income dip early makes the unknown fundable."},{"prompt":"A few days later, you sit down to actually build a savings goal. What do you prioritise?","options":[{"text":"A timed monthly amount that covers the real gap","then":"The overwhelming number turns into a steady monthly habit.","best":true},{"text":"A rough guess, since exact numbers feel nearly impossible now","then":"The guess leaves the plan shakier than it really needs to be."},{"text":"Whatever's easiest to save comfortably this particular month","then":"It's doable now, but doesn't actually track toward the real gap."},{"text":"Ritu's income dip alone, while ignoring the new costs entirely","then":"Half the picture is planned, and half of it simply isn't."}],"why":"A monthly amount tied to the real gap makes the plan solid."},{"prompt":"A relative offers unsolicited advice on what you \"must\" buy for the baby. What do you do?","options":[{"text":"Thank her, then decide together what actually fits your plan","then":"You keep the plan realistic instead of letting the list balloon.","best":true},{"text":"Buy everything on her list, just to feel safe about it","then":"The budget strains under a list that was never really yours."},{"text":"Dismiss her advice outright, without really hearing it","then":"It closes a door that might have had something useful in it."},{"text":"Let her decide the baby's whole budget for you instead","then":"It sidesteps the plan you and Ritu had actually built."}],"why":"Weighing advice against your own plan keeps the budget realistic."},{"prompt":"The due date gets closer, and Ritu asks if you're actually ready. What do you say?","options":[{"text":"Go over the numbers together and see where you stand","then":"You see exactly where you stand, and what's left to sort before the due date.","best":true},{"text":"Say yes right away, without actually checking the numbers","then":"It sounds reassuring, but neither of you actually knows."},{"text":"Say you're worried, without offering anything concrete to fix it","then":"The worry sits there without a plan to actually answer it."},{"text":"Say the family will step in if you happen to fall short","then":"Ritu isn't reassured, since it's a hope and not a plan."}],"why":"Going over the numbers together is what real readiness looks like."}],"debrief":"A coming baby is a shared, timed goal: list the costs and the income dip, then plan.","relearn":"Plan a baby's costs and the income dip early as a shared goal, rather than avoiding the numbers."},
  {"id":"mt-1196","cat":"plan-together","type":"branch","persona":"any","source":"first plan together","hook":"You and your partner Imran are moving in together and want to set up the money side from scratch.","steps":[{"prompt":"You sit down on move-in weekend to talk about it. What do you propose?","options":[{"text":"Agree which costs are shared, then open a joint pot","then":"Imran likes the clarity, and you open the joint pot that week.","best":true},{"text":"Say you'll just see how it goes and sort money out later","then":"Nothing gets decided, and the question waits for the first bills."},{"text":"Suggest whoever happens to pay first for something just covers it","then":"It's easy at first, and it gets confusing within a month."},{"text":"Propose keeping money separate, and settling shared bills as they come","then":"It feels tidy, until each shared bill needs its own negotiation."}],"why":"Agreeing the shared/personal split now prevents drift and confusion later."},{"prompt":"A couple of weeks in, the first bills arrive and Imran asks which ones you should share. What do you include?","options":[{"text":"Rent, utilities and other clearly shared costs","then":"The list is short and obvious, and you both agree quickly.","best":true},{"text":"Everything either of you spends, just to keep it simple","then":"It's simple on paper, and it erases any personal spending room."},{"text":"Only the single biggest bill, handling the rest separately","then":"Smaller shared costs keep needing separate conversations."},{"text":"Whatever Imran happens to suggest, without adding your own view","then":"The list ends up shaped mostly by his priorities, not both."}],"why":"Keeping the joint pot to clearly shared costs makes the system simple and fair."},{"prompt":"A month in, the washing machine breaks and needs a costly repair. What do you do?","options":[{"text":"Sit down together, agree how to cover it, and note it","then":"The system flexes easily, and nothing feels like a surprise.","best":true},{"text":"Pay it quietly yourself and don't record it anywhere","then":"It's sorted, but untracked costs start to build up."},{"text":"Decide on your own how it should be split between you","then":"It might be right, but Imran wasn't part of the call."},{"text":"Argue over whose fault it is and who should pay for it","then":"The repair turns into a bigger fight than it needed to be."}],"why":"Deciding surprise costs together keeps the system honest as life changes."},{"prompt":"Three months on, you check in on how the setup is working. What do you ask?","options":[{"text":"Whether the split still feels fair to you both","then":"Imran says mostly, with one small tweak, and you adjust it.","best":true},{"text":"Whether you're spending noticeably less than before overall","then":"It tells you about spending, not whether the split feels fair."},{"text":"Nothing much, since nobody's actually complained about it","then":"Silence isn't the same as it actually working well for both."},{"text":"Whether Imran thinks it's fair, without sharing your own view","then":"The check-in becomes one-sided instead of a real conversation."}],"why":"Asking if it still feels fair to both of you keeps the structure honest."}],"debrief":"Set up the shared/personal split early; a little structure now saves friction later.","relearn":"Build a light money structure when you move in together, rather than leaving it to drift."},
  {"id":"mt-1197","cat":"plan-together","type":"branch","persona":"Sneha","source":"goal clash","hook":"You want to save for travel; your partner Devansh wants to save for a home first.","steps":[{"prompt":"You each name your priority out loud for the first time. What do you suggest?","options":[{"text":"Set both as goals and agree how to split savings between them","then":"Devansh relaxes, glad his goal isn't being dismissed.","best":true},{"text":"Insist your own goal comes first and his can simply wait","then":"He goes quiet, and the disagreement doesn't really resolve."},{"text":"Drop your own goal so his gets the full funding instead","then":"It's generous, and you privately wonder if your own goal still deserves a slice."},{"text":"Suggest saving for neither goal until you fully agree","then":"Nothing moves forward while you wait for full agreement."}],"why":"Splitting the savings between both goals keeps you a team, not rivals."},{"prompt":"A few days later, you sit down to talk numbers. What do you propose?","options":[{"text":"A percentage for each goal that you both find reasonable","then":"He agrees easily, since both goals are actually moving now.","best":true},{"text":"Whichever goal is closer to being reached gets funded first","then":"It's efficient, but the other goal keeps waiting its turn."},{"text":"A strict fifty-fifty split, no matter how each goal actually feels","then":"It is simple and even, though it ignores how different the two goals really are."},{"text":"Let Devansh set the numbers, since a home feels more urgent","then":"The split ends up shaped mostly around his priority."}],"why":"An agreed split that funds both goals keeps neither of you waiting alone."},{"prompt":"Six months later, the home goal feels well underway and the travel goal lags. What do you do?","options":[{"text":"Check in together and see if the split still feels fair","then":"You tweak it slightly, and both goals keep moving steadily.","best":true},{"text":"Shift more money toward travel just to even things up","then":"It evens the totals, but skips actually talking it through."},{"text":"Quietly accept that home will always come first from now on","then":"The travel goal quietly slides toward the bottom of the list."},{"text":"Stop tracking the totals since comparing them feels a bit tense","then":"Without tracking, one goal can quietly stall unnoticed."}],"why":"Checking in together keeps the split fair as the goals actually move."}],"debrief":"Two goals can share the savings: agree a split rather than ranking one above the other.","relearn":"When goals differ, fund both with an agreed split instead of making one partner wait."},
  {"id":"mt-1198","cat":"plan-together","type":"branch","persona":"any","source":"big loan","hook":"A relative offers to lend you and your partner Naina a large sum, so you can buy a home sooner.","steps":[{"prompt":"The offer comes up at a family lunch. What do you say in the moment?","options":[{"text":"Thank them, and say you'll discuss it together first","then":"Naina catches your eye, glad you didn't answer for both of you.","best":true},{"text":"Accept the offer on the spot since it sounds so generous","then":"Naina hears you agree on the spot, surprised you didn't check with her first."},{"text":"Refuse outright without hearing any more about it first","then":"The relative looks hurt, but says the offer stays open if you change your mind."},{"text":"Say Naina will decide, since it's really her family's offer","then":"It sidesteps the decision instead of making it together."}],"why":"Saying you'll decide together first keeps the choice actually shared."},{"prompt":"That evening, you and Naina sit down to talk about it. What do you focus on first?","options":[{"text":"Whether the repayment fits your existing plan","then":"Laying it against the budget, the picture gets a lot clearer.","best":true},{"text":"How grateful you should feel about such a generous offer","then":"Gratitude fills the conversation, and the numbers wait."},{"text":"Whether saying no would offend the relative badly","then":"Worrying about offence crowds out the actual money question."},{"text":"How much faster the loan lets you move compared to saving","then":"Speed becomes the whole conversation, and cost gets skipped."}],"why":"Checking it against your plan is what actually protects your finances."},{"prompt":"The numbers show the loan would stretch your monthly budget noticeably. What do you do?","options":[{"text":"Propose a smaller amount, or a longer payback period","then":"The relative is open to it, and the fit gets a lot easier.","best":true},{"text":"Take the full amount anyway since it's already been offered","then":"It's accepted, and the monthly squeeze arrives right along with it."},{"text":"Take it all, and promise yourself you'll pick up extra work","then":"The repayments fit on paper, though you already wonder how many extra hours it will take."},{"text":"Ask Naina's parents to help cover the difference on top of that","then":"It solves the maths, and adds another relationship to manage."}],"why":"Adjusting the terms to fit your plan keeps the help useful, not a strain."},{"prompt":"A week later, you go ahead with the loan, and the relative asks how to set it up. What do you do?","options":[{"text":"Put the terms in writing, kindly, so everyone's clear","then":"It feels a little formal, and it protects the relationship later.","best":true},{"text":"Just shake hands and trust the verbal agreement between you","then":"It's warmer in the moment, and if memories differ later, there's nothing written to check."},{"text":"Avoid mentioning any repayment dates to keep things easy","then":"Vagueness now can turn into tension whenever payments are due."},{"text":"Let Naina handle all of the paperwork alone this time","then":"It sidelines you from a decision you should both stand behind."}],"why":"Writing the terms down keeps the loan clear, and the relationship intact."},{"prompt":"A year later, a repayment is due the same week as a tight month. What do you do?","options":[{"text":"Tell the relative honestly and ask for a short adjustment","then":"They understand, and the plan flexes without any hard feeling.","best":true},{"text":"Miss the payment this time without saying anything about it","then":"The silence worries the relative more than a late payment would have."},{"text":"Borrow again elsewhere just to cover this one payment","then":"One loan quietly becomes two, and the plan gets harder to hold."},{"text":"Skip a different bill instead to make the loan payment on time","then":"One obligation gets paid by quietly creating another."}],"why":"Honest, early communication keeps a family loan manageable under pressure."}],"debrief":"A big loan is a shared decision: check it against your plan before saying yes.","relearn":"Decide on a big loan together against your budget, not on the spot."},
  {"id":"mt-1199","cat":"plan-together","type":"branch","persona":"any","source":"emergency fund first","hook":"You and your partner Om have saved a little and aren't sure whether to invest it or keep it handy.","steps":[{"prompt":"Om suggests putting it all into an investment right away. What do you say?","options":[{"text":"Suggest building a few months' cushion first","then":"He agrees, once you explain the reasoning behind it.","best":true},{"text":"Agree right away, since investing sounds like the smarter move","then":"It sounds smart, and it leaves nothing accessible for a surprise."},{"text":"Suggest keeping it all sitting in cash indefinitely instead","then":"It's safe, but it also stops the money from ever growing."},{"text":"Let Om decide alone since he's the one who follows the markets","then":"It sidelines you from a decision that affects you both."}],"why":"A cushion first is a safety net before you chase any returns."},{"prompt":"A month later, Om's laptop dies and needs replacing that week. What do you aim to keep within reach from now on?","options":[{"text":"A few months of essential expenses, clearly reachable","then":"It feels solid, and you both know exactly where it sits.","best":true},{"text":"As much as possible, honestly, before anything else at all","then":"Everything goes into it, and nothing is left to grow."},{"text":"A vague \"enough for emergencies\", left unspecified for now","then":"Without a number, it's hard to know when it's actually done."},{"text":"Whatever happens to be left after this month's investing","then":"The cushion becomes an afterthought instead of the priority."}],"why":"A clear, reachable target makes the cushion an actual plan, not a guess."},{"prompt":"Some months later, Om asks what to do with new savings from here. What do you say?","options":[{"text":"Invest the rest together, keeping the cushion topped up","then":"You both feel steadier starting to invest, with a net underneath.","best":true},{"text":"Keep adding to the cushion indefinitely, honestly, just in case","then":"The safety net is generous, and the money never really moves further."},{"text":"Spend the extra now that the cushion feels reasonably secure","then":"The cushion holds, but nothing beyond it actually grows."},{"text":"Let Om start investing all the new amounts on his own","then":"It sidelines you from decisions about money that's still shared."}],"why":"Once the cushion is set, growing the rest together is the natural next step."}],"debrief":"Build the reachable emergency cushion before tying money up, safety net first.","relearn":"Set up an accessible emergency fund before locking savings away for the long term."},
  {"id":"mt-1200","type":"match","persona":"any","source":"the money tools","hook":"Match each money tool to the job it does.","pairs":[{"left":"Joint account","right":"Shared bills and goals"},{"left":"Personal accounts","right":"Each partner's autonomy"},{"left":"Emergency fund","right":"A cushion for shocks"},{"left":"A timed goal","right":"Funding a big planned cost"},{"left":"A monthly check-in","right":"Keeping the plan on track"}],"relearn":"Each money tool, like joint, personal, fund, goal or check-in, does a distinct, useful job in a fair plan.","cat":"plan-together"},
  {"id":"mt-1201","type":"match","persona":"any","source":"plan for changes","hook":"Match each life change to the planning it calls for.","pairs":[{"left":"A new baby","right":"Budget for new costs and a lower income"},{"left":"Buying a home","right":"A down-payment and EMI plan"},{"left":"A job loss","right":"Lean on the emergency fund"},{"left":"A move to a new city","right":"Deposit, shifting and setup costs"},{"left":"Caring for an ageing parent","right":"Plan for their added monthly needs"}],"relearn":"Each life change, like a baby, a home, a job loss, a move, or a parent, calls for the couple to re-plan together.","cat":"plan-together"},
  {"id":"mt-1202","type":"match","persona":"Sneha","source":"goal to timeline","hook":"Match each goal to the kind of timeline it needs.","pairs":[{"left":"This year's festival spending","right":"A short, near-term plan"},{"left":"A home down-payment","right":"A several-year savings goal"},{"left":"An emergency cushion","right":"Build it first, then maintain"},{"left":"A child's future education","right":"A long, steady, decades-out goal"},{"left":"A weekend trip","right":"A small, quick top-up"}],"relearn":"Goals run on different clocks: near-term, multi-year, ongoing and decades-out all need their own plan.","cat":"plan-together"},
  {"id":"mt-1203","type":"match","persona":"Pooja","source":"who pays what","hook":"Match each cost to where it fairly sits in your plan.","pairs":[{"left":"Rent and household bills","right":"The shared joint pot"},{"left":"Your personal hobby","right":"Your own money"},{"left":"A surprise for your partner","right":"Kept private, your side"},{"left":"The kids' school fees","right":"A shared, planned-for cost"},{"left":"A gift for your own friend","right":"Your personal spending"}],"relearn":"Household and shared costs go in the joint pot; hobbies, surprises and personal gifts stay personal.","cat":"plan-together"},
  {"id":"mt-1229","type":"match","persona":"any","source":"plan step to purpose","hook":"Match each planning step to why it matters.","pairs":[{"left":"Naming a goal's amount","right":"Makes 'someday' measurable"},{"left":"Setting a date","right":"Turns a wish into a schedule"},{"left":"Saving the day income arrives","right":"Saves before it gets spent"},{"left":"Both knowing the accounts","right":"Protects you if one is away"},{"left":"A monthly review","right":"Catches drift early"}],"relearn":"An amount, a date, saving first, shared access and a review each move a plan from intention to result.","cat":"plan-together"},
  {"id":"mt-1204","type":"match","persona":"any","source":"fair vs unfair basis","hook":"Match each split idea to whether it's fair or unfair.","pairs":[{"left":"Share costs by income","right":"Fair: fits what each can give"},{"left":"Lower earner goes without","right":"Unfair: deprivation, not a plan"},{"left":"Both get spending money","right":"Fair: autonomy for each"},{"left":"Top earner decides alone","right":"Unfair: a vote bought by salary"},{"left":"Agree the split openly","right":"Fair: built together"}],"relearn":"Fair splits fit each partner's means and are agreed openly; deprivation and salary-bought votes are unfair.","cat":"plan-together"},
  {"id":"mt-1205","type":"match","persona":"Karthik","source":"goal to action","hook":"Match each shared goal to its first concrete step.","pairs":[{"left":"An emergency fund","right":"Auto-save a set amount monthly"},{"left":"A home down-payment","right":"Open a dedicated savings goal"},{"left":"A planned baby","right":"List the new costs together"},{"left":"A debt-free year","right":"List loans and a payoff order"},{"left":"A family holiday","right":"Set a date and a target sum"}],"relearn":"Every shared goal has a first concrete step: automate, open, list, or set a target, to get it moving.","cat":"plan-together"},
  {"id":"mt-1206","type":"match","persona":"any","source":"account to its job","hook":"Match each account or pot to what it's best kept for.","pairs":[{"left":"The joint account","right":"Rent, bills and shared goals"},{"left":"Your personal account","right":"Your own everyday spending"},{"left":"The emergency fund","right":"Untouched until a real shock"},{"left":"A goal savings pot","right":"A named, dated future cost"},{"left":"Both partners' access","right":"Visibility, not one-person control"}],"relearn":"Joint for shared, personal for your own, fund for shocks, goal pot for the future, and access for both.","cat":"plan-together"},
  {"id":"mt-1207","type":"reflect","persona":"any","source":"revisit the plan","hook":"Lensy: a money plan isn't set in stone. Job change, baby, move? Revisit it together when life shifts?","prompt":"What do you think?","options":["Revisit when life shifts","Review regularly","Agreed"],"affirm":"A plan you revisit together as life changes stays useful, instead of quietly becoming wrong and ignored.","relearn":"Revisit the money plan together whenever life changes; a plan is a living thing, not a one-time deal.","cat":"plan-together"},
  {"id":"mt-1208","type":"reflect","persona":"any","source":"ready not rich","hook":"Lensy: planning isn't about being rich, it's about being ready, together. Sit right?","prompt":"What's your take?","options":["Ready together","Sits right","Not about being rich"],"affirm":"Planning is about being ready together, not being rich; any couple can begin.","relearn":"Planning is about being ready together, not being rich; any couple can start.","cat":"plan-together"},
  {"id":"mt-1209","type":"reflect","persona":"Sneha","source":"start small now","hook":"Lensy: a small amount saved today beats a big amount you keep meaning to start. Worth beginning?","prompt":"How does that land?","options":["Start small now","Better than waiting","Begin today"],"affirm":"Starting early with small amounts builds the habit and the cushion that protect a couple.","relearn":"Start saving early even with small amounts; the habit and cushion matter more than the size.","cat":"plan-together"},
  {"id":"mt-1210","type":"reflect","persona":"Pooja","source":"both know money","hook":"Lensy: it's care, not distrust, for both of you to know where the money sits. Feel true?","prompt":"What do you reckon?","options":["Feels true","Care, not distrust","Both should know"],"affirm":"Both partners knowing the accounts and documents is a shared safety net, not a sign of mistrust.","relearn":"Both partners knowing where the money sits is shared care, not distrust.","cat":"plan-together"},
  {"id":"mt-1211","type":"reflect","persona":"any","source":"own and shared","hook":"Lensy: you can pool for the shared life and still keep a little that's simply yours. Sound right?","prompt":"What's your view?","options":["Both can be true","Some that's mine","Pool and keep"],"affirm":"A joint pot for shared costs and personal money for autonomy can comfortably live side by side.","relearn":"You can pool for shared life and still keep some money that's simply your own.","cat":"plan-together"},
  {"id":"mt-1212","type":"reflect","persona":"any","source":"check in monthly","hook":"Lensy: a quick, kind money check-in each month keeps small things from becoming fights. Try it?","prompt":"How does that sit?","options":["Worth a try","Catch it early","A monthly chat"],"affirm":"A light, goal-framed monthly check-in keeps money collaborative instead of letting friction build.","relearn":"A light monthly money check-in keeps the plan collaborative instead of letting friction build.","cat":"plan-together"},
  {"id":"mt-1213","type":"reflect","persona":"Karthik","source":"goal we both want","hook":"Lensy: saving feels lighter when it's a goal you both actually want. Pick one together?","prompt":"What do you feel?","options":["Pick one together","Lighter that way","A goal we share"],"affirm":"A goal both partners care about turns saving into a shared project rather than a chore one imposes.","relearn":"A goal you both want turns saving into a shared project, not a chore one partner imposes.","cat":"plan-together"},
  {"id":"mt-1214","type":"reflect","persona":"any","source":"adjust not abandon","hook":"Lensy: a plan that bends in a hard month is stronger than one that snaps. Make yours flexible?","prompt":"What's your take?","options":["Make it flexible","Bend, don't snap","Adjust as we go"],"affirm":"A plan you adjust together through tough months lasts far longer than a rigid one you abandon at the first miss.","relearn":"Adjust the plan together through a hard month; a flexible plan outlasts a rigid one you abandon.","cat":"plan-together"},
  {"id":"mt-1215","type":"spot","persona":"any","source":"fragile setup flags","hook":"Spot the two red flags in this couple's money setup.","scene":[{"id":"a","text":"An emergency fund covering a few months","trick":false},{"id":"b","text":"Everything riding on one income, no buffer","trick":true},{"id":"c","text":"Shared goals they track together","trick":false},{"id":"d","text":"Only one of them knows the accounts","trick":true},{"id":"e","text":"Both can see where the money is","trick":false}],"why":"Everything on one income with no buffer, and only one partner knowing the accounts, are the fragile, risky parts.","relearn":"Resilience is a buffer and shared access; one income and sole knowledge are the fragile parts.","cat":"plan-together"},
  {"id":"mt-1216","type":"spot","persona":"Sneha","source":"weak goal flags","hook":"Spot the two lines that aren't really a plan.","scene":[{"id":"a","text":"\"Save 50,000 toward the trip by December\"","trick":false},{"id":"b","text":"\"We'll save whatever happens to be left\"","trick":true},{"id":"c","text":"\"Set aside a fixed amount each month\"","trick":false},{"id":"d","text":"\"Money will sort itself out somehow\"","trick":true},{"id":"e","text":"\"Aim for six months' expenses by next year\"","trick":false}],"why":"'Save whatever's left' and 'it'll sort itself out' have no amount or date. They're wishes, not plans.","relearn":"A real goal names an amount and a date; lines without either are wishes, not plans.","cat":"plan-together"},
  {"id":"mt-1217","type":"spot","persona":"any","source":"control creeping in","hook":"Spot the two moves where fair planning slips into one partner controlling.","scene":[{"id":"a","text":"Agreeing the monthly budget together","trick":false},{"id":"b","text":"One partner approving every small purchase","trick":true},{"id":"c","text":"Both able to see the joint account","trick":false},{"id":"d","text":"Hiding the account passwords from your partner","trick":true},{"id":"e","text":"Setting savings goals as a team","trick":false}],"why":"Policing every purchase and hiding the passwords are control, not planning: the two red flags here.","relearn":"Agreeing budgets and sharing access is planning; policing purchases and hiding access is control.","cat":"plan-together"},
  {"id":"mt-1218","type":"spot","persona":"Pooja","source":"hidden vulnerability flags","hook":"Spot the two habits that leave a couple exposed in a crisis.","scene":[{"id":"a","text":"Both partners know the key documents","trick":false},{"id":"b","text":"Only one tracks every account and password","trick":true},{"id":"c","text":"A reachable emergency cushion exists","trick":false},{"id":"d","text":"No savings set aside for any shock","trick":true},{"id":"e","text":"Goals are reviewed together monthly","trick":false}],"why":"One person holding all access and having no cushion for a shock are the two habits that leave a couple exposed.","relearn":"Sole access to the money and no cushion for a shock are the habits that leave a couple exposed.","cat":"plan-together"},
  {"id":"mt-1219","type":"spot","persona":"any","source":"budget gaps","hook":"Spot the two gaps in this couple's brand-new budget.","scene":[{"id":"a","text":"Rent and bills are accounted for","trick":false},{"id":"b","text":"Nothing set aside for emergencies","trick":true},{"id":"c","text":"A small monthly savings amount agreed","trick":false},{"id":"d","text":"No personal spending money for either","trick":true},{"id":"e","text":"Shared goals written down with dates","trick":false}],"why":"No emergency cushion and no personal spending money for either partner are the two gaps a fair budget should fill.","relearn":"A fair budget covers an emergency cushion and some personal spending money for each partner.","cat":"plan-together"},
  {"id":"mt-1220","type":"spot","persona":"Karthik","source":"unfair split flags","hook":"Spot the two unfair moves in how this couple splits money.","scene":[{"id":"a","text":"Shared costs split in proportion to income","trick":false},{"id":"b","text":"The lower earner left without essentials","trick":true},{"id":"c","text":"Both keep some personal spending money","trick":false},{"id":"d","text":"The top earner decides everything alone","trick":true},{"id":"e","text":"The split was agreed openly together","trick":false}],"why":"Leaving the lower earner without essentials and letting the top earner decide alone are the two unfair moves.","relearn":"Depriving the lower earner and letting the top earner decide alone are the unfair moves to catch.","cat":"plan-together"},
  {"id":"mt-1221","type":"spot","persona":"any","source":"plan-drift flags","hook":"Spot the two habits that quietly let a money plan drift.","scene":[{"id":"a","text":"A fixed amount saved the day income lands","trick":false},{"id":"b","text":"Never checking how the goals are going","trick":true},{"id":"c","text":"Refilling the fund after dipping into it","trick":false},{"id":"d","text":"Leaving the fund empty after an emergency","trick":true},{"id":"e","text":"A quick monthly review together","trick":false}],"why":"Never reviewing the goals and never refilling the emptied fund are the two habits that let a plan quietly drift.","relearn":"Reviewing goals and refilling the fund keep a plan alive; neglecting both lets it quietly drift.","cat":"plan-together"},
  {"id":"mt-1222","cat":"plan-together","type":"role-play","persona":"Karthik","source":"windfall talk","hook":"A bonus just landed, and you want to decide with your partner Meher how to use it.","setup":"You bring it up before either of you spends it.","steps":[{"prompt":"Meher asks: \"So what are you thinking, for the bonus?\"","options":[{"text":"\"Before it disappears, can we agree how to split it?\"","then":"\"Yes, let's actually plan it this time,\" she says.","best":true},{"text":"\"It's basically my bonus, so I'll handle it myself.\"","then":"\"Oh,\" she says, a little surprised it isn't a shared decision."},{"text":"\"Let's not overthink it. It'll probably sort itself out.\"","then":"She hesitates. \"Last time, it just vanished.\""},{"text":"\"You decide. Honestly, I don't mind either way.\"","then":"\"Okay,\" she says, though she'd rather decide it together."}],"why":"Agreeing a split up front keeps a windfall from quietly disappearing."},{"prompt":"Meher says: \"I'd love to put some toward the emergency fund.\"","options":[{"text":"\"Good idea. Let's also set aside a bit for something fun.\"","then":"\"Deal,\" she says, already smiling at the idea of the fun part.","best":true},{"text":"\"Let's just put all of it straight into the fund then.\"","then":"\"All of it?\" she asks. \"Then nothing's left for us to enjoy.\""},{"text":"\"I'd rather spend most of it now, honestly, while we can.\"","then":"\"Most of it?\" she says, frowning. \"The fund needs more than that.\""},{"text":"\"Whatever you think. I don't have a strong opinion on it.\"","then":"\"I'd like your actual opinion too,\" she says gently."}],"why":"Balancing the fund with a bit of fun keeps the split feeling fair to both."},{"prompt":"Meher asks: \"So how do we actually split the numbers?\"","options":[{"text":"\"Let's write down clear amounts for each part right now.\"","then":"\"Good,\" she says, and you settle on the numbers together.","best":true},{"text":"\"Roughly however it feels right in the moment, honestly.\"","then":"She frowns. \"Then we'll just end up spending it.\""},{"text":"\"I'll work it out myself and just let you know after.\"","then":"\"Okay,\" she says, though she'd rather be part of settling it."},{"text":"\"Let's decide later, once we've both thought about it more.\"","then":"\"Okay,\" she says, \"as long as later doesn't mean never.\""}],"why":"Clear numbers, decided together, keep the split honest and real."}],"relearn":"Decide windfalls together up front: split between saving and a shared treat before it quietly vanishes."},
  {"id":"mt-1223","cat":"plan-together","type":"role-play","persona":"Pooja","source":"both-know talk","hook":"You want you and your partner Nikhil to both know the accounts, without it sounding like distrust.","setup":"It's a quiet evening at home.","steps":[{"prompt":"Nikhil asks: \"Why now? Is something wrong?\"","options":[{"text":"\"Nothing's wrong. Let's spend ten minutes so we both know the accounts, just in case.\"","then":"\"Fair enough,\" he says, relaxing once he hears the reason.","best":true},{"text":"\"You handle all of it. Honestly, I don't need to know.\"","then":"\"Okay,\" he says, though it leaves you without a real picture."},{"text":"\"I just have a bad feeling lately. That's all.\"","then":"He tenses, unsure what exactly prompted the worry."},{"text":"\"Never mind. It's really not that important anyway.\"","then":"The moment passes, and the gap in knowing stays open."}],"why":"Naming it as shared safety, not suspicion, keeps the request light."},{"prompt":"A few days later, Nikhil asks: \"Should we actually go through the accounts together?\"","options":[{"text":"\"Let's list the main accounts and where the key papers are.\"","then":"He nods and starts pulling up his banking app right away.","best":true},{"text":"\"Just tell me whenever it actually matters.\"","then":"\"Sure,\" he says. \"Just ask me when you need something.\""},{"text":"\"Let's cover every single account, however small it is.\"","then":"\"Every single one?\" he asks, already looking tired."},{"text":"\"I'll just watch while you handle it. That's easiest.\"","then":"\"Okay,\" he says, and clicks through it all faster than you can follow."}],"why":"Starting with the essentials keeps the habit doable, not overwhelming."},{"prompt":"Weeks later, Nikhil asks: \"Do you want us to look at the accounts together now and then, so neither of us is guessing?\"","options":[{"text":"\"Yes, let's make it a quiet yearly habit.\"","then":"\"Good idea,\" he says, and notes it down for next year.","best":true},{"text":"\"No need. Honestly, we'll know if something's wrong.\"","then":"\"Maybe,\" he says, though you both know things keep changing."},{"text":"\"Only if something changes first, I suppose.\"","then":"\"Okay,\" he says, and neither of you sets a date."},{"text":"\"Let's not plan that far ahead just yet.\"","then":"\"Fair,\" he says, and the idea drifts off."}],"why":"Making it a regular, small habit keeps the safety net current over time."}],"relearn":"Asking that both of you know the accounts and papers is shared safety, not a sign of distrust."},
  {"id":"mt-1224","cat":"plan-together","type":"role-play","persona":"Sneha","source":"keep some own","hook":"You and your partner Dhruv are setting up your money, and you want a little of your own.","setup":"It's Sunday, and you're both at the kitchen table.","steps":[{"prompt":"Dhruv says: \"I think one joint account makes everything simpler.\"","options":[{"text":"\"Let's pool for shared life, and each keep a little that's ours.\"","then":"He pauses, then nods. \"Okay, that makes sense too.\"","best":true},{"text":"\"Fine, take it all. I'll keep nothing separate from now on.\"","then":"\"If you're sure,\" he says, sounding unsure himself."},{"text":"\"No, I'd honestly rather keep everything fully separate.\"","then":"He looks disappointed. He'd hoped for more shared ground."},{"text":"\"Whatever you think is best. Honestly, I don't mind.\"","then":"\"I'd like to know what you actually think,\" he says."}],"why":"Proposing both a joint pot and personal money honours shared goals and your own footing."},{"prompt":"A few days later, Dhruv asks: \"So how much should each of us keep for ourselves?\"","options":[{"text":"\"A small amount each, enough for ordinary things, no permission needed.\"","then":"\"That sounds fair,\" he says, and you settle on a number together.","best":true},{"text":"\"As much as either of us wants, honestly, with no real limit.\"","then":"\"Then what's left for the joint account?\" he asks."},{"text":"\"Just a token amount, really, mostly symbolic more than anything.\"","then":"\"Okay,\" he says, \"though that won't cover much of anything.\""},{"text":"\"Let's decide that later, once we've merged the rest first.\"","then":"\"Fine,\" he says, \"but let's set it before the month starts.\""}],"why":"A clear, comfortable personal amount is what makes the independence real."},{"prompt":"A month in, Dhruv asks: \"How's the setup feeling for you so far?\"","options":[{"text":"\"Good, though I'm still getting used to spending it freely.\"","then":"He nods. \"Fair. It's there so you never need to ask.\"","best":true},{"text":"\"Fine, no complaints. Let's not go over it.\"","then":"\"Okay,\" he says, though he had hoped you would say more."},{"text":"\"It's working, but let's just merge it all eventually anyway.\"","then":"\"Oh,\" he says, surprised you'd want to undo it already."},{"text":"\"You tell me. Are you happy with how I'm spending it?\"","then":"He blinks. \"It's your money. I don't need to approve it.\""}],"why":"Answering honestly, including the awkward part, keeps the setup working for both of you."},{"prompt":"Your friend Tara asks: \"My partner and I might merge everything. What would you do?\"","options":[{"text":"\"A joint pot plus some of our own works for us.\"","then":"Tara nods slowly. \"That's worth raising with him. Thanks.\"","best":true},{"text":"\"Merge everything. It's simplest for most couples, honestly.\"","then":"Tara says it sounds easy, though she hasn't thought about her own share."},{"text":"\"Never merge. Keep it all separate. It's much cleaner.\"","then":"Tara frowns. \"That sounds like a lot of splitting bills, though.\""},{"text":"\"Just go with whatever your partner prefers. It's easier.\"","then":"Tara shrugs. \"I suppose that's easiest,\" and drops what she wants."}],"why":"Sharing what worked for you, without laying down a rule, gives her a real option to weigh."}],"relearn":"Proposing a joint pot plus personal money keeps shared goals and your own autonomy together."},
  {"id":"mt-1225","cat":"plan-together","type":"role-play","persona":"any","source":"start the check-in","hook":"You want to start a light monthly money check-in with your partner Ayesha.","setup":"One quiet evening, you mention the idea over dinner.","steps":[{"prompt":"Ayesha asks: \"A monthly check-in, like a meeting?\"","options":[{"text":"\"More like a quick, no-blame chat about how our goals are going.\"","then":"\"That sounds okay, actually,\" she says.","best":true},{"text":"\"Not a meeting. We can just talk whenever a big bill comes up.\"","then":"\"So only once something's already gone wrong?\" she asks."},{"text":"\"Yes, a proper meeting, once a month, with an agenda and notes.\"","then":"\"That sounds a bit formal,\" she says, hesitating slightly."},{"text":"\"Something like that. We'll figure out the details later.\"","then":"She hesitates. \"Later tends to mean never with us.\""}],"why":"Framing it as quick and no-blame makes a regular check-in feel light, not heavy."},{"prompt":"Ayesha asks: \"What would we actually talk about each time?\"","options":[{"text":"\"How our goals are going, plus anything on our minds.\"","then":"\"Okay, that feels manageable,\" she says.","best":true},{"text":"\"Every single expense from the month, in careful detail.\"","then":"\"That sounds exhausting,\" she says, already dreading it."},{"text":"\"Whatever's actually bothering either of us about money.\"","then":"She winces. \"So it's a complaints session?\""},{"text":"\"We'll decide each time, honestly, with no fixed topics at all.\"","then":"\"Hmm,\" she says. \"Then it might just drift.\""}],"why":"A light, goal-focused agenda keeps the check-in easy to actually keep."},{"prompt":"After your first check-in, Ayesha asks: \"Should we keep doing this?\"","options":[{"text":"\"Yes, let's keep it going, same time each month.\"","then":"\"Good,\" she says, \"that actually felt useful.\"","best":true},{"text":"\"Only if something feels urgent next time around.\"","then":"She shrugs. \"Okay, but then we'll probably forget.\""},{"text":"\"Let's see how busy next month turns out to be.\"","then":"\"Sure,\" she says, though \"busy\" has a way of winning out."},{"text":"\"Once was probably enough for now, honestly.\"","then":"\"Oh,\" she says, a little deflated. \"I was starting to like it.\""}],"why":"Keeping a fixed, regular slot is what turns one good chat into a real habit."}],"relearn":"A quick, no-blame monthly check-in keeps money collaborative and catches small things early."},
  {"id":"mt-1226","cat":"plan-together","type":"role-play","persona":"any","source":"baby plan talk","hook":"A baby is on the way for you and Rehaan, and you want to plan the money together.","setup":"Tonight, after dinner, you finally sit down to talk.","steps":[{"prompt":"Rehaan says: \"Honestly, the money side scares me a bit.\"","options":[{"text":"\"Let's list the new costs and the income dip, then set a small goal.\"","then":"\"Okay,\" he says, sounding steadier already.","best":true},{"text":"\"Let's not think about the money. Honestly, it'll work out.\"","then":"\"I wish I believed that,\" he says, and asks to list it out anyway."},{"text":"\"You handle the numbers. I'll handle the rest of it.\"","then":"\"I don't want to do this alone,\" he says. \"Can we list it together?\""},{"text":"\"It'll be expensive. There's honestly no getting around it.\"","then":"He goes quiet, then says, \"Maybe a list would make it less scary.\""}],"why":"Listing the costs and income dip together turns fear into something plannable."},{"prompt":"Rehaan asks: \"Where do we even start listing it all?\"","options":[{"text":"\"With the essentials first, then we can add the rest.\"","then":"\"That feels manageable,\" he says, starting to write things down.","best":true},{"text":"\"Let's list absolutely everything we can think of, right away.\"","then":"The long list overwhelms both of you before you've even planned."},{"text":"\"Whatever comes to mind, honestly, in no particular order.\"","then":"The list ends up messy, and some real costs slip through."},{"text":"\"Let's ask friends with kids to share their list first.\"","then":"It's useful eventually, though it delays starting your own."}],"why":"Starting with essentials keeps the list manageable instead of overwhelming."},{"prompt":"Rehaan asks: \"How much should we try to save each month?\"","options":[{"text":"\"Let's add up the costs, then pick an amount we can really keep.\"","then":"He nods. \"A real number, not a guess. I can do that.\"","best":true},{"text":"\"As much as we can possibly manage, each and every month.\"","then":"He looks worried. \"That won't last past the third month.\""},{"text":"\"Let's not fix a number. Honestly, just save what's left over.\"","then":"\"And if nothing's left?\" he asks."},{"text":"\"Whatever number happens to feel reassuring right now.\"","then":"\"Sure,\" he says, though neither of you knows if it's enough."}],"why":"Tying a realistic monthly amount to the real costs makes the goal actually fundable."}],"relearn":"Listing a baby's costs and income dip early, then setting a small goal, makes it fundable, not frightening."},
  {"id":"mt-1227","cat":"plan-together","type":"role-play","persona":"any","source":"tight month talk","hook":"Money was tight for you and your partner Sameer, and you couldn't save this month.","setup":"You're both clearing up after dinner.","steps":[{"prompt":"Sameer notices the savings app shows nothing added. He asks: \"What happened this month?\"","options":[{"text":"\"This month was tight, so let's adjust the plan together.\"","then":"\"Okay, that sounds fair,\" he says, relaxing a little.","best":true},{"text":"\"This whole savings thing clearly isn't working, honestly.\"","then":"\"Wait, really?\" he says, surprised at how far that jumps."},{"text":"\"I'm not sure, honestly. I didn't really check it closely.\"","then":"\"Let's actually look together,\" he says, a little unsettled."},{"text":"\"It's fine. Honestly, don't worry about it too much.\"","then":"\"I still want to understand what happened,\" he says gently."}],"why":"Naming a tight month plainly, without drama, keeps it a small fix, not a crisis."},{"prompt":"Sameer asks: \"So what actually made it tight this time?\"","options":[{"text":"\"Let's look at where it went, so we know if it's a one-off.\"","then":"\"Good idea,\" he says, pulling up the statement.","best":true},{"text":"\"I think you spent more than usual this month, honestly.\"","then":"\"That feels like it's aimed at me,\" he says, stiffening."},{"text":"\"Not sure. Prices just feel higher lately, I guess.\"","then":"\"Maybe, but let's actually check,\" he says, unconvinced."},{"text":"\"Does it really matter why? It already happened.\"","then":"\"It kind of does,\" he says, \"so we don't repeat it.\""}],"why":"Checking the real reason together keeps the fix accurate, not a guess."},{"prompt":"Sameer checks the statement and says: \"It was mostly that wedding trip. What about next month?\"","options":[{"text":"\"Then let's go back to the same amount next month.\"","then":"\"Sounds good,\" he says, already feeling steadier about it.","best":true},{"text":"\"Let's double it next month to make up for this one.\"","then":"\"That sounds like a lot,\" he says, already worried it'll slip too."},{"text":"\"Let's lower it for good, honestly, just to be safe.\"","then":"\"For one trip?\" he asks. \"That feels like too big a cut.\""},{"text":"\"Let's skip a couple more months first, just to be sure.\"","then":"\"Let's not skip it,\" he says. \"Let's just try again next month.\""}],"why":"A one-off tight month only needs a restart at the same amount, not a big change."},{"prompt":"Next month, the saving goes through and Sameer says: \"See, back on track.\"","options":[{"text":"\"Yes. Let's keep a quick check-in on it each month.\"","then":"Sameer smiles. \"A short check each month, I can do that.\"","best":true},{"text":"\"Yeah, that was honestly a close call though.\"","then":"\"It really wasn't, in the end,\" he says, a little puzzled."},{"text":"\"Let's just not have another tight month like that again.\"","then":"\"We can't always control that,\" he says, a bit deflated."},{"text":"\"Good, now let's save some extra as well, to be safe.\"","then":"\"Let's not overcorrect,\" he says. \"The plan was already fine.\""}],"why":"A short monthly check keeps future tight months small and shared."}],"relearn":"A tight month is a tweak, not a failure. Adjust the plan together and carry on."},
  {"id":"mt-1228","cat":"plan-together","type":"role-play","persona":"Karthik","source":"split fairly talk","hook":"You earn more than your partner Isha and want to split costs fairly, not by who earns most.","setup":"It's the first weekend of the new year.","steps":[{"prompt":"Isha asks: \"How are we splitting the bills this year?\"","options":[{"text":"\"Let's split costs by what each can give, both keeping spending money.\"","then":"\"That sounds really fair,\" she says, relaxing visibly.","best":true},{"text":"\"I earn more, so I'll decide where it all goes.\"","then":"\"Okay,\" she says, though it sits a little uneasily with her."},{"text":"\"Let's just split everything exactly in half.\"","then":"\"That would be tight for me,\" she says honestly."},{"text":"\"You decide. I don't mind either way.\"","then":"\"I'd rather we figure it out together,\" she says."}],"why":"Splitting by capacity, with spending money for both, is fairer than earning more deciding all."},{"prompt":"Isha asks: \"How exactly should we work out the numbers?\"","options":[{"text":"\"A percentage of each income, so it scales fairly.\"","then":"\"That makes sense,\" she says, and you work out the numbers.","best":true},{"text":"\"Whatever feels reasonable in the moment, I suppose.\"","then":"\"So we'd argue about it every month?\" she asks."},{"text":"\"Mostly what I decide is fair, honestly, in the end.\"","then":"\"Oh,\" she says, hearing that the decision isn't really shared."},{"text":"\"Let's not calculate it too precisely. That feels excessive.\"","then":"She hesitates. \"Then how will we know it's fair?\""}],"why":"A percentage of income gives the split a clear, fair rule to rely on."},{"prompt":"A few months later, Isha gets a raise. She asks: \"Should we adjust the split now?\"","options":[{"text":"\"Yes, let's recalculate it together at the new numbers.\"","then":"\"Good,\" she says, glad the system flexes as things change.","best":true},{"text":"\"No need. Honestly, the old split still works just fine.\"","then":"\"If you say so,\" she says, though it no longer quite fits."},{"text":"\"Great. Then let's just go fifty-fifty from now on.\"","then":"\"I still earn less than you,\" she says, frowning."},{"text":"\"Yes, and with your raise, you can cover most of it now.\"","then":"\"That's a big swing,\" she says. \"Shouldn't we work it out from both incomes?\""}],"why":"Revisiting the split as incomes change keeps the system fair over time."}],"relearn":"Splitting shared costs by what each can give, with spending money for both, is fairer than earning more deciding all."},
  {"id":"mt-1260","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"joint only","relearn":"A shared joint account is good, but each partner also keeping some money of their own protects them both.","hook":"\"Once you marry, all the money should be in one pot only. Keeping anything separate means you don't trust each other.\"","myth":{"un":"Keeping any money of your own means you don't trust each other.","re":"A joint pot for shared costs plus some money each can call their own is normal and healthy, not distrust.","why":"Autonomy and partnership sit fine together."}},
  {"id":"mt-1261","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"in-laws decide","relearn":"Your salary and savings are yours to have a say over; that say doesn't disappear into the in-laws' decisions.","hook":"\"In a joint family, the elders decide the money, so a wife's own salary isn't really hers to manage.\"","myth":{"un":"In a joint family the elders decide, so a wife's salary isn't hers to manage.","re":"You can respect the family and still keep a real say over your own earnings and savings.","why":"Respect and your own footing aren't opposites."}},
  {"id":"mt-1262","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"literacy gendered","relearn":"Knowing how the bank, savings and documents work is a learnable skill, not a man's department.","hook":"\"Understanding banking and investments is the husband's department; a wife doesn't need to bother with it.\"","myth":{"un":"Understanding banking is the husband's department; a wife needn't bother.","re":"Both partners knowing how the money, accounts and papers work is protection, and it's a skill anyone can learn.","why":"Financial know-how is learned, not gendered."}},
  {"id":"mt-1263","cat":"stay-independent","type":"strike-rewrite","persona":"Razia","source":"stridhan is family","relearn":"Stridhan, your wedding gold and gifts, is your own property; keeping a say over it is your right, not greed.","hook":"\"Asking to keep control of your own wedding gold and gifts after marriage is selfish.\"","myth":{"un":"Wanting a say over your own wedding gold and gifts is selfish.","re":"Stridhan is a woman's own property; keeping access and a say over it is her right, not selfishness.","why":"Your own property stays yours after marriage."}},
  {"id":"mt-1264","cat":"stay-independent","type":"strike-rewrite","persona":"Sneha","source":"depend is love","relearn":"Depending fully on a partner for money isn't proof of love; keeping your own footing is care for your future self.","hook":"\"Truly loving partners depend on each other completely, so wanting your own money means you're holding back.\"","myth":{"un":"Wanting your own money means you're holding back from the relationship.","re":"Keeping some financial footing of your own is planning for your future self, not holding love back.","why":"Love and self-reliance aren't a trade-off."}},
  {"id":"mt-1265","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"access not needed","relearn":"Knowing where the accounts, passwords and papers are isn't snooping; both partners deserve that access.","hook":"\"If your partner handles everything, you don't need to know the passwords or where the documents are.\"","myth":{"un":"If your partner handles it all, you needn't know the passwords or papers.","re":"Both partners knowing where the money, logins and documents are is fair and protective, not snooping.","why":"Shared access is part of a fair plan."}},
  {"id":"mt-1266","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"earn but no say","relearn":"Earning a salary and having a real say over it should go together; one without the other isn't fair.","hook":"\"It's fine for a woman to earn, as long as the men in the family decide what happens to her pay.\"","myth":{"un":"A woman can earn, as long as the men decide what happens to her pay.","re":"Earning should come with a real say over your own money; handing the decisions to others isn't fair.","why":"A pay packet without a voice isn't independence."}},
  {"id":"mt-1267","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"emergency fund distrust","relearn":"A small personal cushion isn't a bag packed to leave; it's the buffer any adult needs for the unexpected.","hook":"\"Keeping a little emergency money of your own means you're secretly planning to walk out.\"","myth":{"un":"Keeping a little emergency money of your own means you're planning to leave.","re":"A small personal cushion is sensible adult planning for job loss, illness or surprises, not an exit bag.","why":"Everyone needs a buffer for the unexpected."}},
  {"id":"mt-1268","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"career pause forever","relearn":"Pausing paid work for family is a valid choice, but it needn't mean giving up access, savings and a way back.","hook":"\"Once you leave your job for the family, it makes sense to close your own account and let your partner hold it all.\"","myth":{"un":"Once you leave your job, close your own account and let your partner hold it all.","re":"Even on a career break you can keep your own account, some savings and a route back to work.","why":"A pause needn't mean losing your footing."}},
  {"id":"mt-1269","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"too late","relearn":"It's never too late to start building your own financial footing; small steps now still protect future you.","hook":"\"If you've gone years with no money of your own, it's too late to start being financially independent now.\"","myth":{"un":"After years with no money of your own, it's too late to start now.","re":"It's never too late to open an account, learn the basics and start small; every step rebuilds your footing.","why":"Independence is built in small steps, any time."}},
  {"id":"mt-1270","cat":"stay-independent","type":"strike-rewrite","persona":"Sneha","source":"single needs less","relearn":"A single person's own savings and literacy matter just as much; independence isn't only a married-woman issue.","hook":"\"Financial independence is only something married women need to worry about, not single people.\"","myth":{"un":"Financial independence is only a married woman's concern, not a single person's.","re":"Everyone benefits from their own savings and money skills; building them while single makes any future life easier.","why":"Your own footing helps at every life stage."}},
  {"id":"mt-1271","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"shared phone","relearn":"Having your own way to check your account, not only a shared family phone, is part of real access.","hook":"\"It's fine that a wife has no phone or login of her own as long as the family shares one device.\"","myth":{"un":"It's fine to have no login of your own if the family shares one phone.","re":"Your own way to see your account and money, not only a shared device, is part of real, private access.","why":"Shared-only access can quietly lock you out."}},
  {"id":"mt-1272","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"trust replaces plan","relearn":"Trusting your partner is good, but trust plus your own safety net beats trust alone if life turns.","hook":"\"If you really trust your partner, you don't need any financial backup of your own. Trust is enough.\"","myth":{"un":"If you truly trust your partner, you need no financial backup of your own.","re":"Trust is the foundation, but keeping your own cushion means you're covered if illness, job loss or change hits.","why":"Trust plus a safety net beats trust alone."}},
  {"id":"mt-1273","cat":"stay-independent","type":"strike-rewrite","persona":"Karthik","source":"protect for her","relearn":"Helping a partner keep her own account and skills isn't a favour you grant; it's an equal's right you support.","hook":"\"A caring husband shows love by handling all the money so his wife never has to worry about a thing.\"","myth":{"un":"A caring husband handles all the money so his wife never has to worry.","re":"Real care helps your partner stay across the money and keep her own footing, not take all of it off her.","why":"Care keeps her involved, not in the dark."}},
  {"id":"mt-1274","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"asking is normal","relearn":"Needing permission for every ordinary purchase isn't normal marriage; both partners deserve some free spending.","hook":"\"Having to ask your spouse before buying anything for yourself is just what being married is.\"","myth":{"un":"Asking your spouse before buying anything for yourself is just marriage.","re":"Both partners deserve some money for ordinary spending with no permission needed; needing to ask for all of it isn't normal.","why":"Routine permission-seeking signals lost autonomy."}},
  {"id":"mt-1275","cat":"stay-independent","type":"sort","persona":"any","source":"builds or weakens","relearn":"Your own account, knowing the finances and some savings build footing; handing over all access and never checking weakens it.","hook":"Sort: builds your own financial footing, or quietly weakens it?","items":[{"id":"a","text":"Opening an account in your own name"},{"id":"b","text":"Handing over your card, PIN and all access"},{"id":"c","text":"Learning to read your own bank statement"},{"id":"d","text":"Never checking where the family money goes"},{"id":"e","text":"Keeping a small cushion of your own"},{"id":"f","text":"Letting one person hold every login"}],"bins":[{"id":"builds","label":"Builds footing","valence":"pos"},{"id":"weakens","label":"Weakens it","valence":"neg"}],"key":{"a":"builds","b":"weakens","c":"builds","d":"weakens","e":"builds","f":"weakens"}},
  {"id":"mt-1276","cat":"stay-independent","type":"sort","persona":"Razia","source":"yours or shared","relearn":"Stridhan and your own salary are yours; rent and the joint emergency fund are shared. The difference is worth knowing.","hook":"Sort: this money is your own, or it's the couple's shared pool.","items":[{"id":"a","text":"Your wedding gold (stridhan)"},{"id":"b","text":"The joint emergency fund"},{"id":"c","text":"Your personal salary account"},{"id":"d","text":"The rent you both pay"},{"id":"e","text":"A gift given only to you"},{"id":"f","text":"The shared grocery budget"}],"bins":[{"id":"yours","label":"Your own","valence":"pos"},{"id":"shared","label":"Shared pool","valence":"neutral"}],"key":{"a":"yours","b":"shared","c":"yours","d":"shared","e":"yours","f":"shared"}},
  {"id":"mt-1277","cat":"stay-independent","type":"sort","persona":"Pooja","source":"keeps say or loses it","relearn":"Joint decisions and knowing the accounts keep your say; routing every choice through the men loses it.","hook":"Sort: keeps your say over the money, or hands it away.","items":[{"id":"a","text":"Sitting in on the family money decisions"},{"id":"b","text":"Letting only the men decide your spending"},{"id":"c","text":"Knowing the account balances yourself"},{"id":"d","text":"Signing papers you've never read"},{"id":"e","text":"Setting some goals you both agree on"},{"id":"f","text":"Being told the budget after it's decided"}],"bins":[{"id":"keeps","label":"Keeps your say","valence":"pos"},{"id":"loses","label":"Hands it away","valence":"neg"}],"key":{"a":"keeps","b":"loses","c":"keeps","d":"loses","e":"keeps","f":"loses"}},
  {"id":"mt-1278","cat":"stay-independent","type":"sort","persona":"Reshma","source":"green or careful","relearn":"Own account, free small spends and shared access are healthy; zero access and asking for every rupee are warning signs.","hook":"Sort: a healthy sign of independence, or a 'watch this' warning sign?","items":[{"id":"a","text":"Each partner can support themselves if needed"},{"id":"b","text":"One partner has no access to any money"},{"id":"c","text":"Both can spend small amounts freely"},{"id":"d","text":"You must ask before spending a rupee"},{"id":"e","text":"Both know where the documents are"},{"id":"f","text":"One is barred from seeing the accounts"}],"bins":[{"id":"healthy","label":"Healthy sign","valence":"pos"},{"id":"warning","label":"Warning sign","valence":"uhoh"}],"key":{"a":"healthy","b":"warning","c":"healthy","d":"warning","e":"healthy","f":"warning"}},
  {"id":"mt-1279","cat":"stay-independent","type":"sort","persona":"any","source":"protects break or not","relearn":"On a career break, your own account, savings and a route back protect you; closing accounts and erasing skills don't.","hook":"Sort: on a career break, this protects your footing, or chips at it.","items":[{"id":"a","text":"Keeping your own account open"},{"id":"b","text":"Closing every account in your name"},{"id":"c","text":"Saving a little each month still"},{"id":"d","text":"Letting all your skills go rusty on purpose"},{"id":"e","text":"Staying in touch with your field"},{"id":"f","text":"Handing every login to your partner"}],"bins":[{"id":"protects","label":"Protects footing","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"protects","b":"chips","c":"protects","d":"chips","e":"protects","f":"chips"}},
  {"id":"mt-1280","cat":"stay-independent","type":"sort","persona":"any","source":"value of unpaid","relearn":"Cooking, childcare, running the home and elder care are real unpaid economic work; idleness isn't on the list.","hook":"Sort: is this real unpaid economic work a homemaker does, or not work at all?","items":[{"id":"a","text":"Caring for the children all day"},{"id":"b","text":"Cooking every meal for the house"},{"id":"c","text":"Lazing about doing nothing useful"},{"id":"d","text":"Running the home and the budget"},{"id":"e","text":"Looking after ageing parents"},{"id":"f","text":"Just being a burden on the earner"}],"bins":[{"id":"work","label":"Real unpaid work","valence":"pos"},{"id":"myth","label":"Not work (a myth)","valence":"neg"}],"key":{"a":"work","b":"work","c":"myth","d":"work","e":"work","f":"myth"}},
  {"id":"mt-1281","cat":"stay-independent","type":"sort","persona":"any","source":"three pillars","relearn":"Access, literacy and a cushion are the pillars of footing; 'just trust him' and 'don't ask questions' aren't.","hook":"Sort: a true pillar of staying financially independent, or a hollow line?","items":[{"id":"a","text":"Having access to your own money"},{"id":"b","text":"\"Just trust him with all of it\""},{"id":"c","text":"Understanding the basics yourself"},{"id":"d","text":"\"Don't ask, it's not your worry\""},{"id":"e","text":"Keeping a savings cushion"},{"id":"f","text":"\"A good wife stays out of money\""}],"bins":[{"id":"pillar","label":"True pillar","valence":"pos"},{"id":"hollow","label":"Hollow line","valence":"neg"}],"key":{"a":"pillar","b":"hollow","c":"pillar","d":"hollow","e":"pillar","f":"hollow"}},
  {"id":"mt-1282","cat":"stay-independent","type":"sort","persona":"Sneha","source":"independence myth","relearn":"Own savings and skills serve you at any stage; 'only married women need it' and 'too late now' are myths.","hook":"Sort: a true reason to build your own footing, or a myth that holds people back?","items":[{"id":"a","text":"It covers you if a job or health changes"},{"id":"b","text":"\"Only married women need to bother\""},{"id":"c","text":"It gives you real choices and options"},{"id":"d","text":"\"It's too late to start once you're older\""},{"id":"e","text":"It's respect for your own future self"},{"id":"f","text":"\"Wanting it means you distrust your partner\""}],"bins":[{"id":"true","label":"True reason","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"}},
  {"id":"mt-1283","cat":"stay-independent","type":"branch","persona":"Pooja","source":"salary to in-laws","hook":"Your in-laws expect your whole salary handed over monthly, leaving you nothing of your own.","steps":[{"prompt":"Your mother-in-law asks for the full amount again this month. What do you do?","options":[{"text":"Tell your husband, Arun, how this affects you and ask for his help","then":"He listens, surprised he hadn't realised how hard this has been on you.","best":true},{"text":"Tell yourself a good daughter-in-law doesn't keep her own pay","then":"The thought keeps you quiet, and the worry stays with you alone."},{"text":"Wonder if wanting some money of your own makes you selfish","then":"The doubt keeps you second-guessing yourself, and nothing changes."},{"text":"Take a cousin's advice that every new bride just has to adjust","then":"Her words make it sound normal, and you feel even more alone with it."}],"why":"Telling someone you trust means you don't carry this alone. None of it is your fault."},{"prompt":"On payday, the demand comes again, and you wonder if it's even allowed. What do you do?","options":[{"text":"Call 181 to ask, even though you're not sure it counts","then":"The person who answers listens, explains your options, and says none of this is your fault.","best":true},{"text":"Decide it can't be abuse, since nobody in the house hits you","then":"You don't ask anyone, and the question of your pay stays unanswered."},{"text":"Wait until you're completely sure it's serious enough to ask","then":"Weeks pass while you try to be sure, still without any answers."},{"text":"Keep it quiet, since family matters should stay in the family","then":"The silence leaves you on your own with it for another month."}],"why":"You can ask for help while unsure. Taking your whole salary is economic abuse, never your fault."},{"prompt":"You want some of your pay to stay safely yours. What do you do first?","options":[{"text":"Open an account in your own name that only you can access","then":"It's a quiet, practical step, and what goes in stays yours.","best":true},{"text":"Decide you owe it to them, since they've done so much for you","then":"The sense of owing them makes keeping anything back feel wrong."},{"text":"Take a friend's advice to spend it fast so less gets handed over","then":"The money goes quickly, and none of it is saved for you either."},{"text":"Trust that it will ease by itself once you've been in the family longer","then":"It doesn't ease by itself, and your pay still isn't yours."}],"why":"An account only you can reach gives you footing of your own, which you're entitled to."},{"prompt":"A month later, Arun notices how tense you are and asks what would help. What do you say?","options":[{"text":"Say you'll set a fair amount for the house, and keep the rest","then":"He agrees, and says he'll stand with you when his parents ask.","best":true},{"text":"Say maybe you're the problem and should try harder to fit in","then":"He shakes his head, but you still feel it's somehow on you."},{"text":"Say it's how every joint family works, so it's not a problem","then":"He takes you at your word, and nothing about the demand changes."},{"text":"Say it isn't your place to raise it with his parents","then":"He doesn't push, and his parents keep expecting your whole pay."}],"why":"Your pay is yours to decide. A fair share you choose, with his support, keeps your footing."}],"debrief":"Taking your whole salary is economic abuse, never your fault. Reach someone you trust or 181. You can give a fair share and still keep money of your own.","relearn":"You can contribute fairly and still keep your own account and a say over your pay. It's never your fault if in-laws push back."},
  {"id":"mt-1284","cat":"stay-independent","type":"branch","persona":"any","source":"no money of own","hook":"A year into your relationship with Farooq, you realise you have no account or savings of your own, and it worries you.","steps":[{"prompt":"The worry comes back when a friend mentions her own savings. What do you do?","options":[{"text":"Open your own account, save a little, and talk it over with Farooq","then":"Farooq is a little surprised, then genuinely supportive.","best":true},{"text":"Wait until you're earning more before bothering with any of it","then":"Waiting for \"enough\" just delays both the habit and the cushion."},{"text":"Keep the worry entirely to yourself for now, honestly","then":"It sits quietly, unaddressed, while nothing actually changes."},{"text":"Ask Farooq to just set something up for you instead","then":"It gets set up, though it's still his choice more than yours."}],"why":"Starting small now, and talking about it, builds real footing whatever you earn."},{"prompt":"A few weeks later, Farooq offers to manage all the money from now on, since he enjoys it. What do you say?","options":[{"text":"Say you'd like his support, but you'll run your own savings","then":"He agrees, glad to back you in a way that keeps it yours.","best":true},{"text":"Agree, since he enjoys it and is good with numbers","then":"It's easier, though your footing slips back into his hands."},{"text":"Agree for now, and plan to bring up your own savings later","then":"\"Later\" keeps slipping, and the worry quietly returns."},{"text":"Refuse to let him near any of the money at all","then":"He's hurt, and the shared side of your money gets harder to plan."}],"why":"Asking for support, not management, keeps your footing truly your own."},{"prompt":"Three months later, you check what's in your own name. What do you do now?","options":[{"text":"Save a set amount each month, and check in with Farooq now and then","then":"Your cushion grows slowly, and it feels steady, not fragile.","best":true},{"text":"Stop thinking about it, since things at home feel fine","then":"Things stay fine, and you still have little of your own."},{"text":"Move whatever's there into the joint account, for convenience","then":"It's convenient, and your own footing folds back into shared money."},{"text":"Keep your saving entirely hidden, even from Farooq","then":"It grows, but hiding it adds a strain that openness wouldn't."}],"why":"Keeping the habit going, openly, is what turns a start into lasting footing."}],"debrief":"Start small now: your own account and a little saving build footing, whatever you earn.","relearn":"If you've drifted to no money of your own, rebuild footing: your own account and small savings."},
  {"id":"mt-1285","cat":"stay-independent","type":"branch","persona":"Karthik","source":"husband's move","hook":"You handle all the bills, and you realise Meera has no idea where any of it is.","steps":[{"prompt":"Meera asks why you always deal with the bank alone. What do you do?","options":[{"text":"Sit down together and open an account in her name too","then":"Meera relaxes as the numbers stop feeling like a fog.","best":true},{"text":"Say you've got it handled so she needn't worry","then":"She nods, but keeps checking with you before every rupee."},{"text":"Promise to explain it all once things settle down","then":"Weeks pass, and settling down keeps moving further away."},{"text":"Hand her the passbooks and let her figure it out","then":"She flips through them alone, unsure where to start."}],"why":"Walking her through it together builds real footing, not just access to papers."},{"prompt":"Your sister-in-law later says a wife needn't know account details. What do you say?","options":[{"text":"Say plainly that both of you should know the account details","then":"She raises an eyebrow, then talks about something else.","best":true},{"text":"Laugh it off and change the subject","then":"Everyone moves on, but the comment repeats at the next family do."},{"text":"Say it's unusual, but you're 'trying it out'","then":"She nods, satisfied it's just a phase you'll grow out of."},{"text":"Say it's private, and drop it without correcting her","then":"She backs off, but the 'wife needn't know' idea stays unchallenged in the family."}],"why":"Naming it plainly, once, settles the question without inviting a debate."},{"prompt":"Months later, Meera wants to use her own savings for a course she's eyeing. What do you do?","options":[{"text":"Tell her it's her call, since it's her personal money","then":"She books the course that evening, glad she didn't need to ask.","best":true},{"text":"Ask her to check with you first, out of habit","then":"She pauses and waits for your yes before deciding."},{"text":"Suggest she save it instead, just in case","then":"She sets the plan aside, a little disappointed."},{"text":"Offer to look at the numbers with her first","then":"You go over the numbers together, though she never needed your sign-off."}],"why":"Personal money means her call, without needing your yes first."},{"prompt":"At a family function, an uncle asks you, not Meera, how your savings are doing. What do you do?","options":[{"text":"Say Meera has an equal say too, and turn to her to answer","then":"Meera answers what she can, and the uncle turns to her with his next question.","best":true},{"text":"Answer for both of you, since he asked you directly","then":"He nods along, and Meera stays out of the conversation."},{"text":"Joke that Meera spends it and you're the one who saves it","then":"The uncle laughs, and Meera's smile tightens."},{"text":"Answer briefly, then tell Meera about it later at home","then":"She hears it secondhand, after the chance to speak has passed."}],"why":"Turning the question to both of you shows her footing is real, not just on paper."}],"debrief":"Bring your partner across the money and set up her own account. That's care that lasts.","relearn":"A partner who wants fairness helps the other stay across the money and keep her own footing."},
  {"id":"mt-1286","cat":"stay-independent","type":"branch","persona":"any","source":"document access","hook":"You realise you don't know the bank passwords or where the policy papers are kept.","steps":[{"prompt":"It's dinner, and you're deciding whether to raise it. What do you do?","options":[{"text":"Ask to sit down together and list where everything is","then":"Your partner pulls out a folder, and together you make a shared list.","best":true},{"text":"Say it's fine since your partner has it handled","then":"You let it go, still not knowing where anything is kept."},{"text":"Wait for a better moment to ask","then":"The better moment never quite arrives, and the question fades."},{"text":"Ask your parents how they manage it themselves instead","then":"They share their own system, but your partner still hasn't heard the question."}],"why":"Asking together turns a gap into a shared list you can both use."},{"prompt":"A month later, your partner mentions a two-week work trip. What do you do?","options":[{"text":"Go through the bills due and where each login is kept, together","then":"You sit down for an hour and note where every payment comes from.","best":true},{"text":"Ask them to set everything to auto-pay so you needn't touch it","then":"They set it up, and you still couldn't say which account pays what."},{"text":"Say you'll just call them if anything comes up","then":"Midway through the trip a bill arrives, and they're hard to reach."},{"text":"Ask them to pay everything early, before they leave","then":"They rush to clear it all, and you learn nothing about where things live."}],"why":"Going through it together before a trip means either of you can act when it counts."},{"prompt":"Once they're back, your partner asks how you'd like to keep this information from now on. What do you say?","options":[{"text":"Suggest going through it together once a year and updating it","then":"You agree to a short yearly check, and it becomes a habit.","best":true},{"text":"Say it's fine as it is for now","then":"Nothing gets written down or updated, and the gaps quietly grow."},{"text":"Leave it to your partner to update when needed","then":"It only gets updated when something goes wrong."},{"text":"Ask them to write it all down for you once","then":"They write a list alone, and within a year it's out of date."}],"why":"Reviewing what you know together each year is what keeps it actually useful."}],"debrief":"Both knowing where the money and documents live is basic fairness. Ask for it openly.","relearn":"Both partners knowing where accounts, passwords and papers are is part of a fair plan, not distrust."},
  {"id":"mt-1287","cat":"stay-independent","type":"branch","persona":"Reshma","source":"asking for every rupee","hook":"You have to ask your partner before buying even small things, and it's wearing you down.","steps":[{"prompt":"You want to buy a small gift for a friend's birthday. What do you do?","options":[{"text":"Propose a set amount you each can spend freely, no asking needed","then":"Your partner pauses, then agrees to try it for a month.","best":true},{"text":"Ask as usual, since that's just how marriage works","then":"He says yes this time, and the asking continues as before."},{"text":"Skip the gift, telling yourself it isn't really your money","then":"You show up empty handed and feel smaller for it."},{"text":"Buy it quietly and hope it doesn't come up","then":"It doesn't come up, but you feel uneasy for days after."}],"why":"Asking for every small thing isn't your fault. A set free amount ends the daily asking."},{"prompt":"A week later, you sit down with the month's budget, and your partner asks how personal spending should work. What do you say?","options":[{"text":"Suggest the same no-ask amount for each of you, set together","then":"He thinks it over, and you settle on one amount for each of you.","best":true},{"text":"Say a small amount for you is enough, since he earns it","then":"He agrees quickly, and your amount ends up a fraction of his."},{"text":"Let him decide how it works, since he knows the bills","then":"He sets it up his way, without asking what you actually spend on."},{"text":"Say a good wife asks first, so nothing needs to change","then":"He shrugs, and the asking carries on as before."}],"why":"One equal amount each, agreed together, keeps it fair whoever earns the money."},{"prompt":"Your mother-in-law overhears you two discussing spending money and warns that money freedom ruins a household. What do you say?","options":[{"text":"Say calmly that money of your own is fair for you both","then":"She purses her lips but doesn't push further.","best":true},{"text":"Say it's really your partner's call, not yours","then":"She turns her comments toward him instead, and the pressure just moves."},{"text":"Agree that wanting your own money might be selfish","then":"The idea of money of your own quietly gets shelved."},{"text":"Accept that a daughter-in-law's money belongs to the household","then":"She seems satisfied, and your own money slowly becomes the household's."}],"why":"Some money of your own is fair, not greedy, and saying so calmly holds your ground."},{"prompt":"Weeks later, he still questions what you spend, and it doesn't feel right. What do you do?","options":[{"text":"Talk to a trusted friend or relative, or call 181 to talk it through","then":"Someone finally hears you out, and says none of this is your fault.","best":true},{"text":"Tell yourself you're overreacting, since he never shouts","then":"The heavy feeling stays, and you stop mentioning it."},{"text":"Keep it to yourself so the family doesn't gossip","then":"The weight stays yours alone, and nobody knows it is there."},{"text":"Decide that every wife has to ask like this","then":"You stop questioning it, and the asking starts to feel normal."}],"why":"It's never your fault. Talking to someone you trust, or calling 181, can help you see it clearly."}],"debrief":"Both partners deserve some free spending money, which is fair, not greedy. Being made to ask for every rupee is control, not your fault. 181 can help.","relearn":"Needing to ask for every small spend isn't normal; agreeing some free personal spending restores autonomy."},
  {"id":"mt-1288","cat":"stay-independent","type":"branch","persona":"Sneha","source":"entering shared life","hook":"You're moving in together and haven't yet worked out how you'll handle money as a couple.","steps":[{"prompt":"He suggests merging everything into one account that he'll manage. What do you say?","options":[{"text":"Suggest a joint account for shared costs and a personal one each","then":"He thinks about it, then agrees it sounds fairer.","best":true},{"text":"Agree to merge everything to keep things simple","then":"He takes charge of the single account, and you're left with no access of your own."},{"text":"Say you'll think about it and change the subject","then":"The plan stays undecided, and moving day arrives without a system."},{"text":"Say you'd rather keep everything fully separate, just to be safe about it","then":"He looks unsure how you'll manage shared bills at all."}],"why":"Joint for shared costs plus a personal account each keeps you both independent."},{"prompt":"A few weeks in, the rent is due. What do you do?","options":[{"text":"Agree together how you'll both pay shared costs each month","then":"You settle how much each of you puts toward rent and bills every month.","best":true},{"text":"Let him pay this month while you sort it out later","then":"He covers it, and setting up any system keeps getting postponed."},{"text":"Split it evenly by transferring him your share","then":"It works this once, but there's still no ongoing system."},{"text":"Put it on a card and settle up eventually","then":"The card bill grows, and 'eventually' keeps slipping."}],"why":"Agreeing together how shared costs get paid turns any plan into something that works."},{"prompt":"Your father asks how you're managing money now that you've moved in. What do you say?","options":[{"text":"Tell him honestly where things stand and what you're aiming for","then":"He listens, and says it sounds like you're thinking it through.","best":true},{"text":"Say your partner is handling most of it, since he's better with numbers","then":"Your father looks a little concerned, and you brush it off."},{"text":"Say you'll tell him once it's all settled","then":"He lets it go, and the real answer waits."},{"text":"Change the subject to avoid a lecture","then":"He drops it, though the question was a fair one."}],"why":"Being honest about where you are, and where you're headed, shows a plan, not a gap."},{"prompt":"Six months in, you want to check how the money side has settled. What do you say?","options":[{"text":"Suggest a short monthly check-in on how it's going","then":"He likes the idea, and you agree on a ten-minute Sunday chat.","best":true},{"text":"Assume it's fine since nothing's gone wrong","then":"Small frustrations quietly build with no outlet."},{"text":"Wait for him to raise it himself if something starts to feel off","then":"Neither of you raises it, and small issues go unspoken."},{"text":"Handle any wobble yourself quietly, without looping him in","then":"You quietly smooth it over alone, and the plan stays only yours to track."}],"why":"A regular check-in catches drift before it turns into a real problem."}],"debrief":"A joint pot for shared costs plus a personal account each keeps both independent.","relearn":"Entering a shared life, keep your own account and literacy while you build joint plans. Both can be true."},
  {"id":"mt-1289","cat":"stay-independent","type":"branch","persona":"Pooja","source":"homemaker claim","hook":"You've paused work to run the home, and money conversations still default to your partner.","steps":[{"prompt":"One evening he offers you a small monthly allowance, with extra if you ask. What do you say?","options":[{"text":"Ask for access to the joint money and a real say instead","then":"He pauses, then agrees it makes more sense than an allowance.","best":true},{"text":"Accept the allowance and plan to ask for more later","then":"He agrees, and you start having to ask each time you need extra."},{"text":"Say you don't need any money of your own right now","then":"He takes you at your word, and the offer quietly closes."},{"text":"Ask to think about it before deciding","then":"He says take your time, and the offer sits unanswered for now."}],"why":"Access and a say value your work as equal, not something to be granted."},{"prompt":"A month later, you want to buy something for your sister's baby shower. What do you do?","options":[{"text":"Tell him you'll use the household money. It's yours too","then":"He nods, and you choose the gift yourself without asking twice.","best":true},{"text":"Ask him first anyway, out of old habit you can't shake","then":"He says yes, but you notice you asked anyway."},{"text":"Skip the gift, since you didn't earn the money","then":"You show up without a gift and feel the gap all evening."},{"text":"Use money your mother gave you instead","then":"It works this time, but it isn't really a system."}],"why":"The household money is yours too, so an ordinary gift needs no permission."},{"prompt":"At a family function, an aunt says a homemaker shouldn't need a say in the money. What do you say?","options":[{"text":"Say your home work has real value, so the say is equal","then":"The aunt looks surprised, then moves on to another topic.","best":true},{"text":"Laugh it off without really answering","then":"The comment lands unanswered, and it likely comes up again."},{"text":"Agree it's unusual but say your partner insisted","then":"It sounds like his idea, not something you believe too."},{"text":"Say nothing and let your partner respond","then":"He answers for you, and your own voice stays out of it."}],"why":"Naming your work's value yourself is what actually shifts the room."}],"debrief":"Running the home is real work; your share is access and a say, not an allowance.","relearn":"A homemaker's claim on the money is equal; a fair plan gives her access and say, not an allowance."},
  {"id":"mt-1290","cat":"stay-independent","type":"branch","persona":"any","source":"learn the basics","hook":"You've never managed money and feel lost when your partner talks accounts, EMIs and savings.","steps":[{"prompt":"Your partner mentions the EMI due date at dinner. What do you do?","options":[{"text":"Ask them to walk you through what an EMI actually is","then":"They explain it simply, and it makes more sense than you expected.","best":true},{"text":"Nod along so you don't seem behind","then":"You still don't know what an EMI is, and the moment passes."},{"text":"Say money isn't your strength and change the subject","then":"The topic drops, and you're just as lost next time."},{"text":"Look it up alone later instead of asking","then":"You read a little, but the specific numbers still don't make sense."}],"why":"Asking directly gets you clear answers, faster than guessing alone."},{"prompt":"A week later, you want to understand the monthly savings plan. What do you do?","options":[{"text":"Ask your partner to go through the numbers together","then":"You sit down together, and the plan finally makes sense to you.","best":true},{"text":"Trust that your partner has it under control","then":"The plan stays theirs alone, and you're still outside it."},{"text":"Ask a friend to explain savings plans in general","then":"It helps a little, but your own plan is still a mystery."},{"text":"Decide to learn it properly once you're less busy","then":"Busy keeps happening, and the plan stays unexplained."}],"why":"Going through your own numbers together builds real, usable understanding."},{"prompt":"Your partner suggests you try paying a bill yourself this month. What do you do?","options":[{"text":"Try it, and ask questions if you get stuck","then":"You manage it, with one quick question halfway through.","best":true},{"text":"Ask your partner to just do it, since it's faster","then":"It's faster this time, but you learn nothing new."},{"text":"Put it off until the due date is close","then":"You rush it at the last minute and feel flustered."},{"text":"Ask your partner to watch over your shoulder the whole time","then":"It works, but you never quite feel like you did it yourself."}],"why":"Doing it yourself, questions and all, is how the learning actually sticks."},{"prompt":"Months later, a relative asks who 'really' handles the money in your house. What do you say?","options":[{"text":"Say it should be both of you, and you want to learn your part","then":"The relative looks a little surprised, then asks what you plan to pick up first.","best":true},{"text":"Say it's their department, since they're better with numbers","then":"The relative nods, and the idea that it's not your strength sticks."},{"text":"Laugh and say numbers were never your thing","then":"The relative chuckles, and the moment passes without more said."},{"text":"Deflect and ask them about something else instead","then":"The moment passes without the truth getting said."}],"why":"Saying it should be shared, and owning that you want to learn, keeps it honest."}],"debrief":"Money skills are learned; ask, learn the basics and take your seat at the table.","relearn":"If you've left all money matters to your partner, start learning the basics, not staying in the dark."},
  {"id":"mt-1291","cat":"stay-independent","type":"match","persona":"Reshma","source":"footing tools","relearn":"Each tool of footing does a job: account = access, literacy = good decisions, savings = a cushion, own ID = proof, network = a way back.","hook":"Match each tool of staying independent to what it gives you.","pairs":[{"left":"An account in your own name","right":"Money you can reach without asking"},{"left":"Knowing how banking works","right":"The skill to decide for yourself"},{"left":"A savings cushion","right":"A buffer when life throws a surprise"},{"left":"Your own ID and documents","right":"Proof of who you are, in your hands"},{"left":"Staying in touch with your field","right":"A route back to earning if you need it"}]},
  {"id":"mt-1292","cat":"stay-independent","type":"match","persona":"Pooja","source":"myth to reality","relearn":"Each independence myth has a fair reply: dependence isn't love, skill is learned, home work has value.","hook":"Match each 'stay dependent' myth to the fair reality.","pairs":[{"left":"\"Depending fully proves love\"","right":"Your own footing is care for future you"},{"left":"\"Money is the husband's department\"","right":"Financial skill is learned, not gendered"},{"left":"\"A homemaker has no claim\"","right":"Unpaid home work is real value"},{"left":"\"Asking for every rupee is normal\"","right":"Both deserve some free spending"},{"left":"\"It's too late to start now\"","right":"Small steps rebuild footing at any age"}]},
  {"id":"mt-1293","cat":"stay-independent","type":"match","persona":"any","source":"what protects whom","relearn":"Each footing habit pays off in a real moment: a cushion in job loss, your account in illness, literacy in a big decision.","hook":"Match each habit of independence to the moment it quietly protects you.","pairs":[{"left":"A personal emergency cushion","right":"When a job is suddenly lost"},{"left":"Your own bank access","right":"If your partner is ill and away"},{"left":"Understanding the finances","right":"When a big money decision comes"},{"left":"Knowing where papers are kept","right":"When a document is needed fast"},{"left":"Some savings of your own","right":"When you want a real choice"}]},
  {"id":"mt-1294","cat":"stay-independent","type":"match","persona":"Razia","source":"stridhan and rights","relearn":"Your own things carry your own rights: stridhan is yours, your salary is yours to have a say over, your ID is yours to hold.","hook":"Match each thing that is yours to the right that stays with it.","pairs":[{"left":"Your wedding gold and gifts (stridhan)","right":"Your own property, by law"},{"left":"Your monthly salary","right":"Yours to have a real say over"},{"left":"Your bank account","right":"Access that needs nobody's permission"},{"left":"Your identity documents","right":"Papers you're entitled to hold yourself"},{"left":"Your share of a shared plan","right":"A say, whether or not you earn cash"}]},
  {"id":"mt-1295","cat":"stay-independent","type":"match","persona":"any","source":"build vs erode","relearn":"For each footing-builder there's an eroder it answers: own account vs no access, literacy vs being kept in the dark, savings vs no cushion.","hook":"Match each thing that builds footing to the habit it protects you from.","pairs":[{"left":"Keeping your own account","right":"Having no access to any money"},{"left":"Learning the finances yourself","right":"Being kept in the dark on purpose"},{"left":"Saving a little each month","right":"Living with no cushion at all"},{"left":"Sharing where documents are","right":"One person hoarding every login"},{"left":"Some free spending each","right":"Needing permission for every rupee"}]},
  {"id":"mt-1296","cat":"stay-independent","type":"match","persona":"Karthik","source":"care moves","relearn":"A caring partner's move matches a need: show the accounts, set up her account, share passwords, back a way back.","hook":"Match each caring move to the footing it helps a partner keep.","pairs":[{"left":"Showing her the accounts together","right":"She knows where the money stands"},{"left":"Opening an account in her name","right":"She has money she can reach"},{"left":"Sharing the passwords and papers","right":"She isn't locked out if you're away"},{"left":"Naming her home work as real value","right":"She's an equal, not a dependent"},{"left":"Backing her route back to work","right":"She keeps options open ahead"}]},
  {"id":"mt-1297","cat":"stay-independent","type":"match","persona":"Sneha","source":"life stage footing","relearn":"Footing matters at every stage: single = your own habits, new couple = both accounts, break = keep access, later = a cushion stands.","hook":"Match each life stage to the footing move that fits it.","pairs":[{"left":"Single and earning","right":"Build your own saving and money habits"},{"left":"Newly moving in together","right":"Set up both joint and personal accounts"},{"left":"On a career break","right":"Keep your account, savings and a way back"},{"left":"Running the home unpaid","right":"Hold a real say and shared access"},{"left":"Years in, no money of your own","right":"Start small now; it's never too late"}]},
  {"id":"mt-1298","cat":"stay-independent","type":"reflect","persona":"any","source":"own account feeling","relearn":"Having your own account isn't a wall between you; it's footing that lets you show up as an equal.","hook":"Lensy: an account that's simply yours doesn't divide a couple. It lets you stand as an equal. Sit with that?","prompt":"What comes up for you?","options":["It's footing, not a wall","I'd feel steadier","Equal, not divided"],"affirm":"Your own account is steady ground under your feet, not distance from your partner. Both can be true."},
  {"id":"mt-1299","cat":"stay-independent","type":"reflect","persona":"Sneha","source":"future self","relearn":"Saving for yourself is a gift to the person you'll be in ten years; that's care, not coldness.","hook":"Lensy: the savings you build now are a quiet gift to the you of ten years from now. Worth a thought?","prompt":"Where does that land?","options":["A gift to future me","Care, not coldness","I want that footing"],"affirm":"Building your own footing is respect and care for your future self, never a sign of distrust."},
  {"id":"mt-1300","cat":"stay-independent","type":"reflect","persona":"Pooja","source":"unpaid value","relearn":"The cooking, caring and running of a home is real economic work; naming its worth isn't asking for praise.","hook":"Lensy: running a home and raising children is real, valuable work, even when no payslip names it. Hear that?","prompt":"What's your take?","options":["It's real work","Worth naming","I see its value"],"affirm":"Unpaid home and care work is genuine economic value; an equal claim on the money flows from it, not less."},
  {"id":"mt-1301","cat":"stay-independent","type":"reflect","persona":"any","source":"learn anytime","relearn":"You can start learning money at any age; the first small step beats waiting until you feel 'ready enough'.","hook":"Lensy: nobody is born knowing banking. It's all learnable, starting today, at any age. Does that loosen something?","prompt":"How does that sit?","options":["I can start now","It's learnable","One small step"],"affirm":"Money skills are learned, never gendered or fixed by age; the first small step is always open to you."},
  {"id":"mt-1302","cat":"stay-independent","type":"reflect","persona":"any","source":"some is yours","relearn":"Some money that's simply yours, to spend with no permission, is part of being a whole adult, married or not.","hook":"Lensy: every grown adult deserves a little money that's just theirs, no permission asked. Agree with that?","prompt":"What do you feel?","options":["Yes, some of my own","It's basic dignity","Married or not"],"affirm":"Having some money that's simply yours, no permission needed, is basic adult dignity, not selfishness."},
  {"id":"mt-1303","cat":"stay-independent","type":"reflect","persona":"Reshma","source":"knowing protects","relearn":"Knowing where your money and papers are isn't distrust; it means you could stand on your own feet if you had to.","hook":"Lensy: simply knowing where your money and documents are means you could stand on your own feet if you ever had to. Notice that?","prompt":"What rises in you?","options":["I'd want to know","It's protection","Standing on my own feet"],"affirm":"Knowing where your money and papers are is footing and protection, not a sign you distrust your partner."},
  {"id":"mt-1304","cat":"stay-independent","type":"reflect","persona":"Sneha","source":"single and whole","relearn":"A single life with your own money and plans is a full life, not a waiting room; your footing serves you now.","hook":"Lensy: a single life with your own savings and your own plans is a full life right now, not a waiting room. Sit with it?","prompt":"Where does that land?","options":["A full life now","Not waiting","My own footing serves me"],"affirm":"Your own savings and plans make for a whole, full life at any stage. Independence isn't only for 'later'."},
  {"id":"mt-1305","cat":"stay-independent","type":"reflect","persona":"any","source":"trust plus net","relearn":"You can trust your partner deeply and still keep a safety net; the net is for life's surprises, not for them.","hook":"Lensy: you can trust your partner with your whole heart and still keep a cushion for life's surprises. Both at once?","prompt":"What comes up?","options":["Both can be true","Trust and a net","For surprises, not them"],"affirm":"Deep trust and your own safety net live together fine: the cushion guards against life, not against your partner."},
  {"id":"mt-1306","cat":"stay-independent","type":"spot","persona":"Reshma","source":"two erode footing","relearn":"Your own account and shared access keep footing; handing over all access or needing permission for every rupee erodes it.","hook":"Spot the two lines that quietly erode a partner's financial footing.","scene":[{"id":"a","text":"Both partners can see the accounts","trick":false},{"id":"b","text":"\"Hand me your card and PIN, I'll manage it\"","trick":true},{"id":"c","text":"Each keeps a little savings of their own","trick":false},{"id":"d","text":"\"Ask me before you spend a single rupee\"","trick":true},{"id":"e","text":"You both know where the papers are","trick":false}],"why":"Taking all your access and making you ask for every rupee strip your footing; shared sight and own savings protect it."},
  {"id":"mt-1307","cat":"stay-independent","type":"spot","persona":"Pooja","source":"two unfair bases","relearn":"Agreed goals and each partner's needs are fair grounds; 'he's the man' and 'she earns less' are unfair, gendered ones.","hook":"Spot the two reasons that unfairly hand one partner control of the money.","scene":[{"id":"a","text":"\"We decide by our agreed goals\"","trick":false},{"id":"b","text":"\"He's the man, so he decides\"","trick":true},{"id":"c","text":"\"We weigh each person's needs\"","trick":false},{"id":"d","text":"\"She earns less, so she gets no vote\"","trick":true},{"id":"e","text":"\"We both have a real say\"","trick":false}],"why":"'He's the man' and 'she earns less' are gendered, unfair grounds for control; goals, needs and a shared say are fair."},
  {"id":"mt-1308","cat":"stay-independent","type":"spot","persona":"any","source":"two myths","relearn":"It's never too late, and home work has real value; those framing a homemaker as a burden or 'too late' are the myths.","hook":"Spot the two myths that talk someone out of their own footing.","scene":[{"id":"a","text":"\"It's never too late to start saving\"","trick":false},{"id":"b","text":"\"You earn nothing, so you're a burden\"","trick":true},{"id":"c","text":"\"Home work is real economic value\"","trick":false},{"id":"d","text":"\"It's too late for you to start now\"","trick":true},{"id":"e","text":"\"Small steps still build a cushion\"","trick":false}],"why":"'You're a burden' and 'it's too late' are myths; home work has value and footing can be built at any age."},
  {"id":"mt-1309","cat":"stay-independent","type":"spot","persona":"Reshma","source":"two lock-outs","relearn":"Own login, own ID and a way to check your account are real access; a shared-only phone or hoarded passwords can lock you out.","hook":"Spot the two setups that can quietly lock a partner out of her own money.","scene":[{"id":"a","text":"She has her own banking login","trick":false},{"id":"b","text":"Only one shared phone, held by him","trick":true},{"id":"c","text":"She keeps her own ID documents","trick":false},{"id":"d","text":"He holds every password, she has none","trick":true},{"id":"e","text":"She can check her balance anytime","trick":false}],"why":"A single shared phone he holds and all passwords in his hands can lock her out; her own login, ID and access don't."},
  {"id":"mt-1310","cat":"stay-independent","type":"spot","persona":"Pooja","source":"two erode say","relearn":"Sitting in on decisions and reading what you sign keep your say; routing pay through the men and signing blind hand it away.","hook":"Spot the two habits that hand away a partner's say over the money.","scene":[{"id":"a","text":"You sit in on the money decisions","trick":false},{"id":"b","text":"Your whole pay routes through the men","trick":true},{"id":"c","text":"You read papers before you sign them","trick":false},{"id":"d","text":"You sign whatever you're handed, unread","trick":true},{"id":"e","text":"You help set the shared goals","trick":false}],"why":"Routing all your pay through others and signing blind give away your say; joining decisions and reading first keep it."},
  {"id":"mt-1311","cat":"stay-independent","type":"spot","persona":"any","source":"two fake care","relearn":"Real care brings you across the money; 'I'll handle it all' and 'don't ask questions' keep you in the dark.","hook":"Spot the two 'caring' lines that actually keep a partner dependent.","scene":[{"id":"a","text":"\"Let's look at the accounts together\"","trick":false},{"id":"b","text":"\"I'll handle it all so you never worry\"","trick":true},{"id":"c","text":"\"Here's where the papers are kept\"","trick":false},{"id":"d","text":"\"Don't ask, it's not your worry\"","trick":true},{"id":"e","text":"\"Let's set you up your own account\"","trick":false}],"why":"'I'll handle it all' and 'don't ask' sound kind but keep her in the dark; real care brings her across the money."},
  {"id":"mt-1312","cat":"stay-independent","type":"spot","persona":"Sneha","source":"two not footing","relearn":"A cushion, your own account and literacy are real footing; 'just trust him' and 'he'll always provide' aren't a plan.","hook":"Spot the two lines that sound safe but aren't real financial footing.","scene":[{"id":"a","text":"A savings cushion of your own","trick":false},{"id":"b","text":"\"Just trust him with all of it\"","trick":true},{"id":"c","text":"An account in your own name","trick":false},{"id":"d","text":"\"He'll always provide, so why bother\"","trick":true},{"id":"e","text":"Knowing the basics of your finances","trick":false}],"why":"'Just trust him' and 'he'll always provide' aren't footing; a cushion, your own account and literacy are."},
  {"id":"mt-1313","cat":"stay-independent","type":"role-play","persona":"Pooja","source":"keep my account","hook":"It's a few weeks after your wedding, and your aunt has firm views on how a married woman handles money.","setup":"You keep your voice even, not defensive.","steps":[{"prompt":"Your aunt says: \"You're married now. You should close that account of yours.\"","options":[{"text":"\"We'll plan together, and I'll keep my own account too.\"","then":"She tilts her head. \"Hm. We'll see how long that lasts.\"","best":true},{"text":"\"You're right. I suppose I really should just close it then.\"","then":"She nods. \"Good. That's how it should be.\""},{"text":"\"It's complicated. Let's not get into it.\"","then":"She shrugs. \"Suit yourself. I was only saying.\""},{"text":"\"That's really between me and my husband.\"","then":"Her face tightens. \"I was only trying to help.\""}],"why":"Naming your plan calmly holds your footing without starting a fight."},{"prompt":"She adds: \"Your husband's salary is enough for both of you now.\"","options":[{"text":"\"It isn't about enough. Money of my own is good sense.\"","then":"She pauses. \"I never thought of it that way.\"","best":true},{"text":"\"True. I'll probably stop using mine soon enough.\"","then":"She nods. \"It'll fade once you settle in properly.\""},{"text":"\"Mine's only for emergencies, nothing more than that.\"","then":"\"As long as it stays only for emergencies,\" she says."},{"text":"\"I'm not really sure why I keep it, honestly.\"","then":"\"Even you don't seem sure it's needed,\" she says."}],"why":"Naming it as good sense, not habit, makes your account a plan to keep, not outgrow."},{"prompt":"A week later, she brings it up again: \"Even your mother closed hers when she married.\"","options":[{"text":"\"Every marriage runs differently, and this works for us.\"","then":"She sighs. \"Times have changed, I suppose.\"","best":true},{"text":"\"Maybe I should just follow her example, to keep the peace.\"","then":"\"Good. I'll mention it to your mother,\" she says."},{"text":"\"Let's talk about something else.\"","then":"\"Fine, but we'll come back to this,\" she says."},{"text":"\"I'll think about it.\"","then":"\"Good. I'll check with you again soon,\" she says."}],"why":"Standing by what works for your own marriage answers the comparison without a fight."},{"prompt":"At the next family gathering, she tells the room: \"She's kept her own account. Imagine that!\"","options":[{"text":"\"I have. It works well for us, no need to make it a topic.\"","then":"\"Fair enough,\" a cousin says, and the room moves on.","best":true},{"text":"\"It's not a big deal, really.\"","then":"\"Well, it's a bit unusual, if you ask me,\" a relative says."},{"text":"\"She really shouldn't have brought that up in front of everyone.\"","then":"\"I was only making conversation,\" your aunt says."},{"text":"\"Let's just enjoy the evening.\"","then":"\"Agreed. Let's move on,\" someone says, and the room shifts topic."}],"why":"Owning it plainly, in front of everyone, is what actually settles the topic."}],"relearn":"Naming calmly that you'll keep your own account while you plan together holds your footing without a fight."},
  {"id":"mt-1314","cat":"stay-independent","type":"role-play","persona":"Reshma","source":"ask for access","hook":"You've never seen the bank passwords or where the documents are. You want to ask your partner, without apology.","setup":"It's a quiet evening, and you raise it over tea.","steps":[{"prompt":"Your partner says: \"Why do you need to know all that? I have it handled.\"","options":[{"text":"\"I'd like us to share where the accounts and papers are.\"","then":"He pauses. \"I hadn't thought you wanted to know.\"","best":true},{"text":"\"Sorry to bother you, only if it's no trouble.\"","then":"\"It's fine as it is. But I'll think about it,\" he says."},{"text":"\"Never mind. You've always handled it far better than me anyway.\"","then":"\"Okay. I'll keep at it,\" he says, though he looks unsure."},{"text":"\"Fine, but I might ask again sometime.\"","then":"\"Sure, whenever you like,\" he says."}],"why":"Asking plainly, without apologising, is what actually gets you the access."},{"prompt":"A few days later, he says: \"About the accounts. Going through it all would take a whole evening.\"","options":[{"text":"\"Even just the basics today would help. We can add more later.\"","then":"\"Fair enough,\" he says, and shows you the main account.","best":true},{"text":"\"Okay, whenever suits you.\"","then":"\"Sure, I'll find a time soon,\" he says."},{"text":"\"Forget it. I don't want to be a bother.\"","then":"\"No trouble at all, but okay, later then,\" he says."},{"text":"\"Then skip the evening. Just write the passwords down for me.\"","then":"He hesitates. \"On a scrap of paper? That feels risky.\""}],"why":"Starting with just the basics makes it easy to say yes to today."},{"prompt":"A month later, he says: \"Oh, I opened a new savings account last week, by the way.\"","options":[{"text":"\"Let's make sure we both know every account, old and new.\"","then":"\"Fair point,\" he says. \"Let's go through them all this weekend.\"","best":true},{"text":"\"Nice. Just tell me about it whenever you remember.\"","then":"\"Will do,\" he says, and it slips his mind for months."},{"text":"\"I suppose I'll have to ask you each time from now on.\"","then":"\"Sure, just check with me whenever,\" he says."},{"text":"\"Doesn't matter. You keep track of all that anyway.\"","then":"\"True, no harm done then,\" he says."}],"why":"Agreeing you'll both know every account keeps the access real, not a one-time favour."}],"relearn":"Asking plainly to be shown the accounts and papers is fair; you needn't apologise for wanting access to your own life."},
  {"id":"mt-1315","cat":"stay-independent","type":"role-play","persona":"any","source":"some free spending","hook":"You're tired of asking before every small purchase. You want to propose a fairer setup calmly.","setup":"You bring it up over Sunday breakfast.","steps":[{"prompt":"Your partner asks: \"What's brought this up? We've always done it this way.\"","options":[{"text":"\"Let's each have a set amount we can spend freely, no asking needed.\"","then":"They think it over. \"That actually sounds fair.\"","best":true},{"text":"\"Forget it. I'll just stop buying anything for myself, honestly.\"","then":"\"Okay, if that's what you'd rather,\" they say."},{"text":"\"You decide. Whatever you think is fine.\"","then":"\"Let's just keep things as they are then,\" they say."},{"text":"\"It's just been on my mind lately. That's all.\"","then":"\"Alright, let me know if it's really bothering you,\" they say."}],"why":"Naming a clear, fair setup gets you further than dropping a hint."},{"prompt":"A week later, your partner asks: \"How much do you actually spend on small things in a month?\"","options":[{"text":"\"Let's both look, then pick one equal amount each.\"","then":"They pull up their phone. \"Let's do it now.\"","best":true},{"text":"\"Whatever you think is reasonable is fine by me.\"","then":"\"Okay, I'll pick a number then,\" they say."},{"text":"\"Enough that I stop asking. That's all I know.\"","then":"They sigh. \"Fine. I'll just pick a number, then.\""},{"text":"\"I've never really added it up, honestly.\"","then":"\"Neither have I. Let's guess something small for now,\" they say."}],"why":"Working out one equal amount together makes the plan real, not vague."},{"prompt":"A month in, they ask: \"So, is this new amount actually working for you?\"","options":[{"text":"\"Mostly. Let's check together that it feels fair for both of us.\"","then":"\"Good idea. Let's look at it on Sunday,\" they say.","best":true},{"text":"\"It's fine, I suppose.\"","then":"\"Okay, we'll leave it as is,\" they say."},{"text":"\"Honestly, I kind of miss having you decide these things with me.\"","then":"\"Sure, just ask me like before,\" they say."},{"text":"\"I haven't really used it much.\"","then":"\"Maybe we didn't need it after all, then,\" they say."}],"why":"Checking together that the amount feels fair keeps the setup going, and fair for you both."}],"relearn":"Proposing that you each spend a set amount freely, no permission needed, restores autonomy without picking a fight."},
  {"id":"mt-1316","cat":"stay-independent","type":"role-play","persona":"Pooja","source":"homemaker say","hook":"You run the home unpaid, and money decisions have always started with your partner.","setup":"Tonight he brings up household money over dinner.","steps":[{"prompt":"He says: \"I'll give you a monthly allowance. Just ask whenever you need more.\"","options":[{"text":"\"My home work is real. I'd rather we share access and decide together.\"","then":"He pauses. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Okay, the allowance is fine. I'll just ask you when I need a bit more.\"","then":"\"Good. That's settled,\" he says, then notices you've gone quiet."},{"text":"\"You're right. I don't really earn anything.\"","then":"\"Don't worry. I'll take care of it,\" he says."},{"text":"\"Whatever's easiest for you.\"","then":"\"Alright, I'll set the amount then,\" he says."}],"why":"Naming your work's value asks for an equal say, not a bigger allowance."},{"prompt":"A few days later, he asks: \"Be honest. How would you want the money to work?\"","options":[{"text":"\"Both our names on the joint account, and we decide the big things together.\"","then":"\"Alright, let's set that up this weekend,\" he says.","best":true},{"text":"\"I'm not totally sure, just something fairer.\"","then":"\"Let's think it over some more, then,\" he says."},{"text":"\"You keep managing it. Just tell me the exact amount each month.\"","then":"\"Sure, that's close enough to before,\" he says."},{"text":"\"Maybe we can figure it out later.\"","then":"\"Sure, no rush, whenever you like,\" he says."}],"why":"A concrete plan like joint access and shared decisions is easier to act on than a vague ask."},{"prompt":"A relative later remarks: \"A homemaker doesn't really need a say in the money.\"","options":[{"text":"\"Running this home is real work, so my say is equal.\"","then":"\"Well, I suppose that's fair,\" the relative says, and changes topic.","best":true},{"text":"\"I suppose that's true, in a way.\"","then":"\"Exactly, best to leave it to him,\" the relative says."},{"text":"\"That's really between me and my husband, not anyone else here.\"","then":"\"Fine, fine, just my two cents,\" the relative says."},{"text":"\"Let's not get into this right now.\"","then":"\"Suit yourself. I only meant to help,\" the relative says."}],"why":"Naming your work's value yourself is what actually changes the room's assumption."}],"relearn":"Naming that your home work has value and you want a real say, not an allowance, claims your footing warmly."},
  {"id":"mt-1317","cat":"stay-independent","type":"role-play","persona":"Sneha","source":"why single","hook":"You're single, earning well and building your own plans. At a family function, an aunt corners you.","setup":"She pulls up a chair beside you, in no hurry.","steps":[{"prompt":"Your aunt asks: \"Why bother with all this saving, when you'll marry and it'll merge anyway?\"","options":[{"text":"\"My own savings and plans give me a full, steady life right now.\"","then":"She raises an eyebrow. \"A full life, on your own?\"","best":true},{"text":"\"I suppose I'll stop once I find someone reliable to handle it.\"","then":"\"Good. That's more sensible, really,\" she says."},{"text":"\"That's a strange thing to ask, honestly.\"","then":"Her face tightens. \"I only meant it kindly.\""},{"text":"\"Let's not talk about this here.\"","then":"She shrugs. \"Fine. I only meant to ask.\""}],"why":"Naming your independence as a full life answers without waiting for marriage to explain it."},{"prompt":"A little later, she circles back: \"And when you marry, whose name will the savings be in?\"","options":[{"text":"\"We'd plan together, and my own savings stay mine.\"","then":"She pauses. \"I never thought of it staying yours as well.\"","best":true},{"text":"\"His, I suppose. That's usually how it goes.\"","then":"\"Good. That's how it should be,\" she says."},{"text":"\"I haven't really thought that far ahead.\"","then":"\"Well, it's early days for you yet,\" she says."},{"text":"\"That's a long way off. Let's not worry about it.\"","then":"\"Fair enough. We'll see when the time comes,\" she says."}],"why":"Naming that your footing stays yours, even married, keeps the picture accurate."},{"prompt":"A cousin nearby adds: \"Won't it feel lonely, managing it all yourself?\"","options":[{"text":"\"Not really. I like standing on my own feet.\"","then":"The cousin smiles. \"That's actually kind of nice. I hadn't thought of it that way.\"","best":true},{"text":"\"A little. It'll be easier once someone takes it over.\"","then":"\"Well, that day will come soon enough,\" the cousin says."},{"text":"\"I try not to think about it too much.\"","then":"\"That bad, huh?\" the cousin says."},{"text":"\"Money's easier to manage with a man around, I suppose.\"","then":"\"See, I always thought so too,\" the cousin says."}],"why":"Owning your independence calmly shows it's a full life, not a gap to fill."},{"prompt":"Later, your aunt tells another relative: \"She's still so independent. Imagine that!\"","options":[{"text":"\"I am, and I'm proud of it.\"","then":"The relative smiles. \"Good for you, honestly.\"","best":true},{"text":"\"It's not a big deal, really.\"","then":"\"If you say so,\" the relative says."},{"text":"\"I suppose it's just a phase before marriage.\"","then":"\"See, I told you she'd come around,\" your aunt says."},{"text":"\"Can we talk about something else?\"","then":"\"Sure, sure,\" the relative says, and the room moves on."}],"why":"Owning the comment plainly turns it into pride, not something to explain away."}],"relearn":"Answering the 'why are you still independent' question with calm pride holds your footing without defensiveness."},
  {"id":"mt-1318","cat":"stay-independent","type":"role-play","persona":"Karthik","source":"set her up","hook":"Money at home has always run through you. You want your partner to have her own account and access.","setup":"You bring it up over dinner, and she looks up, puzzled.","steps":[{"prompt":"She asks: \"It's worked fine so far. Why change it now?\"","options":[{"text":"\"Let's open your own account, and make sure we both know our money.\"","then":"She looks surprised. \"You want that?\"","best":true},{"text":"\"I'll keep handling it so you never have to worry.\"","then":"She hesitates. \"Alright. Though I've wondered about it myself.\""},{"text":"\"I'll explain it all to you someday, once things are less hectic.\"","then":"\"Sure, whenever works for you,\" she says."},{"text":"\"Only if you really want to, no pressure.\"","then":"\"I don't know. Do you actually mean that?\" she says."}],"why":"Offering it plainly, as something you want too, makes it a real invitation."},{"prompt":"Later that week, she asks: \"Honestly, would it matter if I had my own account?\"","options":[{"text":"\"Yes. It's your own footing, every day, not just a backup.\"","then":"She nods slowly. \"I hadn't really thought about that.\"","best":true},{"text":"\"Not really. It just seemed like a nice idea to try.\"","then":"\"Okay, if you say so,\" she says."},{"text":"\"Only in case something happens to me, I suppose.\"","then":"\"That's a strange way to put it,\" she says."},{"text":"\"You don't have to have one if you don't want.\"","then":"\"Alright. I'll think about it,\" she says."}],"why":"Naming footing as the reason makes it about her independence, not just a gesture."},{"prompt":"A week later, she asks: \"So how do I actually go about opening it?\"","options":[{"text":"\"Let's go together this weekend. I'll walk you through it.\"","then":"\"Okay, let's do it Saturday then,\" she says.","best":true},{"text":"\"I'll set it up for you, easier that way.\"","then":"\"Sure, thanks for doing that,\" she says."},{"text":"\"You can figure it out yourself. It's really not that complicated.\"","then":"\"I suppose I'll get to it sometime,\" she says."},{"text":"\"Let's wait until we're less busy.\"","then":"\"Alright, whenever we get the time,\" she says."}],"why":"Going together and walking her through it makes the access genuinely hers."}],"relearn":"Offering openly to set your partner up with her own account and full access is partnership, said as an equal's right."},
  {"id":"mt-1319","cat":"stay-independent","type":"role-play","persona":"Razia","source":"stridhan is mine","hook":"Your in-laws have started raising your wedding gold. You want to hold your right plainly.","setup":"Your mother-in-law finds you alone after lunch.","steps":[{"prompt":"She says: \"The gold should stay with the family, for safekeeping.\"","options":[{"text":"\"My stridhan is my own. I'll keep the say over it, with respect for everyone.\"","then":"She pauses. \"I only meant it kindly. Think it over.\"","best":true},{"text":"\"Isn't a bride's gold meant to be the family's now?\"","then":"She nods. \"Exactly. We'll talk about where to keep it.\""},{"text":"\"Maybe I'm being selfish, holding on to it.\"","then":"She pats your hand. \"A good bride shares, beta.\""},{"text":"\"Let's keep this between us. No need to tell anyone.\"","then":"She smiles. \"Of course. It's a family matter.\""}],"why":"Stridhan is yours by law. Holding on to it is your right, and this pressure is never your fault."},{"prompt":"She says: \"It's tradition. Every bride in this family has done it.\"","options":[{"text":"\"I respect your family, but by law the gold stays mine.\"","then":"She sighs. \"We'll see what your husband says.\"","best":true},{"text":"\"If every bride did it, maybe I'm the one being difficult.\"","then":"She softens. \"You're a good girl. You'll see.\""},{"text":"\"That's a shameful tradition. Your family just wants my gold.\"","then":"Her face hardens. \"How dare you speak to me like that.\""},{"text":"\"Isn't it safer with the family than with me, anyway?\"","then":"She smiles. \"That's all I've been saying.\""}],"why":"Respecting the family while naming your right keeps it calm and clear."},{"prompt":"That night, your husband says quietly: \"Amma keeps talking about the gold. What do you want to do?\"","options":[{"text":"\"It stays mine. Let's call NALSA 15100 together and check.\"","then":"He nods slowly. \"Alright. Let's call tomorrow.\"","best":true},{"text":"\"Maybe I'm the problem here. I've upset everyone.\"","then":"He hesitates. \"Nobody said that. But Amma is hurt.\""},{"text":"\"You're her son. Can't you just decide it for me?\"","then":"He looks uneasy. \"I'd rather not get in the middle.\""},{"text":"\"Let's not tell anyone outside the family about any of this.\"","then":"He agrees, relieved, and it stays inside these walls."}],"why":"It is your legal right, and hearing it from real help together makes it a shared stance."},{"prompt":"Your mother-in-law says in front of everyone: \"So, have you decided to be reasonable about the gold?\"","options":[{"text":"\"The gold is my stridhan, and it stays with me.\"","then":"The room goes quiet a moment, then a cousin changes the subject.","best":true},{"text":"\"Maybe the gold really does belong to the family now.\"","then":"She nods. \"Good. We'll sort it out later.\""},{"text":"\"My husband will decide what happens to it.\"","then":"Everyone turns to him, and he looks at the floor."},{"text":"\"A good bride doesn't argue about gold in front of elders.\"","then":"She nods, pleased, and the room takes it as a yes."}],"why":"Saying it plainly holds your ground, even if the pressure doesn't end at once. It is never your fault."}],"relearn":"Stating that your stridhan is your own property and stays in your say is your right, said plainly and without heat."},
  {"id":"mt-1320","cat":"stay-independent","type":"role-play","persona":"any","source":"learn with me","hook":"You feel lost when your partner talks accounts and savings. You want to ask to learn it together, without embarrassment.","setup":"It's Sunday morning, and your partner has the laptop open.","steps":[{"prompt":"Your partner says: \"I'm moving some money into savings this month.\"","options":[{"text":"\"Can you walk me through it? I'd like to learn it with you.\"","then":"They smile. \"Sure. Let's pull it up right now.\"","best":true},{"text":"\"It's all over my head, honestly. Just keep handling it for me.\"","then":"\"No problem,\" they say, and close the laptop."},{"text":"\"I'll never understand this stuff. Don't bother.\"","then":"They pause. \"Don't say that. But okay, I'll leave it.\""},{"text":"\"Sure, sounds good.\"","then":"\"Great,\" they say, and carry on without explaining anything."}],"why":"Asking directly, without apologising for not knowing, gets you real answers."},{"prompt":"A few days later, your partner asks: \"Want to sit with me while I do the budget?\"","options":[{"text":"\"Yes, and go slowly. I want to actually follow it.\"","then":"\"Sure. Let's take it step by step,\" they say.","best":true},{"text":"\"Sure, but just give me the short version.\"","then":"\"Alright, here's the gist,\" they say, and you nod along."},{"text":"\"You go ahead. I'll only slow you down.\"","then":"\"If you're sure,\" they say, and do it alone."},{"text":"\"Maybe next time. I'm a bit tired today.\"","then":"\"No worries, whenever suits you,\" they say."}],"why":"Asking them to go slowly is how the explanation actually becomes learning."},{"prompt":"A month later, your partner asks: \"Should we look at the accounts together each month?\"","options":[{"text":"\"Yes. Let's pick a day and make it a regular thing.\"","then":"\"Good idea. First Sunday of the month?\" they say.","best":true},{"text":"\"Only when you think I need to know something.\"","then":"\"Sure, I'll flag anything that comes up,\" they say."},{"text":"\"Maybe later in the year, once things are calmer.\"","then":"\"Alright, remind me then,\" they say."},{"text":"\"I think I've got the hang of it now.\"","then":"\"Great. Just say if you want to look again,\" they say."}],"why":"A regular look together is what turns one lesson into lasting understanding."}],"relearn":"Asking your partner to teach you the money basics, as a team, builds your literacy without shame."},
  {"id":"mt-1350","cat":"tools-and-help","type":"branch","persona":"any","source":"first talk","hook":"You and your partner have never sat down to talk money. You want a first tool to start.","steps":[{"prompt":"You decide it's time to finally talk about it. What do you do?","options":[{"text":"Pick a calm evening, no phones, and open with goals and worries","then":"The conversation stays open and easy, with no one on the defensive.","best":true},{"text":"Bring it up mid-argument about a bill","then":"The bill fight swallows the bigger conversation you meant to have."},{"text":"Send a long message about it instead of talking in person","then":"The message sits unanswered for two days."},{"text":"Wait for your partner to bring it up first","then":"Neither of you brings it up, and the gap stays there."}],"why":"A calm, chosen moment sets an open, blame-free tone you can build on."},{"prompt":"Soon after, your partner brings up an old loan you didn't know about. What do you do?","options":[{"text":"Stay curious and ask what the plan is for it","then":"Your partner relaxes, relieved it wasn't met with panic.","best":true},{"text":"React with visible shock","then":"Your partner gets defensive, and the talk turns tense."},{"text":"Say nothing and quietly worry about it later","then":"The worry sits with you, unspoken, for days."},{"text":"Change the subject to avoid the awkwardness","then":"The loan stays undiscussed, and so does the plan for it."}],"why":"Staying curious keeps a surprise from turning the whole talk defensive."},{"prompt":"Afterwards, you want money talk to be more than a one-off. What do you say?","options":[{"text":"Suggest making it a regular, short check-in","then":"You agree on a monthly time, and the talk becomes a habit.","best":true},{"text":"Say this was probably enough for now","then":"The next real money talk doesn't happen for months."},{"text":"Assume you'll just talk again when something comes up","then":"The next talk only happens once something's already wrong."},{"text":"Say you'll try to remember to raise it again sometime","then":"Sometime doesn't arrive, and the next talk gets prompted by a problem instead."}],"why":"Turning one good talk into a regular habit is what actually keeps it working."}],"debrief":"The money talk works best chosen calmly and goal-framed, not sprung during a fight.","relearn":"Start the money talk calmly and goal-first; mid-fight, it lands as blame."},
  {"id":"mt-1351","cat":"tools-and-help","type":"branch","persona":"Pooja","source":"money map","hook":"You're newly married and want one shared tool so neither of you is in the dark about the money.","steps":[{"prompt":"You suggest making a shared list of incomes, debts and accounts. What do you do?","options":[{"text":"Sit down together and write it all out plainly","then":"You both leave with a clear picture, written down.","best":true},{"text":"Let your partner draft it and you'll review it later","then":"The draft sits unread for weeks."},{"text":"Keep it mental for now, since it's early days","then":"Details start slipping from memory within a month."},{"text":"Only note the accounts you personally use","then":"The list ends up half complete, missing your partner's side."}],"why":"Writing it out together means both of you can find and grasp the money any time."},{"prompt":"A month later, a new EMI starts up. What do you do?","options":[{"text":"Write it down together, on a shared list, as it starts","then":"It's on paper for both of you, and keeping it current becomes a habit.","best":true},{"text":"Leave writing it down until the end of the year","then":"Details get missed in between, and the picture drifts out of date."},{"text":"Leave it to your partner to remember to note it","then":"It only gets noted when something goes wrong."},{"text":"Decide tracking it formally isn't really necessary","then":"The EMI lives in one head, and the picture gets patchy."}],"why":"Writing changes down together, as they happen, keeps the shared map actually useful."},{"prompt":"Your mother-in-law asks why you need to know 'all that' about the household money. What do you say?","options":[{"text":"Say knowing it keeps you both informed and safe","then":"She nods slowly, and doesn't push further.","best":true},{"text":"Say you're just curious, nothing serious","then":"It sounds less like a right and more like a whim."},{"text":"Say your partner suggested it, not you","then":"It sounds like his idea rather than something you both value."},{"text":"Change the subject to avoid explaining","then":"The comment goes unanswered, and it's likely to return."}],"why":"Naming why it matters shows it as basic fairness, not idle curiosity."}],"debrief":"Both knowing the incomes, debts and where things are is a basic fair-money tool.","relearn":"A shared money map keeps both informed; one-in-the-dark is a vulnerability."},
  {"id":"mt-1352","cat":"tools-and-help","type":"branch","persona":"any","source":"timed goal","hook":"A big cost is coming: your sister's wedding. You want the right tool for it.","steps":[{"prompt":"You first hear the wedding date is set for next year. What do you do?","options":[{"text":"Turn it into a shared, timed savings goal you both add to","then":"You set a monthly amount together, and the cost stops feeling far off.","best":true},{"text":"Decide to worry about it closer to the date","then":"Months slip by with nothing set aside."},{"text":"Assume you'll manage with a loan when the time comes","then":"The idea of a loan sits there as a backup plan, not a real one."},{"text":"Let one of you handle saving for it alone","then":"The goal feels lopsided, carried by only one of you."}],"why":"A known big cost is best met with a shared timed goal, saved early."},{"prompt":"Three months in, an unexpected bill comes up. What do you do?","options":[{"text":"Sit down together and plan for both the bill and the wedding","then":"You rework the monthly numbers, and both costs feel manageable.","best":true},{"text":"Pay the bill now and think about the wedding later","then":"The bill is paid, and the wedding money slips further behind."},{"text":"Dip into the joint account without discussing it","then":"One of you notices later and feels blindsided."},{"text":"Decide the wedding money will just have to come from a loan","then":"The loan quietly hardens into the plan, without either of you choosing it."}],"why":"Planning for both costs together keeps the wedding money realistic instead of quietly failing."},{"prompt":"Your sister asks what you're planning to contribute. What do you say?","options":[{"text":"Check with your partner, then give her a clear number","then":"You agree a figure together that evening, and she can plan around it.","best":true},{"text":"Say you'll figure it out closer to the date","then":"She's left unsure what to expect from you."},{"text":"Guess a number on the spot, without checking with your partner","then":"You realise later it doesn't quite match what you'd actually saved."},{"text":"Say it depends on how things go","then":"The vague answer leaves her planning around a gap."}],"why":"A number you've agreed together is what actually helps her plan, not a vague promise."},{"prompt":"The wedding month arrives, and you're short of what you hoped to give. What do you do?","options":[{"text":"Talk it through together and agree what you can truly give","then":"You settle on an amount within your means, with no debt and no surprise.","best":true},{"text":"Let one of you quietly cover the shortfall","then":"It's covered, but one of you carries more of the weight than agreed."},{"text":"Borrow the difference without discussing it first","then":"The debt becomes a surprise your partner learns about later."},{"text":"Promise the full amount and hope a bonus arrives in time","then":"The promise stands, and the gap stays open as the date nears."}],"why":"Deciding together what you can truly give keeps the goal shared and free of debt."}],"debrief":"A known big cost is best met with a shared timed goal, saved early, not winged.","relearn":"For a big cost, set a shared timed goal early; winging it invites debt."},
  {"id":"mt-1353","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"both accounts","hook":"You earn well; your partner runs the home unpaid. You want a fair set-up for everyday spending.","steps":[{"prompt":"You sit down to plan the household spending. What do you do?","options":[{"text":"Set up joint for shared costs, plus personal money for each","then":"You both leave with money that's simply yours, no asking needed.","best":true},{"text":"Put all income under your name and she asks for what she needs","then":"The asking starts almost immediately, over small things."},{"text":"Give her a fixed amount and call it her share","then":"It works like an allowance, even though that's not the intent."},{"text":"Decide to figure out the details later","then":"Weeks pass without a clear system in place."}],"why":"Joint for shared costs plus personal money each gives both a real stake."},{"prompt":"A week later, she wants to buy a gift for a friend. What do you do?","options":[{"text":"Tell her it's her call. The household money is hers too","then":"She buys the gift without needing to check with you first.","best":true},{"text":"Ask her to run it by you first","then":"She checks with you, and the old pattern quietly continues."},{"text":"Suggest she wait for a bigger purchase to combine it with","then":"The gift plan gets delayed for no real reason."},{"text":"Offer to pick something out together instead","then":"It works out fine, but a choice that was hers ends up shared."}],"why":"The household money is hers as much as yours, so an everyday gift needs no sign-off."},{"prompt":"Your mother later says a wife who doesn't earn shouldn't need money of her own. What do you say?","options":[{"text":"Say her home work has real value, so it's only fair","then":"Your mother pauses, then nods slowly.","best":true},{"text":"Say it's just easier that way, practically speaking","then":"It sounds like convenience, not fairness."},{"text":"Say it's really up to your wife, not you","then":"It sounds like her fight alone, not something you believe too."},{"text":"Change the subject to avoid a longer conversation","then":"The question goes unanswered, and it's likely to return."}],"why":"Naming her work's value is what actually explains the setup, not just excuses it."},{"prompt":"Months in, you want to check how the money is working for both of you. What do you do?","options":[{"text":"Ask her directly whether the way money works feels fair to her","then":"She names one thing that bothers her, and you fix it together.","best":true},{"text":"Assume it's fine since nothing's gone wrong","then":"A small frustration she hasn't voiced quietly builds."},{"text":"Wait for her to raise it if something's off","then":"She doesn't raise it, unsure if it's worth mentioning."},{"text":"Only revisit it if a bill causes friction","then":"The setup only gets checked once something's already wrong."}],"why":"Asking directly is what catches a quiet problem before it becomes a real one."}],"debrief":"Joint for shared costs plus personal money each keeps fairness and autonomy.","relearn":"Both-accounts gives a shared pool and personal money; ask-for-each-rupee is control."},
  {"id":"mt-1354","cat":"tools-and-help","type":"branch","persona":"Sneha","source":"early check-in","hook":"You want a tool to catch money problems early, before they grow into resentment.","steps":[{"prompt":"Your partner asks what you have in mind. What do you propose?","options":[{"text":"A short monthly check-in on the goal, the split, and any worry","then":"You both agree to ten minutes on the first Sunday of the month.","best":true},{"text":"Only talk about money once something's actually gone wrong","then":"The first real talk only happens once there's already a problem."},{"text":"Check in occasionally, whenever it feels needed","then":"Without a set time, the check-ins quietly stop happening."},{"text":"Leave it to whoever notices an issue first","then":"Small things go unnoticed until they've already piled up."}],"why":"A set monthly time turns good intentions into an actual habit."},{"prompt":"A few weeks later, your partner mentions feeling stretched by a shared expense. What do you do?","options":[{"text":"Ask what would make it feel fairer, together","then":"You adjust the split slightly, and the worry eases.","best":true},{"text":"Say it's probably fine and move on","then":"The worry sits there, unaddressed, for another month."},{"text":"Suggest they just manage it for now","then":"The stretch continues, quietly, for weeks."},{"text":"Change the topic to something more positive","then":"The actual concern never really gets discussed."}],"why":"Asking what would help catches the issue while it's still small."},{"prompt":"A few months in, your partner asks if your way of talking about money is working. What do you say?","options":[{"text":"Say what's worked and what's slipped, and agree what to keep","then":"You each name one thing to keep and one to fix, and it feels lighter.","best":true},{"text":"Say it's fine, since nothing big has gone wrong","then":"They nod, and the small things stay unspoken."},{"text":"Say it's nice in theory, but life gets busy","then":"Money talk slips further down the list, one busy month at a time."},{"text":"Say you'd rather only talk when there's an actual problem","then":"They agree, and the next talk starts in the middle of one."}],"why":"Looking honestly at what's working, together, is what keeps the habit alive."}],"debrief":"A light regular check-in airs small issues early, so money talks aren't only crisis talks.","relearn":"A monthly check-in catches issues early; crisis-only talks start angry."},
  {"id":"mt-1355","cat":"tools-and-help","type":"branch","persona":"Reshma","source":"name and route","hook":"Your friend Reshma asks to meet you somewhere quiet, away from her in-laws.","steps":[{"prompt":"She says her husband keeps her salary and checks every rupee of her small allowance. What do you do?","options":[{"text":"Listen fully and tell her it's not her fault","then":"She relaxes a little, relieved someone believes her.","best":true},{"text":"Tell her every marriage has its adjustments","then":"She nods, but her shoulders stay tight, and she says less."},{"text":"Ask her exactly how much he keeps and how often","then":"She feels like she's being cross-examined, not heard."},{"text":"Tell her she should have seen this coming","then":"She flinches and looks down, though she stays sitting with you."}],"why":"Believing her and saying it's not her fault is what lets her keep talking."},{"prompt":"She says she doesn't know if it counts as 'real' abuse. What do you say?","options":[{"text":"Tell her this is economic abuse, whether he hits her or not","then":"She looks a little steadier, hearing it has a name.","best":true},{"text":"Say it's hard to know for sure without a lot more information","then":"She's left as unsure as before, with nowhere to go from there."},{"text":"Say it probably isn't, since there's no violence","then":"Her face falls, and she changes the subject, though the worry stays."},{"text":"Tell her only a counsellor could really say","then":"She nods, still unsure, as if it needs an expert's verdict first."}],"why":"Naming it plainly gives her something solid to hold onto."},{"prompt":"A few days later, Reshma messages you: \"What can I actually do about it?\"","options":[{"text":"Tell her about 181 and say you can call together if she wants","then":"She's relieved it's not something she has to figure out alone.","best":true},{"text":"Tell her to leave right away","then":"She goes quiet, since leaving today isn't something she can safely do."},{"text":"Tell her to talk to her husband calmly about it","then":"She looks doubtful, since calm talks haven't changed anything before."},{"text":"Say you're not sure, but she should probably figure it out soon","then":"The urgency lands on her, without giving her any actual path forward."}],"why":"Naming a real option and staying alongside her respects her pace."},{"prompt":"A week later, Reshma says she knows helplines like 181 exist, but she isn't ready to call anyone yet. What do you do?","options":[{"text":"Say there's no rush, and you're still here whenever she's ready","then":"She looks relieved you're not pushing her before she's ready.","best":true},{"text":"Say she really should just call now, before it gets any worse","then":"She feels pressured, and pulls back a little from you."},{"text":"Stop bringing it up, to avoid overstepping","then":"She's left wondering if you've lost interest in helping."},{"text":"Call 181 yourself, without telling her first","then":"She feels her choice was taken from her, even though you meant well."}],"why":"Respecting her pace, while keeping the door open, keeps her trust intact."},{"prompt":"A month later, Reshma tells you she called 181 last week. What do you say?","options":[{"text":"Tell her that took real courage, and ask how she's feeling","then":"She smiles, glad to have someone to talk it through with now.","best":true},{"text":"Say it's about time she did something","then":"The comment lands as blame instead of support."},{"text":"Ask if she's leaving him now","then":"She feels pushed toward a decision she isn't ready to name yet."},{"text":"Say you hope it all works out okay and change the subject","then":"She's left unsure if you actually want to keep talking about it."}],"why":"Naming her courage and staying curious keeps the support going, at her pace."}],"debrief":"Seizing a salary and a policed allowance is economic abuse; 181 or a counsellor helps.","relearn":"Name salary-seizing and policed allowances as abuse; route to 181 or a counsellor."},
  {"id":"mt-1356","cat":"tools-and-help","type":"branch","persona":"any","source":"unsure is okay","hook":"You're not sure if your money situation is just unfair or actually controlling. You want a tool.","steps":[{"prompt":"You keep going back and forth on whether to say anything. What do you do?","options":[{"text":"Call 181 or a counsellor. You don't need to be certain first","then":"You save the number and feel lighter, planning to call tonight in private.","best":true},{"text":"Decide to ask for help only once you're fully sure it's abuse","then":"Waiting for certainty keeps the question unresolved, week after week."},{"text":"Wait until a friend agrees it's abuse before calling anyone","then":"Your friend can't say for sure, so the call keeps getting put off."},{"text":"Try to talk yourself out of the worry","then":"The worry keeps resurfacing, no matter how you reason with it."}],"why":"You can reach out while unsure; certainty isn't a condition for getting help."},{"prompt":"When you do reach 181 or a counsellor, they ask what's been happening. What do you say?","options":[{"text":"Describe it plainly, even the parts you're unsure about","then":"They help you sort what's fair from what isn't, calmly and clearly.","best":true},{"text":"Say it can't really be abuse, since no one hits you","then":"They explain that controlling money can be abuse too, and ask you to go on."},{"text":"Say you're probably making too much of it","then":"They gently ask you to go on anyway, so you do."},{"text":"Ask them to just tell you if it's abuse or not","then":"They explain it isn't always one clear line, and ask more questions."}],"why":"Describing it plainly, unsure parts included, is what gets you a real answer."},{"prompt":"Afterwards, you feel a little clearer, but still not certain. What do you do?","options":[{"text":"Note down what they said, and check in again if it continues","then":"You feel steadier, knowing you can call again if needed.","best":true},{"text":"Decide the call settled it, one way or the other, and move on","then":"You put the whole thing aside, though the feeling doesn't quite go."},{"text":"Feel silly for having called at all","then":"The doubt about calling outweighs whatever clarity you got."},{"text":"Avoid thinking about it again for a while","then":"The question resurfaces later, just as unresolved as before."}],"why":"Knowing you can check in again keeps the door open, instead of needing one final answer."}],"debrief":"You can reach 181 or a counsellor while unsure. It's never your fault, and certainty isn't a condition for help.","relearn":"Reach out while unsure; you needn't prove it's abuse before asking."},
  {"id":"mt-1357","cat":"tools-and-help","type":"branch","persona":"Pooja","source":"stay informed","hook":"Your in-laws say money is the man's department and you should stay out of it. You want a tool to stay informed.","steps":[{"prompt":"Your father-in-law says this plainly at dinner one evening. What do you do?","options":[{"text":"Say calmly that you'll learn the household money and keep your own account","then":"He raises an eyebrow, but doesn't push further.","best":true},{"text":"Wonder if speaking up would only make you look difficult","then":"The comment goes unanswered, and it's likely to return."},{"text":"Tell yourself money really is the men's side","then":"Your own footing quietly shrinks a little more."},{"text":"Ask your husband to say something instead","then":"He hesitates, and the moment passes without a clear answer."}],"why":"Saying plainly that you'll stay informed and keep your own account holds your footing."},{"prompt":"A week later, your mother-in-law asks why you need to know the household accounts. What do you say?","options":[{"text":"Say knowing the money is your right, not a challenge","then":"She pauses, then lets the topic go.","best":true},{"text":"Say you're just a little curious, nothing more than that","then":"She says it's nothing to worry about, and the accounts stay closed to you."},{"text":"Say your husband wants it that way","then":"She nods and says he can tell you whatever he thinks you need."},{"text":"Avoid answering directly","then":"The question stays open, and it's likely to come up again."}],"why":"Naming it as your right is what actually changes how the question is heard."},{"prompt":"At the next family function, someone jokes that you've 'taken over' the money. What do you say?","options":[{"text":"Say plainly that knowing the money isn't taking it over","then":"The joke lands flat, and the room moves on.","best":true},{"text":"Laugh along to keep things light","then":"The joke sticks, and it gets repeated at the next gathering."},{"text":"Wonder if they have a point about you taking over","then":"The comment goes unanswered, and it settles as the accepted story."},{"text":"Look to your husband to correct it instead of you doing it","then":"He hesitates, and the moment passes without a correction."}],"why":"Correcting it yourself, plainly, is what changes the story people tell."}],"debrief":"Keeping your own account and knowing the money is your right, not a challenge.","relearn":"Your own account and an informed view are your right; being kept out leaves you dependent."},
  {"id":"mt-1358","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"baby plan","hook":"A baby is on the way. You both want a tool to handle the new costs without panic.","steps":[{"prompt":"You first hear the news together. What do you do about the money side?","options":[{"text":"List the new costs together and add a baby line to your shared goal","then":"You leave the evening with a rough number and a plan to grow it.","best":true},{"text":"Assume it'll sort itself out once the baby's here","then":"The costs start arriving before any plan does."},{"text":"Let one of you research it and handle the planning mostly alone for now","then":"The other feels a little out of the loop on something that affects both."},{"text":"Decide to worry about it closer to the due date","then":"The due date gets closer with no real number set aside."}],"why":"A baby's costs met with a shared, listed plan beat hoping it sorts itself out."},{"prompt":"A month later, an unexpected doctor's bill comes up. What do you do?","options":[{"text":"Pay it together and add it to a list of baby costs","then":"It's handled calmly, and your list of baby costs gets more realistic.","best":true},{"text":"Let whoever's nearby pay and sort it out later","then":"Sorting it out later keeps getting pushed off."},{"text":"Pay it from your own account without mentioning it","then":"Your balance dips, and the other finds out only at month's end."},{"text":"Skip writing it down, since it's a small amount","then":"Small unrecorded costs start to add up unnoticed."}],"why":"Covering it together and writing it down keeps your picture of the costs real."},{"prompt":"Your mother suggests you shouldn't worry your wife with the numbers right now. What do you say?","options":[{"text":"Say you want to plan it together, and that suits you both","then":"Your mother nods, though she still looks a little unsure.","best":true},{"text":"Agree it's easier, and quietly start handling the numbers alone for a while","then":"Your wife slowly finds herself left out of the money side."},{"text":"Say you'll think about it, without committing either way","then":"Your mother takes that as agreement, and asks your wife even less."},{"text":"Say nothing and change the subject","then":"The comment goes unanswered, and the assumption stands."}],"why":"Naming that you want to plan together keeps the pregnancy from becoming a reason to sideline her."},{"prompt":"Closer to the due date, the baby costs start feeling real. What do you do?","options":[{"text":"Go through the costs together and adjust for what you've learned","then":"The updated number feels realistic, and you both feel more ready.","best":true},{"text":"Trust the rough number already in your head","then":"The number in your head turns out to be quite a bit off."},{"text":"Let one of you work it out alone to save time","then":"The other isn't quite sure what the plan now is."},{"text":"Decide not to look at any of it again until after the birth","then":"Costs you hadn't counted catch you both a little off guard."}],"why":"Reviewing it together, with what you've learned, keeps the plan actually useful."}],"debrief":"Plan a baby's costs together, early. Hoping it all sorts itself out tends to backfire.","relearn":"Plan a baby's costs together with a shared goal line; hoping backfires."},
  {"id":"mt-1359","cat":"tools-and-help","type":"branch","persona":"any","source":"team habit","hook":"You want one habit that keeps money a team effort year after year, not a power struggle.","steps":[{"prompt":"You're setting expectations early in your shared life. What do you agree on?","options":[{"text":"Decide the big things together and keep both of you literate","then":"You both leave the conversation feeling like equal partners in it.","best":true},{"text":"Let the higher earner quietly decide and inform the other","then":"The higher earner's preferences start setting the direction by default."},{"text":"Agree to split decisions by whoever cares more about each one","then":"It works sometimes, but big decisions still tend to fall to one of you."},{"text":"Decide to figure it out as things come up","then":"Without an agreed habit, decisions start happening ad hoc."}],"why":"Deciding big things together and staying literate keeps money a team effort."},{"prompt":"A year in, a big decision comes up: whether to move cities for a job. What do you do?","options":[{"text":"Talk through the money side together before deciding","then":"You reach a decision that accounts for both your situations.","best":true},{"text":"Let the higher earner's job take priority automatically","then":"The decision tilts toward one career without much discussion."},{"text":"Decide quickly to avoid a long money conversation","then":"The financial side gets sorted out messily after the fact."},{"text":"Each work out your own side of the money separately","then":"You each plan alone, and the pieces don't quite fit together."}],"why":"Talking the money side through together is what keeps a big decision genuinely shared."},{"prompt":"A relative comments that the top earner should really have the final say. What do you say?","options":[{"text":"Say big calls should be made together, whoever earns what","then":"The relative shrugs, and the comment doesn't really land.","best":true},{"text":"Say it mostly works out that way in practice anyway","then":"It sounds like the relative's assumption was right after all."},{"text":"Laugh it off without really answering","then":"The comment goes unchallenged, and it's likely to return."},{"text":"Agree it might be simpler that way","then":"The idea of shared decisions quietly loses a little ground."}],"why":"Naming the principle out loud keeps it your practice, not just an ideal."},{"prompt":"Years on, a newly married cousin asks what advice you'd give a couple starting out. What do you say?","options":[{"text":"Say to decide big things together, both knowing the money","then":"The cousin looks genuinely interested, and asks how to start.","best":true},{"text":"Say they'll just need to be lucky, like everyone else","then":"The cousin looks a little disappointed, hoping for something useful."},{"text":"Say to let whoever's better with money handle it all","then":"The cousin nods, already picturing one of them in charge."},{"text":"Say you're honestly not sure what to tell them","then":"The cousin shrugs and moves on, no wiser than before."}],"why":"Naming the real habit is what makes it something others can actually learn from."}],"debrief":"Deciding big things together and keeping both literate keeps money a team effort.","relearn":"Decide big things together, keep both literate; earner-decides rebuilds imbalance."},
  {"id":"mt-1361","cat":"tools-and-help","type":"match","hook":"Match each money tool to the moment it's made for.","pairs":[{"left":"The money talk","right":"Starting shared life together"},{"left":"A shared timed goal","right":"A big upcoming cost"},{"left":"The monthly check-in","right":"Keeping things fair over time"},{"left":"Both-accounts setup","right":"Sharing costs, keeping autonomy"},{"left":"Calling 181 or a counsellor","right":"When money turns to control"}],"relearn":"Each money moment has its tool: the talk, the goal, the check-in, both accounts, or a help route.","persona":"any","source":"tool to moment"},
  {"id":"mt-1362","cat":"tools-and-help","type":"match","hook":"Match each money job to the account that does it.","pairs":[{"left":"Rent and shared bills","right":"The joint account"},{"left":"A hobby or a surprise gift","right":"Your personal account"},{"left":"Three months of cushion","right":"The emergency fund"},{"left":"Your partner's own small spends","right":"Their personal account"},{"left":"A timed goal like a home","right":"A shared savings goal"}],"relearn":"Joint for shared costs, personal for autonomy, a fund for cushion, a goal for big timed aims.","persona":"any","source":"job to account"},
  {"id":"mt-1363","cat":"tools-and-help","type":"match","hook":"Match each worry to the tool that answers it.","pairs":[{"left":"\"We keep fighting about money\"","right":"A regular, calm check-in"},{"left":"\"I'm in the dark about our finances\"","right":"A shared money map"},{"left":"\"A huge cost is coming\"","right":"A shared timed goal"},{"left":"\"He keeps my salary from me\"","right":"Reach 181 or a counsellor"},{"left":"\"I have no money of my own\"","right":"Your own personal account"}],"relearn":"Every money worry has a tool: a check-in, a money map, a goal, a help route, or your own account.","persona":"any","source":"worry to tool"},
  {"id":"mt-1364","cat":"tools-and-help","type":"match","hook":"Match each phrase to what it really signals in a couple's money.","pairs":[{"left":"\"No judgement, we're a team\"","right":"A safe, open money talk"},{"left":"\"Ask me before you spend anything\"","right":"Policed control, a red flag"},{"left":"\"Let's both see the accounts\"","right":"Shared, healthy access"},{"left":"\"That's not your concern\"","right":"Being shut out of the money"},{"left":"\"What's our goal this year?\"","right":"Planning together"}],"relearn":"Open, shared, goal-framed lines signal teamwork; permission-policing and shut-outs signal control.","persona":"any","source":"phrase to signal"},
  {"id":"mt-1365","cat":"tools-and-help","type":"match","hook":"Match each helpline or route to what it offers, so you know who to reach.","pairs":[{"left":"181","right":"The women helpline"},{"left":"112","right":"Emergency, immediate danger"},{"left":"NALSA 15100","right":"Free legal aid"},{"left":"A counsellor","right":"Talking it through safely"},{"left":"Respect at Home","right":"More on control at home"}],"relearn":"Know the routes: 181 for women, 112 in danger, NALSA 15100 for legal aid, a counsellor, Respect at Home.","persona":"Razia","source":"route to offer"},
  {"id":"mt-1366","cat":"tools-and-help","type":"match","hook":"Match each step of a fair money setup to what it protects.","pairs":[{"left":"A joint account","right":"Shared costs, run together"},{"left":"Personal money for each","right":"Everyday autonomy"},{"left":"An emergency fund","right":"A cushion for shocks"},{"left":"A monthly check-in","right":"Fairness staying on track"},{"left":"Both staying literate","right":"Neither left in the dark"}],"relearn":"A fair setup protects on every side: shared costs, autonomy, a cushion, fairness, and literacy.","persona":"Karthik","source":"step to protection"},
  {"id":"mt-1367","cat":"tools-and-help","type":"match","hook":"Match each money ritual to how often it fits.","pairs":[{"left":"The big money talk","right":"When starting shared life"},{"left":"The check-in","right":"Once a month"},{"left":"Reviewing the goal","right":"As the goal's date nears"},{"left":"Reaching for help","right":"The moment control appears"},{"left":"Updating the money map","right":"When incomes or accounts change"}],"relearn":"Money tools have their rhythm: the talk up front, a monthly check-in, help the moment control shows.","persona":"any","source":"ritual to rhythm"},
  {"id":"mt-1368","cat":"tools-and-help","type":"match","hook":"Match each unsure feeling to the reassuring truth about getting help.","pairs":[{"left":"\"I'm not sure it's abuse\"","right":"You can ask before you're sure"},{"left":"\"It's shameful to need help\"","right":"That's what support is for"},{"left":"\"No one hit me\"","right":"Economic abuse counts too"},{"left":"\"I depend on him\"","right":"Dependence never excuses control"},{"left":"\"I don't know my rights\"","right":"NALSA 15100 can explain them"}],"relearn":"You can reach out unsure, unashamed; economic abuse counts, and your rights are knowable.","persona":"Reshma","source":"feeling to truth"},
  {"id":"mt-1369","cat":"tools-and-help","type":"role-play","persona":"any","source":"open the talk","hook":"You want to open the very first money talk with your partner without it feeling like an interrogation.","setup":"After dinner, you sit down with a notebook.","steps":[{"prompt":"Your partner looks a little wary and asks: \"Is everything okay?\"","options":[{"text":"\"Yes, I just want us to map our money together, no judgement.\"","then":"They relax. \"Okay, that sounds fair.\"","best":true},{"text":"\"Tell me exactly what you earn and spend, right now, all of it.\"","then":"They stiffen. \"Alright, if you really want to know now.\""},{"text":"\"Nothing. It can wait for another day.\"","then":"They glance at the notebook. \"Is it about money? You can tell me.\""},{"text":"\"We should really talk about your spending.\"","then":"\"My spending? What's wrong with it?\" they say."}],"why":"Framing it as a shared, no-judgement map opens the door instead of closing it."},{"prompt":"After a beat, they admit: \"I've never really known how to talk about money.\"","options":[{"text":"\"Me neither. Let's each share our goals and worries first.\"","then":"\"Alright, I'll go first then,\" they say.","best":true},{"text":"\"You go first. Tell me what's going on with your money.\"","then":"\"Feels a bit one-sided, but okay,\" they say."},{"text":"\"Let's just talk about what we're saving for.\"","then":"\"Sure, that's an easy place to start,\" they say."},{"text":"\"I'm not sure either. You pick where to start.\"","then":"\"Hmm, let me think about it a moment,\" they say."}],"why":"Sharing goals and worries together, both ways, keeps the talk mutual."},{"prompt":"By the end, they ask: \"That wasn't so bad. Should we do this again?\"","options":[{"text":"\"Definitely, let's make it a regular thing.\"","then":"\"Agreed, let's pick a monthly time,\" they say.","best":true},{"text":"\"Maybe if something comes up.\"","then":"\"Alright, we'll see then,\" they say."},{"text":"\"Let's see how we feel next month.\"","then":"\"Sure, no pressure either way,\" they say."},{"text":"\"I think once was probably enough, honestly, for now at least.\"","then":"\"Oh. Okay, if that's what you'd rather,\" they say."}],"why":"Agreeing to make it regular is what turns a good talk into a lasting habit."}],"relearn":"Open the first money talk as a shared, no-judgement map, not a demand for an audit."},
  {"id":"mt-1370","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"propose accounts","hook":"You want a joint account plus a personal one each, and worry it'll sound like distrust.","setup":"You raise it over the week's bills.","steps":[{"prompt":"She asks: \"Why not just put everything in one account?\"","options":[{"text":"\"Joint for our shared costs, and a bit that's each of ours, no permission needed. Fair?\"","then":"She thinks it over. \"Actually, that sounds fair to both of us.\"","best":true},{"text":"\"Put everything in one account I'll manage; simpler that way.\"","then":"\"Alright, if that's simpler for you,\" she says."},{"text":"\"Whatever you think. I don't mind either way.\"","then":"\"I'd rather you had an actual opinion,\" she says."},{"text":"\"Let's keep it fully separate instead, easier to track.\"","then":"\"How would shared costs even work then?\" she says."}],"why":"Framing it as fairness for both of you takes the worry out of the idea."},{"prompt":"She adds: \"Whatever we do, I want the shared bills split fairly.\"","options":[{"text":"\"Agreed. Let's work out a fair split together, from both incomes.\"","then":"\"Okay, let's sit down with the numbers tonight,\" she says.","best":true},{"text":"\"I'll put in whatever's left after my own spending.\"","then":"She frowns. \"So the bills get what's left over?\""},{"text":"\"You decide. I trust your judgement completely on this one.\"","then":"\"I'd rather we decide this together,\" she says."},{"text":"\"Let's match it to our incomes exactly, to the rupee.\"","then":"\"That sounds complicated to keep track of,\" she says."}],"why":"Working out a fair split together keeps the setup feeling mutual."},{"prompt":"A month later, she mentions: \"I'm finally buying the camera I've been saving up for.\"","options":[{"text":"\"That's your call. You don't need my okay.\"","then":"\"Thanks. I appreciate you not second-guessing it,\" she says.","best":true},{"text":"\"Are you sure that's a good use of it?\"","then":"\"It's money I saved myself,\" she says, a little hurt."},{"text":"\"I'd rather you didn't, honestly.\"","then":"\"So I need your okay now?\" she says."},{"text":"\"Let's talk about it before you decide.\"","then":"\"Do I really need to ask, though?\" she says."}],"why":"Letting her decide her own spending without question is what keeps it fair."},{"prompt":"Months in, she asks: \"Is the way we've set things up working for you?\"","options":[{"text":"\"Let's look at it together. Is it fair to us both?\"","then":"\"Yes, let's. I've got a couple of thoughts,\" she says.","best":true},{"text":"\"Fine, I think. We haven't needed to talk about it.\"","then":"\"Hmm. I'd like to, actually,\" she says."},{"text":"\"It works for me. Why, is something wrong?\"","then":"\"Not wrong. Just worth a look,\" she says."},{"text":"\"Good, I think. You haven't complained.\"","then":"\"That's not quite the same thing,\" she says."}],"why":"Checking together whether it's fair to both is what keeps the setup working."}],"relearn":"Frame both-accounts as fairness and autonomy for both, not as distrust or one person's control."},
  {"id":"mt-1371","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"run the check-in","hook":"It's your first monthly check-in. You want to keep it light and on the goal, not a spending trial.","setup":"You both settle on the sofa with the laptop between you.","steps":[{"prompt":"Your partner asks: \"Okay, where do we start?\"","options":[{"text":"\"Quick check-in: how are we doing on the goal, and does the split still feel fair to you?\"","then":"They relax. \"Feels fair. The goal's coming along too.\"","best":true},{"text":"\"Let's go line by line through everything you bought.\"","then":"\"Alright, if that's what you want to do,\" they say."},{"text":"\"Just tell me if anything's bothering you.\"","then":"\"Hmm, let me think if there's anything,\" they say."},{"text":"\"Let's skip the details and just chat.\"","then":"\"Sure, sounds relaxed enough,\" they say."}],"why":"Framing it around the goal and fairness keeps it collaborative, not a trial."},{"prompt":"They say: \"I'm a bit worried about the insurance renewal due next month.\"","options":[{"text":"\"Let's figure out together how to plan for it.\"","then":"\"Thanks, that takes some pressure off,\" they say.","best":true},{"text":"\"It's probably nothing. Don't worry.\"","then":"\"Maybe, but it's still on my mind,\" they say."},{"text":"\"We'll deal with it when it actually comes up.\"","then":"\"Okay, I suppose that's fine too,\" they say."},{"text":"\"That sounds like your problem to sort out.\"","then":"\"I thought this was supposed to be shared,\" they say."}],"why":"Planning for it together is what a check-in is actually for."},{"prompt":"Next month, they ask: \"Same time, same format?\"","options":[{"text":"\"Yes, let's keep going. It's worth it.\"","then":"\"Agreed. It's become easy now,\" they say.","best":true},{"text":"\"Maybe we can stretch it to every couple of months.\"","then":"\"Okay, if you think that's enough,\" they say."},{"text":"\"Sure, though I'm not sure it's really needed.\"","then":"\"I still find it useful, honestly,\" they say."},{"text":"\"Let's play it by ear.\"","then":"\"Alright, whenever you want to then,\" they say."}],"why":"Keeping the same rhythm is what makes the habit actually protective."}],"relearn":"Run the check-in around the goal and fairness, not a line-by-line audit of one partner."},
  {"id":"mt-1372","cat":"tools-and-help","type":"role-play","persona":"any","source":"share the say","hook":"Your partner has started leaving every money choice to you. You want shared ground.","setup":"Tonight they push the bank papers across the table to you.","steps":[{"prompt":"They say: \"You earn more, so you should just decide.\"","options":[{"text":"\"I earn more, but the say is equal. Let's decide big things together.\"","then":"They pause. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Fine, since I earn it, I'll just decide these things and tell you.\"","then":"\"Alright, whatever you think is best,\" they say."},{"text":"\"It's simpler if I handle it for now, so you needn't worry about it.\"","then":"\"That's a relief,\" they say."},{"text":"\"Whatever's easier for you, honestly.\"","then":"\"This is easier, so let's do that,\" they say."}],"why":"Naming that earning more isn't a bigger vote offers shared ground, not sole control."},{"prompt":"They ask: \"But what if we disagree on something big?\"","options":[{"text":"\"Then we talk it through until we find something we both agree with.\"","then":"\"Okay, good, there's a plan for that then,\" they say.","best":true},{"text":"\"I suppose I'd have the final say then, since it's mostly my money anyway.\"","then":"\"Right, so back to how it was, then,\" they say."},{"text":"\"We'd probably just go with whatever feels safer.\"","then":"\"That doesn't really answer it, does it?\" they say."},{"text":"\"Let's cross that bridge if it comes up.\"","then":"\"Alright, hopefully it won't matter,\" they say."}],"why":"Naming how you'd actually work through disagreement makes the shared say real."},{"prompt":"They ask: \"So how do we decide on the car loan, then?\"","options":[{"text":"\"Let's each say what we think and find what works for both.\"","then":"\"Okay, I'll go first with what I'm thinking,\" they say.","best":true},{"text":"\"You know more about loans than I do, so you should pick.\"","then":"\"Alright, I'll look into the options,\" they say."},{"text":"\"Let's just go with the cheaper option to keep it simple.\"","then":"\"Okay, but is that really what either of us wants?\" they say."},{"text":"\"Let's ask a cousin who works in banking and follow his advice.\"","then":"\"A cousin? I'd rather we look at it ourselves,\" they say."}],"why":"Actually talking it through together is what makes 'deciding together' real, not just said."},{"prompt":"Months later, a relative remarks: \"You earn more. You should really be the one deciding.\"","options":[{"text":"\"I want us to decide together, and I'm working on it.\"","then":"The relative shrugs, and the comment doesn't really land.","best":true},{"text":"\"Mostly, yes, I suppose I do end up deciding more of it.\"","then":"\"See, that's how it should be,\" the relative says."},{"text":"\"That's an old-fashioned way to think about it, honestly.\"","then":"\"I only meant it as a compliment,\" the relative says."},{"text":"\"Let's not get into this right now.\"","then":"\"Fine, we'll leave it for now,\" the relative says."}],"why":"Naming the way you want to decide, plainly, keeps it real instead of drifting."}],"relearn":"Earning more isn't a bigger vote; offer shared say rather than taking sole control."},
  {"id":"mt-1373","cat":"tools-and-help","type":"role-play","persona":"any","source":"name the worth","hook":"Your partner runs the home full time, and lately they've gone quiet about money.","setup":"Tonight, as you clear up after dinner, they speak up.","steps":[{"prompt":"They say: \"I feel like a burden, since I don't bring in any money.\"","options":[{"text":"\"Your home and care work has real value. This money is as much yours as mine.\"","then":"They pause. \"I don't usually think of it that way.\"","best":true},{"text":"\"Well, since I bring it in, I'd say the final call is really mine.\"","then":"\"That's kind of what I meant, actually,\" they say."},{"text":"\"Don't be silly. Of course you're not a burden.\"","then":"\"You're just saying that to be nice,\" they say."},{"text":"\"You could always take up some part-time work.\"","then":"\"So you do think I should be earning, then,\" they say."}],"why":"Naming the real value of home and care work directly answers the worry."},{"prompt":"They ask: \"But do you ever actually think of it as equal, honestly?\"","options":[{"text":"\"Yes, genuinely, running this home is work too.\"","then":"\"Okay. That actually helps to hear,\" they say.","best":true},{"text":"\"I try to, most of the time, honestly, though not always.\"","then":"\"So sometimes you don't, then?\" they say."},{"text":"\"It's complicated, but it's fine.\"","then":"\"That doesn't really answer my question,\" they say."},{"text":"\"Does it matter how I think of it?\"","then":"\"It matters to me, yes,\" they say."}],"why":"A direct, honest yes is what actually answers a question this personal."},{"prompt":"At a family lunch, a relative says of your partner: \"Oh, they just stay at home.\"","options":[{"text":"\"There's no 'just' about running a whole home.\"","then":"\"Fair enough, I only meant it in passing,\" the relative says.","best":true},{"text":"\"That's just how some people talk. Don't mind it.\"","then":"\"Exactly, no offence meant,\" the relative says."},{"text":"\"Let's not make a thing of it.\"","then":"\"Right, no need to make a fuss,\" the relative says."},{"text":"\"Can we talk about this later, just the two of us?\"","then":"\"Sure, if you like,\" the relative says, and the moment passes."}],"why":"Answering it out loud, in the moment, is what actually corrects the record."}],"relearn":"Unpaid home and care work is real value; a homemaker's claim on the money is equal, not lesser."},
  {"id":"mt-1374","cat":"tools-and-help","type":"role-play","persona":"Pooja","source":"ask for footing","hook":"You want to ask your partner to set up your own account and access, and fear he'll take it as distrust.","setup":"You raise it. He looks up from the TV.","steps":[{"prompt":"He asks: \"Why now? Has something happened?\"","options":[{"text":"\"I'd like my own account and to know our money, not from distrust, just for my own footing.\"","then":"He relaxes. \"Oh, okay. I thought something was wrong.\"","best":true},{"text":"\"Never mind. You handle it. I don't need to know.\"","then":"He frowns. \"Hang on. You clearly had something in mind.\""},{"text":"\"I've just been thinking about it a lot lately. That's all.\"","then":"He lets that sit. \"Alright. Say more when you're ready.\""},{"text":"\"Everyone says I should have my own account.\"","then":"\"So this is about what everyone says?\" he says."}],"why":"Naming footing as the reason, plainly, answers the 'why now' without sounding like distrust."},{"prompt":"He thinks, then asks: \"What would you want access to, exactly?\"","options":[{"text":"\"The joint account, and where our documents and accounts are kept.\"","then":"\"Alright, let me list it all out for you,\" he says.","best":true},{"text":"\"I'm not totally sure, just more in general, whatever seems fair.\"","then":"\"That's a bit hard to work with,\" he says."},{"text":"\"Whatever you think makes sense.\"","then":"\"Okay, I'll decide what to share, then,\" he says."},{"text":"\"Just a look at the balance sometimes, nothing more.\"","then":"\"Sure, I can show you the balance now and then,\" he says."}],"why":"Naming specific things, the account and the documents, is easier to actually act on."},{"prompt":"A week later, he says: \"Done. Your account's set up, and you can choose your own login.\"","options":[{"text":"\"Thanks. Can we go through it together once?\"","then":"He smiles. \"Sure. Let's do it Sunday.\"","best":true},{"text":"\"Finally, that took a while.\"","then":"He blinks. \"I did it as soon as I could.\""},{"text":"\"Okay, thanks.\"","then":"\"Sure, no problem,\" he says, and goes back to his phone."},{"text":"\"I probably won't use it much, but thanks anyway.\"","then":"\"Well, it's there whenever you need it,\" he says."}],"why":"Going through it together makes the access real and shared, not a one-off favour."},{"prompt":"A relative later asks: \"Why did you need access? Your husband manages it fine.\"","options":[{"text":"\"It's my footing too, not a sign anything's wrong.\"","then":"\"Fair enough. I only wondered,\" the relative says.","best":true},{"text":"\"I'm not totally sure, honestly. He just offered it himself.\"","then":"\"Oh, so it wasn't your idea?\" the relative says."},{"text":"\"You'd have to ask him.\"","then":"\"I'm asking you, though,\" the relative says."},{"text":"\"It's really not a big deal.\"","then":"\"Then why does it feel like something to hide?\" the relative says."}],"why":"Naming it as your own footing, plainly, is what keeps the real reason clear."}],"relearn":"Ask for your own footing as care for your future self, not as a sign you distrust your partner."},
  {"id":"mt-1375","cat":"tools-and-help","type":"role-play","persona":"Reshma","source":"open a door","hook":"A friend hints her husband controls every rupee and bars her from working. You want to open a door.","setup":"You're walking back together from the market.","steps":[{"prompt":"Your friend says: \"It's fine, really. He just likes to keep track of things.\"","options":[{"text":"\"That sounds hard. I'm here if you ever want to talk more.\"","then":"She looks down. \"It's just... a lot, sometimes.\"","best":true},{"text":"\"You must be exaggerating. Surely it can't be that bad.\"","then":"\"Forget I said anything,\" she says, and changes the subject."},{"text":"\"You should really stand up to him.\"","then":"\"It's not that simple for me,\" she says."},{"text":"\"That does sound controlling, doesn't it?\"","then":"\"I don't know. Maybe I'm overreacting,\" she says."}],"why":"Meeting a hint with warmth, not disbelief, keeps the door open for her to say more."},{"prompt":"A little later, she adds, almost to herself: \"I'm not even allowed to work. He says it's not needed.\"","options":[{"text":"\"That's not your fault. How are you feeling about all of it?\"","then":"She exhales. \"Honestly, I don't really know anymore.\"","best":true},{"text":"\"That's really unfair. You should leave.\"","then":"\"It's not that easy for me right now,\" she says."},{"text":"\"A lot of husbands are like that, unfortunately, or so I've heard.\"","then":"\"So it's just normal, then,\" she says."},{"text":"\"Have you tried explaining why it matters to you?\"","then":"\"I have, more than once,\" she says."}],"why":"Naming it's not her fault, and asking how she feels, keeps the focus on her, not on fixing him."},{"prompt":"She asks: \"Do you think this is actually as bad as it sounds?\"","options":[{"text":"\"What you're describing does sound like control, and that's not okay.\"","then":"She nods slowly. \"Hearing you say that actually helps.\"","best":true},{"text":"\"I really couldn't say, honestly. It's your marriage to figure out.\"","then":"\"I suppose no one can, really,\" she says."},{"text":"\"Maybe it's not that serious, honestly.\"","then":"\"Maybe you're right. I'll let it go,\" she says."},{"text":"\"Only you can know that for sure.\"","then":"\"I wish I actually knew, though,\" she says."}],"why":"Naming what it sounds like gives her something honest to weigh, without deciding for her."},{"prompt":"She says: \"I don't know what I'd even do about it.\"","options":[{"text":"\"That sounds really hard. If you ever want, 181 or a counsellor can help, no pressure.\"","then":"\"Say that again, slowly, for me?\" she says.","best":true},{"text":"\"You need to call someone right now.\"","then":"\"I'm not ready for that, not yet,\" she says."},{"text":"\"There's probably nothing much to be done about it, honestly.\"","then":"\"So that's it, then, nothing to do,\" she says."},{"text":"\"I'll figure out who you should call.\"","then":"\"I'd rather figure that out myself, actually,\" she says."}],"why":"Offering a real option, gently and without pressure, respects that the pace is hers."},{"prompt":"A few weeks later, she tells you she's thought about calling 181. What do you say?","options":[{"text":"\"That sounds like a real step. I'm glad, and I'm here either way.\"","then":"She smiles, a little lighter. \"I might call this week.\"","best":true},{"text":"\"Finally, I was starting to worry.\"","then":"\"Sorry it took me this long,\" she says."},{"text":"\"You really should have done that ages ago, if you ask me.\"","then":"\"I know, I know. I'm getting there,\" she says."},{"text":"\"Let me know how it goes.\"","then":"\"I suppose I will,\" she says."}],"why":"Naming it as a real step, without judging the timing, keeps her feeling supported."}],"relearn":"Meet a hint of control with warmth and a quiet route to 181 or a counsellor, not disbelief."},
  {"id":"mt-1376","cat":"tools-and-help","type":"role-play","persona":"any","source":"lower the heat","hook":"Your partner reacts to every money talk as an accusation. You want to set a calmer tone.","setup":"Over dinner, you say you'd like a quick money chat.","steps":[{"prompt":"They snap: \"Why are you always bringing up money like it's my fault?\"","options":[{"text":"\"This isn't blame. I just want us planning together so neither of us is stressed.\"","then":"They soften. \"Okay. Sorry, I get defensive about this.\"","best":true},{"text":"\"Why do you always make money my fault?\"","then":"\"That's not what I said at all!\" they say."},{"text":"\"Forget it. I won't bring it up again.\"","then":"\"Fine by me, honestly,\" they say."},{"text":"\"I'm really not blaming you. Don't be so sensitive about it.\"","then":"\"I'm not being sensitive. I'm being honest,\" they say."}],"why":"Naming it as planning, not blame, is what actually lowers the tension."},{"prompt":"A little later, though, they ask: \"So what did you actually want to talk about?\"","options":[{"text":"\"Just how we're doing on our goal, nothing more.\"","then":"\"Oh. Okay, that's not so bad then,\" they say.","best":true},{"text":"\"A few things you've been spending on, honestly.\"","then":"\"I knew it. This was about blame,\" they say."},{"text":"\"I don't even remember now.\"","then":"\"Then maybe it wasn't that important,\" they say."},{"text":"\"Everything about money, so we can sort it all tonight.\"","then":"\"That sounds like a lot for one night,\" they say."}],"why":"Naming a small, specific topic keeps the conversation from feeling like an ambush."},{"prompt":"A week later, they say, a little cautiously: \"Can we talk about the budget for a minute?\"","options":[{"text":"\"I'm glad you brought it up. Let's talk it through.\"","then":"They visibly relax. \"Okay, good. Here's what's on my mind.\"","best":true},{"text":"\"See, it's not so hard, is it?\"","then":"\"I suppose not, no,\" they say."},{"text":"\"I honestly wasn't expecting that from you today, of all days.\"","then":"\"Is that a bad thing?\" they say."},{"text":"\"Sure, if you really want to.\"","then":"\"Only if you're actually up for it,\" they say."}],"why":"Welcoming it warmly is what encourages them to keep raising things themselves."}],"relearn":"Frame money as a shared problem to solve together, not a fault to assign, to lower the heat."},
  {"id":"mt-1377","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"agree the ritual","hook":"You want to agree a simple recurring money ritual so problems get caught before they build.","setup":"Your partner is making tea when you bring it up.","steps":[{"prompt":"Your partner asks: \"How often were you thinking?\"","options":[{"text":"\"Once a month, ten minutes: the goal, the split, anything either of us is worried about?\"","then":"They nod. \"That sounds doable. Let's start this weekend.\"","best":true},{"text":"\"We'll only talk about money once something actually goes wrong.\"","then":"\"Alright, whenever that happens then,\" they say."},{"text":"\"Maybe once a year would be enough.\"","then":"\"Sure. That's easy to remember, at least,\" they say."},{"text":"\"Whenever we happen to think of it.\"","then":"\"Okay, no fixed time then,\" they say."}],"why":"A short, monthly rhythm is easy to keep and catches issues while they're small."},{"prompt":"They ask: \"What if one of us finds it awkward to bring things up?\"","options":[{"text":"\"Then we each get a turn to say one thing, no interrupting.\"","then":"\"I like that. It feels fairer,\" they say.","best":true},{"text":"\"Then just don't bring it up. It's not a big deal.\"","then":"\"Okay, but then things might pile up,\" they say."},{"text":"\"We'll figure that out whenever it actually happens, I suppose.\"","then":"\"Alright, we'll see then,\" they say."},{"text":"\"I'll do the talking, and you can just listen.\"","then":"\"That sounds a bit one-sided,\" they say."}],"why":"Giving each of you a turn makes it easier to raise things, awkward or not."},{"prompt":"A few months in, they ask: \"Do we really need a set time for money talk?\"","options":[{"text":"\"Yes. Ten minutes a month, even when it's quiet.\"","then":"\"Good. First Sunday of the month, then,\" they say.","best":true},{"text":"\"Maybe once every few months would do.\"","then":"\"If you think that's still enough,\" they say."},{"text":"\"Only if something comes up. Otherwise it's a chore.\"","then":"\"Okay, we'll wait and see, then,\" they say."},{"text":"\"I'm not sure it really makes a difference.\"","then":"\"Hm. Let's leave it, then,\" they say."}],"why":"A set monthly time, kept even when things are quiet, is what makes the habit last."}],"relearn":"A short, agreed monthly ritual catches money issues early, before they pile into a crisis."},
  {"id":"mt-1378","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"own it","hook":"You're single and plan your own money with care. At a family lunch, the questions start again.","setup":"Your aunt sets down her plate and turns to you.","steps":[{"prompt":"Your aunt asks: \"Why bother planning so much, when you'll marry someday?\"","options":[{"text":"\"My own plan and footing are a full life, not a backup for a husband.\"","then":"The aunt pauses. \"I hadn't thought of it that way.\"","best":true},{"text":"\"I suppose I'll only really need it once I actually marry someone.\"","then":"\"Exactly. No rush then,\" the aunt says."},{"text":"\"That's an odd thing to ask, honestly.\"","then":"\"I only meant it kindly,\" the aunt says."},{"text":"\"Let's not get into this today.\"","then":"\"Fine. Another time, then,\" the aunt says."}],"why":"Naming it as a full life answers the question instead of deferring it to marriage."},{"prompt":"A little later, the aunt asks: \"When you marry, won't your husband handle all that?\"","options":[{"text":"\"If I marry, we'll plan together. My footing stays mine.\"","then":"\"I never thought about it staying yours too,\" the aunt says.","best":true},{"text":"\"I suppose he would. That would be easier.\"","then":"\"Good. That's more sensible,\" the aunt says."},{"text":"\"I haven't really thought about that.\"","then":"\"Well, you're young yet. Plenty of time,\" the aunt says."},{"text":"\"That's a long way off for me. Let's not worry about it yet.\"","then":"\"Fair enough. We'll see when it comes,\" the aunt says."}],"why":"Naming that your footing stays yours, married or not, keeps the picture accurate."},{"prompt":"A cousin nearby asks: \"But isn't it a lot to manage without anyone to share the load?\"","options":[{"text":"\"It's mine to manage, and I actually enjoy that.\"","then":"The cousin tilts her head. \"Huh, I never thought of it as enjoyable.\"","best":true},{"text":"\"It is. I'd gladly hand it all to someone else.\"","then":"\"Well, a husband could take it off your hands,\" the cousin says."},{"text":"\"I manage, somehow.\"","then":"\"That sounds more like coping,\" the cousin says."},{"text":"\"I suppose that's the price of being single.\"","then":"\"See, independence really is a burden then,\" the cousin says."}],"why":"Naming it as something you enjoy reframes independence as a choice, not a burden."},{"prompt":"Later, the aunt tells a neighbour: \"She still handles all her own money, at her age.\"","options":[{"text":"\"I do, and it's exactly how I like it.\"","then":"\"Good for you, honestly. How did you start?\" the neighbour says.","best":true},{"text":"\"It's really not that unusual.\"","then":"\"Well, it's a bit unusual for round here,\" the neighbour says."},{"text":"\"It's only for now. Marriage will change it.\"","then":"\"See, I told you she'd come around,\" the aunt says."},{"text":"\"Can we talk about something else?\"","then":"\"Sure, sure,\" the neighbour says, and the room moves on."}],"why":"Owning it plainly, in the moment, is what actually reframes the comment."}],"relearn":"Financial independence is a full life in itself, not a placeholder until marriage."},
  {"id":"mt-1379","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"invite to learn","hook":"You want to invite your partner to learn the money with you, not just hand it over to you.","setup":"On Sunday morning, she finds you paying the month's bills.","steps":[{"prompt":"She says: \"Just handle it. I trust you completely.\"","options":[{"text":"\"Let's both learn our accounts and bills, so either of us can run things if needed.\"","then":"She pauses. \"I hadn't thought I needed to know all that.\"","best":true},{"text":"\"Don't you worry about any of it. I'll handle everything myself.\"","then":"\"Okay, if you're sure that's fine,\" she says."},{"text":"\"I'll explain things to you eventually.\"","then":"\"Sure, whenever works for you,\" she says."},{"text":"\"Sure, whatever's easier for you.\"","then":"\"Alright then, easier it is,\" she says."}],"why":"Inviting her to learn together builds shared footing, not just trust in you."},{"prompt":"A few days later, she asks: \"If something happened to you, would I even know where our money is?\"","options":[{"text":"\"Not yet. That's exactly why I'd like us both to learn it.\"","then":"She nods slowly. \"Okay. I think I'd like that.\"","best":true},{"text":"\"Don't worry. Nothing's going to happen to me.\"","then":"\"I hope not,\" she says, still looking unsure."},{"text":"\"I'll leave the passwords in a drawer for you, just in case.\"","then":"\"Alright, as long as they're somewhere,\" she says."},{"text":"\"You'd just call my brother. He'd sort it all out for you.\"","then":"She frowns. \"I'd rather not have to depend on him.\""}],"why":"Naming the gap honestly, and offering to learn it together, protects you both."},{"prompt":"A week later, she asks: \"Where do I actually start with all of this?\"","options":[{"text":"\"Let's go through this month's bills together, one by one.\"","then":"\"Okay, let's sit down this evening then,\" she says.","best":true},{"text":"\"I'll just write up a summary for you to read on your own time.\"","then":"\"Sure, I'll read through it,\" she says."},{"text":"\"Just watch me do it a few times.\"","then":"\"Alright, I'll watch closely then,\" she says."},{"text":"\"Let's start once things are less busy.\"","then":"\"Okay, whenever you find the time,\" she says."}],"why":"Going through it together, hands-on, is what actually makes the learning stick."}],"relearn":"Invite both partners to stay literate; taking it all over leaves the other dangerously in the dark."},
  {"id":"mt-1380","cat":"tools-and-help","type":"sort","hook":"Sort each move into the tool kit that builds fair money, or the trap that erodes it.","items":[{"id":"a","text":"A monthly no-judgement check-in"},{"id":"b","text":"Keeping your own account and access"},{"id":"c","text":"A shared timed goal for a big cost"},{"id":"d","text":"Handing over your whole salary on demand"},{"id":"e","text":"Asking permission for every small spend"},{"id":"f","text":"Hiding spending from each other"}],"bins":[{"id":"kit","label":"Fair-money tool","valence":"pos"},{"id":"trap","label":"Erodes fairness","valence":"neg"}],"key":{"a":"kit","b":"kit","c":"kit","d":"trap","e":"trap","f":"trap"},"relearn":"Check-ins, your own access and shared goals build fairness; salary-handover, permission and hiding erode it.","persona":"any","source":"kit or trap"},
  {"id":"mt-1381","cat":"tools-and-help","type":"sort","hook":"Sort each spend into the joint pool or each partner's personal money.","items":[{"id":"a","text":"Rent and electricity"},{"id":"b","text":"Your partner's surprise gift for you"},{"id":"c","text":"The shared emergency fund"},{"id":"d","text":"Your own hobby class"},{"id":"e","text":"Groceries for the home"},{"id":"f","text":"Your partner's personal phone top-up"}],"bins":[{"id":"joint","label":"Joint pool","valence":"neutral"},{"id":"personal","label":"Personal money","valence":"tell"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Shared costs and the fund go in the joint pool; gifts, hobbies and personal top-ups stay personal.","persona":"any","source":"joint or personal"},
  {"id":"mt-1382","cat":"tools-and-help","type":"sort","hook":"Sort each line into a green flag of teamwork or an uh-oh sign of control.","items":[{"id":"a","text":"\"Let's both see the accounts\""},{"id":"b","text":"\"You don't need to know what I earn\""},{"id":"c","text":"\"What's our goal this year?\""},{"id":"d","text":"\"Ask me before spending a rupee\""},{"id":"e","text":"\"No judgement, we're a team\""},{"id":"f","text":"\"Working isn't for wives like you\""}],"bins":[{"id":"team","label":"Teamwork","valence":"pos"},{"id":"control","label":"Uh-oh, control","valence":"uhoh"}],"key":{"a":"team","b":"control","c":"team","d":"control","e":"team","f":"control"},"relearn":"Open access and shared goals are teamwork; shut-outs, permission-policing and work-barring are control.","persona":"any","source":"team or control"},
  {"id":"mt-1383","cat":"tools-and-help","type":"sort","hook":"Sort each money tool by when in a shared life you reach for it.","items":[{"id":"a","text":"The big first money talk"},{"id":"b","text":"The monthly check-in"},{"id":"c","text":"A shared timed goal"},{"id":"d","text":"Calling 181 or a counsellor"},{"id":"e","text":"Mapping incomes and accounts"},{"id":"f","text":"Reaching NALSA 15100 for rights"}],"bins":[{"id":"build","label":"Building fair money","valence":"pos"},{"id":"help","label":"When control appears","valence":"tell"}],"key":{"a":"build","b":"build","c":"build","d":"help","e":"build","f":"help"},"relearn":"The talk, check-in, goal and money map build fair money; 181 and NALSA 15100 are for when control appears.","persona":"any","source":"build or help"},
  {"id":"mt-1384","cat":"tools-and-help","type":"sort","hook":"Sort each statement into a fact about the tools, or a myth that keeps couples from using them.","items":[{"id":"a","text":"Any couple can start, rich or not"},{"id":"b","text":"Tools are only for the wealthy"},{"id":"c","text":"Small early savings still matter"},{"id":"d","text":"You must earn a lot to plan"},{"id":"e","text":"Both should know the money"},{"id":"f","text":"Money is only the man's job"}],"bins":[{"id":"fact","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Any couple can start small and both should know the money; 'only for the rich/men' are myths.","persona":"any","source":"fact or myth"},
  {"id":"mt-1385","cat":"tools-and-help","type":"sort","hook":"Sort each response to a friend's money trouble into helpful or unhelpful.","items":[{"id":"a","text":"\"181 or a counsellor can help, no pressure\""},{"id":"b","text":"\"Every marriage is like this, adjust\""},{"id":"c","text":"\"You can ask even if you're unsure\""},{"id":"d","text":"\"You must be exaggerating\""},{"id":"e","text":"\"Needing help isn't shameful\""},{"id":"f","text":"\"Don't tell anyone, just bear it\""}],"bins":[{"id":"help","label":"Helpful","valence":"pos"},{"id":"hurt","label":"Unhelpful","valence":"neg"}],"key":{"a":"help","b":"hurt","c":"help","d":"hurt","e":"help","f":"hurt"},"relearn":"Offering routes and reassurance helps; 'adjust', disbelief and 'tell no one' leave a friend alone.","persona":"Razia","source":"helpful or not"},
  {"id":"mt-1386","cat":"tools-and-help","type":"sort","hook":"Sort each habit by whether it keeps a couple's money sustainable over years, or burns it out.","items":[{"id":"a","text":"Small, regular, honest check-ins"},{"id":"b","text":"One dramatic audit when trust breaks"},{"id":"c","text":"Both staying informed and literate"},{"id":"d","text":"Bottling up money worries for months"},{"id":"e","text":"Updating the goal as life changes"},{"id":"f","text":"Surveilling each other's spending"}],"bins":[{"id":"lasting","label":"Sustainable","valence":"pos"},{"id":"burnout","label":"Burns out","valence":"neg"}],"key":{"a":"lasting","b":"burnout","c":"lasting","d":"burnout","e":"lasting","f":"burnout"},"relearn":"Regular honesty, shared literacy and an updated goal last; crisis audits, bottling up and surveillance burn out.","persona":"Pooja","source":"lasting or not"},
  {"id":"mt-1387","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's no point planning money together until we're earning a lot.\"","myth":{"un":"There's no point planning money together until we're earning a lot.","re":"Planning is about being ready together, not being rich; any couple can start small, early and grow it.","why":"The habit and the cushion matter more than the size of the income."},"relearn":"Planning is about readiness, not riches; any couple can start small and early.","persona":"any","source":"ready not rich"},
  {"id":"mt-1388","cat":"tools-and-help","type":"strike-rewrite","hook":"\"One of us should just handle all the money; two people knowing it only causes confusion.\"","myth":{"un":"One of us should just handle all the money; two people knowing it only causes confusion.","re":"Both partners knowing the money is part of a fair plan; one-in-the-dark is a real vulnerability.","why":"If only one person can find or run the money, the other is left stranded when it counts."},"relearn":"Both knowing the money is fair and protective; leaving one in the dark is a real vulnerability.","persona":"Pooja","source":"both should know"},
  {"id":"mt-1389","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A money check-in is just nagging dressed up; couples who love each other don't need one.\"","myth":{"un":"A money check-in is just nagging dressed up; couples who love each other don't need one.","re":"A light, goal-framed check-in keeps money collaborative; love alone doesn't prevent money fights.","why":"Money is a top source of couple conflict, and open talking, not love alone, is what protects against it."},"relearn":"A goal-framed check-in is care, not nagging; love alone doesn't prevent money fights.","persona":"any","source":"check-in not nagging"},
  {"id":"mt-1390","cat":"tools-and-help","type":"strike-rewrite","hook":"\"You shouldn't ask for help until you're certain your money trouble is really abuse.\"","myth":{"un":"You shouldn't ask for help until you're certain your money trouble is really abuse.","re":"You can reach 181 or a counsellor while still unsure; you needn't prove it's abuse to get support.","why":"Waiting alone for certainty often means waiting too long, and support helps you find clarity either way."},"relearn":"You can seek help while unsure; certainty about abuse isn't a condition for reaching out.","persona":"Reshma","source":"unsure still asks"},
  {"id":"mt-1391","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Keeping your own account once married just means you don't trust your partner.\"","myth":{"un":"Keeping your own account once married just means you don't trust your partner.","re":"Your own account is respect for your future self and basic footing, not a verdict on your partner.","why":"Trust plus a personal safety net is stronger than trust with no footing at all."},"relearn":"Your own account is footing and self-respect, not distrust of your partner.","persona":"any","source":"account not distrust"},
  {"id":"mt-1392","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Asking for help to leave or rebuild after financial control is something to be ashamed of.\"","myth":{"un":"Asking for help to leave or rebuild after financial control is something to be ashamed of.","re":"Needing help to leave or rebuild is never shameful; that's exactly what support and 181 are for.","why":"Financial dependence never justifies control, and reaching out is courage, not failure."},"relearn":"Needing help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"no shame in help"},
  {"id":"mt-1393","cat":"tools-and-help","type":"strike-rewrite","hook":"\"It's not really abuse if he never hits you, just keeps the money tight.\"","myth":{"un":"It's not really abuse if he never hits you, just keeps the money tight.","re":"Seizing a salary or stridhan, cut-offs and barring work are economic abuse, recognised even with no violence.","why":"Indian law under the PWDVA 2005 recognises economic abuse as domestic violence, hits or not."},"relearn":"Economic abuse counts even with no physical violence; control is the line, not bruises.","persona":"Razia","source":"abuse without hits"},
  {"id":"mt-1394","cat":"tools-and-help","type":"reflect","hook":"Lensy: the money talk, the both-accounts setup, the monthly check-in, the help routes. That's the whole kit.","prompt":"What do you make of the kit?","options":["I've got it","Feels doable","Ready to use it"],"affirm":"The talk, both-accounts, the check-in and the help routes are the core tools of fair, safe money.","relearn":"Your toolkit: the money talk, both accounts, the monthly check-in, and the help routes.","persona":"any","source":"the whole kit"},
  {"id":"mt-1395","cat":"tools-and-help","type":"reflect","hook":"Lensy: which tool do you most want to try first with your partner, or your future one?","prompt":"Pick where you'd start:","options":["The first money talk","A monthly check-in","Setting up both accounts"],"affirm":"Any of these is a fine first step; starting anywhere makes money more open and fair.","relearn":"Pick any tool to start; the move that matters is starting the open-money habit at all.","persona":"any","source":"where to start"},
  {"id":"mt-1396","cat":"tools-and-help","type":"reflect","hook":"Lensy: imagine a calm monthly check-in where neither of you dreads the money talk anymore.","prompt":"How does that land for you?","options":["Relieving","Worth building","That's the goal"],"affirm":"A regular, low-stakes check-in is meant to feel like relief and control, not dread.","relearn":"The check-in's whole point is relief and shared control, not another thing to dread.","persona":"Sneha","source":"picture the calm"},
  {"id":"mt-1397","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing 181, 112, NALSA 15100 and a counsellor are one tap away, how does that sit?","prompt":"What's your take?","options":["Reassuring","Good to know","I'll remember it"],"affirm":"Knowing the routes, 181, 112, NALSA 15100, a counsellor, before you need them is quiet protection.","relearn":"Knowing 181, 112, NALSA 15100 and a counsellor before you need them is real protection.","persona":"Razia","source":"routes ready"},
  {"id":"mt-1398","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't have to be certain it's abuse to reach out, you can ask while still unsure.","prompt":"How does that sit with you?","options":["That helps","Less pressure","Good to know"],"affirm":"Reaching out while unsure is completely okay; you needn't prove anything first to get support.","relearn":"You can ask for help while unsure; you don't have to be certain it's abuse first.","persona":"Reshma","source":"unsure is fine"},
  {"id":"mt-1399","cat":"tools-and-help","type":"reflect","hook":"Lensy: open, planned, both-independent, and free of control. That's the money-together formula.","prompt":"Does the formula stick?","options":["Got it","Makes sense","I'll carry it"],"affirm":"Open, planned, both-independent and control-free is the formula for fair, healthy couple finances.","relearn":"The money-together formula: open, planned, both independent, and free of control.","persona":"any","source":"the formula"},
  {"id":"mt-1400","cat":"tools-and-help","type":"reflect","hook":"Lensy: which feels truer for you, that planning is about being ready together, or being rich?","prompt":"Where do you land?","options":["Being ready","Both a bit","Ready together"],"affirm":"Planning is about being ready together, not rich; any couple can begin right where they are.","relearn":"Planning is about being ready together, not being rich; any couple can start now.","persona":"any","source":"ready over rich"},
  {"id":"mt-1401","cat":"tools-and-help","type":"reflect","hook":"Lensy: a homemaker's care and home work is real economic value, equal in the money, not lesser.","prompt":"How does that land?","options":["True","Worth saying","Equal, yes"],"affirm":"Unpaid home and care work is real value; a homemaker's claim on the money is equal, not lesser.","relearn":"Unpaid home and care work is real economic value; the claim on the money is equal.","persona":"any","source":"value of care"},
  {"id":"mt-1402","cat":"tools-and-help","type":"spot","hook":"Spot the two red flags hiding among healthy money tools.","scene":[{"id":"a","text":"A monthly no-judgement check-in","trick":false},{"id":"b","text":"Each of you having personal money","trick":false},{"id":"c","text":"Handing your whole salary over on demand","trick":true},{"id":"d","text":"A shared timed goal for a big cost","trick":false},{"id":"e","text":"Asking permission for every rupee","trick":true}],"why":"Salary-handover-on-demand and permission-for-every-rupee are control, not tools; the rest are healthy.","relearn":"Salary-on-demand and permission-for-every-spend are control; check-ins, personal money and goals aren't.","persona":"any","source":"spot the control"},
  {"id":"mt-1403","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that are myths among the true facts about money tools.","scene":[{"id":"a","text":"Any couple can start, rich or not","trick":false},{"id":"b","text":"Tools are only for the wealthy","trick":true},{"id":"c","text":"Both partners should know the money","trick":false},{"id":"d","text":"Money is really the man's job","trick":true},{"id":"e","text":"Small, early savings still count","trick":false}],"why":"'Only for the wealthy' and 'money is the man's job' are myths; the others are true of the tools.","relearn":"Any couple can start and both should know the money; 'only the rich/men' are the myths.","persona":"any","source":"spot the myth"},
  {"id":"mt-1404","cat":"tools-and-help","type":"spot","hook":"A friend confides about money trouble. Spot the two responses that would hurt, not help.","scene":[{"id":"a","text":"\"181 or a counsellor can help, no pressure\"","trick":false},{"id":"b","text":"\"Every marriage is like this, just adjust\"","trick":true},{"id":"c","text":"\"You can ask even if you're not sure\"","trick":false},{"id":"d","text":"\"You're surely exaggerating it\"","trick":true},{"id":"e","text":"\"Needing help isn't shameful at all\"","trick":false}],"why":"'Just adjust' and 'you're exaggerating' dismiss her; offering routes and reassurance is what helps.","relearn":"Offering routes and reassurance helps; 'just adjust' and disbelief leave a friend more alone.","persona":"Razia","source":"spot the harm"},
  {"id":"mt-1405","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that signal control hiding in a couple's money talk.","scene":[{"id":"a","text":"\"Let's both see the accounts\"","trick":false},{"id":"b","text":"\"You don't need to know what I earn\"","trick":true},{"id":"c","text":"\"What's our goal this year?\"","trick":false},{"id":"d","text":"\"Working isn't for wives like you\"","trick":true},{"id":"e","text":"\"No judgement, we're a team\"","trick":false}],"why":"Shutting a partner out of the income and barring her from work are control; the rest are teamwork.","relearn":"Shut-outs and work-barring signal control; open access and shared goals signal teamwork.","persona":"any","source":"spot the line"},
  {"id":"mt-1406","cat":"tools-and-help","type":"spot","hook":"Spot the two habits that quietly erode a couple's money over time.","scene":[{"id":"a","text":"Regular, honest check-ins","trick":false},{"id":"b","text":"Hiding spending from each other","trick":true},{"id":"c","text":"Both staying literate and informed","trick":false},{"id":"d","text":"Bottling up worries for months","trick":true},{"id":"e","text":"Updating the goal as life changes","trick":false}],"why":"Hidden spending and bottled-up worries erode trust over time; openness and shared literacy build it.","relearn":"Hidden spending and bottling up erode money over time; honesty and shared literacy sustain it.","persona":"Pooja","source":"spot the erosion"},
  {"id":"mt-1407","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that wrongly delay getting help when money turns controlling.","scene":[{"id":"a","text":"Calling 181 or a counsellor early","trick":false},{"id":"b","text":"Waiting silently until it's unbearable","trick":true},{"id":"c","text":"Naming it and learning your rights","trick":false},{"id":"d","text":"Insisting you must be fully sure first","trick":true},{"id":"e","text":"Reaching NALSA 15100 about rights","trick":false}],"why":"Waiting in silence and demanding certainty first both delay help; reaching out early is the right move.","relearn":"Don't wait in silence or for certainty; reach 181, a counsellor or NALSA 15100 early.","persona":"Reshma","source":"spot the delay"},
  {"id":"mt-1408","cat":"tools-and-help","type":"spot","hook":"Spot the two setups that aren't fair money but control wearing its mask.","scene":[{"id":"a","text":"Joint account plus personal money each","trick":false},{"id":"b","text":"One partner barred from any account","trick":true},{"id":"c","text":"An agreed budget you both built","trick":false},{"id":"d","text":"A tiny policed allowance, cut on a whim","trick":true},{"id":"e","text":"Both knowing where the documents are","trick":false}],"why":"Being barred from accounts and a policed, whim-cut allowance are control; agreed, shared setups are fair.","relearn":"Account-barring and policed allowances are control; agreed budgets and shared access are fair.","persona":"any","source":"spot the mask"},
  {"id":"mt-1410","cat":"tools-and-help","type":"branch","persona":"any","source":"one compass","hook":"You want a single principle to carry into every money decision you'll make as a couple.","steps":[{"prompt":"You're about to make your first joint financial decision. What guides it?","options":[{"text":"Plan together, keep both independent, get help if control appears","then":"The decision comes together smoothly, with both of you weighing in.","best":true},{"text":"Default each time to what the higher earner wants","then":"The higher earner's preference quietly becomes the pattern."},{"text":"Decide based on whoever happens to feel more strongly that day","then":"Decisions start to feel inconsistent from one to the next."},{"text":"Put it off until it can't be avoided","then":"The decision gets rushed under pressure, without a real plan."}],"why":"One compass, open and independence-minded, guides every kind of decision."},{"prompt":"Months later, you notice one of you has started avoiding money talk altogether. What do you do?","options":[{"text":"Name it gently and suggest a calm time to talk","then":"The conversation reopens, a little awkward at first, then easier.","best":true},{"text":"Let it slide for now, hoping it resolves on its own eventually","then":"The avoidance quietly continues, unaddressed."},{"text":"Push hard to force a conversation right away","then":"The pressure backfires, and the avoidance deepens."},{"text":"Handle things alone in the meantime","then":"One of you starts making money decisions without the other."}],"why":"Naming the drift gently, early, is what reopens the talk."},{"prompt":"A friend about to move in with her partner asks what one rule you'd give her. What do you say?","options":[{"text":"Plan together, stay independent, get help if control creeps in","then":"Your friend asks if you'd walk her through what that looks like.","best":true},{"text":"Just stay easygoing about it, and it'll work out","then":"Your friend nods, a little unconvinced, and doesn't ask more."},{"text":"Let whoever earns more take the lead","then":"Your friend frowns slightly, unsure that fits her life."},{"text":"Money doesn't need rules if you love each other","then":"Your friend smiles, though it gives her nothing to use."}],"why":"Naming the actual principle is what makes it something to keep returning to."}],"debrief":"One principle carries it: plan together, keep both independent, reach for help if control creeps in.","relearn":"Lead with open and fair; defaulting to the top earner rebuilds the imbalance."},
];

